    public function searchReferredAdmissionCancelled(Request $request)
    {
        $qury = DB::table('ipd_admissionrequest_vw')->where('cancel_ind', 1);

        if (!empty($request->hdn_patient_id)) {
            $qury->where('patient_no_fk', $request->hdn_patient_id);
        }
        if (!empty($request->admission_req_date_from) && !empty($request->admission_req_date_to)) {
            $qury->where(DB::raw("trunc(admission_req_date)"), '>=', date('Y-m-d', strtotime($request->admission_req_date_from)));
            $qury->where(DB::raw("trunc(admission_req_date)"), '<=', date('Y-m-d', strtotime($request->admission_req_date_to)));
        } elseif (!empty($request->admission_req_date_from)) {
            $qury->where(DB::raw("trunc(admission_req_date)"), '=', date('Y-m-d', strtotime($request->admission_req_date_from)));
        } elseif (!empty($request->admission_req_date_to)) {
            $qury->where(DB::raw("trunc(admission_req_date)"), '=', date('Y-m-d', strtotime($request->admission_req_date_to)));
        }
        return Template::loadview("admin.ipd.ipd_request.search_ipd_request_admission_cancelled", [
            'referedCancelledPatients' => $qury->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))->orderBy('admission_req_no_pk', 'desc')->get()->toArray(),
        ]);
    }
