    public function store_ipdAdmissionRejection(Request $request)
    {


        // dd($request->all());
        Validator::make($request->all(), [
            'admission_req_uid' => 'required',
            'hidden_service_no' => 'required',
            'reject_reason' => 'required',
        ])
            ->validate();

        try {

            DB::transaction(function () use ($request) {
                $result = DB::table('ipd_admissionrequest')
                    ->where('patient_no_fk', $request->hidden_service_no)
                    ->where('admission_req_uid', $request->admission_req_uid)
                    ->update([
                        'cancel_reason' => $request->reject_reason,
                        'cancel_ind' => 1,
                        'au_update_by' => Auth::id(),
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                    ]);
            });

            $this->message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Exception $e) {

            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }
        return response()->json($this->message);
    }

