    public function getAdmissionHistory($admission_id)
    {
        $bed_history = DB::table('ipd_admission_bed')
            ->leftJoin('ipds_bed', 'ipds_bed.bed_no_pk', '=', 'ipd_admission_bed.bed_no_fk')
            ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipd_admission_bed.ward_no_fk')
            ->leftjoin('sysc_serviceunit', 'sysc_serviceunit.serviceunit_no_pk', '=', 'ipds_ward.service_unit_no_fk')
            ->select(
                'ipds_bed.bed_name',
                'ipds_ward.ward_name',
                'sysc_serviceunit.serviceunit_name'
            )->where('ipd_admission_bed.admission_no_fk', $admission_id)
            ->orderByDesc('ipd_admission_bed.end_time')
            ->get();
        return $bed_history;
    }
    public function bloodBankRequisitionWorklist()
    {
        $to_date = date('Y-m-d');
        $blood_requisition_data = BloodBankRequisition::leftJoin(
            'sysc_lookupdata',
            'sysc_lookupdata.lookupdata_no_pk',
            '=',
            'bbd_requisition.donor_type'
        )->select('bbd_requisition.requsition_no_pk', 'bbd_requisition.au_entry_at', 'bbd_requisition.patient_code', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date', 'bbd_requisition.patient_name', 'bbd_requisition.patient_age', 'bbd_requisition.bed_cabin_name', 'bbd_requisition.blood_group', 'bbd_requisition.blood_bag_qty', 'bbd_requisition.trensmission_date', 'bbd_requisition.donor_name', 'bbd_requisition.doctor_name', 'sysc_lookupdata.lookupdata_code')
            ->where(DB::raw('TRUNC(bbd_requisition.au_entry_at)'), '>=', DB::raw("TO_DATE('" . date('Y-m-d', strtotime('-7 days')) . "', 'YYYY-MM-DD')"))
            ->where(DB::raw('TRUNC(bbd_requisition.au_entry_at)'), '<=', DB::raw("TO_DATE('" . date('Y-m-d') . "', 'YYYY-MM-DD')"))
            ->orderby('bbd_requisition.au_entry_at', 'desc')
            ->get();
        return Template::loadview("admin.ipd.blood_bank.blood_bank_requisition_worklist", ['blood_requisition_data' => $blood_requisition_data]);
    }
    public function bloodBankRequisitionSearch(Request $request)
    {
        $admission_id = $request->admission_id;
        $hdn_patient_id = $request->hdn_patient_id;
        $prescription_id = $request->prescription_id;
        $requisition_no = $request->requisition_no;
        $requisition_date_from = $request->requisition_date_from != "" ? date('Y-m-d', strtotime($request->requisition_date_from)) : '';
        $admission_date_to = $request->admission_date_to != "" ? date('Y-m-d', strtotime($request->admission_date_to)) : '';

        $query = BloodBankRequisition::leftJoin(
            'sysc_lookupdata',
            'sysc_lookupdata.lookupdata_no_pk',
            '=',
            'bbd_requisition.donor_type'
        )->select('bbd_requisition.requsition_no_pk', 'bbd_requisition.au_entry_at', 'bbd_requisition.patient_code', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date', 'bbd_requisition.patient_name', 'bbd_requisition.patient_age', 'bbd_requisition.bed_cabin_name', 'bbd_requisition.blood_group', 'bbd_requisition.blood_bag_qty', 'bbd_requisition.trensmission_date', 'bbd_requisition.donor_name', 'bbd_requisition.doctor_name', 'sysc_lookupdata.lookupdata_code', 'bbd_requisition.blood_group');
        if ($requisition_no != "") {
            $query->where('bbd_requisition.requsition_no_pk', $requisition_no);
        }
        if ($prescription_id != "") {
            $query->where('bbd_requisition.prescription_no_fk', $prescription_id);
        }
        if ($admission_id != "") {
            $query->where('bbd_requisition.admission_no_fk', $admission_id);
        }
        if ($hdn_patient_id != "") {
            $query->where('bbd_requisition.patient_no_fk', $hdn_patient_id);
        }
        if ($requisition_date_from != "" && $admission_date_to != "") {
            $query->whereBetween('bbd_requisition.au_entry_at', [
                Carbon::parse($requisition_date_from)->startOfDay(),
                Carbon::parse($admission_date_to)->endOfDay()
            ]);
        } elseif ($requisition_date_from != "") {
            $query->whereDate('bbd_requisition.au_entry_at', $requisition_date_from);
        }
        $blood_requisition_data = $query->orderby('bbd_requisition.au_entry_at', 'desc')->get();
        return Template::loadview("admin.ipd.blood_bank.blood_bank_requisition_list", ['blood_requisition_data' => $blood_requisition_data]);
    }

    public function bloodCollectionFromDonor($requsition_no, $donor_no, $admission_no, $admission_date, $blood_group = "", $collection_no = "")
    {

        $donor_id = $donor_no;
        $admission_no = $admission_no;
        $admission_date = $admission_date;
        $collection_no = $collection_no;
        $bloodg = $this->getLookupListByCode("BLOODG");
        $collection_data = [];
        if ($collection_no != "") {
            $collection_data = DB::table('bbd_blood_collection')->select('blood_col_no_pk', 'donor_no_fk', 'admission_no_fk', 'blood_group', 'blood_col_date', 'bag_no', 'remarks')->where('blood_col_no_pk', $collection_no)->first();
        }

        return Template::loadview("admin.ipd.blood_bank.blood_collection_from_donor", ['donor_id' => $donor_id, 'admission_no' => $admission_no, 'collection_data' => $collection_data, 'bloodg' => $bloodg, 'admission_date' => $admission_date, 'blood_group' => $blood_group, 'requsition_no' => $requsition_no, 'donor_id' => $donor_id]);
    }




    public function saveBloodCollectionFromDonor(Request $request)
    {
        $id = $request->blood_collection_no;
        $collected_date = date('Y-m-d');
        try {
            $data = [
                'donor_no_fk' => $request->donor_no_fk,
                'admission_no_fk' => $request->admission_no,
                'blood_group' => $request->blood_group,
                'blood_col_date' => date('Y-m-d', strtotime($collected_date)),
                'bag_no' => $request->bag_no,
                'remarks' => $request->remarks,


            ];
            if ($id == "") {
                $sequence = DB::getSequence();
                $no_pk = $sequence->nextValue('blood_col_no_pk_seq');
                $data['requsition_no_fk'] = $request->requsition_no;
                $data['blood_col_no_pk'] = $no_pk;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_at'] = date('Y-m-d h:i');
                $data['au_entry_session'] = 'session';
                $data['au_entry_hospital_pk_no'] = Session::get('user.ses_hospital_no_pk');
                DB::table('bbd_blood_collection')->insert($data);
            } else {
                $data['au_update_by'] = Auth::id();
                $data['au_update_at'] = date('Y-m-d h:i');
                $data['au_update_session'] = 'update session';
                $data['au_update_hospital_pk_no'] = Session::get('user.ses_hospital_no_pk');
                DB::table('bbd_blood_collection')->where('blood_col_no_pk', $id)->update($data);
            }
            DB::commit();
            $this->message = ['msg' => 'Data Saved Successfully', 'title' => 'Success',];
        } catch (\Throwable $e) {
            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }
        return response()->json($this->message);
    }
    public function bloodCollectionWorklist()
    {
         $donor_data = BBDDonorDetails::select('bbd_donor_details.blood_requisition_no_fk', 'bbd_requisition.prescription_no_fk', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date', 'bbd_donor.donor_name', 'bbd_donor.donor_mobile', 'ipd_admitted_patlist_vw.new_bed_name', 'ipd_admitted_patlist_vw.new_ward_name', 'ipd_admitted_patlist_vw.new_su_name', 'ipd_admitted_patlist_vw.primary_doctor_name', 'ipd_admitted_patlist_vw.primary_doctor_no_fk', 'bbd_donor.donor_no_pk', 'bbd_blood_collection.blood_col_no_pk', 'bbd_blood_collection.blood_group', 'bbd_blood_collection.bag_no', 'bbd_requisition.blood_group', 'bbd_requisition.requsition_no_pk', 'bbd_blood_collection.blood_col_no_pk')
        ->leftjoin('bbd_requisition', 'bbd_requisition.requsition_no_pk', '=', 'bbd_donor_details.blood_requisition_no_fk')
