        ->leftjoin('ipd_admitted_patlist_vw', 'ipd_admitted_patlist_vw.admission_no_pk', '=', 'bbd_requisition.admission_no_fk')
        ->leftjoin('bbd_blood_collection', 'bbd_blood_collection.donor_no_fk', '=', 'bbd_donor.donor_no_pk')
        ->where(DB::raw('TRUNC(bbd_donor.au_entry_at)'), '>=', DB::raw("TO_DATE('" . date('Y-m-d', strtotime('-7 days')) . "', 'YYYY-MM-DD')"))
        ->where(DB::raw('TRUNC(bbd_donor.au_entry_at)'), '<=', DB::raw("TO_DATE('" . date('Y-m-d') . "', 'YYYY-MM-DD')"))
        ->orderby('bbd_donor.au_entry_at', 'desc')->get();

        return Template::loadview("admin.ipd.blood_bank.blood_collection_worklist", ['donor_data' => $donor_data]);
    }
    public function bloodCollectionSearch(Request $request)
    {
        $admission_id = $request->admission_id;
        $uhid = $request->hdn_patient_id;
        $donor_id = $request->hidden_donor_id;
        $prescription_id = $request->prescription_id;
        $requisition_no = $request->requisition_no;
        $requisition_date_from = $request->requisition_date_from != "" ? date('Y-m-d', strtotime($request->requisition_date_from)) : '';
        $admission_date_to = $request->admission_date_to != "" ? date('Y-m-d', strtotime($request->admission_date_to)) : '';

        $query = BBDDonorDetails::select('bbd_donor_details.blood_requisition_no_fk', 'bbd_requisition.prescription_no_fk', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date', 'bbd_donor.donor_name', 'bbd_donor.donor_mobile', 'ipd_admitted_patlist_vw.new_bed_name', 'ipd_admitted_patlist_vw.new_ward_name', 'ipd_admitted_patlist_vw.new_su_name', 'ipd_admitted_patlist_vw.primary_doctor_name', 'ipd_admitted_patlist_vw.primary_doctor_no_fk', 'bbd_donor.donor_no_pk', 'bbd_blood_collection.blood_col_no_pk', 'bbd_blood_collection.blood_group', 'bbd_blood_collection.bag_no', 'bbd_requisition.blood_group', 'bbd_requisition.requsition_no_pk', 'bbd_blood_collection.blood_col_no_pk')
            ->leftjoin('bbd_requisition', 'bbd_requisition.requsition_no_pk', '=', 'bbd_donor_details.blood_requisition_no_fk')
            ->leftjoin('bbd_donor', 'bbd_donor.donor_no_pk', '=', 'bbd_donor_details.donor_no_fk')
            ->leftjoin('ipd_admitted_patlist_vw', 'ipd_admitted_patlist_vw.admission_no_pk', '=', 'bbd_requisition.admission_no_fk')
            ->leftjoin('bbd_blood_collection', 'bbd_blood_collection.donor_no_fk', '=', 'bbd_donor.donor_no_pk');
        // if ($requisition_no !="") {
        //     $query->where('requsition_no_pk',$requisition_no);
        // }
        // if ($requisition_date_from !="" && $admission_date_to !="") {
        //     $query->whereBetween('au_entry_at',[
        //         Carbon::parse($requisition_date_from)->startOfDay(),
        //         Carbon::parse($admission_date_to)->endOfDay()
        //     ]);
        // }elseif($requisition_date_from !=""){
        //     $query->whereDate('au_entry_at',$requisition_date_from);
        // }

        if (isset($request->from_date) && $request->to_date) {
            $query->where(DB::raw('trunc(bbd_donor.au_entry_at)'), '>=', date('Y-m-d', strtotime($request->from_date)))
                  ->where(DB::raw('trunc(bbd_donor.au_entry_at)'), '<=', date('Y-m-d', strtotime($request->to_date)));
        }
        if ($prescription_id != "") {
            $query->where('bbd_requisition.prescription_no_fk', $prescription_id);
        }
        if ($admission_id != "") {
            $query->where('bbd_requisition.admission_no_fk', $admission_id);
        }
        if ($uhid != "") {
            $query->where('bbd_requisition.patient_no_fk', $uhid);
        }
        if ($donor_id != "") {
            $query->where('bbd_donor_details.donor_no_fk', $donor_id);
        }
        $donor_data = $query->orderby('bbd_blood_collection.au_entry_at', 'desc')->get();

        // dd($donor_data);
        return Template::loadview("admin.ipd.blood_bank.blood_collection_list", ['donor_data' => $donor_data]);
    }
    public function bloodBankRequisition( $patient_id = null, $admission_uid = null)
    {
        $bloodg = $this->getLookupListByCode("BLOODG");
        $blood_requisition_data = [];
        $bbbloodtype = $this->getLookupListByCode("BBBLOODTYPE");
        $bbtakentype = $this->getLookupListByCode("BBBLOODTAKENTYPE");
        $bbsideffect = $this->getLookupListByCode("BBSIDEFFECT");
        $donorType = $this->getLookupListByCode("DONORTYPE");
        $bloodg = $this->getLookupListByCode("BLOODG");
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
