            ->first();
        //dd($patient_info);
        return Template::loadview("admin.ipd.blood_bank.blood_bank_requisition", ['bbbloodtype' => $bbbloodtype, 'bbtakentype' => $bbtakentype, 'bbsideffect' => $bbsideffect, 'blood_requisition_data' => $blood_requisition_data, 'donorType' => $donorType, 'bloodg' => $bloodg, 'patient_id' => $patient_id, 'patient_info'=> $patient_info, 'admission_uid' => $admission_uid]);
    }
    public function searchBloodBankRequisition(Request $request)
    {
        $patient_info = null;
        if ($request->admission_id) {
            $patient_info = DB::table('ipd_admitted_patlist_vw')
                ->select(
                    'admission_no_pk',
                    'admission_date',
                    'patient_name',
                    'patient_no_fk',
                    'patient_code',
                    'new_bed_name',
                    'gender_txt',
                    'blood_group_text',
                    'primary_doctor_name',
                    'primary_doctor_no_fk',
                    DB::raw("'' as prescription_no_pk"),
                    'dob'
                )
                ->where('admission_no_pk', $request->admission_id)
                ->where('dis_ind', 0)
                ->first();
        } elseif ($request->uhid) {
            $patient_info = DB::table('ipd_admitted_patlist_vw')
                ->select(
                    'admission_no_pk',
                    'admission_date',
                    'patient_name',
                    'patient_no_fk',
                    'patient_code',
                    'new_bed_name',
                    'gender_txt',
                    'blood_group_text',
                    'primary_doctor_name',
                    'primary_doctor_no_fk',
                    DB::raw("'' as prescription_no_pk"),
                    'dob'
                )
                ->where('patient_no_fk', $request->uhid)
                ->where('dis_ind', 0)
                ->first();
        } elseif ($request->prescription_id) {
            $patient_info = DB::table('psn_t_prescription_vw')
                ->select(
                    'admission_no_fk as admission_no_pk',
                    'patient_name',
                    'patient_no_fk',
                    'patient_code',
                    'bed_name as new_bed_name',
                    'gender_txt',
                    DB::raw("'' as admission_date"),
                    DB::raw("'' as blood_group_text"),
                    'prescription_no_pk',
                    'dob'
                )
                ->where('prescription_no_pk', $request->prescription_id)
                ->first();
        } elseif ($request->invoice_no) {
            $patient_info = DB::table('finc_vouchermst_sum_vw a')
                ->select(
                    'a.invoice_no_pk',
                    'a.invoice_code',
                    'a.invoice_date',
                    'a.admission_no_pk',
                    'a.admission_code',
                    'a.customer_name',
                    'a.patient_no_pk',
                    'a.patient_code',
                    'a.patient_name',
                    'a.age',
                    'a.dob',
                    'a.blood_group_txt as blood_group_text',
                    'a.gender_txt',
                    'b.admission_date',
                    'b.new_bed_name',
                    'b.primary_doctor_name',
                    'b.primary_doctor_no_fk'
                )
                ->leftJoin('ipd_admitted_patlist_vw b', 'a.admission_no_pk', 'b.admission_no_pk')
                ->where('b.dis_ind', 0)
                ->where('invoice_no_pk', $request->invoice_no)->first();
        } else {
            $patient_info = "";
        }

        if ($patient_info) {
            $dob = Carbon::parse($patient_info->dob);
            $age = $dob->diffInYears(Carbon::now());
            $patient_info->age = $age;
        }
        // dd($patient_info);
        return response()->json($patient_info);
    }

