    public function bloodBankRequisitionDonorList($id = null)
    {
        $query = BBDDonorDetails::select('bbd_donor.donor_name', 'bbd_donor.donor_dob', 'bbd_donor.donor_gender', 'sysc_lookupdata.lookupdata_code', 'bbd_donor.donor_age', 'bbd_donor.donor_mobile', 'bbd_donor.donor_address', 'bbd_donor.last_blood_donat_date', 'bbd_donor.fatherorhousbend_name', 'bbd_donor.donor_no_pk', 'bbd_donor_details.blood_group', 'bbd_donor_details.donordtl_no_pk', 'bbd_donor_details.is_selected_donate')
            ->leftJoin('bbd_donor', 'bbd_donor.donor_no_pk', '=', 'bbd_donor_details.donor_no_fk')
            ->leftjoin('sysc_lookupdata', 'sysc_lookupdata.lookupdata_no_pk', '=', 'bbd_donor.donor_type');
        if (isset($id)) {
            $query->where('blood_requisition_no_fk', $id);
        } else {
            $date_from = date('Y-m-d', strtotime(date('Y-m-d', strtotime('-6 days'))));
            $date_to = date('Y-m-d', strtotime(date('Y-m-d')));
            $query->whereBetween('bbd_donor.au_entry_at', [
                Carbon::parse($date_from)->startOfDay(),
                Carbon::parse($date_to)->endOfDay()
            ]);
        }
        $blood_requisition_dtl_data = $query->orderBy('donor_no_pk', 'desc')->get();
        if (isset($id)) {
            return Template::loadview("admin.ipd.blood_bank.blood_bank_requisition_donor_list", ['blood_requisition_dtl_data' => $blood_requisition_dtl_data]);
        } else {
            $donorType = $this->getLookupListByCode("DONORTYPE");
            return Template::loadview("admin.ipd.blood_bank.blood_bank_requisition_donor_list_all", ['blood_requisition_dtl_data' => $blood_requisition_dtl_data, 'donorType' => $donorType]);
        }
    }

