    public function bloodBankCrossMatchListDMHL()
    {
        $data = DB::table('bbd_crossmatch a')
                ->select('a.crossmatch_no_pk', 'a.donordtl_no_pk', 'a.donor_no_fk', 'a.blood_requisition_no_fk', 'a.crossmatch_status', 'a.whole_blood', 'a.whole_blood_exp_date', 'a.prbc_rcc_pcv', 'a.prbc_rcc_pcv_exp_date', 'a.washed_prbc', 'a.washed_prbc_exp_date', 'a.platalet_concentrate', 'a.platalet_concentrate_exp_date', 'a.hbsag', 'a.anti_hbc', 'a.anti_hcv', 'a.hiv_1_2', 'a.malaria_antigen', 'a.vdrl', 'a.blood_bag_no', 'a.blood_issued_ind', 'bbd_donor.donor_name', 'bbd_donor_details.blood_group', 'bbd_requisition.patient_name', 'bbd_requisition.patient_code', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date')
                ->leftJoin('bbd_donor', 'a.donor_no_fk', '=', 'bbd_donor.donor_no_pk')
                ->leftJoin('bbd_donor_details', 'a.donordtl_no_pk', 'bbd_donor_details.donordtl_no_pk')
                ->leftJoin('bbd_requisition', 'a.blood_requisition_no_fk', 'bbd_requisition.requsition_no_pk')
                 ->where(DB::raw('TRUNC(a.au_entry_at)'), '>=', DB::raw("TO_DATE('" . date('Y-m-d', strtotime('-7 days')) . "', 'YYYY-MM-DD')"))
                ->where(DB::raw('TRUNC(a.au_entry_at)'), '<=', DB::raw("TO_DATE('" . date('Y-m-d') . "', 'YYYY-MM-DD')"))
                ->orderBy('a.au_entry_at', 'asc')->get();
        return Template::loadView("admin.ipd.blood_bank.donor_cross_match_worklist_dmhl", ['data' => isset($data) ? $data : []]);
    }

    public function bloodBankCrossMatchListSearchDMHL(Request $request)
    {
        $query = DB::table('bbd_crossmatch a')
        ->select('a.crossmatch_no_pk', 'a.donordtl_no_pk', 'a.donor_no_fk', 'a.blood_requisition_no_fk', 'a.crossmatch_status', 'a.whole_blood', 'a.whole_blood_exp_date', 'a.prbc_rcc_pcv', 'a.prbc_rcc_pcv_exp_date', 'a.washed_prbc', 'a.washed_prbc_exp_date', 'a.platalet_concentrate', 'a.platalet_concentrate_exp_date', 'a.hbsag', 'a.anti_hbc', 'a.anti_hcv', 'a.hiv_1_2', 'a.malaria_antigen', 'a.vdrl', 'a.blood_bag_no', 'a.blood_issued_ind', 'bbd_donor.donor_name', 'bbd_donor_details.blood_group', 'bbd_requisition.patient_name', 'bbd_requisition.patient_code', 'bbd_requisition.admission_no_fk', 'bbd_requisition.admission_date')
        ->leftJoin('bbd_donor', 'a.donor_no_fk', '=', 'bbd_donor.donor_no_pk')
        ->leftJoin('bbd_donor_details', 'a.donordtl_no_pk', 'bbd_donor_details.donordtl_no_pk')
        ->leftJoin('bbd_requisition', 'a.blood_requisition_no_fk', 'bbd_requisition.requsition_no_pk');
        if ($request->cross_match_id) {
            $query->where('a.crossmatch_no_pk', $request->cross_match_id);
        }
        if ($request->donor_id) {
            $query->where('a.donor_no_fk', $request->donor_id);
        }
        if (isset($request->from_date) && $request->to_date) {
            $query->where(DB::raw('trunc(a.au_entry_at)'), '>=', date('Y-m-d', strtotime($request->from_date)))
                  ->where(DB::raw('trunc(a.au_entry_at)'), '<=', date('Y-m-d', strtotime($request->to_date)));
        }
        $data = $query->orderBy('a.au_entry_at', 'asc')->get();
        return Template::loadView("admin.ipd.blood_bank.donor_cross_match_worklist_search_table_dmhl", ['data' => isset($data) ? $data : []]);
    }

    public function bloodBagStickerPDF($id = "", $blood_bag_no = "")
    {
        $results = DB::table('BBD_CROSSMATCH')
            ->select('BBD_CROSSMATCH.CROSSMATCH_NO_PK', 'BBD_CROSSMATCH.WHOLE_BLOOD', 'BBD_CROSSMATCH.PLATALET_CONCENTRATE_EXP_DATE', 'BBD_CROSSMATCH.WASHED_PRBC_EXP_DATE', 'BBD_CROSSMATCH.WHOLE_BLOOD_EXP_DATE', 'BBD_CROSSMATCH.PRBC_RCC_PCV', 'BBD_CROSSMATCH.PRBC_RCC_PCV_EXP_DATE', 'BBD_CROSSMATCH.WASHED_PRBC', 'BBD_CROSSMATCH.PLATALET_CONCENTRATE', 'BBD_CROSSMATCH.BLOOD_BAG_NO', 'BBD_CROSSMATCH.AU_ENTRY_AT', 'BBD_DONOR_DETAILS.BLOOD_GROUP', 'BBD_REQUISITION.PATIENT_NAME', 'BBD_REQUISITION.PATIENT_CODE', 'BBD_BLOOD_COLLECTION.BLOOD_COL_DATE')
            ->leftJoin('BBD_DONOR_DETAILS', 'BBD_CROSSMATCH.DONORDTL_NO_PK', '=', 'BBD_DONOR_DETAILS.DONORDTL_NO_PK')
            ->leftJoin('BBD_REQUISITION', 'BBD_CROSSMATCH.BLOOD_REQUISITION_NO_FK', '=', 'BBD_REQUISITION.REQUSITION_NO_PK')
            ->leftJoin('BBD_BLOOD_COLLECTION', 'BBD_CROSSMATCH.BLOOD_REQUISITION_NO_FK', '=', 'BBD_BLOOD_COLLECTION.REQUSITION_NO_FK')
            ->where('BBD_CROSSMATCH.CROSSMATCH_NO_PK', $id)
            ->first();

        // dd($results);
        $barcode = new BarcodeGenerator();
        $barcode->setText($results->crossmatch_no_pk);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(8);

        $data['lab_no_barcode'] = $barcode->generate();
        $data['label_info'] = $results;

        $pdf = PDF::loadView("admin.ipd.blood_bank.blood_bag_sticker_pdf", $data);
        return $pdf->stream("SM-$results->crossmatch_no_pk.pdf");
    }

    public function bloodBagCrossMatchReportPDF($id = "", $blood_bag_no = "")
