            ->leftJoin('bbd_donor_details', 'bbd_crossmatch.donordtl_no_pk', 'bbd_donor_details.donordtl_no_pk')
           ->leftJoin('bbd_blood_collection', function($join) {
                $join->on('bbd_crossmatch.blood_requisition_no_fk', '=', 'bbd_blood_collection.requsition_no_fk')
                    ->on('bbd_crossmatch.donor_no_fk', '=', 'bbd_blood_collection.donor_no_fk');
