        $barcode->setThickness(25);
        $barcode->setFontSize(8);
        $data['lab_no_barcode'] = $barcode->generate();
        // $data['label_info'] = $results;
        // dd($component_data);
        $pdf = PDF::loadView("admin.ipd.blood_bank.cross_match_report_pdf", ["cross_match_data" => $cross_match_data, "component_data" => $component_data, "data" => $data, "po_hospital_details" => $po_hospital_details]);
        return $pdf->stream("SM-Cross-Match.pdf");
    }

