    public function saveBloodBankRequisition(Request $request)
    {

        try {
            $auth_id = Auth::id();
            $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
            DB::beginTransaction();
            $sequence = DB::getSequence();
            $blood_bank_requisition_sqe = $sequence->nextValue('requsition_no_pk_seq');
            //dd($request->all());
            if($request->status == 'nurse_station' && ($request->patient_id == "" || $request->age == "" || $request->gender == "")){
                $message = ['msg' =>'Patient Id, Age, Gender, Blood Group are required.', 'title' => 'Error'];
                return response()->json($message);
            }
            $data = [
                'patient_no_fk' => $request->hidn_patient_id,
                'patient_code' => $request->patient_id,
                'patient_name' => $request->patient_name,
                'patient_age' => $request->age,
                'patient_gender' => $request->gender,
                'admission_no_fk' => $request->admission_no,
                'admission_date' => $request->admission_date != "" ? date('Y-m-d', strtotime($request->admission_date)) : '',
                'bed_cabin_name' => $request->bed_cabin,
                'blood_group' => $request->blood_group,
                'hemoglobin' => $request->hemoglobin,
                'bp' => $request->bp,
                'pulse' => $request->pulse,
                'blood_bag_qty' => $request->blood_bag_qty,
                'blood_type' => $request->blood_bag_qty_type,
                'donor_type' => $request->donor_type,
                'trensmission_date' => $request->blood_transmission_date != "" ? date('Y-m-d', strtotime($request->blood_transmission_date)) : '',
                'trensmission_time' => $request->in_time != "" ? date('Y-m-d H:i', strtotime($request->in_time)) : '',
                'blood_taken_type' => $request->blood_teken_type,
                'exam_type' => $request->exam_type,
                'tamprature' => $request->temperature,
                'last_blood_donation_date' => $request->last_blood_donation_date != "" ? date('Y-m-d', strtotime($request->last_blood_donation_date)) : '',
                'prev_trensmission_date' => $request->prev_blood_transmission_date != "" ? date('Y-m-d', strtotime($request->prev_blood_transmission_date)) : '',
                'last_blood_sideeffect' => $request->side_effects,
                'pledge_donor' => $request->pledge_donor,
                'donor_name' => $request->donor_name,
                'doctor_name' => $request->doctor_code,
                'doctor_no_fk' => $request->hdn_doctor_id,
            ];

            if ($request->blood_bank_req_id == "") {
                $data['requsition_no_pk'] = $blood_bank_requisition_sqe;
                $data['au_entry_by'] = $auth_id;
                $data['au_entry_at'] = date('Y-m-d');
                $data['au_entry_hospital_no_fk'] = $ses_hospital_id;
                BloodBankRequisition::insert($data);
            } else {
                BloodBankRequisition::where('requsition_no_pk', $request->blood_bank_req_id)->update($data);
            }
            DB::commit();
            $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            $message = ['msg' => $th->getMessage(), 'title' => 'Error'];
        }

        return response()->json($message);
    }
