    public function bloodBagIssueWorklist()
    {
        $data = DB::table('bbd_crossmatch')
            ->select('bbd_crossmatch.*', 'bbd_donor_details.blood_group', 'bbd_requisition.patient_name', 'bbd_requisition.patient_code')
            ->leftJoin('bbd_donor_details', 'bbd_crossmatch.donordtl_no_pk', 'bbd_donor_details.donordtl_no_pk')
            ->leftJoin('bbd_requisition', 'bbd_crossmatch.blood_requisition_no_fk', 'bbd_requisition.requsition_no_pk')
            // ->orderBy('bbd_crossmatch.crossmatch_no_pk', 'asc')
            // ->where('blood_issued_ind', null)
            // ->whereNull('bbd_crossmatch.discard_ind')
            ->where(DB::raw('TRUNC(bbd_crossmatch.au_entry_at)'), '>=', DB::raw("TO_DATE('" . date('Y-m-d', strtotime('-7 days')) . "', 'YYYY-MM-DD')"))
            ->where(DB::raw('TRUNC(bbd_crossmatch.au_entry_at)'), '<=', DB::raw("TO_DATE('" . date('Y-m-d') . "', 'YYYY-MM-DD')"))
            ->orderBy('bbd_crossmatch.au_entry_at', 'asc')
            ->get();

        return Template::loadView("admin.ipd.blood_bank.blood_bag_stock_worklist", ["data" => $data]);
    }

    public function bloodBagIssueWorklistSearch(Request $request)
    {
        $datas = DB::table('bbd_crossmatch')
            ->select('bbd_crossmatch.*', 'bbd_donor_details.blood_group', 'bbd_requisition.patient_name', 'bbd_requisition.patient_code')
            ->leftJoin('bbd_donor_details', 'bbd_crossmatch.donordtl_no_pk', 'bbd_donor_details.donordtl_no_pk')
            ->leftJoin('bbd_requisition', 'bbd_crossmatch.blood_requisition_no_fk', 'bbd_requisition.requsition_no_pk');

        if ($request->issue_status == "issue_pending") {
            $datas->whereNull('bbd_crossmatch.blood_issued_ind')->whereNull('bbd_crossmatch.discard_ind');
        }

        if ($request->issue_status == "issued") {
            $datas->where('bbd_crossmatch.blood_issued_ind', 1)->whereNull('bbd_crossmatch.discard_ind');
        }
        if ($request->issue_status == "expired") {
            $datas->where('bbd_crossmatch.discard_ind', 1);
        }

        if (isset($request->from_date) && $request->to_date && $request->issue_status == "issue_pending") {
            $datas->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '>=', date('Y-m-d', strtotime($request->from_date)))
                ->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '<=', date('Y-m-d', strtotime($request->to_date)))
                ->whereNull('bbd_crossmatch.blood_issued_ind')->whereNull('bbd_crossmatch.discard_ind');
        }

        if (isset($request->from_date) && $request->to_date && $request->issue_status == "issued") {
            $datas->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '>=', date('Y-m-d', strtotime($request->from_date)))
                ->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '<=', date('Y-m-d', strtotime($request->to_date)))
                ->where('bbd_crossmatch.blood_issued_ind', 1)->whereNull('bbd_crossmatch.discard_ind');
        }

        if (isset($request->from_date) && $request->to_date && $request->issue_status == "all") {
            $datas->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '>=', date('Y-m-d', strtotime($request->from_date)))
                ->where(DB::raw('trunc(bbd_crossmatch.au_entry_at)'), '<=', date('Y-m-d', strtotime($request->to_date)));
        }

        if (isset($request->bag_no) && $request->issue_status == "issue_pending") {
            $datas->whereNull('bbd_crossmatch.blood_issued_ind')
                ->where('bbd_crossmatch.crossmatch_no_pk', $request->bag_no)->whereNull('bbd_crossmatch.discard_ind');
        }

        // if (isset($request->bag_no) && $request->issue_status == "issued") {
        //     $datas->where('bbd_crossmatch.blood_issued_ind', 1)
        //         ->where('bbd_crossmatch.blood_bag_no', '=', $request->bag_no)->whereNull('bbd_crossmatch.discard_ind');
        // }
        if (isset($request->bag_no) && $request->issue_status == "issued") {
            $datas->where('bbd_crossmatch.blood_issued_ind', 1)
                ->where('bbd_crossmatch.crossmatch_no_pk', '=', $request->bag_no)->whereNull('bbd_crossmatch.discard_ind');
        }
        if (isset($request->bag_no)) {
            $datas->where('bbd_crossmatch.crossmatch_no_pk', '=', $request->bag_no);
        }

        if (isset($request->patient_id)) {
            $datas->where('bbd_requisition.patient_no_fk', '=', $request->patient_id);
        }

        $data = $datas->orderBy('bbd_crossmatch.au_entry_at', 'asc')->get();
        // dd($data);
        return Template::loadView("admin.ipd.blood_bank.blood_bag_stock_worklist_search", ["data" => $data, 'status' => 1]);
    }

