    public function quickAdmission($patient_id = "", $ref_ind = "", $doctor_no = "", $doctor_name = "", $admReqId = "", Request $request)
    {
        // $bed_data = DB::table('ipds_bed')->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))->where('ward_no_fk', $request->ward_id)->get();

        $requestDepts = DB::table('sysc_serviceunit')
            ->where('ipd_ind', 1)
            ->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'));

        if (Session::get('user.ses_hospital_code') == "UNICO") {
            $requestDepts = $requestDepts->whereNull('emergency_ind');
        }

        $requestDepts = $requestDepts->get(['serviceunit_name', 'serviceunit_no_pk']);

        // dd($requestDepts);
        // $destinationWards = DB::table('ipds_ward')
        //     ->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))
        //     ->orderBy('ward_no_pk', 'asc')
        //     ->get(["ward_name", "ward_no_pk"])
        //     ->toArray();
        $destinationWards = DB::table('ipds_ward')
            ->join('IPDS_BED', 'ipds_ward.ward_no_pk', '=', 'IPDS_BED.ward_no_fk')
            ->join('sysc_serviceunit', 'sysc_serviceunit.serviceunit_no_pk', '=', 'ipds_ward.service_unit_no_fk')
            ->select('ipds_ward.ward_name', 'ipds_ward.ward_no_pk', 'ipds_ward.service_unit_no_fk', DB::raw('COUNT(IPDS_BED.bed_no_pk) as bed_count'))
            ->where('ipds_ward.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->where('ipd_ind', 1)
            ->where('ipds_bed.status', 1)
            ->where('ipds_bed.bed_status', '!=', null);
            if (Session::get('user.ses_hospital_code') == "UNICO") {
                $destinationWards = $destinationWards->whereNull('ipds_ward.emr_ward_ind');
            }
            $destinationWards = $destinationWards
            ->groupBy('ipds_ward.ward_name', 'ipds_ward.ward_no_pk', 'ipds_ward.service_unit_no_fk')
            ->orderBy('ipds_ward.ward_no_pk', 'asc')
            ->get()
            ->toArray();
        // dd($destinationWards);
        // $data = DB::table('ipds_bed bed')
        // ->leftJoin('sysc_serviceunit unit','bed.')
        // ->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))
        // ->where('STATUS', 1)
        // ->orderBy('bed_sl_no', 'asc')
        // ->get();



        $patient_info = [];
        $patientName = DB::table('pat_registration_wl_vw')->where('patient_no_pk', $patient_id)->value('patient_name');
        $requestNote = DB::table('ipd_admissionrequest_vw')->where('admission_req_no_pk', $admReqId)->value('ipd_referred_advice');

        if (Session::get('user.ses_hospital_code') == "UNICO") {
            return Template::loadview("admin.ipd.ipd_request.quick_admission_v2", [
                'requestDepts' => $requestDepts,
                'destinationWards' => $destinationWards,
                'patient_info' => $patient_info,
                'patient_id' => $patient_id,
                'patientName' => $patientName,
                'ref_ind' => $ref_ind,
                'doctor_no' => $doctor_no,
                'request_doctor_name' => $doctor_name,
                'requestNote' => $requestNote,

            ]);
        } else {
            $patientConditions = $this->getLookupListByCode('PATCON');
            $arrivalModes = $this->getLookupListByCode('ARRIVALMODE');
            $marital_status = $this->getLookupListByCode("MARSTS");
            $chiefcom = $this->getLookupListByCode("CHIEFCOM");
            $inform = $this->getLookupListByCode("INFORM");
            $priority = $this->getLookupListByCode("PRIORITY");
            $gender = $this->getLookupListByCode("GENDER");
            $marsts = $this->getLookupListByCode("MARSTS");
            $bloodg = $this->getLookupListByCode("BLOODG");
            $religion = $this->getLookupListByCode("RELIGION");
            $visit_types = $this->getLookupListByCode("VISITTYPE");
            $name_prefix = $this->getLookupListByCode("NAMEPREFIX");
            $patient_type = DB::table('patn_patienttype')->select('patient_type_no_pk', 'patient_type_code', 'patient_type_desc')->where('status', 1)->where('au_entry_hospital_pk_no', session::get('user.ses_hospital_no_pk'))->get();
            $corporate_info = DB::table('ccm_corporateclient_vw')->select('ccm_client_no_pk', 'ccm_client_code', 'ccm_client_name')->where('active_status', '!=', 0)->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))->get();
            $admission_fee = Item::where('item_type', 'ADM')->first();
            $data = DB::select("SELECT bed.*
            FROM ipds_bed bed, ipds_ward ward, sysc_serviceunit unit
           WHERE     bed.STATUS = 1
                 AND BED.WARD_NO_FK = WARD.WARD_NO_PK
                 AND WARD.SERVICE_UNIT_NO_FK = UNIT.SERVICEUNIT_NO_PK
                 AND UNIT.EMERGENCY_DAYCARE_IND_TXT IS NULL");


            return Template::loadview("admin.ipd.ipd_request.quick_admission", [
                'requestDepts' => $requestDepts,
                'destinationWards' => $destinationWards,
                'patientConditions' => $patientConditions,
                'arrivalModes' => $arrivalModes,
                'marital_status' => $marital_status,
                'chiefcom' => $chiefcom,
                'priority' => $priority,
                'gender' => $gender,
                'marsts' => $marsts,
                'bloodg' => $bloodg,
                'visit_types' => $visit_types,
                'patient_info' => $patient_info,
                'name_prefix' => $name_prefix,
                'data' => $data,
                'patient_type' => $patient_type,
                'corporate_info' => $corporate_info,
                'religion' => $religion,
                'admission_fee' => $admission_fee,
                'inform' => $inform,
                'requestNote' => $requestNote,
            ]);
        }
    }

