        $patient_type = DB::table('patn_patienttype')->select('patient_type_no_pk', 'patient_type_code', 'patient_type_desc')->where('status', 1)->where('au_entry_hospital_pk_no', session::get('user.ses_hospital_no_pk'))->get();
        $corporate_info = DB::table('ccm_corporateclient_vw')->select('ccm_client_no_pk', 'ccm_client_code', 'ccm_client_name')->where('active_status', '!=', 0)->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))->get();

        $admission_fee = Item::where('item_type', 'ADM')->first();
        $bed_dt = DB::select(DB::raw("SELECT bed.*, EMERGENCY_DAYCARE_IND_TXT
        FROM    ipds_bed bed
             JOIN
                SYSC_USER_SU_PRIVS_VW user_priv
             ON bed.SU_NO_FK = user_priv.SU_NO_FK
       WHERE bed.bed_no_pk = $bed_id AND EMERGENCY_DAYCARE_IND_TXT IS NOT NULL "));
        // dd($admission_fee);
        return Template::loadview("admin.ipd.ipd_request.quick_admission_emergency", [
            'requestDepts' => $requestDepts,
            'destinationWards' => $destinationWards,
            'patientConditions' => $patientConditions,
            'arrivalModes' => $arrivalModes,
            'marital_status' => $marital_status,
            'chiefcom' => $chiefcom,
            'priority' => $priority,
            'gender' => $gender,
            'marsts' => $marsts,
            'bloodg' => $bloodg,
            'visit_types' => $visit_types,
            'patient_info' => $patient_info,
            'name_prefix' => $name_prefix,
            'data' => $data,
            'patient_type' => $patient_type,
            'corporate_info' => $corporate_info,
            'religion' => $religion,
            'admission_fee' => $admission_fee,
            'bed_dt' => $bed_dt,
        ]);
    }



    public function storeQuickAdmission(Request $request)
    {
        //        added date 25 may
        $id = $request->admission_no_pk;
        // $query = Bed::where('bed_no_pk', $request->bed_id)->wherein('bed_status', [2, 3])->get();
        // if (!$query->isEmpty()) {
        //     $this->message = ['msg' => 'Please Select Available Bed', 'title' => 'Error'];
        //     return response()->json($this->message);
        // }

        if ($id == '') {
