                    $out_jurnal_code = "";
                    $out_error       = "";

                    // Bind inputs
                    $stmt->bindParam(':in_narration', $narration);
                    $stmt->bindParam(':in_integration_type', $integration_type);
                    $stmt->bindParam(':in_invoice_no_fk', $invoice_no_fk);
                    $stmt->bindParam(':in_admission_no_fk', $admission_no);
                    $stmt->bindParam(':in_au_entry_by', $au_entry_by);
                    $stmt->bindParam(':in_au_entry_session', $au_entry_session);
                    $stmt->bindParam(':in_au_entry_hospital_pk_no', $hospital_pk_no);

                    // Bind outputs
                    $stmt->bindParam(':out_jurnal_code', $out_jurnal_code, PDO::PARAM_STR|PDO::PARAM_INPUT_OUTPUT, 500);
                    $stmt->bindParam(':out_error', $out_error, PDO::PARAM_STR|PDO::PARAM_INPUT_OUTPUT, 500);

                    // Execute
                    $stmt->execute();


                    if ($out_error !== null && $out_error !== '' && $out_error != '000' && $out_error != '0') {
                        DB::rollBack();
                        throw new \Exception("Journal deposit failed for invoice {$invoice_no_fk}: " . $out_error);
                    }
                }

                DB::commit();
                }
