    public function storeEmergencyAdmission(Request $request)
    {
        $id = $request->admission_no_pk;


        if ($id == '') {
            DB::beginTransaction();
            $ipdAdmissionDetailsData = DB::table('ipd_admission')->select('patient_no_fk', )->where('patient_no_fk', $request->hdn_patient_id)->where('dis_ind', '!=', 1)->orderBy('admission_no_pk', "desc")->first();
            // dd($ipdAdmissionDetailsData );
            if (!empty($ipdAdmissionDetailsData)) {
                DB::rollback();
                $this->message = ['msg' => 'This Patient Already Admited.', 'title' => 'Error'];
                return response()->json($this->message);
            }
            $pat_type = $request->patient_type;


            date_default_timezone_set('Asia/Dhaka');
            $times = Carbon::now(); //
            $time = date('Y-m-d H:i:s', strtotime($times));

            $su_no = $request->request_department ? $request->request_department : $request->su_id;
            $emr_su_ind = DB::table('sysc_serviceunit')->where('serviceunit_no_pk', $su_no)->value('emr_su_ind');

            $sequence = DB::getSequence();
            $sysc_doctor_no_pk_seq = $sequence->nextValue('ipd_admission_no_pk_seq');

            if ($pat_type == '2') {
                $pat_registration = $this->patient->storeQuickRegisterV1($request);
                $patient_id_value = DB::table("patn_registration")->orderBy('patient_no_pk', "desc")->first();
                $patient_id = $patient_id_value->patient_no_pk ? $patient_id_value->patient_no_pk : "";
            } else {
                $patient_id = $request->hdn_patient_id;
            }
            // dd($pat_type, $patient_id);
            $ward_id = $request->destination_ward ? $request->destination_ward : $request->ward_id;

            $ref_from_emr_ind = ($emr_su_ind == 1) ? 2 : 1;
            $ipdAdmission = [
                'admission_no_pk' => $sysc_doctor_no_pk_seq,
                'admission_uid' => $sysc_doctor_no_pk_seq,
                'su_no_fk' => $su_no,
                'initial_bed_no_fk' => $request->bed_id,
                'curr_bed_no_fk' => $request->bed_id,
                'curr_ward_no_fk' => $ward_id,
                'primary_doctor_no_fk' => $request->doctor_id,
                'first_ref_doc_person_no_fk' => $request->first_ref != null ? $request->first_ref : "",
                'second_ref_doc_person_no_fk' => $request->second_ref != null ? $request->second_ref : "",
                'ref_doc_person_no_fk' => $request->ref_doc != null ? $request->ref_doc : "",
                'admission_date' => $time,
                'opd_department_name' => $request->request_department,
                'covid_vaccinated_ind' => $request->covid_vaccinated,
                'pkg_patient_ind' => $request->pkg_patient_ind,
