                        'father_name' => $request->father_name,
                        'mother_name' => $request->mother_name,
                        'address' => $request->address,
                        'accompanied_by' => $request->accompanied_by,
                        'contact_relaion' => $request->relation,
                        'contact_person_mobile' => $request->contact_number,
                        'ns_receive_time' => date('Y-m-d'),
                        'ns_receive_by' => Auth::id(),
                        'ns_receive_ind' =>1,
                        'au_update_by' => Auth::id(),
                        'au_entry_session' => 1,
                        'au_entry_hospital_no_fk' => Session::get('user.ses_hospital_no_pk')
                    ];

                    IpdAdmissionDetails::where('admission_no_pk', $admission_id)->update($IpdAdmissionDetails);
                    // });
                    DB::commit();
                    $this->message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
                } else {

                    DB::rollback();
                    $this->message = ['msg' => 'Bed Transfer Process Failed' . $outError, 'title' => 'Error'];
                }





            } catch (\Exception $e) {
                DB::rollback();

                $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
            }
            return response()->json($this->message);
        }
    }

    public function searchPatientListNew(Request $request)
    {
        $patient_type = $request->patient_type;
        $patient_code = $request->hdn_patient_id;
        $card_num_cond = $patient_code ? $patient_code : "";
        $admission_uid = $request->admission_id;
        $admission_date_from = date("Y-m-d", strtotime($request->admission_date_from));
        $admission_date_from_cond = $admission_date_from ? $admission_date_from : "";
        $admission_date_to = date("Y-m-d", strtotime($request->admission_date_to));
        $admission_date_to_cond = $admission_date_to ? $admission_date_to : "";


            $query = DB::table('ipd_admitted_patlist_vw')
                        ->when(!empty($admission_date_from) && !empty($admission_date_to), function ($q) use ($admission_date_from, $admission_date_to) {
                            return $q->whereBetween('admission_date', [$admission_date_from, $admission_date_to]);
                        })
                        ->when(!empty($card_num_cond), function ($q) use ($card_num_cond) {
