                        })
                        ->when(!empty($patient_type), function ($q) use ($patient_type) {
                            return $q->where('su_no_fk', $patient_type);
                        })->orderBy('admission_uid', 'desc')
                    ->get();

        return Template::loadview("admin.ipd.ipd_request.ipd_new_patient_list_data", [
