    public function getBedByWard(Request $request)
    {

        if (Session::get('user.ses_hospital_code') == "UNICO") {

            $data = DB::table('ipds_bed')->leftJoin('ipd_admitted_patlist_vw', function ($join) {
                $join->on('ipds_bed.bed_no_pk', '=', 'ipd_admitted_patlist_vw.new_bed_no_fk')
                    ->where('ipd_admitted_patlist_vw.dis_ind', '=', 0);
            })
                ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipds_bed.ward_no_fk')
                ->select('ipds_bed.*', 'ipd_admitted_patlist_vw.admission_no_pk', 'ipd_admitted_patlist_vw.patient_name', 'ipd_admitted_patlist_vw.patient_code', 'ipd_admitted_patlist_vw.primary_doctor_name', 'ipd_admitted_patlist_vw.admission_date', 'ipd_admitted_patlist_vw.new_bed_name', 'ipd_admitted_patlist_vw.new_ward_name', 'ipds_ward.ward_name', 'ipd_admitted_patlist_vw.dis_req_ind', 'ipd_admitted_patlist_vw.dis_ind', 'ipd_admitted_patlist_vw.ns_receive_ind')
                ->where('ipds_bed.status', 1)
                ->where('ipds_bed.bed_status', '!=', null)
                ->where('ipds_bed.ward_no_fk', $request->bed_value)
                // ->where('ipds_ward.service_unit_no_fk', $request->dept_id)
                ->orderBy('ipds_bed.bed_sl_no', 'asc')
                ->get();

            return Template::loadview("admin.ipd.ipd_request.ipd_bed_viewer_data_v2", ['data' => $data]);
        } else {
            $data = DB::table('ipds_bed')
                ->where('ward_no_fk', $request->bed_value)
                ->where('bed_status', '!=', null)
                ->leftJoin('ipds_ward', 'ward_no_fk', 'ward_no_pk')
                ->orderBy('bed_sl_no', 'asc')->get();
            return Template::loadview("admin.ipd.ipd_request.ipd_bed_viewer_data", ['data' => $data]);
        }
