    public function getBedByWardCount(Request $request)
    {
        $data = DB::table('ipds_bed')
            ->select('bed_no_pk')
            ->where('ward_no_fk', $request->bed_value)
            ->where('bed_status', '!=', null)
            ->where('ipds_bed.status', 1)
            ->leftJoin('ipds_ward', 'ward_no_fk', 'ward_no_pk')
            ->get();

        $available = DB::table('ipds_bed')
            ->select('bed_no_pk')
            ->where('ward_no_fk', $request->bed_value)
            ->leftJoin('ipds_ward', 'ward_no_fk', 'ward_no_pk')
            ->where('bed_status', 1)
            ->where('ipds_bed.status', 1)
            ->get();

        $occupied = DB::table('ipds_bed')
            ->select('bed_no_pk')
            ->where('ward_no_fk', $request->bed_value)
            ->leftJoin('ipds_ward', 'ward_no_fk', 'ward_no_pk')
            ->where('bed_status', 2)
            ->where('ipds_bed.status', 1)
            ->get();
        $not_ready = DB::table('ipds_bed')
            ->select('bed_no_pk')
            ->where('ward_no_fk', $request->bed_value)
            ->leftJoin('ipds_ward', 'ward_no_fk', 'ward_no_pk')
            ->where('bed_status', 3)
            ->where('ipds_bed.status', 1)
            ->get();

        $data_count_total = count($data);
        $data_count_available = count($available);
        $data_count_occupied = count($occupied);
        $not_ready = count($not_ready);
        // dd($data_count_total,$data_count_available,$data_count_occupied);
        return response()->json([$data_count_total, $data_count_available, $data_count_occupied, $not_ready]);

        // return Template::loadview("admin.ipd.ipd_request.ipd_bed_viewer", ['data_count' => $data_count]);
    }

