    public function ipdgetbedinfo(request $request)
    {
        $bed_id = $request->bed_id;
        $bed_status = $request->bed_status;
        if ($bed_status == 1) {
            $bed_details = db::table('ipds_bed a')->select("a.*", "b.WARD_NAME", "c.SERVICEUNIT_NAME")->leftjoin("IPDS_WARD b", "b.WARD_NO_PK", "=", "a.WARD_NO_FK")->leftjoin("SYSC_SERVICEUNIT c", "c.SERVICEUNIT_NO_PK", "=", "a.SU_NO_FK")->where('bed_no_pk', $bed_id)->where('bed_status', $bed_status)->get();
            if (Session::get('user.ses_hospital_code') == "UNICO") {
                return template::loadview("admin.ipd.ipd_request.bed_data_view_v2", ['bed_details' => $bed_details]);
            } else {
                return template::loadview("admin.ipd.ipd_request.bed_data_view", ['bed_details' => $bed_details]);
            }
        } elseif ($bed_status == 2) {
            $bed_details = db::table('ipds_bed')->where('bed_no_pk', $bed_id)->where('bed_status', $bed_status)->get();
            $patient_info = db::table('ipd_admitted_patlist_vw')->where('initial_bed_no_fk', $bed_id)->where('bed_status', $bed_status)->first();
            if (Session::get('user.ses_hospital_code') == "UNICO") {
                return template::loadview("admin.ipd.ipd_request.bed_data_view_v2", ['patient_info' => $patient_info, 'bed_details' => $bed_details]);
            } else {
                return template::loadview("admin.ipd.ipd_request.bed_data_view", ['patient_info' => $patient_info, 'bed_details' => $bed_details]);
            }
        } elseif ($bed_status == 3) {
            $bed_details = db::table('ipds_bed')->where('bed_no_pk', $bed_id)->where('bed_status', $bed_status)->get();
            if (Session::get('user.ses_hospital_code') == "UNICO") {
                return template::loadview("admin.ipd.ipd_request.bed_data_view_v2", ['bed_details' => $bed_details]);
            } else {
                return template::loadview("admin.ipd.ipd_request.bed_data_view", ['bed_details' => $bed_details]);
            }
        }
    }

    public function getDeptByWard(Request $request)
    {
        $destinationWards = DB::select("   SELECT ward_no_pk,
        IPDS_BED.ward_no_fk,
        ward_name,
        COUNT (bed_no_pk) bed_count
        FROM sysc_serviceunit
                LEFT JOIN ipds_ward
                ON sysc_serviceunit.serviceunit_no_pk =
                        ipds_ward.service_unit_no_fk
               LEFT JOIN ipds_bed
                ON IPDS_WARD.WARD_NO_PK = IPDS_BED.WARD_NO_FK
        WHERE ipds_ward.status = 1 AND ipds_ward.service_unit_no_fk = $request->ward_data
        --and ipds_bed.bed_status is not null
        GROUP BY ward_no_pk, IPDS_BED.ward_no_fk, ward_name");
        //    dd($request->ward_data, $destinationWards);

        return Template::loadview("admin.ipd.ipd_request.ipd_ward", ['destinationWards' => $destinationWards]);
    }

