    public function ipdAdmissionPdf($admission_id)
    {
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $admission_pat = DB::table('IPD_ADMITTED_PATLIST_VW')->where('admission_no_pk', $admission_id)->first();
        $ipd_patient_tab_rec = DB::table('ipd_admission_details')->where('admission_no_pk', $admission_id)->first();
        // $bed_transfer_info = DB::table('ipd_admission_bed')->where('admission_no_fk', $admission_id)->first();
        $bed_history = DB::table('ipd_admission_bed')
            ->leftJoin('ipds_bed', 'ipds_bed.bed_no_pk', '=', 'ipd_admission_bed.bed_no_fk')
            ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipd_admission_bed.ward_no_fk')
            ->leftjoin('sysc_serviceunit', 'sysc_serviceunit.serviceunit_no_pk', '=', 'ipds_ward.service_unit_no_fk')
            ->select(
                'ipd_admission_bed.ipd_adm_bed_no_pk',
                'ipd_admission_bed.ipd_adm_bed_date',
                'ipd_admission_bed.admission_no_fk',
                'ipd_admission_bed.sl_no',
                'ipd_admission_bed.start_time',
                'ipd_admission_bed.end_time',
                'ipd_admission_bed.bed_no_fk',
                'ipd_admission_bed.ward_no_fk',
                'ipd_admission_bed.su_no_fk',
                'ipd_admission_bed.bed_assignment_type',
                'ipds_bed.bed_no_pk',
                'ipds_bed.bed_name',
                'ipds_ward.ward_name',
                'ipd_admission_bed.status',
                'sysc_serviceunit.serviceunit_name'
            )->where('ipd_admission_bed.admission_no_fk', $admission_id)
            ->orderByDesc('ipd_admission_bed.end_time')
            ->get();



        $latest_bed_info = DB::table('ipd_admission_bed')
            ->leftJoin('ipds_bed', 'ipds_bed.bed_no_pk', '=', 'ipd_admission_bed.bed_no_fk')
            ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipd_admission_bed.ward_no_fk')
            ->leftJoin('sysc_serviceunit', 'ipd_admission_bed.su_no_fk', '=', 'sysc_serviceunit.serviceunit_no_pk')
            ->select('ipds_ward.ward_name', 'ipds_bed.bed_name', 'sysc_serviceunit.serviceunit_name')
            ->where('ipd_admission_bed.admission_no_fk', $admission_id)
            ->orderByDesc('ipd_admission_bed.start_time')
            ->first();

        $ward_name = $latest_bed_info->ward_name ?? null;
        $bed_name = $latest_bed_info->bed_name ?? null;
        $serviceunit_name = $latest_bed_info->serviceunit_name ?? null;
        // dd($ward_name,$bed_name,$serviceunit_name);

        $title = $admission_pat->admission_uid;
        $barcode = new BarcodeGenerator();
        $barcode->setText($title);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $barcode_admission_no = $barcode->generate();
        $title = $admission_pat->patient_code;
        $pat_barcode = new BarcodeGenerator();
        $pat_barcode->setText($title);
        $pat_barcode->setType(BarcodeGenerator::Code128);
        $pat_barcode->setLabel('');
        $pat_barcode->setScale(1);
        $pat_barcode->setThickness(25);
        $pat_barcode->setFontSize(10);
        $barcode_pat_no = $pat_barcode->generate();
        $prepared_by_info = DB::table('wsec_user')->where('user_no_pk', $admission_pat->au_entry_by)->first();
        if ($po_hospital_details->hospital_code != 'KBMH') {

            if ($po_hospital_details->hospital_code == 'IMPERIAL') {
                return view("admin.ipd.ipd_request.ipd_admission_form_imperial", ['admission_pat' => $admission_pat, 'barcode_admission_no' => $barcode_admission_no, 'po_hospital_details' => $po_hospital_details, 'barcode_pat_no' => $barcode_pat_no, 'prepared_by_info' => $prepared_by_info]);
            } else {


                $pdf = PDF::loadView("admin.ipd.ipd_request.ipd_admission_print", ['admission_pat' => $admission_pat, 'ipd_patient_tab_rec' => $ipd_patient_tab_rec, 'barcode_admission_no' => $barcode_admission_no, 'po_hospital_details' => $po_hospital_details, 'barcode_pat_no' => $barcode_pat_no, 'prepared_by_info' => $prepared_by_info, 'bed_history' => $bed_history, 'serviceunit_name' => $serviceunit_name]);
                return $pdf->stream('Ipd Addmission Print.pdf');
            }
        } else {
            return view("admin.ipd.ipd_request.ipd_admission_form_kbmh", ['admission_pat' => $admission_pat, 'barcode_admission_no' => $barcode_admission_no, 'po_hospital_details' => $po_hospital_details, 'barcode_pat_no' => $barcode_pat_no, 'prepared_by_info' => $prepared_by_info, 'ward_name' => $ward_name, 'bed_name' => $bed_name, 'serviceunit_name' => $serviceunit_name]);
        }
    }
