    public function ipdBusinessOffice($type='')
    {
        ini_set('memory_limit', '-1');
        ini_set('max_execution_time', '3000');
        ini_set('request_terminate_timeout', '3000');

        $to_date = date("Y-m-d");
        if (Session::get('user.ses_hospital_code') == "IMPERIAL") {
            $oneMonthAgo = $to_date;
        } else {
            $oneMonthAgo = date('Y-m-d', strtotime('-30 days', strtotime($to_date)));
        }
        if ($type === 'EMERGENCY') {
            $today_discharge_patient = DB::table('IPD_ADMISSION as ipd')
                ->leftJoin('ipd_admitted_patlist_vw as vw', 'vw.admission_no_pk', '=', 'ipd.admission_no_pk')
                ->select(DB::raw('count(ipd.dis_ind) as count_discharge_patient'))
                ->where('vw.emergency_ind', 1)
                ->whereDate('ipd.DIS_DATE', date('Y-m-d'))
                ->first();

            $oneMonthAdmitedPatient = DB::table('IPD_ADMISSION as ipd')
                ->leftJoin('ipd_admitted_patlist_vw as vw', 'vw.admission_no_pk', '=', 'ipd.admission_no_pk')
                ->select(DB::raw('count(ipd.admission_no_pk) as thirty_days_stay'))
                ->where('ipd.dis_ind', '!=', 1)
                ->where('ipd.death_ind', '!=', 1)
                ->where('vw.emergency_ind', 1)
                ->whereRaw('TRUNC(ipd.admission_date) BETWEEN TO_DATE(?, \'YYYY-MM-DD\') AND TO_DATE(?, \'YYYY-MM-DD\')', [$oneMonthAgo, date('Y-m-d')])
                ->first();
        } else {
            $today_discharge_patient = DB::table('IPD_ADMISSION as ipd')
                ->leftJoin('ipd_admitted_patlist_vw as vw', 'vw.admission_no_pk', '=', 'ipd.admission_no_pk')
                ->select(DB::raw('count(ipd.dis_ind) as count_discharge_patient'))
                ->whereNull('vw.emergency_ind')
                ->whereDate('ipd.DIS_DATE', date('Y-m-d'))
                ->first();

            $oneMonthAdmitedPatient = DB::table('IPD_ADMISSION as ipd')
                ->leftJoin('ipd_admitted_patlist_vw as vw', 'vw.admission_no_pk', '=', 'ipd.admission_no_pk')
                ->select(DB::raw('count(ipd.admission_no_pk) as thirty_days_stay'))
                ->where('ipd.dis_ind', '!=', 1)
                ->where('ipd.death_ind', '!=', 1)
                ->whereNull('vw.emergency_ind')
                ->whereRaw('TRUNC(ipd.admission_date) BETWEEN TO_DATE(?, \'YYYY-MM-DD\') AND TO_DATE(?, \'YYYY-MM-DD\')', [$oneMonthAgo, date('Y-m-d')])
                ->first();
                // dd( $oneMonthAdmitedPatient);
        }

        // dd($oneMonthAdmitedPatient);

        $consultant = []; // DB::table("doctor_info_vw")->select('person_no_pk', 'full_name')->where("doctor_ind", 1)->where('status', 1)->get()->toArray();
        $serviceunit = []; // DB::table("sysc_serviceunit")->select('serviceunit_no_pk', 'serviceunit_name')->where("ipd_ind", 1)->where('status', 1)->get()->toArray();
        $bed_info = []; // DB::table("ipds_bed")->select("bed_no_pk", "bed_name")->where('status', 1)->get()->toArray();
        $ward_info = []; // DB::table("ipds_ward")->select("ward_no_pk", "ward_name")->where('status', 1)->get()->toArray();


        $hospital_no = Session('user.ses_hospital_no_pk');

        if ($type==='EMERGENCY') {
                $admission_info = DB::select("select reg.patient_code as patient_code, reg.patient_no_pk as patient_no_fk,ip.admission_no_pk,trunc(ip.admission_date) admission_date,ip.primary_doctor_no_fk,fnc_docname(ip.primary_doctor_no_fk)PRIMARY_DOCTOR_NAME,
            ip.curr_bed_no_fk,(select bed_name from ipds_bed where bed_no_pk =ip.curr_bed_no_fk) NEW_BED_NAME,null BED_NAME,ip.curr_ward_no_fk,
            (select WARD_NAME from ipds_ward where WARD_NO_PK=ip.curr_ward_no_fk) NEW_WARD_NAME,null WARD_NAME,
                    ip.su_no_fk,fnc_serviceunitname(ip.su_no_fk) department_name,reg.patient_name,reg.gender_txt ,  nvl(dtl.HOUSEKEEPING_BILL_IND,0) HOUSEKEEPING_BILL_IND ,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND, ip.DIS_REQ_IND, ip.DIS_IND,
                    reg.dob,pat_age(reg.dob,nvl(dod,trunc(ip.admission_date))) age,ip.DIS_DATE,null LAST_PAYMENT_DATE,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount)-sum(mst.ledger_amt_payment) ADVANCE_DUE,sum(mst.ledger_amt_payment) PAID_AMOUNT,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount) LEDGER_AMT_PAYABLE,
                    (select lookupdata_code from sysc_lookupdata where lookupdata_no_pk=reg.blood_group) BLOOD_GROUP_TEXT,reg.mobile1 ,reg.PRESENT_ADDR,
                    CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE)) TOTAL_DAYS,sum(mst.ledger_amt_sales) LEDGER_AMT_SALES,sum(mst.ledger_amt_discount) LEDGER_AMT_DISCOUNT,sum(mst.ledger_amt_payment) LEDGER_AMT_PAYMENT
            ,admvw.remarks as remarks,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks from ipd_admission ip join IPD_ADMISSION_DETAILS dtl
            on ip.admission_no_pk=dtl.admission_no_pk
            left join finc_ledgermst mst
            on ip.admission_no_pk=mst.admission_no_fk
            join patn_registration reg
            on ip.patient_no_fk=reg.patient_no_pk

            left join ipd_admitted_patlist_vw admvw
            on admvw.admission_no_pk=ip.admission_no_pk
             left join sysc_serviceunit su
            on su.serviceunit_no_pk=admvw.new_su_no_fk

            where su.emergency_ind =1
            and nvl(ip.DIS_IND,0)=0

            and ip.au_entry_hospital_no_fk= $hospital_no
            group by reg.patient_code, ip.admission_no_pk,trunc(ip.admission_date),ip.primary_doctor_no_fk,ip.curr_bed_no_fk,ip.curr_ward_no_fk,reg.PRESENT_ADDR, ip.DIS_REQ_IND,ip.DIS_DATE, ip.DIS_IND,dtl.HOUSEKEEPING_BILL_IND,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND,
            ip.su_no_fk,reg.patient_name,reg.patient_no_pk,reg.gender_txt,reg.dob,reg.blood_group,reg.mobile1,reg.dod,NVL (ip.DIS_DATETIME, SYSDATE),ip.ADMISSION_DATE,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks,admvw.remarks
            order by trunc(ip.admission_date) desc,ip.admission_no_pk desc");
        }else{
                 $admission_info = DB::select("select reg.patient_code as patient_code, reg.patient_no_pk as patient_no_fk,ip.admission_no_pk,trunc(ip.admission_date) admission_date,ip.primary_doctor_no_fk,fnc_docname(ip.primary_doctor_no_fk)PRIMARY_DOCTOR_NAME,
            ip.curr_bed_no_fk,(select bed_name from ipds_bed where bed_no_pk =ip.curr_bed_no_fk) NEW_BED_NAME,null BED_NAME,ip.curr_ward_no_fk,
            (select WARD_NAME from ipds_ward where WARD_NO_PK=ip.curr_ward_no_fk) NEW_WARD_NAME,null WARD_NAME,
                    ip.su_no_fk,fnc_serviceunitname(ip.su_no_fk) department_name,reg.patient_name,reg.gender_txt ,  nvl(dtl.HOUSEKEEPING_BILL_IND,0) HOUSEKEEPING_BILL_IND ,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND, ip.DIS_REQ_IND, ip.DIS_IND,
                    reg.dob,pat_age(reg.dob,nvl(dod,trunc(ip.admission_date))) age,ip.DIS_DATE,null LAST_PAYMENT_DATE,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount)-sum(mst.ledger_amt_payment) ADVANCE_DUE,sum(mst.ledger_amt_payment) PAID_AMOUNT,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount) LEDGER_AMT_PAYABLE,
                    (select lookupdata_code from sysc_lookupdata where lookupdata_no_pk=reg.blood_group) BLOOD_GROUP_TEXT,reg.mobile1 ,reg.PRESENT_ADDR,
                    CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE)) TOTAL_DAYS,sum(mst.ledger_amt_sales) LEDGER_AMT_SALES,sum(mst.ledger_amt_discount) LEDGER_AMT_DISCOUNT,sum(mst.ledger_amt_payment) LEDGER_AMT_PAYMENT
            ,admvw.remarks as remarks,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks from ipd_admission ip join IPD_ADMISSION_DETAILS dtl
            on ip.admission_no_pk=dtl.admission_no_pk
            left join finc_ledgermst mst
            on ip.admission_no_pk=mst.admission_no_fk
            join patn_registration reg
            on ip.patient_no_fk=reg.patient_no_pk

            left join ipd_admitted_patlist_vw admvw
            on admvw.admission_no_pk=ip.admission_no_pk
             left join sysc_serviceunit su
            on su.serviceunit_no_pk=admvw.new_su_no_fk

            where su.emergency_ind is null
            and nvl(ip.DIS_IND,0)=0

            and ip.au_entry_hospital_no_fk= $hospital_no
            group by reg.patient_code, ip.admission_no_pk,trunc(ip.admission_date),ip.primary_doctor_no_fk,ip.curr_bed_no_fk,ip.curr_ward_no_fk,reg.PRESENT_ADDR, ip.DIS_REQ_IND,ip.DIS_DATE, ip.DIS_IND,dtl.HOUSEKEEPING_BILL_IND,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND,
            ip.su_no_fk,reg.patient_name,reg.patient_no_pk,reg.gender_txt,reg.dob,reg.blood_group,reg.mobile1,reg.dod,NVL (ip.DIS_DATETIME, SYSDATE),ip.ADMISSION_DATE,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks,admvw.remarks
            order by trunc(ip.admission_date) desc,ip.admission_no_pk desc");
        }

        

        return Template::loadview("admin.ipd.ipd_business_office.ipd_business_office", ["serviceunit" => $serviceunit, "consultant" => $consultant, "bed_info" => $bed_info, "ward_info" => $ward_info, "admission_info" => $admission_info, 'today_discharge_patient' => $today_discharge_patient, 'oneMonthAdmitedPatient' => $oneMonthAdmitedPatient,'type'=>$type]);
    }

    public function ipdDipositAmt($admission_no){
        $dipositAmDtl=DB::table('finc_ipddepositmst')->select('finc_ipddepositmst.*','wsec_user.user_fullname')->leftJoin('wsec_user','wsec_user.user_no_pk','=','finc_ipddepositmst.au_entry_by')->where('admission_no_fk',$admission_no)->get();
        $sumDipositAmt=$dipositAmDtl->sum('pay_amount') ?? 0;

        return [
                'deposit_details' => $dipositAmDtl,
                'sum_deposit_amount' => $sumDipositAmt
            ];
    }
    public function ipdPhrClearance()
    {
        $ses_hospital_id = DB::table('sysc_serviceunit')->select('clearance_ind')->where('serviceunit_no_pk', Session::get('user.su_pk_no'))->first();
        // dd($ses_hospital_id);
        $consultant = DB::table("doctor_info_vw")->where("doctor_ind", 1)->get();
        $serviceunit = DB::table("sysc_serviceunit")->where("ipd_ind", 1)->get();
        $bed_info = DB::table("ipds_bed")->select("bed_no_pk", "bed_name")->get();
        $ward_info = DB::table("ipds_ward")->select("ward_no_pk", "ward_name")->get();
        $admission_info = [];
        if ($ses_hospital_id->clearance_ind == 1) {
            $admission_info = DB::table("ipd_admitted_patlist_vw")
                ->leftJoin("finc_admission_sum_vw", "ipd_admitted_patlist_vw.admission_no_pk", "finc_admission_sum_vw.admission_no_pk")
                ->select("ipd_admitted_patlist_vw.*", "finc_admission_sum_vw.ledger_amt_payment", "finc_admission_sum_vw.advance_due", "finc_admission_sum_vw.paid_amount", 'finc_admission_sum_vw.ledger_amt_payable', "finc_admission_sum_vw.ledger_amt_discount", "finc_admission_sum_vw.ledger_amt_sales", "finc_admission_sum_vw.last_payment_date")
                // ->where("ipd_admitted_patlist_vw.admission_date", date("Y-m-d"))
                ->where("ipd_admitted_patlist_vw.dis_ind", "=", 0)
                ->where('ipd_admitted_patlist_vw.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
                ->orderBy("ipd_admitted_patlist_vw.admission_no_pk", "DESC")
                ->paginate(10);
        }

        // $pay_last_date=DB::table("finc_ledgermst")->select(DB::raw(" trunc(ledger_date) as ledger_date"))->where("ledger_amt_payment",">",0)->orderby("ledger_no_pk","desc")->first();

        // dd($admission_info);
        return Template::loadview("admin.ipd.ipd_business_office.ipd_phr_clearance", ["serviceunit" => $serviceunit, "consultant" => $consultant, "bed_info" => $bed_info, "ward_info" => $ward_info, "admission_info" => $admission_info]);
    }


    public function ipdPayment($admission_id)
    {
        $hospital_id = Session::get('user.ses_hospital_no_pk');
        $invoice_number = DB::select("select invoice_no_pk from finc_invoicemst_sum_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id");

        $patientInfo = DB::select("select * from ipd_admitted_patlist_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id ");
        // dd($patientInfo);
        $patientId = $patientInfo[0]->{'patient_no_fk'};
        $invoice_id = [];
        $price_0 = [];
        $item_type = [];
        if (!empty($invoice_number)) {
            foreach ($invoice_number as $value) {
                $invoice_id[] = $value->invoice_no_pk;
                $price_0[] = 0;
                $cancel[] = 1;
                $item_type[] = "MED";
            }
        }

        $item_details = DB::table("finc_invoicedtl_vw")->where('au_entry_hospital_pk_no', $hospital_id)->whereNotIn('module_code', ['PHR', 'PHR-I', 'PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU', 'PHR-NICU', 'PHR-PICU'])->whereIn("invoice_no_fk", $invoice_id)->whereNotIn("item_rate", $price_0)->get();

        // dd($item_details); ->whereNotIn("cancel_ind", $cancel) ->whereNotIn("item_type", $item_type)

        // $paymentHistories = DB::table("FINC_LEDGERMST_PAYDISC_VW")->where("admission_no_pk", $admission_id)->where('ledger_amt_payment','!=',0)->get();

        $paymodes = $this->getLookupListByCodeCustomKey("lookupdata_code", "PAYMODE");
        $pay_types = $this->getLookupListByCode("PAYTYPE");

        $paymentHistories = DB::SELECT("select mst.ledger_amt_payment,
			mst.disc_amt_by_doc,mst.disc_amt_by_hosp,
			mst. au_entry_at as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
			from finc_ledgermst mst left join SYSC_MODULE mod on mod.module_no_pk = mst.module_no_fk join wsec_user uname
			on mst.au_entry_by=uname.user_no_pk
			where mst.admission_no_fk=$admission_id and
			mst.ledger_amt_payment <> 0 and mod.MODULE_CODE not in  ('PHR' ,'PHR-I','PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU','PHR-NICU','PHR-PICU') and nvl(mst.payment_subtype,'#') != 'Pharmacy'  and mst.ledger_amt_payment is not null");

        $discountHistoris = DB::SELECT("select mst.LEDGER_AMT_PAYMENT,
			mst.DISC_AMT_BY_DOC,mst.DISC_AMT_BY_HOSP,
			mst.au_entry_at as invoice_date,UNAME.USER_NAME LEDGER_ENTRY_TXT ,mst.ledger_amt_discount
			from finc_ledgermst mst join wsec_user uname
			on mst.AU_ENTRY_BY=UNAME.USER_NO_PK
            join SYSC_MODULE mod on mod.module_no_pk = mst.module_no_fk
			where mst.ADMISSION_NO_FK=$admission_id and
			mod.module_code not in  ('PHR','PHR-I','PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU','PHR-NICU','PHR-PICU') ");
        // AND (mst.disc_amt_by_doc > 0 OR mst.disc_amt_by_hosp > 0)
        // dd($discountHistoris);
        $totalDiscount = $this->getTotalDiscount($discountHistoris);
        $bank_name = $this->getLookupListByCode("AGENTBANKING");
        $ipd_sub_type = $this->getLookupListByCode("IPDPAYSUBTYPE");
        // dd($ipd_sub_type);
        $type = 'Total IPD';
        return Template::loadview("admin.ipd.ipd_payment", ["patientInfo" => $patientInfo, "ipd_sub_type" => $ipd_sub_type, "item_details" => $item_details, 'paymodes' => $paymodes, 'pay_types' => $pay_types, 'admission_id' => $admission_id, 'patientId' => $patientId, 'paymentHistories' => $paymentHistories, 'totalDiscount' => $totalDiscount, 'bank_name' => $bank_name, 'type' => $type]);
    }



        // Deposit amount payment

    public function paymentDeposit()
    {
        $admission_id = null;
        $hospital_id = Session::get('user.ses_hospital_no_pk');
        $card_type=$this->getLookupListByCode("CARDTYPE");
        // If admission_id is null or empty, return an empty view or default values
        if (empty($admission_id)) {
            return Template::loadview("admin.ipd.payment_deposit", [
                "patientInfo" => [],
                "ipd_sub_type" => [],
                "item_details" => [],
                'paymodes' => $this->getLookupListByCodeCustomKey("lookupdata_code", "PAYMODE"),
                'pay_types' => $this->getLookupListByCode("DPAYTYPE"),
                // 'pay_types' => $this->getLookupListByCode("PAYTYPE"),
                'admission_id' => null,
                'patientId' => null,
                'paymentHistories' => [],
                'totalDiscount' => 0,
                'bank_name' => $this->getLookupListByCode("AGENTBANKING"),
                'type' => 'Total IPD',
                'bill' => [],
                'patient_type' => [],
                'corporate_info' => [],
                'card_type' => $card_type
            ]);
        }

        // Fetch invoice numbers
        $invoice_number = DB::select("SELECT invoice_no_pk
                                    FROM finc_invoicemst_sum_vw
                                    WHERE admission_no_pk = ?
                                    AND au_entry_hospital_pk_no = ?", [$admission_id, $hospital_id]);

        // Fetch patient info
        $patientInfo = DB::select("SELECT *
                                FROM ipd_admitted_patlist_vw
                                WHERE admission_no_pk = ?
                                AND au_entry_hospital_pk_no = ?", [$admission_id, $hospital_id]);

        if (empty($patientInfo)) {
            $patientId = null;
        } else {
            $patientId = $patientInfo[0]->{'patient_no_fk'};
        }

        $invoice_id = [];
        $price_0 = [];
        $item_type = [];
        $cancel = [];

        if (!empty($invoice_number)) {
            foreach ($invoice_number as $value) {
                $invoice_id[] = $value->invoice_no_pk;
                $price_0[] = 0;
                $cancel[] = 1;
                $item_type[] = "MED";
            }
        }

        // Fetch item details
        $item_details = DB::table("finc_invoicedtl_vw")
            ->where('au_entry_hospital_pk_no', $hospital_id)
            ->whereIn("invoice_no_fk", $invoice_id)
            ->whereNotIn("item_rate", $price_0)
            ->get();

        // Payment modes, types
        $paymodes = $this->getLookupListByCodeCustomKey("lookupdata_code", "PAYMODE");
        // $pay_types = $this->getLookupListByCode("PAYTYPE");
        $pay_types = $this->getLookupListByCode("DPAYTYPE");
        // dd($pay_types);

        // Payment histories
        $paymentHistories = DB::SELECT("SELECT mst.ledger_amt_payment,
                                                mst.disc_amt_by_doc,
                                                mst.disc_amt_by_hosp,
                                                mst.au_entry_at AS invoice_date,
                                                uname.user_name AS ledger_entry_txt,
                                                mst.pay_type
                                        FROM finc_ledgermst mst
                                        LEFT JOIN SYSC_MODULE mod ON mod.module_no_pk = mst.module_no_fk
                                        JOIN wsec_user uname ON mst.au_entry_by = uname.user_no_pk
                                        WHERE mst.admission_no_fk = ?
                                        AND mst.ledger_amt_payment <> 0
                                        AND mst.ledger_amt_payment IS NOT NULL", [$admission_id]);

        // Total discount
        $totalDiscount = DB::table('finc_ipdpatientbill_vw')
            ->select(DB::raw('SUM(dis) as discount'))
            ->where('admission_no_pk', $admission_id)
            ->groupBy('admission_no_pk')
            ->value('discount') ?? 0;

        // Other lookups
        $bank_name = $this->getLookupListByCode("AGENTBANKING");
        $ipd_sub_type = $this->getLookupListByCode("IPDPAYSUBTYPE");
        $patient_type = DB::table('patn_patienttype')
            ->select('patient_type_no_pk', 'patient_type_code', 'patient_type_desc')
            ->where('status', 1)
            ->where('au_entry_hospital_pk_no', $hospital_id)
            ->get();
        $corporate_info = DB::table('ccm_corporateclient_vw')
            ->select('ccm_client_no_pk', 'ccm_client_code', 'ccm_client_name')
            ->where('active_status', '!=', 0)
            ->where('au_entry_hospital_pk_no', $hospital_id)
            ->get();

        $type = 'Total IPD';
        $bill = DB::table("finc_ipdpatientbill_vw")
            ->where("admission_no_pk", $admission_id)
            ->where("sales", ">", 0)
            ->get();

        return Template::loadview("admin.ipd.payment_deposit", [
            "patientInfo" => $patientInfo,
            "ipd_sub_type" => $ipd_sub_type,
            "item_details" => $item_details,
            'paymodes' => $paymodes,
            'pay_types' => $pay_types,
            'admission_id' => $admission_id,
            'patientId' => $patientId,
            'paymentHistories' => $paymentHistories,
            'totalDiscount' => $totalDiscount,
            'bank_name' => $bank_name,
            'type' => $type,
            'bill' => $bill,
            'patient_type' => $patient_type,
            'corporate_info' => $corporate_info,
            'card_type' => $card_type,
        ]);
    }



