                    $payment->bindValue(':in_given_amt', $totalPaymentAmount);
                    $payment->bindValue(':in_disc_type_lookup_no_fk', $zero);
                    $payment->bindValue(':in_disc_remarks', $remarks1, PDO::PARAM_STR);
                    $payment->bindValue(':in_disc_amt_by_doc', $discountAmountbyDoctor);
                    $payment->bindValue(':in_disc_amt_by_doc_no_fk', $dis_by);
                    $payment->bindValue(':in_disc_amt_request_by_name', $dis_request_by);
                    $payment->bindValue(':in_disc_amt_by_hosp', $discountAmountbyHospital);
                    $payment->bindValue(':in_disc_amt_by_hosp_auth_by', $in_au_entry_by); /* while olnly discount type is hopital */

                    $payment->bindArray(':in_paymood', $paymentMethod, count($paymentMethod), $numelems, SQLT_CHR);

                    $payment->bindArray(':in_pay_mood_type', $paymentType, count($paymentType), $numelems, SQLT_CHR);
                    $payment->bindArray(':in_bank_name', $paymentBankName, count($paymentBankName), $numelems, SQLT_CHR);
                    $payment->bindArray(':in_transaction_id', $trxnID, count($trxnID), $numelems, SQLT_CHR);
                    $payment->bindArray(':in_bank_card_no', $cardNumber, count($cardNumber), $numelems, SQLT_CHR);
                    $payment->bindArray(':in_acc_holder_name', $accHolderName, count($accHolderName), $numelems, SQLT_CHR);
                    $payment->bindArray(':in_payment_amt', $paymentByType, count($paymentByType), $numelems, SQLT_FLT);

                    $totalPayMode = count($paymentMethod);
                    $totalPayMode = intval($totalPayMode);

                    $in_ledgertrn_no = $out_ledger_no = $out_ledgertrn_no = 0;
                    $payment->bindValue(':in_paymood_count', $totalPayMode);
                    $payment->bindValue(':in_payment_subtype', $in_payment_subtype);
                    $payment->bindValue(':in_au_entry_by', $in_au_entry_by);
                    $payment->bindValue(':in_au_entry_session', $in_au_entry_session);
                    $payment->bindValue(':in_au_entry_hospital_pk_no', $hospital_id);
                    $payment->bindValue(':in_ledgertrn_no', $in_ledgertrn_no);

                    $out_error = $out_ledger_id = "'0'";
                    $payment->bindParam(':out_ledger_no', $out_ledger_no, PDO::PARAM_INT);
                    $payment->bindParam(':out_ledger_id', $out_ledger_id, PDO::PARAM_STR, 500);
                    $payment->bindParam(':out_ledgertrn_no', $out_ledgertrn_no, PDO::PARAM_INT);
                    $payment->bindParam(':out_error', $out_error, PDO::PARAM_STR, 500);
                    // dd($payment);
                    $payment->execute();


                }

                if ($out_error == 000) {

                    $sequences = DB::getSequence();
                    $deposit_no_pk_seq = $sequences->nextValue('deposit_no_pk_seq');


                    $depositData = [
                        'DEPOSIT_NO_PK'           => $deposit_no_pk_seq,
                        'PATIENT_NO_FK'           => $patientID,
                        'CORPORATE_NO_FK'         => $zero,
                        'ADMISSION_NO_FK'         => $admissionID,
                        'INVOICE_NO_FK'           => DB::raw("(SELECT INVOICE_NO_FK FROM FINC_LEDGERMST WHERE LEDGER_NO_PK = $out_ledger_no)"),
                        'PAY_AMOUNT'              => $totalAmount,
                        'LEDGERTRN_NO_FK'         => $out_ledgertrn_no,
                        'LEDGER_NO_FK'            => $out_ledger_no,
                        'STATUS'                  => 1,
                        'AU_ENTRY_BY'             => $in_au_entry_by,
                        'AU_ENTRY_AT'             => now(),
                        'AU_ENTRY_SESSION'        => $in_au_entry_session,
                        'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_id,
                    ];

                    DB::table('finc_ipddepositmst')->insert($depositData);

                    $message = [
                        'msg'       => 'Data Saved Successfully',
                        'title'     => 'Success',
                        'insert_id' => $out_ledger_no
                    ];
                        DB::commit();
                    return response()->json($message);
                } else {
                DB::rollback();
                $message = ['msg' => $out_error, 'title' => 'Error'];
                return response()->json($message, 400);
                }
            }
        } catch (\Exception $e) {
            DB::rollback();

            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
            return response()->json($message, 400);
        }
    }

    public function getDeposits($patient_id)
    {
        $deposits = DB::table('finc_ipddepositmst as f')
            ->select(
                'f.deposit_no_pk',
                'f.invoice_no_fk',
                'f.pay_amount',
                'f.status',
                'f.au_entry_at',
                'p.patient_code',
                'p.patient_name',
                'u.user_fullname as cashier_name',
                'u.user_code as cashier_code'
            )
            ->leftJoin('patn_registration as p', 'p.patient_no_pk', '=', 'f.patient_no_fk')
            ->leftJoin('wsec_user as u', 'u.user_no_pk', '=', 'f.au_entry_by')
            ->where('f.patient_no_fk', $patient_id)
            ->whereNull('f.admission_no_fk')
            ->whereNull('f.re_invoice_no_fk')
            ->where('f.pay_amount', '>=', 0)
            ->orderBy('f.au_entry_at', 'desc')
            ->get();

        return response()->json($deposits);
    }



