    public function discountAdjustment(Request $request){
        $corporateNO=$request->newCorporeateNo;
        $newPatType=$request->newPatType;
        $admission_no=$request->admission_no;
        $patient_no=$request->patient_no;
        DB::beginTransaction();
        $auth_id = Auth::id();
        $date=date('Y-m-d H:i');
        $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
        $in_au_entry_session='discount adjustment from ipd payment';
        // dd($request->all());
         $age_years = 0;
        if ($newPatType =="STAFFDEPENDENTCHILD") {
            $pat_reg=DB::table('patn_registration')->where('patient_no_pk',$patient_no)->select('dob')->first();

            $birth_date = $pat_reg->dob !='' ? date('Y-m-d',strtotime($pat_reg->dob)):'' ;
            if ( $birth_date !='') {
                $current_date = date('Y-m-d');
                $birth_date_obj = new DateTime($birth_date);
                $current_date_obj = new DateTime($current_date);
                $diff = $current_date_obj->diff($birth_date_obj);
                $age_years = $diff->y;
            }
            $max_age_discount=DB::table('sysc_discountpolicy')->where('dispolicy_code', $newPatType)->value('max_age')??0;
            // dd( $max_age_discount, $age_years);
            if ($max_age_discount > 0 && $age_years > $max_age_discount) {
                 $newPatType ="GENERAL";
            }
        }

        try {
            $out_error = "";
            $pdo = DB::getPdo();
            $discountAdjustment = $pdo->prepare("begin pkg_corporate.prc_patconv_discount_wp(
                    :in_admission_no_fk,
                    :in_patient_type,
                    :in_ccm_client_no_pk,
                    :in_payment_date,
                    :in_au_entry_by,
                    :in_au_entry_session,
                    :in_au_entry_hospital_pk_no,
                    :out_error);
                    end;");

            $discountAdjustment->bindParam(':in_admission_no_fk', $admission_no);
            $discountAdjustment->bindParam(':in_patient_type', $newPatType);
            $discountAdjustment->bindParam(':in_ccm_client_no_pk', $corporateNO);
            $discountAdjustment->bindParam(':in_payment_date', $date);
            $discountAdjustment->bindParam(':in_au_entry_by', $auth_id);
            $discountAdjustment->bindParam(':in_au_entry_session', $in_au_entry_session);
            $discountAdjustment->bindParam(':in_au_entry_hospital_pk_no', $ses_hospital_id);
            $discountAdjustment->bindParam(':out_error', $out_error, PDO::PARAM_STR, 500);
            // dd($discountAdjustment);
            $discountAdjustment->execute();

            DB::commit();
            $message = ['msg' => 'Discount Adjustment Successfull.', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            $message = ['msg' => 'Discount Adjustment Failled._'.$th, 'title' => 'Error'];
        }
         return response()->json($message);

    }
