    public function ipdSingleItemCancel(Request $request){
        $admission_no=$request->admission_no;
        $item_type=$request->item_type;
        $invoiceNo=$request->invoiceNo;
        $cancel_remarks=$request->cancel_remarks;
        $item_no=[$request->item_no];
        $canceQty=[$request->canceQty];
        $itemQty=[$request->itemQty];
        $expiry_date=$request->expiry_date !="" ? [date('dmY',strtotime($request->expiry_date))] :[null];
        $batch_no=[$request->batch_no];
        $internal_batch_no_uq=[$request->internal_batch_no_uq];
        // dd( $canceQty,  $expiry_date);
        $coun=count($itemQty);
        DB::beginTransaction();
        $auth_id = Auth::id();
        $cancel_date=date('Y-m-d H:i');
        $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
        $in_au_entry_session='Cancel from ipd payment';
        $refund_reason = '';
        $refund_amount = 0;

        if ($item_type=="MED") {
            $module_info = DB::table("sysc_module")->where("module_code", "PHR-I")->select("module_no_pk")->first();
        }else{
            $module_info = DB::table("sysc_module")->where("module_code", "IPD")->select("module_no_pk")->first();
        }
        $cunter_su_no=DB::table('finc_invoicemst')->where('invoice_no_pk',$invoiceNo)->value('counter_su_no_fk');
        $module_id = isset($module_info->module_no_pk) ? $module_info->module_no_pk : "0";
        $numelems=500;
        // dd($counterNo);
        //    $cunter_su_no =0;

        try {

                $pdo = DB::getPdo();

                $in_ledgertrn_no = 0;
                $out_ledgertrn_no = $outError = $out_invoice_id = $out_invoice_no = '';

            if ( $item_type=="MED" || $item_type=="INV" || $item_type=="MSU" || $item_type=="CONSUM") {

                $refund_amount = 0;
                $refund_reason = '';
                $billinvoice = $pdo->prepare("begin pkg_billing_v0.prc_phr_sales_cancel_batch_exp(
                :in_cancel_date,
                :in_invoice_no_pk,
                :in_refund_amount,
                :in_refund_reason,
                :in_item_no_fk,
                :in_cancel_qty,
                :in_item_batch_fk,
                :in_item_expiry_dt,
                :in_intern_batch_fk,
                :in_item_count,
                :in_module_no_fk,
                :in_admission_no_fk,
                :in_counter_su_no_fk,
                :in_au_entry_by,
                :in_au_entry_session,
                :in_au_entry_hospital_pk_no,
                :in_ledgertrn_no,
                :out_invoice_no,
                :out_invoice_id,
                :out_ledgertrn_no,
                :out_error); end;");
                $refund_amount = round($refund_amount);
                $billinvoice->bindParam(':in_cancel_date', $cancel_date); // will be adjust later
                $billinvoice->bindParam(':in_invoice_no_pk', $invoiceNo);
                $billinvoice->bindParam(':in_refund_amount', $refund_amount);
                $billinvoice->bindParam(':in_refund_reason', $refund_reason);
                $billinvoice->bindArray(':in_item_no_fk', $item_no, count($item_no), $numelems, SQLT_INT);
                $billinvoice->bindArray(':in_cancel_qty', $canceQty, count($canceQty), $numelems, SQLT_INT);
                $billinvoice->bindArray(':in_item_batch_fk', $batch_no, count($batch_no), $numelems, SQLT_CHR);
                $billinvoice->bindArray(':in_item_expiry_dt', $expiry_date, count($expiry_date), $numelems, SQLT_CHR);
                $billinvoice->bindArray(':in_intern_batch_fk', $internal_batch_no_uq, count($internal_batch_no_uq), $numelems, SQLT_CHR);
                $billinvoice->bindParam(':in_item_count', $coun);
                $billinvoice->bindParam(':in_module_no_fk', $module_id);
                $billinvoice->bindParam(':in_admission_no_fk', $admission_no);
                $billinvoice->bindParam(':in_counter_su_no_fk', $cunter_su_no);
                $billinvoice->bindParam(':in_au_entry_by', $auth_id);
                $billinvoice->bindParam(':in_au_entry_session', $in_au_entry_session);
                $billinvoice->bindParam(':in_au_entry_hospital_pk_no', $ses_hospital_id);
                $billinvoice->bindParam(':in_ledgertrn_no', $in_ledgertrn_no);
                $billinvoice->bindParam(':out_invoice_no', $out_invoice_no, PDO::PARAM_INT);
                $billinvoice->bindParam(':out_invoice_id', $out_invoice_id, PDO::PARAM_STR, 10000);
                $billinvoice->bindParam(':out_ledgertrn_no', $out_ledgertrn_no, PDO::PARAM_INT);
                $billinvoice->bindParam(':out_error', $outError, PDO::PARAM_STR, 100000);
                //   dd($billinvoice);
                $billinvoice->execute();

            }else {


                $billinvoice = $pdo->prepare("begin pkg_billing_v0.prc_sales_cancellation(:in_cancel_date,:in_invoice_no_pk,:in_refund_amount,:in_refund_reason,:in_item_no_fk,:in_cancel_qty,:in_item_count,:in_module_no_fk,:in_admission_no_fk,:in_counter_su_no_fk,:in_au_entry_by,:in_au_entry_session,:in_au_entry_hospital_pk_no,:in_ledgertrn_no,:out_invoice_no,:out_invoice_id,:out_ledgertrn_no,:out_error); end;");

                    $billinvoice->bindParam(':in_cancel_date', $cancel_date); // will be adjust later
                    $billinvoice->bindParam(':in_invoice_no_pk', $invoiceNo);
                    $billinvoice->bindParam(':in_refund_amount', $refund_amount);
                    $billinvoice->bindParam(':in_refund_reason', $refund_reason);
                    $billinvoice->bindArray(':in_item_no_fk', $item_no, count($item_no), $numelems, SQLT_INT);
                    $billinvoice->bindArray(':in_cancel_qty', $canceQty, count($canceQty), $numelems, SQLT_FLT);
                    $billinvoice->bindParam(':in_item_count', $coun);
                    $billinvoice->bindParam(':in_module_no_fk', $module_id);
                    $billinvoice->bindParam(':in_admission_no_fk', $admission_no);
                    $billinvoice->bindParam(':in_counter_su_no_fk', $cunter_su_no);
                    $billinvoice->bindParam(':in_au_entry_by', $auth_id);
                    $billinvoice->bindParam(':in_au_entry_session', $in_au_entry_session);
                    $billinvoice->bindParam(':in_au_entry_hospital_pk_no', $ses_hospital_id);
                    $billinvoice->bindParam(':in_ledgertrn_no', $in_ledgertrn_no);
                    $billinvoice->bindParam(':out_invoice_no', $out_invoice_no, PDO::PARAM_INT);
                    $billinvoice->bindParam(':out_invoice_id', $out_invoice_id, PDO::PARAM_STR, 500);
                    $billinvoice->bindParam(':out_ledgertrn_no', $out_ledgertrn_no, PDO::PARAM_INT);
                    $billinvoice->bindParam(':out_error', $outError, PDO::PARAM_STR, 500);
                    // dd($billinvoice);
                    $billinvoice->execute();
            }

            if ($outError==999) {
                DB::rollback();
                $message = ['msg' => 'Item Cancel Failled.', 'title' => 'Error'];
            }
            DB::table('finc_invoicedtl')->where('invoice_no_fk',$invoiceNo)->where('item_no_fk',$request->item_no)->update(['item_cancel_remarks'=>$cancel_remarks]);
            DB::commit();
            $message = ['msg' => 'Item Cancel Successfull.', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            $message = ['msg' => 'Item Cancel Failled._'.$th, 'title' => 'Error'];
        }
         return response()->json($message);

    }


    public function CategoryItemDetails($categoryId = "",$admission_id=""){

      $data = DB::table('finc_inv_itemdtl_vw as mst')
        ->select(
            'mst.admission_no_pk',
            'mst.invoice_no_fk as invoice_no_pk',
            'mst.invoice_date',
            'mst.patient_name',
            'mst.patient_code',
            'mst.age',
            'mst.item_name',
            'mst.item_no_fk',
            'mst.itemtype_no_fk',
            'mst.item_qty',
            'mst.ledgerdtl_amt_sales as item_rate',
            'mst.urgent_fee',
            'mst.cancel_qty',
            'mst.ledgerdtl_amt_payment as invoicedtl_amt_payment',
            'mst.disc_amount as invoicedtl_amt_discount',
            'mst.item_type_name',
            'mst.item_type',
            'mst.expiry_date',
            'mst.batch_no',
            'mst.internal_batch_no_uq',
             'item_cancel_remarks'
        )
        ->where('mst.admission_no_pk', $admission_id)
        ->where('mst.itemtype_no_fk', $categoryId)
        ->orderByDesc('mst.invoice_date')
        ->get();

        // dd($categoryId);
        $admissionInfo=DB::table('ipd_admitted_patlist_vw')->select('admission_no_pk','patient_name','gender_txt','age','admission_date','new_bed_name','mobile1')->where('admission_no_pk',$admission_id)->first();

        return Template::loadview("admin.ipd.category_item_details", ["data" => $data,'admissionInfo'=>$admissionInfo]);

    }


