    public function getTotalDiscount($discountInformations)
    {
        $totalDiscount = 0;

        foreach ($discountInformations as $key => $payhistory) {

            $totalDiscount += $payhistory->ledger_amt_discount;
            // $payhistory->disc_amt_by_doc + $payhistory->disc_amt_by_hosp;
        }
        // dd($totalDiscount);
        return $totalDiscount;
    }

