        //     left join finc_admission_sum_vw b
        //     on a.admission_no_pk = b.admission_no_pk
        //     $sql_cond order by a.admission_no_pk desc");
        $ses_hospital_id = DB::table('sysc_serviceunit')->select('clearance_ind')->where('serviceunit_no_pk', Session::get('user.su_pk_no'))->first();
        $admission_info = [];
        if ($ses_hospital_id->clearance_ind == 1) {
            $admission_info = DB::table("ipd_admitted_patlist_vw")
                ->leftJoin("finc_admission_sum_vw", "ipd_admitted_patlist_vw.admission_no_pk", "finc_admission_sum_vw.admission_no_pk")
                ->select("ipd_admitted_patlist_vw.*", "finc_admission_sum_vw.ledger_amt_payment", "finc_admission_sum_vw.advance_due", "finc_admission_sum_vw.paid_amount", 'finc_admission_sum_vw.ledger_amt_payable', "finc_admission_sum_vw.ledger_amt_discount", "finc_admission_sum_vw.ledger_amt_sales")
                ->where('ipd_admitted_patlist_vw.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
                ->whereRaw($sql_cond)
                ->orderBy("ipd_admitted_patlist_vw.admission_no_pk", "DESC")
                ->paginate(50);
        }
        // dd($admission_info);
        return Template::loadview("admin.ipd.ipd_business_office.ipd_phr_clearance_result", ["admission_info" => $admission_info, 'consultant' => $consultant, 'serviceunit' => $serviceunit, 'bed_info' => $bed_info, 'ward_info' => $ward_info]);
    }



