        //     $sql_cond = "ipd_admitted_patlist_vw.dis_req_ind == 0 and ipd_admitted_patlist_vw.dis_ind == 0";
        // }

        if ($request->isMethod('post')) {
            Cache::forget('sql_cond');
        }

        if (!Cache::has('sql_cond') && !empty($sql_cond)) {

            Cache::put('sql_cond', $sql_cond);
        }

        if ($sql_cond == '') {
            $sql_cond = Cache::get('sql_cond'); //' (ipd_admitted_patlist_vw.dis_ind=0' ;

        }



        // $admission_info = DB::select("select a.*,b.ledger_amt_payment,b.advance_due,b.ledger_amt_payable,b.ledger_amt_discount,b.ledger_amt_sales from
        //     ipd_admitted_patlist_vw a
