        $hospital_no = Session('user.ses_hospital_no_pk');
        // $admission_info = DB::select("select reg.patient_code, patient_no_pk as patient_no_fk,ip.admission_no_pk,trunc(admission_date) admission_date,primary_doctor_no_fk,fnc_docname(primary_doctor_no_fk)PRIMARY_DOCTOR_NAME,
        //     curr_bed_no_fk,(select bed_name from ipds_bed where bed_no_pk =ip.curr_bed_no_fk) NEW_BED_NAME,null BED_NAME,curr_ward_no_fk,
        //     (select WARD_NAME from ipds_ward where WARD_NO_PK=ip.curr_ward_no_fk) NEW_WARD_NAME,null WARD_NAME,
        //     su_no_fk,fnc_serviceunitname(su_no_fk) department_name,patient_name,gender_txt ,  nvl(HOUSEKEEPING_BILL_IND,0) HOUSEKEEPING_BILL_IND ,
        //     HK_CLEAR_IND, DK_CLEAR_IND,  CAFETERIA_CLEAR_IND,  PHR_CLEAR_IND,   FIN_CLEAR_IND, DIS_REQ_IND, DIS_IND,
        //             dob,pat_age(dob,nvl(dod,trunc(admission_date))) age,DIS_DATE,null LAST_PAYMENT_DATE,sum(ledger_amt_sales)-sum(ledger_amt_discount)-sum(ledger_amt_payment) ADVANCE_DUE,sum(ledger_amt_payment) PAID_AMOUNT,sum(ledger_amt_sales)-sum(ledger_amt_discount) LEDGER_AMT_PAYABLE,
        //             (select lookupdata_code from sysc_lookupdata where lookupdata_no_pk=reg.blood_group) BLOOD_GROUP_TEXT,mobile1 ,PRESENT_ADDR,
        //             CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE)) TOTAL_DAYS,sum(ledger_amt_sales) LEDGER_AMT_SALES,sum(ledger_amt_discount) LEDGER_AMT_DISCOUNT,sum(ledger_amt_payment) LEDGER_AMT_PAYMENT,ip.lock_remarks
        //     from ipd_admission ip join IPD_ADMISSION_DETAILS dtl
        //     on ip.admission_no_pk=dtl.admission_no_pk
        //     left join finc_ledgermst mst
        //     on ip.admission_no_pk=mst.admission_no_fk
        //     join patn_registration reg
        //     on ip.patient_no_fk=reg.patient_no_pk
        //     where  $sql_cond
        //     and ip.au_entry_hospital_no_fk= $hospital_no
        //     group by reg.patient_code, ip.admission_no_pk,trunc(admission_date),primary_doctor_no_fk,curr_bed_no_fk,curr_ward_no_fk,PRESENT_ADDR, DIS_REQ_IND,DIS_DATE, DIS_IND,HOUSEKEEPING_BILL_IND,ip.lock_remarks,
        //     HK_CLEAR_IND, DK_CLEAR_IND,  CAFETERIA_CLEAR_IND,  PHR_CLEAR_IND,   FIN_CLEAR_IND,
        //             su_no_fk,patient_name,patient_no_pk,gender_txt,dob,blood_group,mobile1,dod,NVL (ip.DIS_DATETIME, SYSDATE),ip.ADMISSION_DATE ,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks
        //        order by trunc(admission_date) desc,ip.admission_no_pk desc");


        // dd($data,$request->patient_type,  $sql_cond);
        if ($request->patient_type==='EMERGENCY') {

                $admission_info = DB::select("select reg.patient_code as patient_code, reg.patient_no_pk as patient_no_fk,ip.admission_no_pk,trunc(ip.admission_date) admission_date,ip.primary_doctor_no_fk,fnc_docname(ip.primary_doctor_no_fk)PRIMARY_DOCTOR_NAME,
            ip.curr_bed_no_fk,(select bed_name from ipds_bed where bed_no_pk =ip.curr_bed_no_fk) NEW_BED_NAME,null BED_NAME,ip.curr_ward_no_fk,
            (select WARD_NAME from ipds_ward where WARD_NO_PK=ip.curr_ward_no_fk) NEW_WARD_NAME,null WARD_NAME,
                    ip.su_no_fk,fnc_serviceunitname(ip.su_no_fk) department_name,reg.patient_name,reg.gender_txt ,  nvl(dtl.HOUSEKEEPING_BILL_IND,0) HOUSEKEEPING_BILL_IND ,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND, ip.DIS_REQ_IND, ip.DIS_IND,
                    reg.dob,pat_age(reg.dob,nvl(dod,trunc(ip.admission_date))) age,ip.DIS_DATE,null LAST_PAYMENT_DATE,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount)-sum(mst.ledger_amt_payment) ADVANCE_DUE,sum(mst.ledger_amt_payment) PAID_AMOUNT,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount) LEDGER_AMT_PAYABLE,
                    (select lookupdata_code from sysc_lookupdata where lookupdata_no_pk=reg.blood_group) BLOOD_GROUP_TEXT,reg.mobile1 ,reg.PRESENT_ADDR,
                    CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE)) TOTAL_DAYS,sum(mst.ledger_amt_sales) LEDGER_AMT_SALES,sum(mst.ledger_amt_discount) LEDGER_AMT_DISCOUNT,sum(mst.ledger_amt_payment) LEDGER_AMT_PAYMENT
            ,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks from ipd_admission ip join IPD_ADMISSION_DETAILS dtl
            on ip.admission_no_pk=dtl.admission_no_pk
            left join finc_ledgermst mst
            on ip.admission_no_pk=mst.admission_no_fk
            join patn_registration reg
            on ip.patient_no_fk=reg.patient_no_pk

            left join ipd_admitted_patlist_vw admvw
            on admvw.admission_no_pk=ip.admission_no_pk
             left join sysc_serviceunit su
            on su.serviceunit_no_pk=admvw.new_su_no_fk

             where  $sql_cond and su.emergency_ind =1

            and ip.au_entry_hospital_no_fk= $hospital_no
            group by reg.patient_code, ip.admission_no_pk,trunc(ip.admission_date),ip.primary_doctor_no_fk,ip.curr_bed_no_fk,ip.curr_ward_no_fk,reg.PRESENT_ADDR, ip.DIS_REQ_IND,ip.DIS_DATE, ip.DIS_IND,dtl.HOUSEKEEPING_BILL_IND,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND,
            ip.su_no_fk,reg.patient_name,reg.patient_no_pk,reg.gender_txt,reg.dob,reg.blood_group,reg.mobile1,reg.dod,NVL (ip.DIS_DATETIME, SYSDATE),ip.ADMISSION_DATE,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks
            order by trunc(ip.admission_date) desc,ip.admission_no_pk desc");
        }else{
                 $admission_info = DB::select("select reg.patient_code as patient_code, reg.patient_no_pk as patient_no_fk,ip.admission_no_pk,trunc(ip.admission_date) admission_date,ip.primary_doctor_no_fk,fnc_docname(ip.primary_doctor_no_fk)PRIMARY_DOCTOR_NAME,
            ip.curr_bed_no_fk,(select bed_name from ipds_bed where bed_no_pk =ip.curr_bed_no_fk) NEW_BED_NAME,null BED_NAME,ip.curr_ward_no_fk,
            (select WARD_NAME from ipds_ward where WARD_NO_PK=ip.curr_ward_no_fk) NEW_WARD_NAME,null WARD_NAME,
                    ip.su_no_fk,fnc_serviceunitname(ip.su_no_fk) department_name,reg.patient_name,reg.gender_txt ,  nvl(dtl.HOUSEKEEPING_BILL_IND,0) HOUSEKEEPING_BILL_IND ,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND, ip.DIS_REQ_IND, ip.DIS_IND,
                    reg.dob,pat_age(reg.dob,nvl(dod,trunc(ip.admission_date))) age,ip.DIS_DATE,null LAST_PAYMENT_DATE,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount)-sum(mst.ledger_amt_payment) ADVANCE_DUE,sum(mst.ledger_amt_payment) PAID_AMOUNT,sum(mst.ledger_amt_sales)-sum(mst.ledger_amt_discount) LEDGER_AMT_PAYABLE,
                    (select lookupdata_code from sysc_lookupdata where lookupdata_no_pk=reg.blood_group) BLOOD_GROUP_TEXT,reg.mobile1 ,reg.PRESENT_ADDR,
                    CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE)) TOTAL_DAYS,sum(mst.ledger_amt_sales) LEDGER_AMT_SALES,sum(mst.ledger_amt_discount) LEDGER_AMT_DISCOUNT,sum(mst.ledger_amt_payment) LEDGER_AMT_PAYMENT
            ,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks from ipd_admission ip join IPD_ADMISSION_DETAILS dtl
            on ip.admission_no_pk=dtl.admission_no_pk
            left join finc_ledgermst mst
            on ip.admission_no_pk=mst.admission_no_fk
            join patn_registration reg
            on ip.patient_no_fk=reg.patient_no_pk

            left join ipd_admitted_patlist_vw admvw
            on admvw.admission_no_pk=ip.admission_no_pk
             left join sysc_serviceunit su
            on su.serviceunit_no_pk=admvw.new_su_no_fk

             where  $sql_cond and su.emergency_ind is null


            and ip.au_entry_hospital_no_fk= $hospital_no
            group by reg.patient_code, ip.admission_no_pk,trunc(ip.admission_date),ip.primary_doctor_no_fk,ip.curr_bed_no_fk,ip.curr_ward_no_fk,reg.PRESENT_ADDR, ip.DIS_REQ_IND,ip.DIS_DATE, ip.DIS_IND,dtl.HOUSEKEEPING_BILL_IND,
            dtl.HK_CLEAR_IND, dtl.DK_CLEAR_IND,  dtl.CAFETERIA_CLEAR_IND,  dtl.PHR_CLEAR_IND,   dtl.FIN_CLEAR_IND,
            ip.su_no_fk,reg.patient_name,reg.patient_no_pk,reg.gender_txt,reg.dob,reg.blood_group,reg.mobile1,reg.dod,NVL (ip.DIS_DATETIME, SYSDATE),ip.ADMISSION_DATE,ip.lock_ind,ip.lock_date,ip.lock_by,ip.lock_remarks
            order by trunc(ip.admission_date) desc,ip.admission_no_pk desc");
        }


        return Template::loadview("admin.ipd.ipd_business_office.ipd_business_office_result", ["admission_info" => $admission_info]);
