    public function ipdDischargeSummary($admission_id = "")
    {
        $priority = $this->getLookupListByCode("PRIORITY");
        $duration_mu = $this->getPresLookupListByCode("DURMU");
        $gender = $this->getLookupListByCode("GENDER");

        $instructions = $this->getPresLookupListByCode("INSTRUCTION");
        $route = $this->getPresLookupListByCode("ROUTE");
        $dose = $this->getPresLookupListByCode("DOSE");

        // $meddurmu = $this->getPresLookupListByCode("DURMU", "psn_lookupdata_uid");
        $followup_mu = $this->getPresLookupListByCode("FOLLOWUPMU");
        $admission_info = DB::table('finc_admission_sum_vw a')->select("a.*", "b.new_ward_name", "b.new_bed_name")->where('a.admission_no_pk', $admission_id)->leftJoin("ipd_admitted_patlist_vw b", "a.admission_no_pk", "=", "b.admission_no_pk")->first();
        $admissiton_id = $admission_info = DB::table('ipd_admitted_patlist_vw a')->select("a.*")->where('a.admission_no_pk', $admission_id)->first();

        $paitent_info = DB::table('patient_info_vw')->where('patient_no_pk', $admissiton_id->patient_no_fk)->first();

        $admission_details = DB::table('ipd_admission_details')->where('admission_no_pk', $admission_id)
            ->first();

        $pre_ot_anaesthesia_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->pre_ot_anaesthesia_no)->first()->full_name ?? "";
        $pre_ot_surgeon_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->pre_ot_surgeon_no)->first()->full_name ?? "";
        $pre_ot_anaesthetist_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->pre_ot_anaesthetist_no)->first()->full_name ?? "";
        $post_ot_anaesthesia_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->post_ot_anaesthesia_no)->first()->full_name ?? "";
        $post_ot_surgeon_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->post_ot_surgeon_no)->first()->full_name ?? "";
        $post_ot_anaesthetist_no = DB::table("hrms_personnel")->select("full_name")->where("person_no_pk", $admission_details->post_ot_anaesthetist_no)->first()->full_name ?? "";
        // dd($admission_details);
        $dis_investigation_info = DB::table('ipd_discharge_investigation')
            ->where('admission_no_fk', $admission_id)
            ->where('patient_no_fk', $admission_info->patient_no_fk)->get();
        $dis_med_info = DB::table('ipd_discharge_med')
            ->where('admission_no_fk', $admission_id)
            ->where('patient_no_fk', $admission_info->patient_no_fk)
            ->orderBy('discharge_med_pk_no', 'asc')
            ->get();

        $prescription_med = DB::table('psn_t_prescription_med')
            ->where('admission_pk_no', $admission_id)
            ->where('patient_no_fk', $admission_info->patient_no_fk)
            // ->where('continue_ind',  1)
            ->where('DISCONTINE_IND',  0)
            ->get()
            ->map(function ($item) {
                $item->item_no_fk = $item->item_no_fk ?? $item->item_no_pk ?? null;
                $item->item_name = $item->brand_name ?? $item->generic_name ?? '';
                // $item->dosage = $item->dosage '';
                // $item->duration = $item->duration ?? '';
                // $item->duration_mu = $item->duration_mu ?? '';
                // $item->item_qty = $item->item_qty ?? $item->qty ?? '';
                // $item->continue_ind = $item->continue_ind ?? 0;
                $item->med_taken_instruction = $item->instruction_take ?? '';
                $item->route = $item->route ?? '';
                return $item;
            });


         if ($dis_med_info->isNotEmpty()) {
            $merged_med_info = $dis_med_info;
            } else {
                $merged_med_info = $prescription_med;
            }
        // if ($dis_med_info->isNotEmpty()) {
        //     $merged_med_info = $dis_med_info->sortByDesc('au_entry_at')->values();
        // } else {
        //     $merged_med_info = $prescription_med->sortByDesc('au_entry_at')->values();
        // }

        $dis_template = DB::table('ipd_disccharge_template')
            ->select('dis_template_name', 'dis_template_no_pk')
            ->orderBy('dis_template_no_pk', 'desc')
            ->get();
        // dd($admission_details);
        return Template::loadview(
            "admin.ipd.discharge.discharge_summary",
            [
                'paitent_info' => $paitent_info,
                'admission_info' => $admission_info,
                'followup_mu' => $followup_mu,
                'instructions' => $instructions,
                'dose' => $dose,
                'dis_investigation_info' => $dis_investigation_info,
                'dis_med_info' => $merged_med_info,
                'admission_details' => $admission_details,
                'dis_template' => $dis_template,
                'gender' => $gender,
                'route' => $route,
                'pre_ot_anaesthesia_no' => $pre_ot_anaesthesia_no,
                'pre_ot_surgeon_no' => $pre_ot_surgeon_no,
                'pre_ot_anaesthetist_no' => $pre_ot_anaesthetist_no,
                'post_ot_anaesthesia_no' => $post_ot_anaesthesia_no,
                'post_ot_surgeon_no' => $post_ot_surgeon_no,
                'post_ot_anaesthetist_no' => $post_ot_anaesthetist_no,
            ]
        );
    }
