        // Oracle-friendly date comparison
        $query->whereRaw(
            "TRUNC(dis_datetime) >= TO_DATE(?, 'YYYY-MM-DD') AND TRUNC(dis_datetime) <= TO_DATE(?, 'YYYY-MM-DD')",
            [$discharge_from, $discharge_to]
