                                ->toArray(),
        ]);
    }

    public function dischargeReqListRevenuePosting()
    {
        $oneMonthAgo = date('Y-m-d');

        $dis_reqLists = DB::table('ipd_admitted_patlist_vw as ipd')
            ->leftJoin(DB::raw("(
                SELECT
                    mst.admission_no_pk,
                    SUM(lmst.ledger_amt_sales) AS sales,
                    SUM(lmst.ledger_amt_discount) AS discount,
                    SUM(lmst.ledger_amt_payment) AS payment
                FROM finc_ledgermst lmst
                JOIN finc_invoicemst mst
                    ON lmst.invoice_no_fk = mst.invoice_no_pk
                GROUP BY mst.admission_no_pk
            ) finc"), 'finc.admission_no_pk', '=', 'ipd.admission_no_pk')
            ->where('ipd.dis_ind', 1)
            ->whereBetween(DB::raw("TRUNC(ipd.dis_datetime)"), [$oneMonthAgo, date('Y-m-d')])
            ->select(
                'ipd.*',
                DB::raw('NVL(finc.sales, 0) AS total_sales'),
                DB::raw('NVL(finc.discount, 0) AS total_discount'),
                DB::raw('NVL(finc.payment, 0) AS total_payment')
            )
            ->orderBy('ipd.dis_datetime', 'desc')
            ->get();

        $ipds_wards = DB::table('ipds_ward')
            ->select('ward_name', 'ward_no_pk')
            ->orderBy('ward_no_pk', 'desc')
            ->get()
            ->toArray();

        return Template::loadview("admin.ipd.discharge.discharge_req_list_revenue_posting", [
            'dis_reqLists' => $dis_reqLists,
            'ipds_wards'   => $ipds_wards,
        ]);
    }


    public function searchDischargeListRevenuePosting(Request $request)
    {
        $query = DB::table('ipd_admitted_patlist_vw as ipd')
            ->leftJoin(DB::raw("(
                SELECT
                    mst.admission_no_pk,
                    SUM(lmst.ledger_amt_sales) AS sales,
                    SUM(lmst.ledger_amt_discount) AS discount,
                    SUM(lmst.ledger_amt_payment) AS payment
                FROM finc_ledgermst lmst
                JOIN finc_invoicemst mst
                    ON lmst.invoice_no_fk = mst.invoice_no_pk
                GROUP BY mst.admission_no_pk
            ) finc"), 'finc.admission_no_pk', '=', 'ipd.admission_no_pk');

        // Filters
        if (!empty(request('discharge_ward'))) {
            $query->where('ipd.ward_no_pk', request('discharge_ward'));
        }
        if (!empty(request('hdn_patient_id'))) {
            $query->where('ipd.patient_no_fk', request('hdn_patient_id'));
        }
        if (!empty(request('hdn_admission_id'))) {
            $query->where('ipd.admission_no_pk', request('hdn_admission_id'));
        }

        if (!empty(request('admission_date_from')) && !empty(request('admission_date_to'))) {
            $query->where(DB::raw("TRUNC(ipd.dis_date)"), '>=', date('Y-m-d', strtotime(request('admission_date_from'))));
            $query->where(DB::raw("TRUNC(ipd.dis_date)"), '<=', date('Y-m-d', strtotime(request('admission_date_to'))));
        } elseif (!empty(request('admission_date_from'))) {
            $query->where(DB::raw("TRUNC(ipd.dis_date)"), '=', date('Y-m-d', strtotime(request('admission_date_from'))));
        } elseif (!empty(request('admission_date_to'))) {
            $query->where(DB::raw("TRUNC(ipd.dis_date)"), '=', date('Y-m-d', strtotime(request('admission_date_to'))));
        }

        if (!empty(request('revenue_status'))) {
            if (request('revenue_status') == '1') {
                $query->where('ipd.revenue_ind', 1);
            } elseif (request('revenue_status') == '2') {
                $query->whereNull('ipd.revenue_ind');
            }
        }

        $dis_reqLists = $query
            ->where('ipd.dis_ind', 1)
            ->select(
                'ipd.*',
                DB::raw('NVL(finc.sales, 0) AS total_sales'),
                DB::raw('NVL(finc.discount, 0) AS total_discount'),
                DB::raw('NVL(finc.payment, 0) AS total_payment')
            )
            ->orderBy('ipd.dis_datetime', 'desc')
            ->get()
            ->toArray();

        return Template::loadview("admin.ipd.discharge.search_discharge_req_list_revenue", [
            'dis_reqLists' => $dis_reqLists,
        ]);
    }

    public function revenuePostingSingle($admissionID)
    {
        return $this->revenuePostingLogic([$admissionID]);
    }

    public function revenuePosting(Request $request)
    {
        $admissionIDs = $request->admissionID ?? $request->admission_id;

        if (!is_array($admissionIDs)) {
            $admissionIDs = explode(',', $admissionIDs);
        }

        return $this->revenuePostingLogic($admissionIDs);
    }


    protected function revenuePostingLogic(array $admissionIDs)
    {
        $auth_id       = Auth::id();
        $hospital_id   = Session::get('user.ses_hospital_no_pk');
        $pdo           = DB::getPdo();

        $successList = [];
        $failedList  = [];

        foreach ($admissionIDs as $admission_id) {
            $admission_id = trim($admission_id);
            if (empty($admission_id)) continue;

            DB::beginTransaction();

            try {
                $journalCode = '';
                $accError    = '';
                $entry_session = "REVENUEPOST_" . time() . "_" . $admission_id;

                $prcAccounts = $pdo->prepare("
                    BEGIN pkg_v1_accounts.prc_ipdrevenue(
                        :in_narration,
                        :in_integration_type,
                        :in_discharge_date,
                        :in_module_no_fk,
                        :in_admission_no_fk,
                        :in_au_entry_by,
                        :in_au_entry_session,
                        :in_au_entry_hospital_pk_no,
                        :out_jurnal_code,
                        :out_error
                    ); END;
                ");

                $narration        = 'IPD Sales Revenue Posting';
                $integration_type = 'SALES';
                $discharge_date = DB::table('ipd_admitted_patlist_vw')
                    ->where('admission_no_pk', $admission_id)
                    ->value('dis_date');
                // if ($discharge_date) {
                //     $discharge_date = date('Y-m-d', strtotime($discharge_date));
                // }

                // dd($discharge_date);
                if (empty($discharge_date)) {
                    $failedList[] = "Admission ID {$admission_id} → Failed (No discharge date found)";
                    continue;
                }
                $module_no_fk     = 2;

                $prcAccounts->bindParam(':in_narration', $narration);
                $prcAccounts->bindParam(':in_integration_type', $integration_type);
                $prcAccounts->bindParam(':in_discharge_date', $discharge_date);
                $prcAccounts->bindParam(':in_module_no_fk', $module_no_fk);
                $prcAccounts->bindParam(':in_admission_no_fk', $admission_id);
                $prcAccounts->bindParam(':in_au_entry_by', $auth_id);
                $prcAccounts->bindParam(':in_au_entry_session', $entry_session);
                $prcAccounts->bindParam(':in_au_entry_hospital_pk_no', $hospital_id);
                $prcAccounts->bindParam(':out_jurnal_code', $journalCode, PDO::PARAM_STR | PDO::PARAM_INPUT_OUTPUT, 50);
                $prcAccounts->bindParam(':out_error', $accError, PDO::PARAM_STR | PDO::PARAM_INPUT_OUTPUT, 4000);

                $prcAccounts->execute();

                if ($accError != '000') {
                    DB::rollBack();
                    $failedList[] = "Admission ID {$admission_id} → Failed ({$accError})";
                    continue;
                }

                DB::table('ipd_admission')
                    ->where('admission_no_pk', $admission_id)
                    ->update(['revenue_ind' => 1]);

                DB::commit();
                $successList[] = "Admission ID {$admission_id} → Success (Journal: {$journalCode})";
            } catch (\Exception $e) {
                DB::rollBack();
                $failedList[] = "Admission ID {$admission_id} → Exception: " . $e->getMessage();
            }
        }

        $msg = '';
        if (count($successList)) $msg .= "<strong>Successful Postings:</strong><br>" . implode('<br>', $successList) . "<br><br>";
        if (count($failedList)) $msg .= "<strong>Failed Postings:</strong><br>" . implode('<br>', $failedList);

        $title = count($failedList) === 0 ? 'Success' : 'Partial Success';

        return response()->json(['msg' => $msg, 'title' => $title]);
    }



