    public function saveCafePatient(Request $request)
    {
        $patients = $request->input('patients', []);
        $mealDate = $request->input('meal_date');
        $category = $request->input('category');

        if (!$patients || !$category) {
            return response()->json(['message' => 'Please select category and at least one patient'], 422);
        }

        foreach ($patients as $patientData) {
        $admissionId = $patientData['admission_id'] ?? '';
        $remarks     = $patientData['remarks'] ?? '';

        if (!$admissionId) continue;

            $patient = DB::table('IPD_ADMITTED_PATLIST_VW')
                ->where('ADMISSION_NO_PK', $admissionId)
                ->select('ADMISSION_NO_PK','PATIENT_NO_FK')
                ->first();

            if (!$patient) continue;

            $cafe_complementary_no = DB::select("SELECT CAFE_COMPLEMENTARY_NO_PK_SEQ.NEXTVAL as id FROM DUAL")[0]->id;

            DB::table('CAFE_COMPLEMENTARY')->insert([
                'CAFE_COMPLEMENTARY_NO_PK' => $cafe_complementary_no,
                'ADMISSION_NO_FK'           => $patient->admission_no_pk,
                'PATIENT_NO_FK'             => $patient->patient_no_fk,
                'SEARCH_DATE'               => date('Y-m-d', strtotime($mealDate)),
                'CATEGORY'                  => $category,
                'REMARKS'               => $remarks,
                'AU_ENTRY_AT'               => now(),
                'AU_UPDATE_AT'              => now(),
            ]);
        }

        return response()->json(['message' => 'Selected patients saved successfully']);
    }


