                        :in_disc_remarks,
                        :in_disc_amt_by_doc,
                        :in_disc_amt_by_doc_no_fk,
                        :in_disc_amt_request_by_name,
                        :in_disc_amt_by_hosp,
                        :in_disc_amt_by_hosp_auth_by,
                        :in_au_entry_by,
                        :in_au_entry_session,
                        :in_au_entry_hospital_pk_no,
                        :in_ledgertrn_no,
                        :out_ledger_no,
                        :out_ledger_id,
                        :out_ledgertrn_no,
                        :out_error
                          ); end;");
                        $null = null;
                        // $payment->bindValue(':in_payment_date',$currentDate);
                        // $payment->bindValue(':in_payment_datetime', $currentDateTime);
                        $discount_return->bindValue(':in_ref_ledger_no_pk', $zero);
                        $discount_return->bindValue(':in_module_no_fk', $module_id);
                        $discount_return->bindValue(':in_patient_no_fk', $patientID);
                        $discount_return->bindValue(':in_admission_no_fk', $admissionID);
                        $discount_return->bindValue(':in_invoice_no_fk', $zero);
                        $discount_return->bindValue(':in_counter_su_no_fk', $zero);
                        $discount_return->bindValue(':in_ledger_amt_discount', $return_discount_amt);
                        $discount_return->bindValue(':in_cor_client_no_fk', $zero);
                        $discount_return->bindValue(':in_disc_type_lookup_no_fk', $zero);
                        $discount_return->bindValue(':in_disc_remarks', $remarks1, PDO::PARAM_STR);
                        $discount_return->bindValue(':in_disc_amt_by_doc', $null);
                        $discount_return->bindValue(':in_disc_amt_by_doc_no_fk', $null);
                        $discount_return->bindValue(':in_disc_amt_request_by_name', $null);
                        $discount_return->bindValue(':in_disc_amt_by_hosp', $null);
                        $discount_return->bindValue(':in_disc_amt_by_hosp_auth_by', $in_au_entry_by);
                        $discount_return->bindValue(':in_au_entry_by', $in_au_entry_by);
                        $discount_return->bindValue(':in_au_entry_session', $in_au_entry_session);
                        $discount_return->bindValue(':in_au_entry_hospital_pk_no', $hospital_id);
                        $discount_return->bindValue(':in_ledgertrn_no', $zero);

                        $out_error2 = $out_ledger_no = $out_ledger_id = $out_ledgertrn_no = "'0'";
                        $discount_return->bindParam(':out_ledger_no', $out_ledger_no, PDO::PARAM_INT);
                        $discount_return->bindParam(':out_ledger_id', $out_ledger_id, PDO::PARAM_STR, 500);
                        $discount_return->bindParam(':out_ledgertrn_no', $out_ledgertrn_no, PDO::PARAM_INT);
                        $discount_return->bindParam(':out_error', $out_error2, PDO::PARAM_STR, 500);
                        // dd($discount_return);
                        $discount_return->execute();

                        DB::commit();
                    }
                }
            }
            DB::commit();
            $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success', 'insert_id' => $out_ledger_no];


            return response()->json($message);
        } catch (\Exception $e) {
            DB::rollback();

            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
            return response()->json($message, 400);
        }
    }

