        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME,
        sum(DAY_SUM_ITEM_QTY) DAY_SUM_ITEM_QTY, sum(DAY_SUM_CANCEL_QTY) DAY_SUM_CANCEL_QTY, sum(DAY_SUM_INVOICEDTL_AMT_SALES+(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)-(DAY_SUM_ITEM_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SUM_INVOICEDTL_AMT_SALES,
        sum(DAY_SUM_INVOICEDTL_AMT_DIS) DAY_DISCOUNT,
        SUM(DAY_SUM_INVOICEDTL_AMT_SRVCRGU*DAY_SUM_ITEM_QTY-(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SERVICE_CHARGE
        from RPT_02_IPD_BILL_INV_DETAIL_VW
        where admission_no_pk = $admission_id

        and  ITY_GROUP_HEADER_NO = 4
        group by ADMISSION_NO_PK, PAR_ITEMTYPE_CODE, PAR_ITEM_TYPE_NAME
        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME");

        // and UPPER(PAR_ITEMTYPE_CODE) = UPPER('PHARMACY')

        $total_payment = DB::select("select sum(ledger_amt_payment) total_payment from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'PAYMENT'");
        $total_discount = DB::select("select sum(ledger_amt_discount) total_discount from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'DISCOUNT'");
        $total_payment_return = DB::select("select sum(ledger_amt_payment) total_payment from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'PAYMENTR'");
        $total_discount_return = DB::select("select sum(ledger_amt_discount) total_discount from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'DISCOUNTR'");


