            $total_discount_invst = DB::select("select sum(tot_discount) discount_invst from finc_pat_servicewisedtl_vw where admission_no_pk = $admission_id and UPPER(PARENT_TYPE_CODE) = UPPER('INVESTIGATION')");
            $total_discount_pharmacy = DB::select("select sum(tot_discount) discount_pharmacy from finc_pat_servicewisedtl_vw where admission_no_pk = $admission_id and UPPER(PARENT_TYPE_CODE) = UPPER('PHARMACY')");
        } else {
            $total_discount_hos_srv = DB::select("SELECT SUM (LEDGERDTL_AMT_DISCOUNT) discount_hossrv FROM finc_ledgerdtl dis , finc_ledgermst mst , sysc_itemtype type WHERE  dis.LEDGER_NO_FK = mst.LEDGER_NO_PK AND mst.ADMISSION_NO_fK = $admission_id and dis.ITEMTYPE_NO_FK=type.ITEMTYPE_NO_pk and ITEMTYPE_NO_PK not in (1,2,4)");
