            $total_discount_pharmacy = DB::select("SELECT SUM (LEDGERDTL_AMT_DISCOUNT) discount_pharmacy FROM finc_ledgerdtl dis , finc_ledgermst mst , sysc_itemtype type WHERE  dis.LEDGER_NO_FK = mst.LEDGER_NO_PK AND mst.ADMISSION_NO_fK = $admission_id and dis.ITEMTYPE_NO_FK=type.ITEMTYPE_NO_pk and ITEMTYPE_NO_PK = 4");
        }





        //dd($investigation);

        $bill_info = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "<>", "MED")->get();


        $bill_info_phr = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "=", "MED")->get();
        // dd($bill_info);
        $bill = DB::table("finc_admission_billpay")->where("admission_no_fk", $admission_id)->first();
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $userInfo = Auth::user();
        $paymentHistories_data = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join SYSC_MODULE mod on mod.MODULE_NO_PK = mst.MODULE_NO_FK
    		where mst.admission_no_fk=$admission_id and mod.module_code NOT IN ('PHR','PHR-I')   ");

        foreach ($paymentHistories_data as $value) {
            $paymentHistories = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }
        $paymentHistories_data_phr = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join SYSC_MODULE mod on mod.MODULE_NO_PK = mst.MODULE_NO_FK
    		where mst.admission_no_fk=$admission_id and mod.MODULE_CODE in ('PHR','PHR-I') ");

        foreach ($paymentHistories_data_phr as $value) {
            $paymentHistories_phr = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }

        if ($po_hospital_details->hospital_code != 'KBMH') {
            $pdf = App::make('dompdf.wrapper');
            $pdf = PDF::loadView("admin.ipd.ipd_business_office.ipd_new_draft_print_new", [
                'admission_info' => $admission_info,
                'paitent_info' => $paitent_info,
                'invoice_barcode' => $invoice_barcode,
                'pat_barcode' => $pat_barcode,
                'bill_info' => $bill_info,
                'bill' => $bill,
                'paymentHistories' => $paymentHistories,
                'po_hospital_details' => $po_hospital_details,
                'userInfo' => $userInfo,
                'bill_info_phr' => $bill_info_phr,
                'paymentHistories_phr' => $paymentHistories_phr,

                'hospital_service' => $hospital_service,
                'investigation' => $investigation,
                'pharmacy' => $pharmacy,
                'total_payment' => $total_payment,
                'total_discount' => $total_discount,
                'total_payment_return' => $total_payment_return,
                'total_discount_return' => $total_discount_return,

                'total_discount_hos_srv' => $total_discount_hos_srv,
                'total_discount_invst' => $total_discount_invst,
                'total_discount_pharmacy' => $total_discount_pharmacy,
            ]);
            // ->setPaper('a4', 'landscape');
            return $pdf->stream("IPD_draft_print.pdf", array("Attachment" => false));
        } else {
            return view("admin.ipd.ipd_request.ipd_draft_bill_kbmh", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr]);
        }
    }

