        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME,ITEM_NAME");


        $investigation = DB::select("select ADMISSION_NO_PK, PAR_ITEMTYPE_CODE, PAR_ITEM_TYPE_NAME
        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME,
        sum(DAY_SUM_ITEM_QTY) DAY_SUM_ITEM_QTY, sum(DAY_SUM_CANCEL_QTY) DAY_SUM_CANCEL_QTY, sum(DAY_SUM_INVOICEDTL_AMT_SALES+(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)-(DAY_SUM_ITEM_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SUM_INVOICEDTL_AMT_SALES,
        sum(DAY_SUM_INVOICEDTL_AMT_DIS) DAY_DISCOUNT,
        SUM(DAY_SUM_INVOICEDTL_AMT_SRVCRGU*DAY_SUM_ITEM_QTY-(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SERVICE_CHARGE
        from RPT_02_IPD_BILL_INV_DETAIL_VW
        where admission_no_pk = $admission_id
        and UPPER(PAR_ITEMTYPE_CODE) = UPPER('INVESTIGATION')
        group by ADMISSION_NO_PK, PAR_ITEMTYPE_CODE, PAR_ITEM_TYPE_NAME
        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME");


        $pharmacy = DB::select("select ADMISSION_NO_PK, PAR_ITEMTYPE_CODE, PAR_ITEM_TYPE_NAME
        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME,
        sum(DAY_SUM_ITEM_QTY) DAY_SUM_ITEM_QTY, sum(DAY_SUM_CANCEL_QTY) DAY_SUM_CANCEL_QTY, sum(DAY_SUM_INVOICEDTL_AMT_SALES+(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)-(DAY_SUM_ITEM_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SUM_INVOICEDTL_AMT_SALES,
        sum(DAY_SUM_INVOICEDTL_AMT_DIS) DAY_DISCOUNT,
        SUM(DAY_SUM_INVOICEDTL_AMT_SRVCRGU*DAY_SUM_ITEM_QTY-(DAY_SUM_CANCEL_QTY*DAY_SUM_INVOICEDTL_AMT_SRVCRGU)) DAY_SERVICE_CHARGE
        from RPT_02_IPD_BILL_INV_DETAIL_VW
        where admission_no_pk = $admission_id
        and UPPER(PAR_ITEMTYPE_CODE) = UPPER('PHARMACY')
        group by ADMISSION_NO_PK, PAR_ITEMTYPE_CODE, PAR_ITEM_TYPE_NAME
        , ITY_GROUP_HEADER_CODE, ITY_GROUP_HEADER_NAME");


        $total_payment = DB::select("select sum(ledger_amt_payment) total_payment from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'PAYMENT'");
        $total_discount = DB::select("select sum(ledger_amt_discount) total_discount from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'DISCOUNT'");
        $total_payment_return = DB::select("select sum(ledger_amt_payment) total_payment from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'PAYMENTR'");
        $total_discount_return = DB::select("select sum(ledger_amt_discount) total_discount from rpt_02_ipd_bill_payment_vw where admission_no_fk = $admission_id and trn_type_code = 'DISCOUNTR'");



        $total_discount_hos_srv = DB::select("select sum(tot_discount) discount_hossrv from finc_pat_servicewisedtl_vw where admission_no_pk = $admission_id and UPPER(PARENT_TYPE_CODE) not in  ('INVESTIGATION','PHARMACY')");
        $total_discount_invst = DB::select("select sum(tot_discount) discount_invst from finc_pat_servicewisedtl_vw where admission_no_pk = $admission_id and UPPER(PARENT_TYPE_CODE) = UPPER('INVESTIGATION')");
        $total_discount_pharmacy = DB::select("select sum(tot_discount) discount_pharmacy from finc_pat_servicewisedtl_vw where admission_no_pk = $admission_id and UPPER(PARENT_TYPE_CODE) = UPPER('PHARMACY')");



        //dd($investigation);

        $bill_info = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "<>", "MED")->get();


        $bill_info_phr = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "=", "MED")->get();
        // dd($bill_info);
        $bill = DB::table("finc_admission_billpay")->where("admission_no_fk", $admission_id)->first();
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $userInfo = Auth::user();
        $paymentHistories_data = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join SYSC_MODULE mod on mod.MODULE_NO_PK = mst.MODULE_NO_FK
    		where mst.admission_no_fk=$admission_id and mod.module_code NOT IN ('PHR','PHR-I')   ");

        foreach ($paymentHistories_data as $value) {
            $paymentHistories = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }
        $paymentHistories_data_phr = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join SYSC_MODULE mod on mod.MODULE_NO_PK = mst.MODULE_NO_FK
    		where mst.admission_no_fk=$admission_id and mod.MODULE_CODE in ('PHR','PHR-I') ");

        foreach ($paymentHistories_data_phr as $value) {
            $paymentHistories_phr = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }



        // dd($paymentHistories);
        if ($po_hospital_details->hospital_code != 'KBMH') {

            $pdf = App::make('dompdf.wrapper');
            $pdf = PDF::loadView("admin.ipd.ipd_business_office.ipd_new_final_print", [
                'admission_info' => $admission_info,
                'paitent_info' => $paitent_info,
                'invoice_barcode' => $invoice_barcode,
                'pat_barcode' => $pat_barcode,
                'bill_info' => $bill_info,
                'bill' => $bill,
                'paymentHistories' => $paymentHistories,
                'po_hospital_details' => $po_hospital_details,
                'userInfo' => $userInfo,
                'bill_info_phr' => $bill_info_phr,
                'paymentHistories_phr' => $paymentHistories_phr,

                'hospital_service' => $hospital_service,
                'investigation' => $investigation,
                'pharmacy' => $pharmacy,
                'total_payment' => $total_payment,
                'total_discount' => $total_discount,
                'total_payment_return' => $total_payment_return,
                'total_discount_return' => $total_discount_return,
                'total_discount_hos_srv' => $total_discount_hos_srv,
                'total_discount_invst' => $total_discount_invst,
                'total_discount_pharmacy' => $total_discount_pharmacy,
            ]);
            return $pdf->stream("IPD_final_print.pdf", array("Attachment" => false));
        } else {
            return view("admin.ipd.ipd_request.ipd_draft_bill_kbmh", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr]);
        }
    }

