    public function dischargeRequestByDoctor($admissionID = "")
    {
        $dortor_id = DB::table('ipd_admitted_patlist_vw a')->where('a.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))->select('a.primary_doctor_no_fk', 'b.full_name')->leftjoin('doctor_info_vw b', 'a.primary_doctor_no_fk', '=', 'b.person_no_pk')->where('admission_no_pk', $admissionID)->first();
        // dd($dortor_id);
