    public function saveIpdBillLock(Request $request)
    {
        // dd($request->all());
        DB::beginTransaction();
        try {
            if($request->hdn_lock_ind){
                $data = [
                    'lock_ind' => '',
                    'lock_date' => '',
                    'lock_by' => '',
                    'lock_remarks' => $request->remarks
                ];
            }else{
                $data = [
                    'lock_ind' => 1,
                    'lock_date' => date('Y-m-d H:i'),
                    'lock_by' => Auth::id(),
                    'lock_remarks' => $request->remarks
                ];
            }

            DB::table('ipd_admission')->where('admission_no_pk', $request->hdn_admission_id)->update($data);
            DB::commit();
            $message = ['msg' => ' Save successfully.', 'title' => 'Success'];
            return response()->json($message, 200);
        } catch (\Throwable $th) {
            BD::rollbark();
            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
            return response()->json($message, 500);
        }
    }
    public function updateDischargeRequest(Request $request)
    {

        try {
            $data = [
                'dis_req_ind' => 1,
                'dis_req_by' => $request->hdn_doctor_id,
                'dis_req_time' => date("Y-m-d H:i:s"),
            ];
            DB::table('ipd_admission')->where('admission_no_pk', $request->hdn_admission_id)->update($data);
            DB::commit();
            $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Exception $e) {
            DB::rollback();
            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }
        return response()->json($message);
    }

    public function updateIpdDischarge($admissionID = "")
    {
        try {
            if(Session::get('user.ses_hospital_code') != "KPJ"){
                if (DB::table('ipd_admission_bed')
                    ->where('admission_no_fk', $admissionID)
                    ->whereNull('END_TIME')
                    ->exists()) {
                    throw new Exception('Please at first generate Bed Charge');
                }
            }

            if (Session::get('user.ses_hospital_code') == "KPJ") {
                $lockCheck = DB::table('ipd_admitted_patlist_vw')
                    ->where('admission_no_pk', $admissionID)
                    ->value('lock_ind');

                if ($lockCheck != 1) {
                    throw new Exception('Please at first Bill Lock');
                }
            }



            if (Session::get('user.ses_hospital_code') == "JKMH") {
                $data = [
                    'dis_req_ind'   => 1,
                    'dis_req_by'    => Auth::id(),
                    'dis_req_time'  => date("Y-m-d H:i:s"),
                    'dis_ind'       => 1,
                    'dis_by'        => Auth::id(),
                    'dis_date'      => date("Y-m-d"),
                    'dis_datetime'  => date("Y-m-d H:i:s"),
                ];
            } else {
                $data = [
                    'dis_ind'      => 1,
                    'dis_by'       => Auth::id(),
                    'dis_date'     => date("Y-m-d"),
                    'dis_datetime' => date("Y-m-d H:i:s"),
                ];
            }

            $bed = DB::table("ipd_admission a")
                ->select("a.admission_no_pk", "a.curr_bed_no_fk", "w.ward_name", "b.bed_name", "s.serviceunit_name", "b.bed_no_pk")
                ->leftJoin("ipds_ward w", "a.curr_ward_no_fk", "=", "w.ward_no_pk")
                ->leftJoin("ipds_bed b", "a.curr_bed_no_fk", "=", "b.bed_no_pk")
                ->leftJoin("sysc_serviceunit s", "a.su_no_fk", "=", "s.serviceunit_no_pk")
                ->where("admission_no_pk", $admissionID)
                ->orderBy("admission_no_pk", "desc")
                ->first();

            DB::table('ipd_admission')->where('admission_no_pk', $admissionID)->update($data);

            $auth_id    = Auth::id();
            $hospital_id = Session::get('user.ses_hospital_no_pk');
            $hospital_code = Session::get('user.ses_hospital_code');
            $pdo = DB::getPdo();

            $journalCode = '';
            $accError = '';
            $outError = '';

            /**
             * যদি KPJ hospital হয় → আগে Revenue Posting হবে
             */
            // if ($hospital_code == "KPJ") {
            //     $prcAccounts = $pdo->prepare("BEGIN pkg_v1_accounts.prc_ipdrevenue(
            //         :in_narration,
            //         :in_integration_type,
            //         :in_discharge_date,
            //         :in_module_no_fk,
            //         :in_admission_no_fk,
            //         :in_au_entry_by,
            //         :in_au_entry_session,
            //         :in_au_entry_hospital_pk_no,
            //         :out_jurnal_code,
            //         :out_error
            //     ); END;");

            //     $narration        = 'IPD Sales Revenue Posting';
            //     $integration_type = 'SALES';
            //     $discharge_date   = date("Y-m-d");
            //     $module_no_fk     = 2;
            //     $entry_session    = "SESSION123";

            //     $prcAccounts->bindParam(':in_narration', $narration);
            //     $prcAccounts->bindParam(':in_integration_type', $integration_type);
            //     $prcAccounts->bindParam(':in_discharge_date', $discharge_date);
            //     $prcAccounts->bindParam(':in_module_no_fk', $module_no_fk);
            //     $prcAccounts->bindParam(':in_admission_no_fk', $admissionID);
            //     $prcAccounts->bindParam(':in_au_entry_by', $auth_id);
            //     $prcAccounts->bindParam(':in_au_entry_session', $entry_session);
            //     $prcAccounts->bindParam(':in_au_entry_hospital_pk_no', $hospital_id);
            //     $prcAccounts->bindParam(':out_jurnal_code', $journalCode, PDO::PARAM_STR|PDO::PARAM_INPUT_OUTPUT, 50);
            //     $prcAccounts->bindParam(':out_error', $accError, PDO::PARAM_STR|PDO::PARAM_INPUT_OUTPUT, 4000);
            //     $prcAccounts->execute();
            //     // dd($accError);


            //     if ($accError != '000') {
            //         DB::rollback();
            //         return response()->json(['msg' => 'Revenue Posting Failed - ' . $accError, 'title' => 'Error']);
            //     }
            // }

            /**
             * Bed Tracking call (সব hospital এর জন্য common)
             */
            $bed_no = null;
            $entry_session = "session";
            $discharge_ind = 1;
            $start_date = date("Y-m-d H:i:s");

            $bedTransfer = $pdo->prepare("BEGIN pkg_billing_ipd_v0.prc_bed_tracking(
                :in_admission_no_fk,
                :in_old_bed_no_fk,
                :in_new_bed_no_fk,
                :in_start_time,
                :in_discharge_ind,
                :in_au_entry_by,
                :in_au_entry_session,
                :in_au_entry_hospital_pk_no,
                :out_error
            ); END;");

            $bedTransfer->bindParam(':in_admission_no_fk', $admissionID);
            $bedTransfer->bindParam(':in_old_bed_no_fk', $bed->bed_no_pk);
            $bedTransfer->bindParam(':in_new_bed_no_fk', $bed_no);
            $bedTransfer->bindParam(':in_start_time', $start_date);
            $bedTransfer->bindParam(':in_discharge_ind', $discharge_ind);
            $bedTransfer->bindParam(':in_au_entry_by', $auth_id);
            $bedTransfer->bindParam(':in_au_entry_session', $entry_session);
            $bedTransfer->bindParam(':in_au_entry_hospital_pk_no', $hospital_id);
            $bedTransfer->bindParam(':out_error', $outError, PDO::PARAM_STR|PDO::PARAM_INPUT_OUTPUT, 500);

            $bedTransfer->execute();

            if ($outError == '000') {
                DB::commit();
                $msg = 'Discharge Successfully'
                    . '<br> Department: ' . $bed->serviceunit_name
                    . '<br> Ward: ' . $bed->ward_name
                    . '<br> Bed Name: ' . $bed->bed_name;

                // if ($hospital_code == "KPJ") {
                //     $msg .= '<br> Journal Code: ' . $journalCode;
                // }

                $message = ['msg' => $msg, 'title' => 'Success'];
            } else {
                DB::rollback();
                $message = ['msg' => 'Bed Transfer Process Failed - ' . $outError, 'title' => 'Error'];
            }
        } catch (\Exception $e) {
            DB::rollback();
            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($message);
    }

