                            'duration_mu' => isset($request->medicine_duration_mu[$i]) ? $request->medicine_duration_mu[$i] : '',
                            'continue_ind' => isset($continue_ind_val) ? 1 : 0,
                            'patient_no_fk' => $request->hdn_patient_id,
                            'approve_ind' => 0,
                            'status' => 1,
                            'au_entry_session' => 'SESSION',
                            'ipd_entry_by' => Auth::id(),
                            'au_entry_by' => Auth::id(),
                            'au_entry_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                            'au_entry_at' => date('Y-m-d H:i:s'),
                        ];
                        // dd( $pressData);
                        DB::table('psn_t_prescription_med')->insert($pressData);



                        $discharge_med_pk_no = $sequence->nextValue('discharge_med_pk_no_seq');
                        $continue_ind_val = $request->input('is_continue_' . $request->hdn_item_id[$i]);
                        $data = [
                            'discharge_med_pk_no' => $discharge_med_pk_no,
                            'discharge_med_mst_id' => ($coutRow + 1),
                            'admission_no_fk' => $request->hdn_admission_id,
                            'item_no_fk' => isset($request->hdn_item_id[$i]) ? $request->hdn_item_id[$i] : '',
                            'item_name' => isset($request->hdn_item_name[$i]) ? $request->hdn_item_name[$i] : '',
                            'item_qty' => isset($request->medicine_quantity[$i]) ? $request->medicine_quantity[$i] : '',
                            'med_taken_instruction' => isset($request->instruction[$i]) ? $request->instruction[$i] : '',
                            'route' => isset($request->medicine_route[$i]) ? $request->medicine_route[$i] : '',
                            'dosage' => isset($request->medicine_dose[$i]) ? $request->medicine_dose[$i] : '',
                            'duration' => isset($request->medicine_duration_type[$i]) ? $request->medicine_duration_type[$i] : '',
                            'duration_mu' => isset($request->medicine_duration_mu[$i]) ? $request->medicine_duration_mu[$i] : '',
                            'continue_ind' => isset($continue_ind_val) ? 1 : 0,
                            'patient_no_fk' => $request->hdn_patient_id,
                            'prescription_no_fk' => $press_pk_no,
                            'au_entry_session' => 'SESSION',
                            'au_entry_by' => Auth::id(),
                            'au_entry_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                            'au_entry_at' => date('Y-m-d'),
                        ];
                        //   dump($data);
                        // dd($request->instruction[$i]);

                        DB::table('ipd_discharge_med')->insert($data);
                    }
                }
                //  dd($request->medicine_duration_mu);
            }
            // dd($pressData);
            DB::commit();
            $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Exception $e) {
            DB::rollback();
            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }
        return response()->json($message);
    }
