    public function ipdSummaryBillPrintV2($admission_id = "")
    {
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_id)->first();
        $paitent_info = DB::table('patient_info_vw')->where('patient_no_pk', $admission_info->patient_no_fk)->first();
        // dd($admission_info);
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        // $barcode->setText('62542525245');
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($paitent_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();

        $bill = DB::table("finc_ipdpatientbill_vw")->where("admission_no_pk", $admission_id)->get();
        $advancePayment = DB::table("finc_ledgermst")
            ->leftJoin('wsec_user', 'wsec_user.user_no_pk', '=', 'finc_ledgermst.au_entry_by')
            ->select('finc_ledgermst.ledger_no_pk', 'finc_ledgermst.ledger_datetime', 'finc_ledgermst.ledger_amt_payment', 'finc_ledgermst.pay_type', 'wsec_user.user_fullname')
            ->where("admission_no_fk", $admission_id)
            ->where('trn_type_code', 'PAYMENT')
            ->whereIn('pay_type', ['ADVANCE', 'REFUND','FINAL BILL'])
            ->get();

        $paymentHistories = DB::select(DB::raw("select sum(mst.ledger_amt_payment) ledger_amt_payment,sum( mst.disc_amt_by_doc) disc_amt_by_doc,sum(mst.disc_amt_by_hosp) disc_amt_by_hosp,sum(mst.ledger_amt_discount) ledger_amt_discount,
                            trunc(mst. LEDGER_DATE) as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
                            from finc_ledgermst mst left join sysc_module mod
                            on mod.module_no_pk = mst.module_no_fk join wsec_user uname
                            on mst.au_entry_by=uname.user_no_pk
                            where mst.admission_no_fk= $admission_id
                            and mst.ledger_amt_payment > 0
                            group by trunc(mst. LEDGER_DATE),uname.user_name ,mst.pay_type
                            order by trunc(mst. LEDGER_DATE) asc"));


        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $userInfo = Auth::user();

        // Bed Calculation
        $bed_history = DB::table('ipd_admission_bed')
            ->leftJoin('ipds_bed', 'ipds_bed.bed_no_pk', '=', 'ipd_admission_bed.bed_no_fk')
            ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipd_admission_bed.ward_no_fk')
            ->select(
                'ipd_admission_bed.ipd_adm_bed_no_pk',
                'ipd_admission_bed.ipd_adm_bed_date',
                'ipd_admission_bed.admission_no_fk',
                'ipd_admission_bed.sl_no',
                'ipd_admission_bed.start_time',
                'ipd_admission_bed.end_time',
                'ipd_admission_bed.bed_no_fk',
                'ipd_admission_bed.ward_no_fk',
                'ipd_admission_bed.su_no_fk',
                'ipd_admission_bed.bed_assignment_type',
                'ipds_bed.bed_no_pk',
                'ipds_bed.bed_name',
                'ipds_bed.bed_charge_amount',
                'ipds_ward.ward_name',
                'ipd_admission_bed.status'
            )->where('ipd_admission_bed.admission_no_fk', $admission_id)->whereRaw('nvl(ipd_admission_bed.calculation_ind,0) = 0')
            ->orderByDesc('ipd_admission_bed.end_time')
            ->get();
        $charge = 0;
        $bed_days = 0;
        foreach ($bed_history as $item) {
            // Assuming $startDateTime and $endDateTime are Carbon instances or datetime strings
            $startDateTime = Carbon::parse($item->start_time);
            $endDateTime = $item->end_time ? Carbon::parse($item->end_time) : Carbon::now();

            // Admit time calculation
            if ($startDateTime->hour >= 12) {
                $admittedTime = $startDateTime->copy()->setTime(12, 0);
            } elseif ($startDateTime->hour < 10) {
                $admittedTime = $startDateTime->copy()->subDay()->setTime(12, 0);
            } elseif ($startDateTime->hour >= 10 && $startDateTime->hour < 12) {
                $admittedTime = $startDateTime->copy()->setTime(12, 0);
            } else {
                $admittedTime = $startDateTime->copy()->setTime(12, 0);
            }

            // End time calculation
            $dischargeTime = $endDateTime->copy()->setTime(12, 0);
            $add_day = ($startDateTime->hour < 10) ? 1 : 0;
            $add_end_day = ($endDateTime->hour >= 12) ? 1 : 0;

            $days = $admittedTime->diffInDays($dischargeTime) + $add_day + $add_end_day;
            $item->days = $days == 0 ? 1 : $days;
            $item->total = $item->days * $item->bed_charge_amount;
        }


        $pdf = App::make('dompdf.wrapper');
        $pdf = PDF::loadView("admin.ipd.ipd_business_office.ipd_summary_bill_print_v2", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'advancePayment' => $advancePayment, 'bed_history' => $bed_history]);
        return $pdf->stream("IPD_final_bill_print.pdf", array("Attachment" => false));

    }

