    //    added By Nazmul Date 23may2021
    public function editIpdAdmission(Request $request, $admission_id)
    {

        $ipd_admissions = DB::table("ipd_admitted_patlist_vw a")
            ->select('b.*', 'a.old_bed_no_fk', 'a.new_ward_no_fk', 'a.new_bed_no_fk', 'a.new_su_no_fk', 'b.covid_vaccinated_ind', 'ser.item_name')
            ->leftJoin("ipd_admission b", "a.admission_no_pk", "=", "b.admission_no_pk")
            ->leftJoin("sysc_serviceitem ser", "ser.item_no_pk", "=", "a.pkg_item_no_fk")
            ->where("a.admission_no_pk", $admission_id)
            ->get();

        // $this->model->show($admission_id);
        $ipd_admission = $ipd_admissions[0];
        // dd($ipd_admission->new_ward_no_fk);



        $IpdAdmissionDetails = $this->model2->show($admission_id);
        // dd($IpdAdmissionDetails);
        $admission_data = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_id)->first();
        $requestDepts = DB::table('sysc_serviceunit')->where('ipd_ind', 1)->get(['serviceunit_name', 'serviceunit_no_pk']);

        if (Session::get('user.ses_hospital_code') == 'UNICO') {
            $destinationWards = DB::table('ipds_ward')
                ->join('IPDS_BED', 'ipds_ward.ward_no_pk', '=', 'IPDS_BED.ward_no_fk')
                ->join('sysc_serviceunit', 'sysc_serviceunit.serviceunit_no_pk', '=', 'ipds_ward.service_unit_no_fk')
                ->select('ipds_ward.ward_name', 'ipds_ward.ward_no_pk', 'ipds_ward.service_unit_no_fk', DB::raw('COUNT(IPDS_BED.bed_no_pk) as bed_count'))
                ->where('ipds_ward.au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))
                ->where('ipd_ind', 1)
                ->where('ipds_bed.status', 1)
                ->where('ipds_bed.bed_status', '!=', null)
                ->groupBy('ipds_ward.ward_name', 'ipds_ward.ward_no_pk', 'ipds_ward.service_unit_no_fk')
                ->orderBy('ipds_ward.ward_no_pk', 'asc')
                ->get()
                ->toArray();
            $bed_data = DB::table('ipds_bed')->leftJoin('ipd_admitted_patlist_vw', function ($join) {
                $join->on('ipds_bed.bed_no_pk', '=', 'ipd_admitted_patlist_vw.new_bed_no_fk')
                    ->where('ipd_admitted_patlist_vw.dis_ind', '=', 0);
            })
                ->leftJoin('ipds_ward', 'ipds_ward.ward_no_pk', '=', 'ipds_bed.ward_no_fk')
                ->select('ipds_bed.*', 'ipd_admitted_patlist_vw.admission_no_pk', 'ipd_admitted_patlist_vw.patient_name', 'ipd_admitted_patlist_vw.patient_code', 'ipd_admitted_patlist_vw.primary_doctor_name', 'ipd_admitted_patlist_vw.admission_date', 'ipd_admitted_patlist_vw.new_bed_name', 'ipd_admitted_patlist_vw.new_ward_name', 'ipds_ward.ward_name', 'ipd_admitted_patlist_vw.dis_req_ind', 'ipd_admitted_patlist_vw.dis_ind', 'ipd_admitted_patlist_vw.ns_receive_ind')
                ->where('ipds_bed.status', 1)
                ->where('ipds_bed.bed_status', '!=', null)
                // ->where('ipds_bed.ward_no_fk', $request->bed_value)
                ->where('ipds_bed.bed_no_pk', $ipd_admissions[0]->new_bed_no_fk)
                ->orderBy('ipds_bed.bed_sl_no', 'asc')
                ->get();
            return Template::loadview("admin.ipd.ipd_request.quick_admission_v2", [
                'requestDepts' => $requestDepts,
                'destinationWards' => $destinationWards,
                // 'patientConditions' => $patientConditions,
                // 'arrivalModes' => $arrivalModes,
                // 'marital_status' => $marital_status,
                // 'chiefcom' => $chiefcom,
                // 'priority' => $priority,
                // 'gender' => $gender,
                // 'marsts' => $marsts,
                // 'bloodg' => $bloodg,
                // 'visit_types' => $visit_types,
                'ipd' => $ipd_admission,
                'IpdAdmissionDetails' => $IpdAdmissionDetails,
                'data' => $bed_data,
