    public function bedTransfer($admissionId)
    {
        $old_bed_id = DB::table("ipd_admitted_patlist_vw a")->select("a.new_bed_no_fk as bed_no_fk", 'a.new_su_name', "w.ward_name", "b.bed_name", "s.serviceunit_name")
            // DB::table("ipd_admission_bed a")->select("a.bed_no_fk","w.ward_name","b.bed_name","s.serviceunit_name")
            ->leftJoin("ipds_ward w", "a.new_ward_no_fk", "=", "w.ward_no_pk")
            ->leftJoin("ipds_bed b", "a.new_bed_no_fk", "=", "b.bed_no_pk")
            ->leftJoin("sysc_serviceunit s", "a.su_no_fk", "=", "s.serviceunit_no_pk")
            ->where("admission_no_pk", $admissionId)
            ->where('a.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->first();

        // dd($old_bed_id);
        $requestDepts = DB::table('sysc_serviceunit')
            ->where('ipd_ind', 1)
            ->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->get(['serviceunit_name', 'serviceunit_no_pk']);
        $ward = Ward::select('ward_no_pk', 'ward_name')
            ->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))
            ->get();
        $bed_cat = $this->getLookupListByCode("BED");
        $data = DB::table('ipds_bed')->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_no_pk'))->where('STATUS', 1)->get();

        return Template::loadview("admin.ipd.bed_transfer.bed_transfer", [
            'ward' => $ward,
            'requestDepts' => $requestDepts,
            'bed_cat' => $bed_cat,
            'admissionId' => $admissionId,
            'old_bed_id' => $old_bed_id,
            'data' => $data,
        ]);
    }
    public function bedTransferProcess(Request $request)
    {

        $auth_id = Auth::id();
        DB::beginTransaction();
        $admission_no_fk = $request->admission_id;
        $old_bed_id = $request->old_bed_id;

        $bed_no = $request->bed_id;
        $entry_session = "session";
        // $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
        $hospital_id = Session::get('user.ses_hospital_no_pk');
        $discharge_ind = 0;
        $start_date = date("Y-M-d H:i:s");
        $outError = $out_invoice_id = $out_invoice_no = '';
        $su_no = $request->request_department ? $request->request_department : $request->su_id;

        $department = DB::table('sysc_serviceunit')->select('serviceunit_name')->where('serviceunit_no_pk', $su_no)->first()->serviceunit_name;

        $ref_from_emr_ind = ($department == 'EMERGENCY' || $request->ref_from_emr_ind != '') ? 2 : 1;

        $ref_emer_check = DB::table('IPD_ADMISSION')->select('iptype_ind')->where('admission_no_pk', $admission_no_fk)->first()->iptype_ind;
        $ref_emer_ind = '';
        if ($ref_emer_check == 2) {
            $ref_emer_ind = 1;
        }

        DB::table('ipd_admission')->where('admission_no_pk', $admission_no_fk)->update([
            'ref_from_emr_ind' => $ref_emer_ind,
            'iptype_ind' => $ref_from_emr_ind,
        ]);
        DB::commit();


        $pdo = DB::getPdo();

        $bedTransfer = $pdo->prepare("begin pkg_billing_ipd_v0.prc_bed_tracking(:in_admission_no_fk,:in_old_bed_no_fk,:in_new_bed_no_fk,:in_start_time,:in_discharge_ind,:in_au_entry_by,:in_au_entry_session,:in_au_entry_hospital_pk_no,:out_error); end;");

        $bedTransfer->bindParam(':in_admission_no_fk', $admission_no_fk);
        $bedTransfer->bindParam(':in_old_bed_no_fk', $old_bed_id);
        $bedTransfer->bindParam(':in_new_bed_no_fk', $bed_no);
        $bedTransfer->bindParam(':in_start_time', $start_date);
        $bedTransfer->bindParam(':in_discharge_ind', $discharge_ind);
        $bedTransfer->bindParam(':in_au_entry_by', $auth_id);
        $bedTransfer->bindParam(':in_au_entry_session', $entry_session);
        $bedTransfer->bindParam(':in_au_entry_hospital_pk_no', $hospital_id);
        $bedTransfer->bindParam(':out_error', $outError, PDO::PARAM_STR, 500);
        // dd( $bedTransfer);
        $bedTransfer->execute();

        if ($outError == '000') {
            DB::commit();
            $message = ['msg' => 'Bed Transfer Process completed successfully', 'title' => 'Success'];

            // ['msg' => 'Bed Transfer Process completed successfully.', 'title' => 'Success'];


        } else {

            DB::rollback();
            $message = ['msg' => 'Bed Transfer Process Failed' . $outError, 'title' => 'Error'];
        }

        return json_encode($message);
    }

