    public function assignBed($adms_no = "", $wrd_name = "", $wrd_no = "", $bed_no = "")
    {
        $ipds_beds = DB::table('ipds_bed')
            ->where("ward_no_fk", "=", $wrd_no)
            // ->where('au_entry_hospital_no_fk', Session::get('user.ses_hospital_id'))
            ->orderBy('bed_no_pk', 'asc')
            ->get()
            ->toArray();

        $bedStats['total_beds'] = count($ipds_beds);
        $bedStats['available'] = 0;
        $bedStats['occupied'] = 0;
        $bedStats['not_ready'] = 0;

        if (!empty($ipds_beds)) {
            foreach ($ipds_beds as $ipds_bed) {
                if ($ipds_bed->bed_status == 1) {
                    $bedStats['available']++;
                } else if ($ipds_bed->bed_status == 2) {
                    $bedStats['occupied']++;
                } else if ($ipds_bed->bed_status == 3) {
                    $bedStats['not_ready']++;
                }
            }
        }

        return Template::loadview("admin.ipd.nurse_station.assign_bed", [
            'ipds_beds' => $ipds_beds,
            'bedStats' => $bedStats,
            'ward_name' => $wrd_name,
            'ward_no' => $wrd_no,
            'admission_no' => $adms_no,
            'bed_no' => $bed_no,
            //'bed_no' => 3,
        ]);
    }


    public function updateAssignBed(Request $request)
    {
        try {
            DB::table('ipd_admission')
                ->where('admission_no_pk', $request->admission_no_pk)
                ->update([
                    'curr_bed_no_fk' => $request->curr_bed_no_fk,
                    'curr_ward_no_fk' => $request->ward_no_fk,
                    'au_update_at' => date('Y-m-d'),
                    'au_update_session' => "SESSION",
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                ]);
            DB::table('ipds_bed')
                ->where('bed_no_pk', $request->curr_bed_no_fk)
                ->update([
                    'bed_status' => 2,
                    'au_update_at' => date('Y-m-d'),
                    'au_update_session' => "SESSION",
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                ]);
            if ($request->prev_bed_no_fk != "NaN") {
                DB::table('ipds_bed')
                    ->where('bed_no_pk', $request->prev_bed_no_fk)
                    ->update([
                        'bed_status' => 1,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                    ]);
            }
            $this->message = ['msg' => 'Data Successfully updated', 'title' => 'Success',];
        } catch (\Exception $e) {
            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($this->message);
    }

    public function nurseStationPatientDetails($patient_id = "", $admission_uid = "", $type = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->get()->first();

        $duration_mu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_name");
        $communicated_by = $this->getLookupListByCode("IPDPSNMEDIA");

        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");
        $dose = $this->getPresLookupListByCode("DOSE", "pres_lookupdata_name");
        $meddurmu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_code");
        $route = $this->getPresLookupListByCode("ROUTE", "pres_lookupdata_name");
        $ipd_followup_type = $this->getLookupListByCode("IPDFOLLOWUPTYPE");

        $ipd_vitals = DB::table('psn_t_patvitals_ipd_vw')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $patient_info->admission_no_pk)->orderBy('vital_no_pk', 'desc')->get()->toArray();

        // - NVL(b.ret_quantity,0)
        $ipd_med_lists = DB::select("select DISTINCT psn_t_prescription_med_vw.prescription_med_no_pk,psn_t_prescription_med_vw.pack_type, psn_t_prescription_med_vw.prescription_no_fk, psn_t_prescription_med_vw.au_entry_at,psn_t_prescription_med_vw.item_name,psn_t_prescription_med_vw.dosage,psn_t_prescription_med_vw.duration,psn_t_prescription_med_vw.duration_mu,psn_t_prescription_med_vw.item_qty,psn_t_prescription_med_vw.uom_txt,psn_t_prescription_med_vw.au_entry_by au_name,psn_t_prescription_med_vw.au_entry_at au_date,psn_t_prescription_med_vw.instruction_take,psn_t_prescription_med_vw.ipd_instructed_doc_name,psn_t_prescription_med_vw.ipd_instruct_media_name,psn_t_prescription_med_vw.item_no_fk,psn_t_prescription_med_vw.uom_no_fk,psn_t_prescription_med_vw.admission_pk_no,psn_t_prescription_med_vw.au_entry_at,psn_t_prescription_med_vw.au_entry_at,psn_t_prescription_med_vw.patient_no_fk,(NVL(b.issue_quantity,0) - ( NVL(c.teken_qty,0)  + NVL(b.ret_quantity,0) + NVL(b.after_ret_quantity,0)) ) as current_qty , NVL(b.ret_quantity,0) + NVL(b.after_ret_quantity,0) as ret_quantity , NVL(b.req_quantity,0) as req_quantity
        from    psn_t_prescription_med_vw
            left join
              (select item_no_fk, admission_no_fk ,sum (phr_requisition_item_vw.issue_quantity) as issue_quantity, sum (phr_requisition_item_vw.return_quantity)  as ret_quantity,sum(phr_requisition_item_vw.return_after_receive_qty) as after_ret_quantity, sum (phr_requisition_item_vw.req_quantity) as req_quantity from  phr_requisition_item_vw group by  item_no_fk, admission_no_fk) b
             on psn_t_prescription_med_vw.admission_pk_no = b.admission_no_fk and b.item_no_fk = psn_t_prescription_med_vw.item_no_fk
            left join
              (select item_pk_no, admission_no_fk ,sum (ipd_prescription_med_nsadm.item_qty) as teken_qty from  ipd_prescription_med_nsadm group by  item_pk_no, admission_no_fk) c on psn_t_prescription_med_vw.admission_pk_no = c.admission_no_fk and c.item_pk_no = psn_t_prescription_med_vw.item_no_fk

             where psn_t_prescription_med_vw.admission_pk_no = $patient_info->admission_no_pk and psn_t_prescription_med_vw.continue_ind = 1 order by psn_t_prescription_med_vw.prescription_med_no_pk DESC");

        $ipd_med_list = [];
        foreach ($ipd_med_lists as $key => $value) {
            $ipd_med_list[$value->item_no_fk] = $value;
        }
        $extra_med = DB::table('psn_t_prescription_med')->select('psn_t_prescription_med.*', 'hrms_personnel.full_name as ipd_instructed_doc_name')->leftJoin('hrms_personnel', 'hrms_personnel.person_no_pk', '=', 'psn_t_prescription_med.ipd_instruct_doc_person_no_fk')->where('admission_pk_no', $patient_info->admission_no_pk)->where('item_no_fk', 0)->get();
        //  dd($extra_med);

        $ipd_investigations = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->whereIn('LOOKUPDATA_UID', ['RAD', 'LAB'])->orderBy('au_entry_at', 'desc')->get()->toArray();
        //        $ipd_ot_list = DB::table('opt_ot_confirmlist_wl_vw')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $patient_info->admission_no_pk)->orderBy('ot_req_date', 'desc')->get()->toArray();
        $ipd_diet_list = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->where('LOOKUPDATA_UID', 'FOOD')->orderBy('au_entry_at', 'desc')->get()->toArray();

        $ipd_advice_plan_assessment = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->orderBy('au_entry_at', 'desc')->get()->toArray();

        $ipd_otherServices = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->where('LOOKUPDATA_UID', 'SERVICE')->orderBy('au_entry_at', 'desc')->get()->toArray();
        $ipd_discontinue_med_list = DB::table('psn_t_prescription_med_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->where('continue_ind', 0)->orderBy('au_entry_at', 'desc')->get()->toArray();
        $ipd_ot_list = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient_id)->where('admission_pk_no', $patient_info->admission_no_pk)->where('LOOKUPDATA_UID', 'SUR')->orderBy('au_entry_at', 'desc')->get()->toArray();

        //Indented Medicine
        $indented_items = DB::table('IPD_PATINDENTMST_MED_VW')->where('issue_ind', 1)->where('patient_no_fk', $patient_id)->orderBy('patindentdtl_no_pk', 'desc')->get();
        $clinical_data = DB::table('psn_t_prescription')
            ->select('prescription_uid', 'au_entry_at', 'clinical_symptoms', 'diagnosis')
            ->where('patient_no_fk', $patient_id)
            ->get();

        Session(['current_route' => url()->current()]);


        $stores = DB::table('sysc_user_store_su_privs_vw')
            ->where([
                'user_no_fk' => Auth::id(),
            ])
            ->orWhere('au_entry_hospital_no_fk', Session::get('user.ses_hospital_id'))
            ->get()
            ->toArray();

        // dd($stores);
        return Template::loadview("admin.ipd.nurse_station.nurse_station_patient_details", ['patient_info' => $patient_info, 'duration_mu' => $duration_mu, 'communicated_by' => $communicated_by, 'instructions' => $instructions, 'dose' => $dose, 'meddurmu' => $meddurmu, 'route' => $route, 'ipd_vitals' => $ipd_vitals, 'ipd_med_list' => $ipd_med_list, 'ipd_investigations' => $ipd_investigations, 'ipd_ot_list' => $ipd_ot_list, 'ipd_diet_list' => $ipd_diet_list, 'ipd_otherServices' => $ipd_otherServices, "ipd_discontinue_med_list" => $ipd_discontinue_med_list, 'indented_items' => $indented_items, 'ipd_advice_plan_assessment' => $ipd_advice_plan_assessment, 'ipd_followup_type' => $ipd_followup_type, 'stores' => $stores, 'extra_med' => $extra_med, 'type' => $type, 'clinical_data' => $clinical_data]);
    }

    public function nurseStationPatientNotes($patient_id = "", $admission_uid = "", $type = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->get()->first();

        $nicuFollowupData = DB::table('ipd_nicu_chart')->select('*')->where('nicuchart_type', 'followup')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $admission_uid)->where('status', 1)->orderBy('nicu_no_pk', 'desc')->get();
        $nicuProcedureData = DB::table('ipd_nicu_chart')->select('*')->where('nicuchart_type', 'procedure')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $admission_uid)->where('status', 1)->orderBy('nicu_no_pk', 'desc')->get();
        $nicuAdmissionData = DB::table('ipd_nicu_chart')->select('*')->where('nicuchart_type', 'admission')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $admission_uid)->where('status', 1)->orderBy('nicu_no_pk', 'desc')->get();
        $nicuCommunicationData = DB::table('ipd_nicu_chart')->select('*')->where('nicuchart_type', 'communication')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $admission_uid)->where('status', 1)->orderBy('nicu_no_pk', 'desc')->get();
        $nicuDischargeData = DB::table('ipd_nicu_chart')->select('*')->where('nicuchart_type', 'discharge')->where('patient_no_fk', $patient_id)->where('admission_no_fk', $admission_uid)->where('status', 1)->orderBy('nicu_no_pk', 'desc')->get();

        // dd($stores);
        return Template::loadview("admin.ipd.nicu_station.nicu_station_patient_notes", ['patient_info' => $patient_info, 'nicuFollowupData' => $nicuFollowupData, 'nicuProcedureData' => $nicuProcedureData, 'nicuAdmissionData' => $nicuAdmissionData, 'nicuCommunicationData' => $nicuCommunicationData, 'nicuDischargeData' => $nicuDischargeData]);
    }
