    public function storeNurseStationPatientDetails(Request $request)
    {
        $auth_id = Auth::id();
        $user_info = Auth::user();

        DB::beginTransaction();

        $followup_date_char = explode("-", $request->followUpDate); //date("Y-m-d", strtotime($request->followUpDate));
        $followup_date_day = $followup_date_char[0];
        $followup_date_month = $followup_date_char[1];
        $followup_date_year = $followup_date_char[2];
        $followup_date = $followup_date_day . "/" . $followup_date_month . "/" . $followup_date_year;

        $followup_time_char = explode(":", $request->followUpTiem);
        $followup_time_h = $followup_time_char[0];
        $followup_time_m = $followup_time_char[1];
        $followup_time = $followup_time_h . ":" . $followup_time_m;


        $follow_up_type_date_char = explode("-", $request->followUpTypeDate);
        $follow_up_type_date_day = $follow_up_type_date_char[0];
        $follow_up_type_date_month = $follow_up_type_date_char[1];
        $follow_up_type_date_year = $follow_up_type_date_char[2];
        $follow_up_type_date = $follow_up_type_date_day . "/" . $follow_up_type_date_month . "/" . $follow_up_type_date_year;

        $follow_up_type_time_char = explode(":", $request->followUpTypeTiem);
        $follow_up_type_time_time_h = $follow_up_type_time_char[0];
        $follow_up_type_time_time_m = $follow_up_type_time_char[1];
        $follow_up_type_time = $follow_up_type_time_time_h . ":" . $follow_up_type_time_time_m;



        // dd($followup_date  ,  $followup_time);
        // try {
        $in_doctor_person_no_fk = $request->doctor_id;
        $in_service_unit_no_fk = $request->doctor_id;
        //$in_su_no_fk         = $request->hdn_patient_no_fk;
        $in_admission_no_fk = $request->hdn_admission_no_pk;
        $in_ipd_ind = 1;
        $in_hospital_code = 'HC';
        $in_ipd_instruct_media_name = $request->instruct_media_name;

        $txt_pulse = $request->txt_pulse;
        $txt_bp_sys = $request->txt_bp_sys;
        $txt_bp_dia = $request->txt_bp_dia;
        $txt_temperature = $request->txt_temperature;
        $in_heart_condition = $request->in_heart_condition;
        $in_lung_condition = $request->in_lung_condition;
        $in_dehydeation = $request->in_dehydeation;
        $in_bladder_condition = $request->in_bladder_condition;
        $in_bowel_condition = $request->in_bowel_condition;
        $in_rr = $request->in_rr;
        $txt_height = '';
        $txt_weight = '';
        $txt_ofc = '';
        $txt_bmi = $request->bmi != '' ? $request->bmi : '';

        $followUpDate = $request->followUpDate != "" ? strval($followup_date) : "";
        $followUpTiem = $request->followUpTiem != "" ? strval($followup_time) : "";
        $spo2 = $request->spo2 ?? "";
        $anemia = $request->anemia ?? "";
        $height = $request->height ?? "";
        $weight = $request->weight ?? "";

        $jaundice = $request->jaundice ?? "";
        $followUpNote = $request->followUpNote ?? "";
        $advice = $request->advice ?? "";
        $assessment = $request->assessment ?? "";
        $plan = $request->plan ?? "";

        $total_intake = $request->total_intake ?? "";
        $total_output = $request->total_output ?? "";
        $bed_sore = $request->bed_sore ?? "";
        $lime_physio = $request->lime_physio ?? "";
        $chest_physio = $request->chest_physio ?? "";

        $clinical_symptoms = $request->clinical_symptoms ?? "";
        $diagnosis = $request->diagnosis ?? "";

        $pat_complains = $request->followUpNotePc;
        $follow_up_type = $request->followUpType;
        // dd( $follow_up_type_date,
        // $follow_up_type_time,
        // $pat_complains,
        // $follow_up_type);
        $item_id = $request->item_id;
        $item_name = $request->item_name;
        // dd($spo2, $total_intake, $total_output, $bed_sore, $lime_physio,$chest_physio);

        $in_item_lookupdata_no_fk = $in_report_serial_dtl = $in_presdtl_data = $in_itemtype_lookupdata_code = $in_itemtype_lookup_code = [];
        if (!empty($item_name)) {
            for ($i = 0; $i < sizeof($item_name); $i++) {
                if ($item_name[$i] != "") {
                    $in_item_lookupdata_no_fk[$i] = $item_id[$i];
                    $in_report_serial_dtl[$i] = 0;
                    $in_presdtl_data[$i] = $item_name[$i];
