                    $in_itemtype_lookup_code[$i] = isset($request->lookup_code[$i]) ? $request->lookup_code[$i] : '';
                }
            }
        } else {
            $in_item_lookupdata_no_fk[] = 0;
            $in_report_serial_dtl[] = 0;
            $in_presdtl_data[] = 0;
            $in_itemtype_lookupdata_code[] = 0;
