        $prescription->bindParam(':out_prescription_uid', $null, PDO::PARAM_STR, 500);
        $prescription->bindParam(':out_error', $out_error, PDO::PARAM_STR, 500);
        //  dd($prescription);
        $prescription->execute();

        if ($out_error == 000) {
