            // //$ipd_ot_list = DB::table('opt_ot_confirmlist_wl_vw')->where('patient_no_fk', $request->hdn_patient_no_fk)->where('admission_no_fk', $request->hdn_admission_no_pk)->orderBy('ot_req_date', 'desc')->get()->toArray();
            // $ipd_diet_list = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $request->hdn_patient_no_fk)->where('admission_pk_no', $request->hdn_admission_no_pk)->where('LOOKUPDATA_UID', 'FOOD')->orderBy('au_entry_at', 'desc')->get()->toArray();
