            // return Template::loadview("admin.ipd.nurse_station.nurse_station_patient_prescribed_list", ['ipd_vitals' => $ipd_vitals, 'ipd_med_list' => $ipd_med_list, 'ipd_investigations' => $ipd_investigations, 'ipd_ot_list' => $ipd_ot_list, 'ipd_diet_list' => $ipd_diet_list, 'ipd_otherServices' => $ipd_otherServices, "ipd_discontinue_med_list" => $ipd_discontinue_med_list]);
