    public function nurseStationVitalStore(Request $request)
    {
        $sequence = DB::getSequence();
        $psn_t_patvitals_seq = $sequence->nextValue('psn_t_patvitals_seq');
        $data = [
            'ipd_follow_up_date' => $request->followTypeDate,
            'ipd_follow_up_time' => $request->followUpTypeTime,
            // 'ipd_follow_up_note' => $request->followuptype,
            'pulse_val' => $request->txt_pulse,
            'bp_val_sys' => $request->txt_bp_sys,
            'bp_val_dia' => $request->txt_bp_dia,
            'temp_val' => $request->txt_temperature,
            'rr_value' => $request->in_rr,
            'spo2_value' => $request->spo2,
            'heart' => $request->in_heart_condition,
            'lung_condition' => $request->in_lung_condition,
            'anemia_condition' => $request->anemia,
            'jaundice_condition' => $request->jaundice,
            'dehyration_condition' => $request->in_dehydeation,
            'bowel_condition' => $request->in_bowel_condition,
            'bladder_condition' => $request->in_bladder_condition,
            'height_val' => $request->height,
            'weight_val' => $request->weight,
            'bmi' => $request->bmi,
            'activity' => $request->in_activity,
            'cannula_check' => (int) $request->in_cannula_check,
            'cbg' => $request->in_cbg,
            'o2support' => $request->in_o2support,
            'patient_no_fk' => $request->hdn_patient_no_fk,
            'admission_no_fk' => $request->hdn_admission_no_pk,
            'status' => 1
        ];
        $data['au_entry_by'] = Auth::user()->user_no_pk;
        $data['au_entry_at'] = date('Y-m-d h:i:s');
        $data['au_entry_session'] = 'Vital';
        $data['vital_no_pk'] = $psn_t_patvitals_seq;
        $data['au_entry_hospital_no_fk'] = Session::get('user.ses_hospital_no_pk');
        // dd($data);
        DB::table('psn_t_patvitals')->insert($data);
        $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success',];

        return response()->json($message);
    }

    public function patientTreatmentPrint($prescription = "", $admission = "", $patient = "")
    {

        $ipd_vitals = DB::table('psn_t_patvitals_ipd_vw')->where('patient_no_fk', $patient)->where('admission_no_fk', $admission)->where('prescription_no_fk', $prescription)->orderBy('prescription_no_fk', 'desc')->first();
        $ipd_diet_list = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient)->where('admission_pk_no', $admission)->where('LOOKUPDATA_UID', 'FOOD')->where('prescription_no_fk', $prescription)->orderBy('au_entry_at', 'desc')->first();
        $ipd_med_list = DB::table('psn_t_prescription_med_vw')->where('patient_no_fk', $patient)->where('admission_pk_no', $admission)->where('prescription_no_fk', $prescription)->where('continue_ind', 1)->orderBy('au_entry_at', 'desc')->get()->toArray();

        $ipd_advice_plan_assessment = DB::table('psn_t_prescription_dtl_vw')->where('patient_no_fk', $patient)->where('admission_pk_no', $admission)->where('prescription_no_fk', $prescription)->orderBy('au_entry_at', 'desc')->first();

        $pat_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission)->first();
        $dortor_info = DB::table('psn_t_prescription_vw')->select('doctor_signature')->where('prescription_no_pk', $prescription)->first();
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $pdf = App::make('dompdf.wrapper');
        $pdf = PDF::loadView("admin.ipd.nurse_station.patient_treatment_print", ['ipd_vitals' => $ipd_vitals, 'ipd_med_list' => $ipd_med_list, 'ipd_advice_plan_assessment' => $ipd_advice_plan_assessment, 'pat_info' => $pat_info, 'po_hospital_details' => $po_hospital_details, 'dortor_info' => $dortor_info, 'ipd_diet_list' => $ipd_diet_list])->setPaper('a4', 'portrait');
        return $pdf->stream("invoice.pdf", array("Attachment" => false));
    }


