    public function storePatientDeathInfoFromDoctorStationPopUp(Request $request)
    {
        try {
            DB::table('ipd_admission')
                ->where('admission_no_pk', $request->hidden_admission_no_pk)
                ->update([
                    'death_ind' => 1,
                    'death_declared_by' => Auth::id(),
                    'cause_of_death' => $request->cause_of_death,
                    'death_declared_time' => date('Y-m-d H:i:s', strtotime($request->death_date . ' ' . $request->death_time)),
                    'au_update_by' => Auth::id(),
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                ]);
            $this->message = ['msg' => 'Death Information Saved Successfully', 'title' => 'Success',];
        } catch (\Exception $e) {
            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($this->message);
    }
    public function dischargePatientFromDoctorStation(Request $request)
    {
        try {
            DB::table('ipd_admission')
                ->where('admission_no_pk', $request->admission_no_pk)
                ->update([
                    'dis_req_ind' => 1,
                    'dis_req_by' => Auth::id(),
                    'dis_req_time' => date('Y-m-d'),
                    'au_update_by' => Auth::id(),
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                ]);

            $this->message = ['msg' => 'Discharge Request Sent Successfully', 'title' => 'Success',];
