    public function SilDil()
    {
        return Template::loadview("admin.ipd.sil_dil", [
            'sil_dil_list' => DB::table('ipd_sil_dil_wl_vw')->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_id'))->orderBy('sil_dil_date', 'desc')->get()->toArray(),
