    public function searchSilDil(Request $request)
    {
        $qury = DB::table('ipd_sil_dil_wl_vw');
        if (!empty(request('search_sil_dil'))) {
            $qury->where('sil_dil_ind', request('search_sil_dil'));
        }
        if (!empty(request('patient_no_hidden'))) {
            $qury->where('patient_no_fk', request('patient_no_hidden'));
        }
        if (!empty(request('search_select_patient_date'))) {
            $qury->where(DB::raw("trunc(sil_dil_date)"), '=', date('Y-m-d', strtotime(request('search_select_patient_date'))));
        }

        return Template::loadview("admin.ipd.search_sil_dil", [
            'sil_dil_list' => $qury->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_id'))->orderBy('sil_dil_date', 'desc')->get()->toArray(),
        ]);
    }
    public function print_SilDil(Request $request)
    {
        $qury = DB::table('ipd_sil_dil_wl_vw');
        if (!empty(request('print_sil_dil'))) {
            $qury->where('sil_dil_ind', request('print_sil_dil'));
        }
        if (!empty(request('print_patient_no_hidden'))) {
            $qury->where('patient_no_fk', request('print_patient_no_hidden'));
        }
        if (!empty(request('print_select_patient_date'))) {
            $qury->where(DB::raw("trunc(sil_dil_date)"), '=', date('Y-m-d', strtotime(request('print_select_patient_date'))));
        }
        $data['sildilList'] = $qury->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_id'))->orderBy('sil_dil_date', 'desc')->get();

        if ($request->print_type == 'pdf') {
            return $this->generatePdf('admin.ipd.sil_dil_pdf', "sil-dil-report-list", $data);
        }
        if ($request->print_type == 'excel') {
            return $this->generateExcel('admin.ipd.sil_dil_excel', 'sil-dil-report-list', $data);
        }
    }

    public function storeSilDil(Request $request)
    {
        $auth_id = Auth::id();
        Validator::make($request->all(), [
            'select_patient_date' => 'required',
            'select_patient' => 'required',
            'sil_dil' => 'required',
        ])
            ->validate();

        DB::beginTransaction();

        try {

            $data = [
                'sil_dil_date' => date('Y-m-d', strtotime($request->select_patient_date)),
                'patient_no_fk' => $request->patient_no_fk_hidden,
                'patient_name' => $request->select_patient,
                'service_number' => $request->service_number_hidden,
                'sil_dil_ind' => $request->sil_dil,
                'status' => 1
            ];
            // AU_ENTRY_BY
            $data['au_entry_by'] = $auth_id;
            $data['au_entry_session'] = 'SESSION';
            $data['au_entry_hospital_pk_no'] = Session::get('user.ses_hospital_id');
            $this->model_IPDSILDIL->create($data);

            DB::commit();
            $this->message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Exception $e) {
            DB::rollback();
            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($this->message);
    }
    public function deleteSilDil(Request $request)
    {
        try {
            DB::table('ipd_sil_dil')
                ->where('ipd_sil_dil_no_pk', $request->ipd_sil_dil_no_pk)
                ->delete();
            $this->message = ['msg' => 'Record Deleted Successfully', 'title' => 'Success',];
        } catch (\Exception $e) {
            $this->message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($this->message);
    }
