    public function bedOccupancyHistoryData(Request $request)
    {
        $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
        $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        if (!empty($request->search_date_from) && !empty($request->search_date_to)) {

            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";


        $query = DB::select(DB::raw("select * from BED_OCCUPANCY_HISTORY_VW $sql_cond  "));
        return Template::loadview("admin.ipd.bed_occupancy.bed_occupancy_history_list", [
            'data' => $query,
            'date_from' => $date_from,
            'date_to' => $date_to
        ]);
    }

