    // Reports

    public function ipdPatientReport()
    {
        $ward_name = DB::table('ipds_ward as ipd')
            ->leftJoin('ipd_admission_details details', 'details.ward_no_fk', '=', 'ipd.ward_no_pk')
            ->select('ipd.ward_no_pk', 'ipd.ward_uid', 'ipd.ward_name')
            ->where('ipd.status', 1)
            ->orderBy('ipd.ward_name', 'asc')
            ->distinct('ipd.ward_no_pk')
            ->get();
        return Template::loadview("admin.ipd.reports.ipd_patient", ["ward_name" => $ward_name]);
    }

    public function ipdPatientReportList(Request $request)
    {
        $ward = $request->ward_name;
        $emr_pat_type = $request->emr_pat_type;
        if ($emr_pat_type != '') {
            if ($emr_pat_type == 1) {
                $checkPatType = 'and IPTYPE_IND = 1';
            } elseif ($emr_pat_type == 2) {
                $checkPatType = 'and IPTYPE_IND = 2';
                // $checkPatType = 'and (IPTYPE_IND = 2 or REF_FROM_EMR_IND = 1)';
            } else {
                $checkPatType = '';
            }
        }

        // Print the resulting array

        $type = $request->type;
        $pat_type = $request->pat_type;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;
        $doctor_id = $request->doctor_id;
        $referred_id = $request->referred_id;

        if (!empty($date_from) && !empty($date_to)) {

            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        } else {
            $date_from = "";
            $date_to = "";
        }

        $emergency = " and ipd.EMERGENCY_DAYCARE_IND_TXT is null";
        $sql_cond = "";

        $clause = ($sql_cond == "") ? " where" : " and";

        if ($type != 'Death Patient') {
            if ($pat_type == 4) {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.dis_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
            } elseif ($pat_type == 6) {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY') " : "";
            } elseif ($pat_type == 3) {
            } else {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
            }
        } else {
            $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.death_declared_time) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
        }

        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($ward != "") ? " $clause ward.ward_no_pk = '$ward'" : "";

        $clause = ($sql_cond == "") ? " WHERE" : " AND";
        $sql_cond .= " $clause ward.emr_ind != 1";


        $clause = ($sql_cond == "") ? " where" : "and";
        $sql_cond .= ($doctor_id != "") ? " $clause ipd.primary_doctor_no_fk=$doctor_id" : "";

        $clause = ($sql_cond == "") ? " where" : "and";
        $sql_cond .= ($referred_id != "") ? " $clause ipd_adm_v.ref_doc_person_no_fk = $referred_id" : "";


        $clause = ($sql_cond == "") ? " where" : "and";
        $sql_cond .= ($referred_id != "") ? " $clause ipd_adm_v.ref_doc_person_no_fk = $referred_id" : "";
        // dd($pat_type);
        if ($pat_type == 1) {
            $report_data = db::select("select ipd.admission_no_pk,
                                        ipd.admission_uid,
                                        ipd.admission_date,
                                        ipd.primary_doctor_no_fk,
                                        ipd.patient_no_fk,
                                        ipd.dis_date,
                                        ipd.dis_datetime,
                                        ipd.dis_ind,
                                        ipd.death_ind,
                                        ipd.death_declared_time,
                                        pat.patient_name,
                                        pat.gender,
                                        pat.gender_txt,
                                        pat.age,
                                        pat.patient_code,
                                        pat.patient_type,
                                        pat.patient_photo,
                                        per.full_name,
                                        per.person_no_pk,
                                        per.person_code,
