        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $barcode_no = $barcode->generate();

        $financials = DB::select("
            SELECT
                mst.admission_no_pk,
                SUM(lmst.ledger_amt_sales) AS sales,
                SUM(lmst.ledger_amt_discount) AS discount,
                SUM(lmst.ledger_amt_payment) AS payment
            FROM finc_ledgermst lmst
            JOIN finc_invoicemst mst
                ON lmst.invoice_no_fk = mst.invoice_no_pk
            GROUP BY mst.admission_no_pk
        ");
        $financeData = collect($financials)->keyBy('admission_no_pk');
        $report_data = collect($report_data)->map(function ($item) use ($financeData) {
            $admission_id = $item->admission_no_pk;

            $item->total_sales = $financeData[$admission_id]->sales ?? 0;
            $item->total_discount = $financeData[$admission_id]->discount ?? 0;
            $item->total_payment = $financeData[$admission_id]->payment ?? 0;

            // you can also compute payable & due here
            $item->total_payable = $item->total_sales - $item->total_discount;
            // $item->total_due = $item->total_payable - $item->total_payment;
            if ($item->total_payment > $item->total_payable) {
                // Extra payment → Refund
                $item->advance = $item->total_payment - $item->total_payable;
                $item->total_due = 0;
            } else {
                // Normal case → Due
                $item->advance = 0;
                $item->total_due = $item->total_payable - $item->total_payment;
            }


            return $item;
        });

        // dd($report_data);

        $pdf = PDF::loadView("admin.ipd.reports.ipd_patient_pdf", [
            'report_data' => $report_data,
            'po_hospital_details' => $po_hospital_details,
            'barcode_no' => $barcode_no,
            'from_date' => $date_from,
            'to_date' => $date_to,
            'type' => $type
        ])->setPaper('a4', 'landscape');
        return $pdf->stream('Ipd ' . $type . '.pdf');
    }
