                SUM(lmst.ledger_amt_discount) AS discount,
                SUM(lmst.ledger_amt_payment) AS payment
            FROM finc_ledgermst lmst
            JOIN finc_invoicemst mst
                ON lmst.invoice_no_fk = mst.invoice_no_pk
            GROUP BY mst.admission_no_pk
