            $item->total_sales = $financeData[$admission_id]->sales ?? 0;
            $item->total_discount = $financeData[$admission_id]->discount ?? 0;
            $item->total_payment = $financeData[$admission_id]->payment ?? 0;

            // you can also compute payable & due here
            $item->total_payable = $item->total_sales - $item->total_discount;
            // $item->total_due = $item->total_payable - $item->total_payment;
            if ($item->total_payment > $item->total_payable) {
                // Extra payment → Refund
                $item->advance = $item->total_payment - $item->total_payable;
                $item->total_due = 0;
            } else {
                // Normal case → Due
                $item->advance = 0;
                $item->total_due = $item->total_payable - $item->total_payment;
            }


            return $item;
        });

