    public function ipdPatientDeptWiseReportPdf(Request $request)
    {
        $type = $request->type;
        $pat_type = $request->pat_type;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;
        $doctor_id = $request->doctor_id;
        $referred_id = $request->referred_id;
        $ward = $request->ward_name;

        if (!empty($date_from) && !empty($date_to)) {

            $date_from = "$request->search_date_from";
            $date_to = "$request->search_date_to";
        } else {
            $date_from = "";
            $date_to = "";
        }

        $emergency = "and ipd.EMERGENCY_DAYCARE_IND_TXT is null";
        $sql_cond = "";
        $clause = ($sql_cond == "") ? " where" : " and";

        if ($type != 'Death Patient') {
            if ($pat_type == 4) {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.dis_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
            } elseif ($pat_type == 6) {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY') or trunc(ipd.dis_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY') or trunc(ipd.death_declared_time) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
            } elseif ($pat_type == 3) {
            } else {
                $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
            }
        } else {
            $sql_cond .= ($date_from != "") ? " $clause trunc(ipd.death_declared_time) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
        }
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($ward != "") ? " $clause ward.ward_no_pk = '$ward'" : "";

        $clause = ($sql_cond == "") ? " where" : "and";
        $sql_cond .= ($doctor_id != "") ? " $clause ipd.primary_doctor_no_fk = $doctor_id" : "";
        $clause = ($sql_cond == "") ? " where" : "and";
        $sql_cond .= ($referred_id != "") ? " $clause ipd_adm_v.ref_doc_person_no_fk = $referred_id" : "";
        if ($pat_type == 1) {
            $report_data = db::select(" SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS concatenated_ward_names,
            LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS concatenated_bed_names,
            emp.su_name,
            per.full_name
            FROM
                ipd_admission ipd
            LEFT JOIN
                hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
            LEFT JOIN
                EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
            JOIN
                ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
            LEFT JOIN
                ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
            LEFT JOIN
                ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
            LEFT JOIN
                IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
                $emergency
            GROUP BY
                emp.su_name, per.full_name
        order by  emp.su_name asc");
        } elseif ($pat_type == 2) {
            $report_data = db::select("
            SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS concatenated_ward_names,
            LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS concatenated_bed_names,
            emp.su_name,
                per.full_name
            FROM
                ipd_admission ipd
            LEFT JOIN
                hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
            LEFT JOIN
                EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
            JOIN
                ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
            LEFT JOIN
                ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
            LEFT JOIN
                ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
            LEFT JOIN
                IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
                $sql_cond $emergency
            GROUP BY
                emp.su_name, per.full_name
            order by  emp.su_name asc

          ");
        } elseif ($pat_type == 3) {
            $clause = ($sql_cond == "") ? " where" : " and";
            $sql_cond .= $clause . " ipd.dis_ind = 0 ";
            $report_data = db::select("

            SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(bed_concatenated.bed_name, ', ') WITHIN GROUP (ORDER BY bed_concatenated.bed_name) AS concatenated_bed_names,
            LISTAGG(ward_concatenated.ward_name, ', ') WITHIN GROUP (ORDER BY ward_concatenated.ward_name) AS concatenated_ward_names,
            emp.su_name,
            per.full_name
        FROM
            ipd_admission ipd
        LEFT JOIN
            hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
        LEFT JOIN
            EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
        JOIN
            ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
        LEFT JOIN
            ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
        LEFT JOIN
            (
                SELECT
                    ipd.admission_no_pk,
                    LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS bed_name
                FROM
                    ipd_admission ipd
                LEFT JOIN
                    ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
                GROUP BY
                    ipd.admission_no_pk
            ) bed_concatenated ON ipd.admission_no_pk = bed_concatenated.admission_no_pk
        LEFT JOIN
            (
                SELECT
                    ipd.admission_no_pk,
                    LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS ward_name
                FROM
                    ipd_admission ipd
                LEFT JOIN
                    ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
                LEFT JOIN
                    ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
                GROUP BY
                    ipd.admission_no_pk
            ) ward_concatenated ON ipd.admission_no_pk = ward_concatenated.admission_no_pk
        LEFT JOIN
            IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
              $sql_cond $emergency

            AND ipd.dis_ind = 0
        GROUP BY
            emp.su_name, per.full_name
        ORDER BY
            emp.su_name ASC

            ");

            // dd( $report_data);


        } elseif ($pat_type == 4) {
            $report_data = db::select("
            SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS concatenated_ward_names,
            LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS concatenated_bed_names,
            emp.su_name,
            per.full_name
            FROM
                ipd_admission ipd
            LEFT JOIN
                hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
            LEFT JOIN
                EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
            JOIN
                ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
            LEFT JOIN
                ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
            LEFT JOIN
                ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
            LEFT JOIN
                IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
                $sql_cond $emergency and  ipd.dis_ind = 1
            GROUP BY
                emp.su_name, per.full_name
            order by  emp.su_name asc
           ");
        } elseif ($pat_type == 5) {
            $report_data = db::select("
            SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS concatenated_ward_names,
            LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS concatenated_bed_names,
            emp.su_name,
            per.full_name
            FROM
                ipd_admission ipd
            LEFT JOIN
                hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
            LEFT JOIN
                EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
            JOIN
                ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
            LEFT JOIN
                ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
            LEFT JOIN
                ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
            LEFT JOIN
                IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
                $sql_cond $emergency and  ipd.death_ind = 1
            GROUP BY
                emp.su_name, per.full_name
            order by  emp.su_name asc
           ");
        } elseif ($pat_type == 6) {

            $clause = ($sql_cond == "") ? " where" : "and";
            $sql_cond .= ($doctor_id != "") ? " $clause ipd.primary_doctor_no_fk = $doctor_id" : "";
            $report_data = db::select(" SELECT
            COUNT(ipd.admission_no_pk) AS total_admissions,
            LISTAGG(ward.ward_name, ', ') WITHIN GROUP (ORDER BY ward.ward_name) AS concatenated_ward_names,
            LISTAGG(bed.bed_name, ', ') WITHIN GROUP (ORDER BY bed.bed_name) AS concatenated_bed_names,
            emp.su_name,
            per.full_name
            FROM
                ipd_admission ipd
            LEFT JOIN
                hrms_personnel per ON ipd.primary_doctor_no_fk = per.person_no_pk
            LEFT JOIN
                EMPLOYEE_LIST_VW emp ON emp.person_no_pk = per.person_no_pk
            JOIN
                ipd_admission_details details ON ipd.admission_no_pk = details.admission_no_pk
            LEFT JOIN
                ipds_ward ward ON details.ward_no_fk = ward.ward_no_pk
            LEFT JOIN
                ipds_bed bed ON ipd.curr_bed_no_fk = bed.bed_no_pk
            LEFT JOIN
                IPD_ADMITTED_PATLIST_VW ipd_adm_v ON ipd.ADMISSION_NO_PK = ipd_adm_v.ADMISSION_NO_PK
                $sql_cond $emergency
            GROUP BY
                emp.su_name, per.full_name
            order by  emp.su_name asc");
        }
        $report_datas = collect($report_data)->groupBy('su_name');

        $report_data_count = count($report_data);
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $title = '124526';
        $barcode = new BarcodeGenerator();
        $barcode->setText($title);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $barcode_no = $barcode->generate();

        $pdf = PDF::loadView("admin.ipd.reports.ipd_patient_dept_wise_pdf", [
            'report_data' => $report_datas,
            'report_data_count' => $report_data_count,
            'po_hospital_details' => $po_hospital_details,
            'barcode_no' => $barcode_no,
            'from_date' => $date_from,
            'to_date' => $date_to,
            'type' => $type
        ])->setPaper('a4', 'portrait');
        return $pdf->stream('Ipd ' . $type . '.pdf');
    }

