        } elseif ($type == "Due") {
            if ($report_type == "IPD") {
                $report_data = db::select("
            SELECT finc.admission_no_pk,
                   finc.customer_name,
                   finc.cashier_name,
                   SUM (finc.due) due,
                   finc.patient_code,
                   finc.patient_name,
                   finc.gender_txt,
                   ipd.age,
                   ipd.admission_date,
                   finc.mobile1,
                   finc.cashier_name
              FROM    finc_invoicemst_c022_sum_vw finc
                   left JOIN
                      ipd_admission ipd
                   ON finc.admission_no_pk = ipd.admission_no_pk
             $sql_cond_type
             $sql_cond
          GROUP BY finc.admission_no_pk,
                   finc.customer_name,
                   finc.cashier_name,
                   finc.patient_code,
                   finc.patient_name,
                   finc.gender_txt,
                   ipd.age,
                   ipd.admission_date,
                   finc.mobile1,
                   finc.cashier_name order by  ipd.admission_date desc");
            } else {
                $report_data = db::select("SELECT invoice_code,finc.customer_name,
                    SUM (finc.due) due,
                    finc.patient_code,
                    finc.patient_name,
                    finc.cashier_name,
                    finc.gender_txt,
                    ipd.age,
                    invoice_date,
                    finc.mobile1,
                   finc.cashier_name
                FROM    finc_invoicemst_c022_sum_vw finc
                    LEFT JOIN
                        ipd_admission ipd
                    ON finc.admission_no_pk = ipd.admission_no_pk
                    $sql_cond_type  $sql_cond
            GROUP BY invoice_code,
                    finc.customer_name,
                    finc.patient_code,
                    finc.patient_name,
                    finc.cashier_name,
                    finc.gender_txt,
                    ipd.age,
                    invoice_date,
                    finc.mobile1,
                   finc.cashier_name");
            }
        }

        return Template::loadView("admin.ipd.reports.ipd_refund_due_patient_list", ['report_data' => $report_data, 'type' => $type, 'report_type' => $report_type]);
    }

