    public function ipdIndoorPatientReportList(Request $request)
    {
        $doctor = $request->card_hidn;
        $add_id = $request->add_id;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;
        if (!empty($date_from) && !empty($date_to)) {

            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($doctor != "") ? " $clause doc_no = $doctor" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($add_id != "") ? " $clause admission_no_pk = $add_id" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(admission_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";

        $report_data = DB::select(DB::raw("select con.admission_pk_no,
               con.doc_name,
               con.doc_no,
               con.doctor_visit_date_time,
               count (con.no_of_visit) visit,
               con.visit_type,
               adm.patient_name,
               adm.age,
               adm.admission_date,
               adm.admission_uid,
               adm.gender_txt,
               con.patient_no_fk,
               adm.bed_uid,
               adm.bed_name
          from ipd_consultation_count_vw con, ipd_admitted_patlist_vw adm
         where con.admission_pk_no = adm.admission_no_pk $sql_cond
      group by con.admission_pk_no,
               con.doc_name,
               con.doc_no,
               con.doctor_visit_date_time,
               adm.patient_name,
               adm.age,
               adm.admission_date,
               adm.admission_uid,
               adm.gender_txt,
               con.visit_type,
               con.patient_no_fk,
               adm.bed_uid,
               adm.bed_name
      order by con.doc_no,adm.admission_uid desc"));



        $report_arr = [];
        foreach ($report_data as $data) {
            $report_arr[$data->bed_name][] = $data;
        }
        return Template::loadView("admin.ipd.reports.ipd_indoor_visit_fee_list", ['report_arr' => $report_arr]);
    }

