        $from_store_su_no_fk = isset($request->store_from) ? $request->store_from : 0;
        $po_no = 0;
        $supplier_no_fk = isset($request->supplier_id) ? $request->supplier_id : 0;
        $stock_type = $request->stock_type;
        $item_pk_no = [];
        $item_pvms = [];
        $item_qty = [];
        $item_uom = [];
        $item_price = [];
        $item_entry_dtl = [];
        $empty_arr = [];
        $hdn_single_quantity = [];
        $item_uom_phur = [];
        $phur_qty = [];
        $demand_no_fk = 1;
        $in_au_entry_by = Auth::id();
        $in_au_entry_session = 'SESSION';
        $in_au_entry_hospital_pk_no = !empty(Session::get('user.ses_hospital_no_pk')) ? Session::get('user.ses_hospital_no_pk') : '0';
        $numelems = 500;
        $null = '';
        $out_itemtrans_uid = '0';

        $item_no[] = $request->item_no;
        $item_qty_arr[] = $request->qty ?? 0;
        if (!empty($item_no)) {
            for ($i = 0; $i < count($item_no); $i++) {
                $item_pk_no = isset($item_no[$i]) ? $item_no[$i] : 0;
                // $item_pvms[$i] = $null;
                // $item_query[$i] = DB::table('sysc_serviceitem')->where('item_no_pk', $item_pk_no[$i])->first();
                // $supplier_name= $item_query[$i]->supplier_pk_no;
                // $item_uom[$i]= $item_query[$i]->uom_no_fk;
                $item_qty = isset($item_qty_arr[$i]) ? $item_qty_arr[$i] : 0;
                // $item_price[$i] =  $item_query[$i]->sales_price ?? 0;
                // $item_entry_dtl[$i] = $i + 1;
                // $empty_arr[$i] = 0;
            }
        }
        $module = DB::table('sysc_module')->select('module_no_pk')->where('module_code', "PHR-I")->first();
        $refund_reason = '';
        $module_no_fk = $module->module_no_pk;
        $admission_no = $request->admission_no;
        $ledgertrn_no = '';
        $out_invoice_no = $out_ledgertrn_no = "";
        $out_invoice_id = $out_error = "";
        // dd(  $item_pk_no,$item_qty,$module_no_fk,$admission_no,$store_su_no_fk,$chalan_date,$refund_reason);
        $indent_detail_no = $request->indent_details;


        if ($request->type == "1") {
            $data = [
                'RETURN_RECV_QUANTITY' => $item_qty,
                'RETURN_RECV_AT' => date('Y-m-d'),
                'RETURN_RECV_BY' => Auth::id(),
                'RETURN_RECV_IND' => 1,
                'au_update_hospital_pk_no' => Session::get('user.ses_hospital_no_pk'),
            ];
            DB::table('IPD_PATINDENTDTL')
                ->where([
                    'patindentdtl_no_pk' => $indent_detail_no,
                ])->update($data);
            DB::commit();
            $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        } else {

            $pdo = DB::getPdo();
            $stock_adjustment = $pdo->prepare("begin pkg_billing_ipd_v0.prc_phr_ipd_sales_cancellation(
                :in_cancel_date,
                :in_refund_reason,
                :in_item_no_fk,
                :in_cancel_QTY,
                :in_module_no_fk,
                :in_admission_no_fk,
                :in_counter_su_no_fk,
                :in_au_entry_by,
                :in_au_entry_session,
                :in_au_entry_hospital_pk_no,
                :in_ledgertrn_no,
                :out_invoice_no,
                :out_invoice_id,
                :out_ledgertrn_no,
                :out_error);
            end;
            ");
            $stock_adjustment->bindparam('in_cancel_date', $chalan_date);
            $stock_adjustment->bindparam('in_refund_reason', $refund_reason);
            $stock_adjustment->bindparam('in_item_no_fk', $item_pk_no);
            $stock_adjustment->bindparam('in_cancel_QTY', $item_qty);
            $stock_adjustment->bindparam('in_module_no_fk', $module_no_fk);
            $stock_adjustment->bindparam('in_admission_no_fk', $admission_no);
            $stock_adjustment->bindparam('in_counter_su_no_fk', $store_su_no_fk);
            $stock_adjustment->bindparam('in_au_entry_by', $in_au_entry_by);
            $stock_adjustment->bindparam('in_au_entry_session', $in_au_entry_session);
            $stock_adjustment->bindparam('in_au_entry_hospital_pk_no', $in_au_entry_hospital_pk_no);
            $stock_adjustment->bindparam('in_ledgertrn_no', $ledgertrn_no);
            $stock_adjustment->bindParam(':out_invoice_no', $out_invoice_no, PDO::PARAM_INT);
            $stock_adjustment->bindParam(':out_invoice_id', $out_invoice_id, PDO::PARAM_STR, 500);
            $stock_adjustment->bindParam(':out_ledgertrn_no', $out_ledgertrn_no, PDO::PARAM_INT);
            $stock_adjustment->bindParam(':out_error', $out_error, PDO::PARAM_STR, 500);
            // dd( $stock_adjustment);

            $stock_adjustment->execute();

            $data = [
                'after_return_recv_qty' => $item_qty,
                'after_return_recv_at' => date('Y-m-d'),
                'after_return_recv_by' => Auth::id(),
                'after_return_recv_ind' => 1,
                'au_update_hospital_pk_no' => Session::get('user.ses_hospital_no_pk'),
            ];

            if ($out_error == '000') {
                DB::table('ipd_patindentdtl')
                    ->where([
                        'patindentdtl_no_pk' => $indent_detail_no,
                    ])->update($data);
                DB::commit();
                $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
            } else {
                DB::rollback();
                $this->message = ['msg' => 'Failled.', 'title' => 'Error'];
            }
        }





        // } catch (\Throwable $th) {
        //     DB::rollback();
        //     $this->message = ['msg' => 'Failled.' , 'title' => 'Error'];
        // }
        return response()->json($this->message);
    }
