   public function anaesthiticRecordOtTypeWise(Request $request)
{
    // You can get a specific request parameter to check your condition.
    $condition = $request->type;
    // Check if the condition is 1
    if ($condition == 1) {
        // If condition is 1, execute your original query
        $pat_info = DB::table('ipd_admitted_patlist_vw as adm')
            ->join('opt_prescribed_ot as ot', 'adm.admission_no_pk', '=', 'ot.admission_no_fk')
            ->leftJoin('ot_complete_status as status', 'status.admission_no_fk', '=', 'adm.admission_no_pk')
            ->where('ot.anest_clearance_ind', 1)
            ->where('ot.ot_comfirmation_ind', 1)
            ->orderBy('adm.admission_no_pk', 'desc')
            ->get();
    } else {
        // Else, run your second query (the one you provided with GROUP BY)
        $pat_info = DB::select(DB::raw("SELECT
                        PATIENT_NAME,
                        GENDER_TXT,
                        MOBILE1,
                        sysc_serviceitem.item_name,
                        OPT_PRESCRIBED_OT.OT_REQ_NO_PK,
                        OPT_PRESCRIBED_OT.ot_date,
                        OPT_PRESCRIBED_OT.PATIENT_NO_FK,
                        OPT_PRESCRIBED_OT.REFF_ANES_DEPT_NO_FK
                    FROM
                        opt_prescribed_ot
                    LEFT JOIN
                        patn_registration
                        ON OPT_PRESCRIBED_OT.PATIENT_NO_FK = patn_registration.PATIENT_NO_pK
                    LEFT JOIN
                        sysc_serviceitem
                        ON OPT_PRESCRIBED_OT.item_no_fk = sysc_serviceitem.item_no_pk
                    WHERE
                        anest_clearance_ind = 1
                        AND ot_comfirmation_ind = 1
                        AND OPT_PRESCRIBED_OT.admission_no_fk IS NULL  -- Corrected the NULL check
                    GROUP BY
                        PATIENT_NAME,
                        GENDER_TXT,
                        MOBILE1,
                        sysc_serviceitem.item_name,
                        OPT_PRESCRIBED_OT.OT_REQ_NO_PK,
                        OPT_PRESCRIBED_OT.ot_date,
                        OPT_PRESCRIBED_OT.PATIENT_NO_FK,
                        OPT_PRESCRIBED_OT.REFF_ANES_DEPT_NO_FK
                    ORDER BY
                        OPT_PRESCRIBED_OT.ot_date desc"));
    }
    return Template::loadview("admin.ipd.reports.anaesthetic_record_list", [
        'pat_info' => $pat_info,
        'condition' => $condition
    ]);
}



