    }

    public function otCompleteStore(Request $request)
    {

        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();
        try {
            $data = [
                'anesth_record' => $request->anaes_record,
                'op_note' => $request->operation_note,
                'pre_anes_chkup_frm' => $request->pre_anes_checkup,
                'pre_oper_chklist' => $request->pre_oprerative_checkup,
                'high_risk_consent' => $request->high_risk_consent,
                'ot_complete_ind' => $request->ot_dropdown,
                'admission_no_fk' => $request->admission_id,
                'status' => 1,

            ];

            $sequence = DB::getSequence();
            $ot_complete_status_no_pk_seq = $sequence->nextValue('ot_complete_status_no_pk_seq');

            if ($request->ot_id == "") {
                $data['ot_complete_status_no_pk'] = $ot_complete_status_no_pk_seq;
                $data['AU_ENTRY_BY'] = $auth_id;
                $data['AU_ENTRY_AT'] = date('Y-m-d');
                $data['AU_ENTRY_SESSION'] = 'sessoin';
                $data['au_entry_hospital_pk_no'] = $hospital_no_pk;
                DB::table('ot_complete_status')->insert($data);
            } else {
                $data['AU_UPDATE_BY'] = $auth_id;
                DB::table('ot_complete_status')->where('ot_complete_status_no_pk', $request->ot_id)->update($data);
            }
            DB::commit();
            $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            $this->message = ['msg' => 'Failled.', 'title' => 'Error'];
        }
        return response()->json($this->message);
    }
