    public function preAnestheticCheckupForm($patient_id = "", $ref_no = "")
    {

        $pat_info = DB::table('ipd_admitted_patlist_vw')->where('patient_no_fk', $patient_id)->first();

        $ot_info = DB::table('OPD_REFF_ANESTHESIA_DEPT')->where('patient_no_fk', $patient_id)->first();

       $pre_anesthetic_checkup = DB::table('anesthetics_checkup_form')
                                ->select(
                                    'anesthetics_checkup_form.*',
                                    'ans.full_name as full_name',
                                    'hrms_personnel.full_name as full_name_2'
                                )
                                ->leftJoin('hrms_personnel as ans', 'ans.person_no_pk', '=', 'anesthetics_checkup_form.anesthetist_id_fk')
                                ->leftJoin('hrms_personnel', 'hrms_personnel.person_no_pk', '=', 'anesthetics_checkup_form.pre_asses_anes_no_fk')
                                ->where(function ($query) use ($patient_id, $ref_no) {
                                    $query->where('patient_id_fk', $patient_id)
                                        ->orWhere('REFF_ANES_DEPT_NO_fK', $ref_no);
                                })
                                ->first();



        if (Session::get('user.ses_hospital_code') != "DMHL") {
            return Template::loadView("admin.ipd.reports.pre_anesthetic_checkup_form", ['pat_info' => $pat_info, 'pre_anesthetic_checkup' => $pre_anesthetic_checkup, 'ot_info' => $ot_info, 'ref_no' => $ref_no]);
        } else {
            return Template::loadView("admin.ipd.reports.pre_anesthetic_checkup_form_dmhl", ['pat_info' => $pat_info, 'pre_anesthetic_checkup' => $pre_anesthetic_checkup]);
        }
    }

