    public function postAnestheticCheckupForm($patient_id = "", $ref_no = "")
    {

        $pat_info = DB::table('patient_info_vw')->where('patient_no_pk', $patient_id)->first();
        //dd($pat_info);

        $pre_anesthetic_checkup = DB::table('POST_ANESTHESIA_ORDERS')
            ->select('POST_ANESTHESIA_ORDERS.*', 'ans.full_name as full_name', 'hrms_personnel.full_name as full_name_2')
            ->leftJoin('hrms_personnel ans', 'ans.person_no_pk', '=', 'post_anesthesia_orders.person_no_fk')
            ->leftJoin('hrms_personnel', 'hrms_personnel.person_no_pk', '=', 'post_anesthesia_orders.person_no_fk')
            ->where(function ($query) use ($patient_id, $ref_no) {
            $query->where('patient_no_fk', $patient_id)
            ->orWhere('REFF_ANES_DEPT_NO_fK', $ref_no);
            })
