    public function postAnestheticCheckupStore(Request $request)
    {

        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

       try {
            // Collect basic data from the request
            $data = [
                'patient_no_fk' => $request->pat_id,
                'admission_no_fk' => $request->admission_id,
                // 'ot_date' => $request->date != "" ? date("Y-m-d", strtotime($request->date)) : "",
                'doctor_name' => $request->doctor_name,
                'doctor_id_fk' => $request->hdn_doctor_id,
                'AU_ENTRY_BY' => $auth_id,
                'AU_UPDATE_BY' => $auth_id,
                'AU_ENTRY_AT' => date('Y-m-d'),
                'AU_ENTRY_SESSION' => 'session',
                'au_entry_hospital_pk_no' => $hospital_no_pk,
            ];

            // Additional fields (based on your table structure)
            $additionalData = [
                'POSITION' => $request->position,
                'FLOW_MINT' => $request->p_others,
                'OXYGEN' => $request->oxygen,
                'MONITOR_DTL' => $request->ox_others,
                'FLOW_HR' => $request->flow_hr,
                'NPO' => $request->npo,
                'ANALGESIA' => $request->analgesia,
                'FLUID' => $request->fluid,
                'SPECIAL_INSTRUCTIONS' => $request->special_instructions,
                'SHIFT_TO' => $request->shift_to,
                'ANESTHESIOLOGIST' => $request->anesthesiologists,
                'ANESTHESIOLOGIST_NO_FK' => $request->hdn_anesthesiologists,
                'SURGEONS' => $request->surgeons,
                'SURGEONS_NO_FK' => $request->hdn_surgeons,
                'REFF_ANES_DEPT_NO_FK' => $request->ref_no,

            ];

            // Merge the basic data with the additional fields
            $data = array_merge($data, $additionalData);
            // dd($data);
            // Handle sequence for creating a new record
            $sequence = DB::getSequence();
            $ot_operation_no_pk = $sequence->nextValue('ANESTHESIA_ORDERS_NO_PK_SEQ');

            if ($request->anesthesia_orders_no_pk == "") {
                // If no existing record, insert a new one
                $data['anesthesia_orders_no_pk'] = $ot_operation_no_pk;
                DB::table('POST_ANESTHESIA_ORDERS')->insert($data);
            } else {
                // If updating an existing record
                $data['AU_UPDATE_BY'] = $auth_id;
                DB::table('POST_ANESTHESIA_ORDERS')
                    ->where('anesthesia_orders_no_pk', $request->anesthesia_orders_no_pk)
                    ->update($data);
            }

            DB::commit();

            // Return a success message
            $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            // Return an error message if the transaction fails
            $this->message = ['msg' => 'Failed to save data.', 'title' => 'Error'];
        }

        return response()->json($this->message);
    }


    public function ipdPharmacyPayment($admission_id)
    {
        $hospital_id = Session::get('user.ses_hospital_no_pk');
        $invoice_number = DB::select("select invoice_no_pk from finc_invoicemst_sum_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id");

        $patientInfo = DB::select("select patient_no_fk from ipd_admitted_patlist_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id ");
        $patientId = $patientInfo[0]->{'patient_no_fk'};
        $invoice_id = [];
        $price_0 = [];
        $item_type = [];
        if (!empty($invoice_number)) {
            foreach ($invoice_number as $value) {
                $invoice_id[] = $value->invoice_no_pk;
                $price_0[] = 0;
                $cancel[] = 1;
                $item_type[] = "MED";
            }
        }
        $item_details = DB::table("finc_invoicedtl_vw")->where('au_entry_hospital_pk_no', $hospital_id)->whereIn('module_code', ['PHR', 'PHR-I', 'PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU', 'PHR-NICU', 'PHR-PICU'])->whereIn("invoice_no_fk", $invoice_id)->whereNotIn("item_rate", $price_0)->orderBy('invoice_no_fk', 'desc')->get();



        // $paymentHistories = DB::table("FINC_LEDGERMST_PAYDISC_VW")->where("admission_no_pk", $admission_id)->where('ledger_amt_payment','!=',0)->get();

        $paymodes = $this->getLookupListByCodeCustomKey("lookupdata_code", "PAYMODE");
        $pay_types = $this->getLookupListByCode("PAYTYPE");

        $paymentHistories = DB::SELECT("select mst.ledger_amt_payment,
			mst.disc_amt_by_doc,mst.disc_amt_by_hosp,
			mst. au_entry_at as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
			from finc_ledgermst mst join SYSC_MODULE mod on mod.module_no_pk = mst.module_no_fk join wsec_user uname
			on mst.au_entry_by=uname.user_no_pk
			where mst.admission_no_fk=$admission_id and
			mst.ledger_amt_payment <> 0 and mod.MODULE_CODE in  ('PHR','PHR-I','PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU','PHR-NICU','PHR-PICU') and mst.ledger_amt_payment is not null"); //and mst.payment_subtype ='Pharmacy'

        $discountHistoris = DB::SELECT("select mst.LEDGER_AMT_PAYMENT,
			mst.DISC_AMT_BY_DOC,mst.DISC_AMT_BY_HOSP,
			mst.au_entry_at as invoice_date,UNAME.USER_NAME LEDGER_ENTRY_TXT ,mst.ledger_amt_discount,mod.module_name
			from finc_ledgermst mst join wsec_user uname
			on mst.AU_ENTRY_BY=UNAME.USER_NO_PK
            join SYSC_MODULE mod on mod.module_no_pk = mst.module_no_fk
			where mst.ADMISSION_NO_FK=$admission_id and
			mod.module_code in ('PHR','PHR-I','PHR-E', 'PHR-D', 'PHR-O', 'PHR-ICU', 'PHR-CCU','PHR-NICU','PHR-PICU') ");
        // AND (mst.disc_amt_by_doc > 0 OR mst.disc_amt_by_hosp > 0)

        $totalDiscount = $this->getTotalDiscount($discountHistoris);
        $bank_name = $this->getLookupListByCode("AGENTBANKING");
        $ipd_sub_type = $this->getLookupListByCode("IPDPAYSUBTYPE");

        $type = 'Pharmacy';
        return Template::loadview("admin.ipd.ipd_payment", ["ipd_sub_type" => $ipd_sub_type, "item_details" => $item_details, 'paymodes' => $paymodes, 'pay_types' => $pay_types, 'admission_id' => $admission_id, 'patientId' => $patientId, 'paymentHistories' => $paymentHistories, 'totalDiscount' => $totalDiscount, 'bank_name' => $bank_name, 'type' => $type]);
    }

