    public function ipdPharmacyCancel(Request $request)
    {
        $admission_id = $request->admission_id;
        $hospital_id = Session::get('user.ses_hospital_no_pk');
        $invoice_number = DB::select("select invoice_no_pk from finc_invoicemst_sum_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id");

        $patientInfo = DB::select("select patient_no_fk from ipd_admitted_patlist_vw where admission_no_pk=$admission_id and au_entry_hospital_pk_no = $hospital_id ");
        $patientId = $patientInfo[0]->{'patient_no_fk'};
        $invoice_id = [];
        $price_0 = [];
        $item_type = [];
        if (!empty($invoice_number)) {
            foreach ($invoice_number as $value) {
                $invoice_id[] = $value->invoice_no_pk;
                $price_0[] = 0;
                $cancel[] = 1;
                $item_type[] = "MED";
            }
        }

        $item_details = DB::table("finc_invoicedtl_vw")->where('au_entry_hospital_pk_no', $hospital_id)->whereIn('module_code', ['PHR-I'])->whereIn("invoice_no_fk", $invoice_id)->whereNotIn("item_rate", $price_0)->orderBy('invoice_no_fk', 'desc')->get();

        $type = 'Pharmacy';
        return Template::loadview("admin.ipd.ipd_pharmcy_item_cancel_list", ["item_details" => $item_details, 'admission_id' => $admission_id, 'patientId' => $patientId, 'type' => $type]);
    }



