    public function ipdPatientDisListSearch(Request $request)
    {
        $admission_no = $request->admission_no != "" ? $request->admission_no : 0;
        $mobile_name = $request->mobile_name != "" ? $request->mobile_name : '';
        $bed_id = $request->bed_id != "" ? $request->bed_id : 0;
