        $empty = "";
        $ind = 1;
        $zero = 0;
        $lista = [];
        $stmt = $pdo->prepare($sql);
        $stmt->bindParam(':p_ref_ipdpatient_info', $lista, PDO::PARAM_STMT);
        $stmt->bindParam(':p_patient_no_pk', $zero, PDO::PARAM_INT);
        $stmt->bindParam(':p_admission_no_pk', $admission_no, PDO::PARAM_INT);
        $stmt->bindParam(':p_patient_name', $empty, PDO::PARAM_STR, 100);
        $stmt->bindParam(':p_su_no_fk', $dept_id, PDO::PARAM_INT);
        $stmt->bindParam(':p_from_admission_date', $to_date, PDO::PARAM_STR);
        $stmt->bindParam(':p_to_admission_date', $from_date, PDO::PARAM_STR);
        $stmt->bindParam(':p_disreq_flag', $ind, PDO::PARAM_INT);
        $stmt->bindParam(':p_dis_flag', $ind, PDO::PARAM_INT);
        $stmt->bindParam(':p_mobile_no', $mobile_name, PDO::PARAM_STR);
        $stmt->bindParam(':p_bed_no', $bed_id, PDO::PARAM_INT);
        $stmt->bindParam(':p_ward_no_fk', $ward_id, PDO::PARAM_INT);
        $stmt->bindParam(':p_adm_under_doc_no_fk', $doctor_id, PDO::PARAM_INT);
        $stmt->bindParam(':in_au_entry_hospital_no_fk', $au_hospital_pk_no, PDO::PARAM_INT);

        $stmt->execute();

        oci_execute($lista, OCI_DEFAULT);
        oci_fetch_all($lista, $array, 0, -1, OCI_FETCHSTATEMENT_BY_ROW + OCI_ASSOC);
        oci_free_cursor($lista);


        $ipdpatList = $array;
        return Template::loadView("admin.uhl.ipd-dis-patient-list-worklist", [
