    public function informReportList(Request $request)
    {
        // dd($request->all());
        $type = $request->type;
        $agent_id = $request->agent_id_hdn;
        $staff_id = $request->hdn_staff__id;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;

        if (!empty($date_from) && !empty($date_to)) {

            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $sql_cond_one = "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(reg_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";

        $inform = "where inform_text = " . "'" . $type . "'";
        if ($agent_id != '') {
            $sql_cond_one = $inform . ' and agent_no_fk = ' . $agent_id;
        } else if ($staff_id != '') {
            $sql_cond_one = $inform . ' and agent_no_fk = ' . $staff_id;
        } else {
            $sql_cond_one = $inform;
        }
        if (Session::get('user.ses_hospital_code') != 'IMPALA') {
            $report_data = db::select("
                    SELECT patient_name,
                    reg_date,
                    gender_txt,
                    marital_status_txt,
                    age,
                    mobile1,
                    full_name,
                    person_code,
                    SUM (LEDGER_AMT_SALES) sales,
                    SUM (LEDGER_AMT_DISCOUNT) discount,
                    SUM (LEDGER_AMT_PAYMENT) payment
            FROM patn_registration reg
                    LEFT JOIN hrms_personnel per
                    ON reg.agent_no_fk = per.person_no_pk
                    JOIN finc_ledgermst mst
                    ON REG.PATIENT_NO_PK = MST.PATIENT_NO_FK
                    $sql_cond_one $sql_cond
            GROUP BY patient_name,
                    reg_date,
                    gender_txt,
                    marital_status_txt,
                    age,
                    mobile1,
                    full_name,
                    person_code");
        } else {
            $report_data = db::select("
                    SELECT patient_name,
                    reg_date,
                    gender_txt,
                    marital_status_txt,
                    age,
                    mobile1,
                    full_name,
                    person_code,
                    SUM (LEDGER_AMT_SALES) sales,
                    SUM (LEDGER_AMT_DISCOUNT) discount,
                    SUM (LEDGER_AMT_PAYMENT) payment
            FROM patn_registration reg
                    LEFT JOIN hrms_personnel per
                    ON reg.agent_no_fk = per.person_no_pk
                    LEFT JOIN finc_ledgermst mst
                    ON REG.PATIENT_NO_PK = MST.PATIENT_NO_FK
                    $sql_cond_one $sql_cond
            GROUP BY patient_name,
                    reg_date,
                    gender_txt,
                    marital_status_txt,
                    age,
                    mobile1,
                    full_name,
                    person_code");
        }

        return Template::loadView("admin.ipd.reports.infom_patient_list", ['report_data' => $report_data, 'type' => $type]);
    }

