    public function ipdFinalBillPrintV2($admission_id = "")
    {
        ini_set("max_execution_time", 0);
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_id)->first();
        $paitent_info = DB::table('patient_info_vw')->where('patient_no_pk', $admission_info->patient_no_fk)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        // $barcode->setText('62542525245');
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($paitent_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $bill_info = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "!=", "MED")->get();
        $bill_info_phr = DB::table("finc_admission_billpaydtl")->where("admission_no_pk", $admission_id)->where("sales_amount_dtl", "!=", 0)->where("item_type", "=", "MED")->get();
        $bill = DB::table("finc_admission_billpay")->where("admission_no_fk", $admission_id)->first();
        // $paymentHistories = DB::SELECT("select mst.ledger_amt_payment,
        // 	mst.disc_amt_by_doc,mst.disc_amt_by_hosp,mst.ledger_amt_discount,
        // 	mst. au_entry_at as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
        // 	from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk join wsec_user uname
        // 	on mst.au_entry_by=uname.user_no_pk
        // 	where mst.admission_no_fk=$admission_id and
        // 	mst.ledger_amt_payment <> 0 and mst.ledger_amt_payment is not null  order by mst. au_entry_at asc");

        $paymentHistories = DB::select(DB::raw("select sum(mst.ledger_amt_payment) ledger_amt_payment,sum( mst.disc_amt_by_doc) disc_amt_by_doc,sum(mst.disc_amt_by_hosp) disc_amt_by_hosp,sum(mst.ledger_amt_discount) ledger_amt_discount,
                            trunc(mst. LEDGER_DATE) as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
                            from finc_ledgermst mst left join sysc_module mod
                            on mod.module_no_pk = mst.module_no_fk join wsec_user uname
                            on mst.au_entry_by=uname.user_no_pk
                            where mst.admission_no_fk= $admission_id
                            and mst.ledger_amt_payment > 0
                            group by trunc(mst. LEDGER_DATE),uname.user_name ,mst.pay_type
                            order by trunc(mst. LEDGER_DATE) asc"));

        $paymentHistories_phr = DB::SELECT("select mst.ledger_amt_payment,
        	mst.disc_amt_by_doc,mst.disc_amt_by_hosp,mst.ledger_amt_discount,
        	mst. au_entry_at as invoice_date,uname.user_name ledger_entry_txt,mst.pay_type
        	from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk join wsec_user uname
        	on mst.au_entry_by=uname.user_no_pk
        	where mst.admission_no_fk=$admission_id and
        	mst.ledger_amt_payment <> 0 and mst.ledger_amt_payment is not null and mod.module_code = 'PHR' order by mst. au_entry_at asc");

        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $userInfo = Auth::user();

        $discount_data = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk
    		where mst.admission_no_fk=$admission_id and mod.module_code NOT IN ('PHR','PHR-I')  ");

        foreach ($discount_data as $value) {
            $amount = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }
        $discount_data_phr = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk
    		where mst.admission_no_fk=$admission_id  and mod.module_code = 'PHR-I' "); // and mod.MODULE_CODE = 'PHR' or mod.module_code = 'PHR-I'

        foreach ($discount_data_phr as $value) {
            $amount_phr = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }



         $bill = DB::select(
            "select invoice_datetime,ITY_GROUP_HEADER_NAME,
                                item_name,INVOICE_NO_PK,ITEM_CODE,FULL_NAME,ITEM_TYPE,item_rate as rate,
                                sum (item_qty) qty,
                                sum (net_discount) net_discount,
                                sum (net_collection) amount,sum(CANCEL_QTY) cancel_qty
                            from finc_invoicedtl_detail_vw where admission_no_pk = $admission_id
                            group by ITY_GROUP_HEADER_NAME, item_name,invoice_datetime,INVOICE_NO_PK,ITEM_CODE,FULL_NAME,ITEM_TYPE,item_rate HAVING item_rate > 0
                            order by ITY_GROUP_HEADER_NAME,item_name asc"
        );
        // dd($bill);
       $advancePayment = DB::table('finc_ledgermst')
                  ->where('admission_no_fk', $admission_id)
                  ->sum('ledger_amt_payment');

        $report_dt = [];
        foreach ($bill as $data) {
            $report_dt[$data->ity_group_header_name][] = $data;
        }


        // $discount = DB::select("select ADMISSION_NO_FK,sum(LEDGER_AMT_DISCOUNT) discount from FINC_LEDGERMST where  ADMISSION_NO_FK = $admission_id  group by ADMISSION_NO_FK");
         $discount = DB::select("select admission_no_pk as admission_no_fk,sum(dis) discount from finc_ipdpatientbill_vw where  admission_no_pk = $admission_id  group by admission_no_pk");
        // dd( $discount);
        // return view("admin.ipd.ipd_business_office.ipd_final_bill_kbmh_v2", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'amount' => $amount, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr, 'amount_phr' => $amount_phr, 'report_dt' => $report_dt]);

        // dd($bill);
        $pdf = PDF::loadView("admin.ipd.ipd_business_office.ipd_final_bill_kbmh_v2", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'amount' => $amount, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr, 'amount_phr' => $amount_phr, 'report_dt' => $report_dt, 'discount' => $discount,'advancePayment'=>$advancePayment]);
        return $pdf->stream('ipd_final_bill.pdf');
    }





