        $discount_data = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk
    		where mst.admission_no_fk=$admission_id and mod.module_code NOT IN ('PHR','PHR-I')  ");

        foreach ($discount_data as $value) {
            $amount = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }
        $discount_data_phr = DB::SELECT("select sum(mst.ledger_amt_payment) ledger_amt_payment, sum(mst.ledger_amt_discount)  ledger_amt_discount
    		from finc_ledgermst mst left join sysc_module mod on mod.module_no_pk = mst.module_no_fk
    		where mst.admission_no_fk=$admission_id  and mod.module_code = 'PHR-I' "); // and mod.MODULE_CODE = 'PHR' or mod.module_code = 'PHR-I'

        foreach ($discount_data_phr as $value) {
            $amount_phr = [$value->ledger_amt_payment ? $value->ledger_amt_payment : 0, $value->ledger_amt_discount ? $value->ledger_amt_discount : 0];
        }



        $bill = DB::select("select invoice_datetime,ITY_GROUP_HEADER_NAME,
        item_name,INVOICE_NO_PK,
        sum (item_qty) qty,
        sum (item_rate) rate,
        sum (net_collection) amount,sum(CANCEL_QTY) cancel_qty
   from finc_invoicedtl_detail_vw where admission_no_pk = $admission_id and ITY_GROUP_HEADER_NAME = 'MEDICINE'
group by ITY_GROUP_HEADER_NAME, item_name,invoice_datetime,INVOICE_NO_PK
order by ITY_GROUP_HEADER_NAME,item_name asc");
        // $bill = db::table('finc_invoicedtl_detail_vw')
        // ->select('invoice_datetime','ity_group_header_name','item_name')
        // ->where('admission_no_pk',$admission_id)
        // // ->groupby('ity_group_header_name', 'item_name','invoice_datetime')
        // ->get()->toArray();

        // // dd($bill);

        $report_dt = [];
        foreach ($bill as $data) {
            $report_dt[$data->ity_group_header_name][] = $data;
        }

        $discount = DB::select("select ADMISSION_NO_FK,sum(LEDGER_AMT_DISCOUNT) discount
   from FINC_LEDGERMST where  ADMISSION_NO_FK = $admission_id  group by ADMISSION_NO_FK");
        // return view("admin.ipd.ipd_business_office.ipd_final_bill_kbmh_v2", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'amount' => $amount, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr, 'amount_phr' => $amount_phr, 'report_dt' => $report_dt]);


        $pdf = PDF::loadView("admin.ipd.ipd_business_office.ipd_final_bill_kbmh_v2", ['admission_info' => $admission_info, 'paitent_info' => $paitent_info, 'invoice_barcode' => $invoice_barcode, 'pat_barcode' => $pat_barcode, 'bill_info' => $bill_info, 'bill' => $bill, 'paymentHistories' => $paymentHistories, 'po_hospital_details' => $po_hospital_details, 'userInfo' => $userInfo, 'amount' => $amount, 'bill_info_phr' => $bill_info_phr, 'paymentHistories_phr' => $paymentHistories_phr, 'amount_phr' => $amount_phr, 'report_dt' => $report_dt, 'discount' => $discount]);
        return $pdf->download('ipd_final_bill.pdf');
    }

    public function nicuNotesStore(Request $request)
    {
        $sequence = DB::getSequence();
        $nicu_no_pk_seq = $sequence->nextValue('nicu_no_pk_seq');
        $data = [
            'patient_no_fk' => $request->hdn_patient_no_fk,
            'admission_no_fk' => $request->hdn_admission_no_pk,
            'nicuchart_type' => $request->nicu_chart_type,
            'notes' => $request->notes,
            'status' => 1
        ];
        $data['au_entry_by'] = Auth::user()->user_no_pk;
        $data['au_entry_at'] = date('Y-m-d h:i:s');
        $data['au_entry_session'] = 'Nicu Notes';
        $data['nicu_no_pk'] = $nicu_no_pk_seq;
        $data['au_entry_hospital_no_fk'] = Session::get('user.ses_hospital_no_pk');
        DB::table('ipd_nicu_chart')->insert($data);
        $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success',];

        return response()->json($message);
    }

