    public function cafeteriaReportList(Request $request)
    {
        $admission_id = $request->admission_id;
        $hdn_admission_id = $request->hdn_admission_id;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;

        if (!empty($date_from) && !empty($date_to)) {

            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));

        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($hdn_admission_id != "") ? " $clause admission_no_pk = $hdn_admission_id" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(invoice_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";

        $report_data = db::select("  SELECT ADMISSION_NO_PK,
            ITEM_NO_FK,
            ITEM.ITEM_NAME,
            SUM (ITEM_RATE * (ITEM_QTY - NVL (CANCEL_QTY, 0))) PRICE,
            SUM (ITEM_QTY - NVL (CANCEL_QTY, 0)) QTY
       FROM FINC_INVOICEMST MST, FINC_INVOICEDTL DTL, SYSC_SERVICEITEM ITEM
      WHERE MST.INVOICE_NO_PK = DTL.INVOICE_NO_FK
            AND DTL.ITEM_NO_FK = ITEM.ITEM_NO_PK $sql_cond and admission_no_pk is not null
            and item.item_type = 'FOOD'
   group by admission_no_pk, item_no_fk, item.item_name order by admission_no_pk asc");
        $admitted_data = [];
        foreach ($report_data as $data) {
            $admitted_data[$data->admission_no_pk][] = $data;
        }
        return Template::loadView("admin.ipd.reports.cafeteria_report_search_data", ['admitted_data' => $admitted_data]);
    }

