    public function lohsReportList(Request $request)
    {
        $hdn_admission_id = $request->hdn_admission_id;
        $request_department = $request->request_department;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;

        if (!empty($date_from) && !empty($date_to)) {
            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));
        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($request_department != "") ? " $clause su_no_fk = $request_department" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($hdn_admission_id != "") ? " $clause admission_no_pk = $hdn_admission_id" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(ip.ADMISSION_DATE) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";

        $report_data = DB::select("SELECT patient_no_pk,
             ip.admission_no_pk,
             TRUNC (admission_date) admission_date,
             primary_doctor_no_fk,
             fnc_docname (primary_doctor_no_fk) doctor_name,
             curr_bed_no_fk,
             (SELECT bed_name
                FROM ipds_bed
               WHERE bed_no_pk = ip.curr_bed_no_fk)
                bed_name,
             curr_ward_no_fk,
             su_no_fk,
             fnc_serviceunitname (su_no_fk) department_name,
             patient_name,
             gender_txt gender,
             dob,
             pat_age (dob, NVL (dod, TRUNC (admission_date))) age,
             (SELECT lookupdata_code
                FROM sysc_lookupdata
               WHERE lookupdata_no_pk = reg.blood_group)
                blood_group,
             mobile1 mobile,
             CEIL ( (NVL (ip.DIS_DATETIME, SYSDATE) - ip.ADMISSION_DATE))
                no_of_days
        FROM    ipd_admission ip
             LEFT JOIN
                patn_registration reg
             ON ip.patient_no_fk = reg.patient_no_pk
       WHERE EMERGENCY_DAYCARE_IND_TXT IS NULL $sql_cond");

        return Template::loadView("admin.ipd.reports.lohs_report_search_data", ['report_data' => $report_data]);
    }

