    public function backToadmissionID($adm_id)
    {

        return Template::loadview("admin.ipd.discharge.backto", [
            'dis_reqlists' => db::table('ipd_admitted_patlist_vw adm')
                ->select(
                    'adm.patient_photo',
                    'adm.patient_no_fk',
                    'adm.patient_name',
                    'adm.gender_txt',
                    'adm.age',
                    'adm.mobile1',
                    'adm.admission_no_pk',
                    'adm.admission_date',
                    'adm.dis_req_time',
                    'adm.cause_of_admission',
                    'adm.new_su_name',
                    'adm.new_ward_name',
                    'adm.new_bed_name',
                    'adm.primary_doctor_code',
                    'adm.primary_doctor_name',
                    'adm.refrral_doctor_name',
                    'adm.first_ref_doctor_name',
                    'adm.second_ref_doctor_name',
                    'adm.dis_req_time',
                    'adm.dis_datetime',
                    'dru.user_fullname as dru_name',
                    'du.user_fullname as du_name'
                )
                ->leftjoin('wsec_user dru', 'adm.dis_req_by', 'dru.person_no_fk')
                ->leftjoin('wsec_user du', 'adm.dis_by', 'du.user_no_pk')
                ->where('adm.admission_uid', $adm_id)
                ->get()
        ]);
    }

    public function returnToAdmission(Request $request, $admission_id)
    {
        try {
            // If linked to an admission, check revenue_ind or lock_ind
            if (!empty($admission_id)) {
                $ipd_admission = DB::table('ipd_admission')
                    ->where('admission_no_pk', $admission_id)
                    ->select('revenue_ind', 'lock_ind')
                    ->first();

                if (!empty($ipd_admission)) {
                    if ($ipd_admission->revenue_ind) {
                        throw new \Exception('This admission has already been posted for revenue, cannot be Return admission.');
                    }
                    // if ($ipd_admission->lock_ind) {
                    //     throw new \Exception('This Patient admission is locked and cannot be Return admission.');
                    // }
                }
            }

            db::table('ipd_admission')->where('admission_no_pk', $admission_id)->update([
                'dis_req_ind' => 0,
                'dis_ind' => 0,
                'au_entry_session' => 'Return From Discharge by:' . auth::user()->user_no_pk,
            ]);
            DB::commit();
            $message = ['msg' => 'Data Saved Successfully', 'title' => 'Success'];
        } catch (\Exception $e) {
            DB::rollback();
            $message = ['msg' => $e->getMessage(), 'title' => 'Error'];
        }

        return response()->json($message);
        return redirect()->route('ipd-back-to-admission');
    }

