        $report_data = DB::select("select count (patient_no_fk) total_patient,
                            ward.ward_name
                    from    ipd_admission ipd
                            join
                            ipds_ward ward
                            on ipd.curr_ward_no_fk = ward.ward_no_pk
                            $sql_cond $sql_cond_one
                    group by ward.ward_name");
        return Template::loadView("admin.ipd.reports.ward_wise_report_worklist", ['report_data' => $report_data, 'pat_type' => $pat_type]);
