    public function ipdInvoiceReportList(Request $request)
    {
        $invoice_id = $request->invoice_id;
        $hdn_patient_id = $request->hdn_patient_id;
        $date_from = $request->search_date_from;
        $date_to = $request->search_date_to;

        if (!empty($date_from) && !empty($date_to)) {
            $date_from = "$request->search_date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->search_date_to"; //date('Y/m/d', strtotime($request->date_to));
        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($hdn_patient_id != "") ? " $clause mst.patient_no_fk = $hdn_patient_id" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($invoice_id != "") ? " $clause invoice_no_pk = $invoice_id" : "";
        $clause = ($sql_cond == "") ? " and" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(invoice_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";

        $report_data = DB::select("SELECT invoice_no_pk,MST.CUSTOMER_NAME,
            TRUNC (invoice_date) invoice_date,
            mst.patient_no_fk,
            SUM (ledger_amt_sales) sales,
            SUM (ledger_amt_payment) payment,
            SUM (ledger_amt_discount) discount,
            SUM (ledger_amt_sales - ledger_amt_discount - ledger_amt_payment) due
            FROM finc_ledgermst lmst, finc_invoicemst mst
            WHERE mst.invoice_no_pk = lmst.invoice_no_fk AND mst.admission_no_pk IS NULL $sql_cond
            HAVING ROUND (SUM (ledger_amt_sales)) >
                    SUM (ledger_amt_payment) + SUM (ledger_amt_discount)
            GROUP BY invoice_no_pk, mst.patient_no_fk, TRUNC (invoice_date),MST.CUSTOMER_NAME
            ORDER BY invoice_no_pk");
        return Template::loadView("admin.ipd.reports.opd_invoice_wise_due_report_data", ['report_data' => $report_data]);
    }

