    public function bedTransferReportList(Request $request)
    {
        $ipd_add = $request->hdn_admission_id;
        $bed_id = $request->bed_id;
        $date_from = $request->date_from;
        $date_to = $request->date_to;

        if (!empty($date_from) && !empty($date_to)) {
            $date_from = "$request->date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->date_to"; //date('Y/m/d', strtotime($request->date_to));
        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($ipd_add != "") ? " $clause ipd_admission_bed.admission_no_fk = $ipd_add" : "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($bed_id != "") ? " $clause ipds_bed.bed_no_pk = $bed_id" : "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(ipd_admission_bed.ipd_adm_bed_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
        // dd($sql_cond);
        $report_data = DB::select("SELECT
                ipd_admission_bed.ipd_adm_bed_no_pk,
                ipd_admission_bed.ipd_adm_bed_date,
                ipd_admission_bed.admission_no_fk,
                ipd_admission_bed.sl_no,
                ipd_admission_bed.start_time,
                ipd_admission_bed.end_time,
                ipd_admission_bed.bed_no_fk,
                ipd_admission_bed.ward_no_fk,
                ipd_admission_bed.su_no_fk,
                ipd_admission_bed.bed_assignment_type,
                ipd_admission_bed.calculation_ind,
                ipd_admission_bed.invoice_no_fk,
                ipd_admission_bed.ledgertrn_no_fk,
                ipd_admission_bed.total_days,
                ipds_bed.bed_no_pk,
                ipds_bed.bed_name,
                ipds_ward.ward_name,
                ipd_admission_bed.status,
                ipd_admission.admission_uid,
                patn_registration.patient_name,
                 WSEC_USER.USER_FULLNAME
            FROM ipd_admission_bed
            LEFT JOIN ipds_bed ON ipds_bed.bed_no_pk = ipd_admission_bed.bed_no_fk
            LEFT JOIN ipds_ward ON ipds_ward.ward_no_pk = ipd_admission_bed.ward_no_fk
            join ipd_admission on ipd_admission.ADMISSION_NO_pK = ipd_admission_bed.admission_no_fk
            join patn_registration on patn_registration.patient_no_pk = ipd_admission.patient_no_fk
            join wsec_user on ipd_admission_bed.AU_ENTRY_BY = wsec_user.USER_NO_PK
            $sql_cond
            ORDER BY ipd_admission_bed.ipd_adm_bed_no_pk DESC");

        $beds = [];
        foreach ($report_data as $bed) {
            $beds[$bed->admission_uid][] = $bed;
        }
        return Template::loadView("admin.ipd.reports.bed_transfer_report_data", ['beds' => $beds]);
    }

    public function bedTransferReportPdf(Request $request)
    {
        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();
        $ipd_add = $request->hdn_admission_id;
        $bed_id = $request->bed_id;
        $date_from = $request->date_from;
        $date_to = $request->date_to;

        if (!empty($date_from) && !empty($date_to)) {
            $date_from = "$request->date_from"; //date('Y/m/d', strtotime($request->date_from));
            $date_to = "$request->date_to"; //date('Y/m/d', strtotime($request->date_to));
        } else {
            $date_from = "";
            $date_to = "";
        }

        $sql_cond = "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($ipd_add != "") ? " $clause ipd_admission_bed.admission_no_fk = $ipd_add" : "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($bed_id != "") ? " $clause ipds_bed.bed_no_pk = $bed_id" : "";
        $clause = ($sql_cond == "") ? " where" : " and";
        $sql_cond .= ($date_from != "") ? " $clause trunc(ipd_admission_bed.ipd_adm_bed_date) between TO_DATE('$date_from','DD/MM/YYYY') and TO_DATE('$date_to','DD/MM/YYYY')" : "";
        // dd($sql_cond);
        $report_data = DB::select("SELECT
        ipd_admission_bed.ipd_adm_bed_no_pk,
        ipd_admission_bed.ipd_adm_bed_date,
        ipd_admission_bed.admission_no_fk,
        ipd_admission_bed.sl_no,
        ipd_admission_bed.start_time,
        ipd_admission_bed.end_time,
        ipd_admission_bed.bed_no_fk,
        ipd_admission_bed.ward_no_fk,
        ipd_admission_bed.su_no_fk,
        ipd_admission_bed.bed_assignment_type,
        ipd_admission_bed.calculation_ind,
        ipd_admission_bed.invoice_no_fk,
        ipd_admission_bed.ledgertrn_no_fk,
        ipd_admission_bed.total_days,
        ipds_bed.bed_no_pk,
        ipds_bed.bed_name,
        ipds_ward.ward_name,
        ipd_admission_bed.status,
        ipd_admission.admission_uid,
        patn_registration.patient_name,
        WSEC_USER.USER_FULLNAME
        FROM ipd_admission_bed
        LEFT JOIN ipds_bed ON ipds_bed.bed_no_pk = ipd_admission_bed.bed_no_fk
        LEFT JOIN ipds_ward ON ipds_ward.ward_no_pk = ipd_admission_bed.ward_no_fk
        join ipd_admission on ipd_admission.ADMISSION_NO_pK = ipd_admission_bed.admission_no_fk
        join patn_registration on patn_registration.patient_no_pk = ipd_admission.patient_no_fk
        join wsec_user on ipd_admission_bed.AU_ENTRY_BY = wsec_user.USER_NO_PK
        $sql_cond
        ORDER BY ipd_admission_bed.ipd_adm_bed_no_pk DESC");

        $beds = [];
        foreach ($report_data as $bed) {
            $beds[$bed->admission_uid][] = $bed;
        }
        $title = '123456';
        $barcode = new BarcodeGenerator();
        $barcode->setText($title);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $barcode_no = $barcode->generate();

        $pdf = PDF::loadView("admin.reports.ipd_bed_transfer_print", [
            'beds' => $beds,
            'barcode_no' => $barcode_no,
            'from_date' => $date_from,
            'to_date' => $date_to,
            'po_hospital_details' => $po_hospital_details
        ])->setPaper('a4', 'landscape');
        return $pdf->download('ipd_bed_transfer_report.pdf');
    }




