    public function getDoctorReceivedPatient(Request $request)

    {
        $patientType = $request->input('patient_type', 'all');


        $user_no_pk = Session::get('user.ses_person_no_fk');

        $data = DB::table("IPD_V1_ADMITTED_PAT_NSREQ_WL_VW")
            ->orderBy("admission_date", 'DESC')
            ->where('MOVEMENT_NO', 2)
            ->where('DIS_IND', 0)
            ->where('primary_doctor_no_fk', $user_no_pk)
            ->select("IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.*")
            ->selectRaw("
                fnc_ipdvulnerability(IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.ADMISSION_NO_PK) as vulnerability_alert,
                fnc_ipdClinicalalert(IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.ADMISSION_NO_PK) as clinial_alert,
                fnc_ipdAllergiesalert(IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.ADMISSION_NO_PK) as allergy_alert
            ")
            ->get();


        // Base query for primary doctor patients
        $primaryDoctorPatients = DB::table("ipd_v1_admitted_pat_nsreq_wl_vw as pat")
            ->where('pat.movement_no', 2)
            ->where('pat.dis_ind', 0)
            ->where('pat.primary_doctor_no_fk', $user_no_pk)
            ->select(
                'pat.*',
                DB::raw("fnc_ipdvulnerability(pat.admission_no_pk) as vulnerability_alert"),
                DB::raw("fnc_ipdClinicalalert(pat.admission_no_pk) as clinial_alert"),
                DB::raw("fnc_ipdAllergiesalert(pat.admission_no_pk) as allergy_alert"),
                DB::raw("'primary' as source")
            );

        // Base query for referred patients
        $referredPatientsOnly = DB::table('ipd_consultrecord as cons')
            ->join('ipd_v1_admitted_pat_nsreq_wl_vw as pat', 'cons.admission_no_fk', '=', 'pat.admission_no_pk')
            ->where('cons.to_doctor_no_fk', $user_no_pk)
            ->select(
                'pat.*',
                DB::raw("fnc_ipdvulnerability(pat.admission_no_pk) as vulnerability_alert"),
                DB::raw("fnc_ipdClinicalalert(pat.admission_no_pk) as clinial_alert"),
                DB::raw("fnc_ipdAllergiesalert(pat.admission_no_pk) as allergy_alert"),
                DB::raw("'referred' as source")
            );

        // Apply filter based on patient type
        if ($patientType == 'primary') {
            $mergedPatients = $primaryDoctorPatients->get();
        } elseif ($patientType == 'referred') {
            $mergedPatients = $referredPatientsOnly->get();
        } else {
            $mergedPatients = $primaryDoctorPatients->get()->merge($referredPatientsOnly->get());
        }

        // Optional: Sort by admission_date
        $sortedPatients = $mergedPatients->sortByDesc('admission_date')->values();

        // dd($sortedPatients);

        return response()->json(['message' => 'success', 'data' => $sortedPatients], 200);
    }






