    public function setReceivePatient(Request $request)
    {
        $request->validate([
            'admission_no_pk' => 'required',
            'patient_no_fk' => 'required',
            'nurse_station_no' => 'required',
        ]);

        try {
            $au_entry_at = Carbon::now();
            $au_entry_at = $au_entry_at->toDateString();
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');


            $seq = $this->getSequence('patmovement_NO_PK_seq');

            $data = [
                'patmovement_no_pk' => $seq,
                'admission_no_fk' => $request->admission_no_pk,
                'movement_no' => 2,
                // 'movement_date' => date('m/d/Y'),
                'movement_date' => $au_entry_at,
                'au_entry_by' => Auth::id(),
                'au_entry_session' => $entry_session,
                'au_entry_hospital_no_fk' => $hospital_pk_no,
                'status' => 1,
            ];
            DB::table('IPD_patmovement')->insert($data);

            DB::table('ipd_admission_details')
                ->where('admission_no_pk', $request->admission_no_pk)
                ->update([
                    'ns_receive_ind' => 1,
                    'ns_receive_by' => $request->nurse_station_no,
                    'ns_receive_time' => date('Y-m-d'),
                    'au_update_at' => date('Y-m-d'),
                    'au_update_by' => Auth::id(),
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                ]);
            // dd($request->admission_no_pk);
            DB::commit();
            return response()->json(['title' => 'Success', 'message' => 'Successfully Received', 'success' => true], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['title' => 'Failed', 'message' => $th->getMessage(), 'success' => false], 422);
        }
    }

    public function ipdNursingNote($id)
    {
        $patient_data = DB::table("ipd_admitted_patlist_vw")
            ->select(
                'bed_name',
                'admission_no_pk',
                'patient_no_fk',
                'admission_uid',
                'admission_date',
                'patient_name',
                'gender_txt',
                'patient_code',
                'contact_number',
                'blood_group_text',
                'primary_doctor_name',
                'present_addr',
                'contact_relaion',
                'remarks',
                'patient_type',
                'pkg_item_name',
                'dis_advice',
                'dis_ind',
                'dis_req_ind',
                'patient_type_code',
                'ward_name',
                'ward_no_pk',
                'curr_bed_no_fk',
                'age',
                'ward_uid',
                'dob',
                'lock_ind',
                'lock_date',
                'lock_by',
                'lock_remarks'
            )
            ->where('admission_no_pk', $id)
            ->first();
        if (empty($patient_data)) {
            return view("admin.components.error_alert");
        }



        $allergy_alert = DB::table('ipd_nursingassessment')
            ->where('admission_no_fk', $patient_data->admission_no_pk)
            ->where('patient_no_fk', $patient_data->patient_no_fk)
            ->value('allergies');

        $clinicalcharacteristics = DB::table('ipd_nursingassessment')
            ->where('admission_no_fk', $patient_data->admission_no_pk)
            ->where('patient_no_fk', $patient_data->patient_no_fk)
            ->selectRaw("
                                        NVL(active_cancer, 0) +
                                        NVL(paralysis_paresis, 0) +
                                        NVL(recently_bedridden, 0) +
                                        NVL(localised_tendemess, 0) +
                                        NVL(dvt_assessment_swollen, 0) +
                                        NVL(dvt_assessment_calfswelling, 0) +
                                        NVL(dvt_assessment_pittingedema, 0) +
                                        NVL(dvt_assessment_collateral, 0) +
                                        NVL(dvt_assessment_previousdt, 0) +
                                        NVL(dvt_assessment_veinthrombosis, 0)
                                        AS total
                                    ")
            ->value('total');



        $vulnerabilityassessment = DB::table('ipd_nursingassessment')
            ->where('admission_no_fk', $patient_data->admission_no_pk)
            ->where('patient_no_fk', $patient_data->patient_no_fk)
            ->where(function ($query) {
                $query->where('CHILDREN16', 2)
                    ->orWhere('ADOLESCENT', 2)
                    ->orWhere('ELDER65', 2)
                    ->orWhere('FRAIL_ELDERLY', 2)
                    ->orWhere('TERMINALLY_ILL', 2)
                    ->orWhere('ADL', 2)
                    ->orWhere('INTENSE_CHRONIC_PAIN', 2)
                    ->orWhere('WOMEN_LABOUR', 2)
                    ->orWhere('WOMEN_EXP_TER_PREGNANCY', 2)
                    ->orWhere('EMOTIONAL_DISORDER', 2)
                    ->orWhere('DRUG_DEPENDENCY', 2)
                    ->orWhere('VICTIM_NEGLECT', 2)
                    ->orWhere('INFECTIOUS_DISEASES', 2)
                    ->orWhere('RECEIVING_THERAPY', 2)
                    ->orWhere('IMMUNE_COMPROMISED', 2);
            })
            ->first();


        return Template::loadview("admin.ipd.nurse_station.v2.nursing_note", compact('patient_data', 'allergy_alert', 'clinicalcharacteristics', 'vulnerabilityassessment'));
    }

