    public function dischargeRequest(Request $request)
    {
        $request->validate([
            'admission_no_pk' => 'required'
        ]);

        try {
            DB::table('ipd_admission')
                ->where('admission_no_pk', $request->admission_no_pk)
                ->update([
                    'dis_req_ind' => 1,
                    'dis_req_by' => Auth::id(),
                    'dis_req_time' => date('Y-m-d'),
                    'au_update_by' => Auth::id(),
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                ]);

            $this->message = ['message' => 'Discharge Request Sent Successfully', 'title' => 'Success'];
            return response()->json($this->message, 200);
        } catch (\Exception $e) {
            $this->message = ['message' => $e->getMessage(), 'title' => 'Error'];
            return response()->json($this->message, 422);
        }
    }


