    public function approximateBedCalculation($bed_history, $adms_no)
    {

        // $bed_history = [
        //             (object)['start_time' => '2025-08-01 12:00:00','end_time' => '','days' => 0,'bed_no_fk' => 1,'bed_name' => 1,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 1,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2025-08-01 12:00:00','end_time' => '2025-08-07 15:00:00','days' => 0,'bed_no_fk' => 1,'bed_name' => 1,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 1,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2025-08-01 12:00:00','end_time' => '2025-08-07 15:01:00','days' => 0,'bed_no_fk' => 1,'bed_name' => 1,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 1,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2025-08-01 12:00:00','end_time' => '2025-08-01 12:10:00','days' => 0,'bed_no_fk' => 1,'bed_name' => 1,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 1,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],

        //             (object)['start_time' => '2023-10-01 12:00:00','end_time' => '2023-10-02 15:00:00','days' => 0,'bed_no_fk' => 2,'bed_name' => 2,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 2,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 12:00:00','end_time' => '2023-10-02 15:01:00','days' => 0,'bed_no_fk' => 2,'bed_name' => 2,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 2,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],

        //             (object)['start_time' => '2023-10-01 09:00:00','end_time' => '2023-10-01 15:00:00','days' => 0,'bed_no_fk' => 3,'bed_name' => 3,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 3,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 09:00:00','end_time' => '2023-10-01 15:01:00','days' => 0,'bed_no_fk' => 3,'bed_name' => 3,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 3,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],

        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-02 15:00:00','days' => 0,'bed_no_fk' => 4,'bed_name' => 4,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 4,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-02 15:01:00','days' => 0,'bed_no_fk' => 4,'bed_name' => 4,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 4,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],

        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-01 15:00:00','days' => 0,'bed_no_fk' => 5,'bed_name' => 5,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 5,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-01 15:01:00','days' => 0,'bed_no_fk' => 4,'bed_name' => 4,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 4,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-01 9:00:00','days' => 0,'bed_no_fk' => 5,'bed_name' => 5,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 5,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //             (object)['start_time' => '2023-10-01 08:30:00','end_time' => '2023-10-01 9:01:00','days' => 0,'bed_no_fk' => 5,'bed_name' => 5,'ward_no_fk' => 1,'ward_name' => 1,'ipd_adm_bed_no_pk' => 5,'calculation_ind' => 0,'total_days' => 0,'status' => 1,],
        //         ];






        foreach ($bed_history as $key => $item) {
            // Assuming $startDateTime and $endDateTime are Carbon instances or datetime strings
            $startDateTime = Carbon::parse($item->start_time); // Example: dynamic datetime
            $endDateTime = Carbon::parse($item->end_time);   // Example: dynamic datetime

            $add_day = 0;
            $add_end_day = 0;
            $startHMinute = $startDateTime->hour . '.' . $startDateTime->minute;
            $endHMinute = $endDateTime->hour . '.' . $endDateTime->minute;


            // if($key == 2){
            //     dd($startHMinute , $endHMinute);
            // }

            if ($startHMinute < 9) {
                $add_day = 1;
            }

            // Adjust both start and end times to 12:00 PM (ignoring the actual time part)
            $start = $startDateTime->copy()->setTime(12, 0);


            if (empty($item->end_time)) {
                $end = Carbon::now();

                $endhourMinute = $end->hour . '.' . $end->minute;
                if ($endhourMinute > 15) {
                    $add_end_day = 1;
                }
            } else {
                $end = $endDateTime->copy()->setTime(12, 0);

                if ($endHMinute > 15) {
                    $add_end_day = 1;
                }
            }

            $days = $start->diffInDays($end);

            if ($days == 0 && $endHMinute > 9) {
                $add_end_day = 1;
            }

            // if($key == 1){
            //     dd($start , $end,  $days);
            // }
            $days = $days + $add_day + $add_end_day;
            $item->days = $days == 0 ? 1 : $days;
            $item->total_days =  $item->days;
            $item->total = $item->days * $item->bed_charge_amount;
        }

        // Package Bed days
        $package_no_fk = DB::table("IPD_ADMISSION")
            ->where('ADMISSION_NO_PK', $adms_no)
            ->where('PKG_PATIENT_IND', 1)
            ->value('pkg_item_no_fk');


        if (!empty($package_no_fk)) {
            $item_info = DB::table("SYSC_SERVICEITEM_AUTO")
                ->join('SYSC_SERVICEITEM', 'SYSC_SERVICEITEM.ITEM_NO_PK', 'SYSC_SERVICEITEM_AUTO.AUTO_ITEM_NO_FK')
                ->where('SYSC_SERVICEITEM_AUTO.ITEM_NO_FK', $package_no_fk)
                ->where('SYSC_SERVICEITEM.ITEM_TYPE', 'BED')
                ->select('SYSC_SERVICEITEM_AUTO.AUTO_ITEM_NO_FK', 'SYSC_SERVICEITEM_AUTO.ITEM_QTY', 'SYSC_SERVICEITEM.ITEMTYPE_NO_FK', 'SYSC_SERVICEITEM.ITEM_NO_PK')
                ->first();
            //  dd($item_info);
            $free_days = @$item_info->item_qty;
            $item_no_pk = @$item_info->item_no_pk;



            $available_bed = DB::table('ipds_bed')
                ->where('BED_CHARGE_ITEM_NO_FK', $item_no_pk)
                // ->where('bed_status', 1)
                ->pluck('bed_no_pk')->toArray();



            // dd($available_bed, $free_days,$item_info );

            // Find the first bed assignment (by earliest start_time) and get its primary key
            $bed_history = collect($bed_history)->sortBy('start_time')->values();


            // Only set days for the first bed assignment (by pk) if package bed exists
            if (!empty($available_bed)) {
                // Track how many free days are left to allocate
                $remaining_free_days = (int) $free_days;
                foreach ($bed_history as $item) {
                    if (in_array($item->bed_no_fk, $available_bed)) {
                        // If there are still free days left
                        if ($remaining_free_days > 0) {
                            // If this bed assignment covers more than the remaining free days
                            if ($item->days >= $remaining_free_days) {
                                $item->remarks = "Applied {$remaining_free_days} Days from {$free_days} Days Package";
                                $item->days = $item->days - $remaining_free_days;
                                $item->days = $item->days < 0 ? 0 : $item->days;
                                $item->total = $item->days * $item->bed_charge_amount;
                                $remaining_free_days = 0;
                            } else {
                                // This bed assignment is fully covered by free days
                                $item->remarks = "Applied {$item->days} Days from {$free_days} Days Package";
                                $remaining_free_days -= $item->days;
                                $item->days = 0;
                                $item->total = 0;
                            }
                        } else {
                            // No free days left, normal calculation
                            $item->total = $item->days * $item->bed_charge_amount;
                        }
                    } else {
                        // Not an available bed, normal calculation
                        $item->total = $item->days * $item->bed_charge_amount;
                    }
                }
                // Exit the loop after updating the first bed assignment group

            }

            $bed_history = collect($bed_history)->sortBy('end_time')->values();
        }


        return $bed_history;
    }

    public function updateAssignBedV2(Request $request)
    {
        $request->validate([
            'prev_bed_no_fk' => 'required',
            'curr_bed_no_fk' => 'required',
            'ward_no_fk' => 'required',
            'admission_no_pk' => 'required'
        ]);

        try {

            DB::beginTransaction();

            $word_no_fk = DB::table('ipds_bed')->where('bed_no_pk', $request->curr_bed_no_fk)->value('ward_no_fk');
            $su_no_fk = DB::table('ipds_ward')->where('ward_no_pk', $word_no_fk)->value('service_unit_no_fk');
            $prev_word_no_fk = DB::table('ipds_bed')->where('bed_no_pk', $request->prev_bed_no_fk)->value('ward_no_fk');


            $emr_ind = DB::table('ipds_ward')->where('ward_no_pk', $word_no_fk)->value('emr_ind');
            if ($emr_ind == 1) {
                $iptype_ind = 2;
            } else {
                $iptype_ind = 1;
            }



            $iptype = DB::table('ipd_admission')->select('iptype_ind')->where('admission_no_pk', $request->admission_no_pk)->first()->iptype_ind;
            if ($iptype == 2 && $emr_ind != 1) {
                $ref_from_emr_ind = 1;
            } else {
                $ref_from_emr_ind = 0;
            }


            DB::table('ipd_admission')
                ->where('admission_no_pk', $request->admission_no_pk)
                ->update([
                    'curr_bed_no_fk' => $request->curr_bed_no_fk,
                    'curr_ward_no_fk' => $word_no_fk,
                    'iptype_ind' => $iptype_ind,
                    'ref_from_emr_ind' => $ref_from_emr_ind,
                    'au_update_at' => date('Y-m-d'),
                    'au_update_session' => "SESSION",
                    'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                ]);




            $sequence = $this->getSequence('ipd_admission_bed_seq');
            $au_entry_at = Carbon::now();
            $au_entry_at = $au_entry_at->toDateString();
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $movement_seq = $this->getSequence('patmovement_no_pk_seq');

            $data = [
                'PATMOVEMENT_NO_PK' => $movement_seq,
                'ADMISSION_NO_FK' => $request->admission_no_pk,
                'MOVEMENT_DATE' => date('Y-m-d'),
                'MOVEMENT_NO' => 3,
                'status' => 1,
                'au_entry_at' => $au_entry_at,
                'au_entry_by' => Auth::id(),
                'au_entry_session' => $entry_session,
                'au_entry_hospital_no_fk' => $hospital_pk_no,

            ];

            if ($word_no_fk != $prev_word_no_fk) {
                DB::table('IPD_PATMOVEMENT')->insert($data);
            }

            if ($request->transfer_hold == 1) {
                DB::table('ipd_admission_bed')->where('admission_no_fk', $request->admission_no_pk)->whereNull('end_time')->update(['status' => 2]);
                DB::table('ipds_bed')
                    ->where('bed_no_pk', $request->curr_bed_no_fk)
                    ->update([
                        'bed_status' => 2,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                    ]);
            } else {
                DB::table('ipd_admission_bed')->where('admission_no_fk', $request->admission_no_pk)->whereNull('end_time')->update(['end_time' => date('Y-m-d H:i:s')]);


                DB::table('ipds_bed')
                    ->where('bed_no_pk', $request->prev_bed_no_fk)
                    ->update([
                        'bed_status' => 1,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                    ]);


                DB::table('ipds_bed')
                    ->where('bed_no_pk', $request->curr_bed_no_fk)
                    ->update([
                        'bed_status' => 2,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                    ]);
            }

            DB::table('ipd_admission_details')->where('admission_no_pk', $request->admission_no_pk)->update([
                'ward_no_fk' => $word_no_fk,
            ]);






            // $su_no_fk = DB::table("ipd_admitted_patlist_vw")->where('admission_no_pk', $request->admission_no_pk)->value('su_no_fk');

            $data = [
                'ipd_adm_bed_no_pk' => $sequence,
                'admission_no_fk' => $request->admission_no_pk,
                'sl_no' => 1,
                'start_time' => date('Y-m-d H:i:s'),
                'ipd_adm_bed_date' => date('Y-m-d H:i:s'),
                'bed_no_fk' => $request->curr_bed_no_fk,
                'ward_no_fk' => $word_no_fk,
                'su_no_fk' => $su_no_fk,
                'bed_assignment_type' => 'BEDTRANSFER',
                'au_entry_at' => $au_entry_at,
                'au_entry_by' => Auth::id(),
                'au_entry_session' => $entry_session,
                'au_entry_hospital_no_pk' => $hospital_pk_no,
                'status' => 1,
            ];
            DB::table('ipd_admission_bed')->insert($data);

            DB::commit();
            return response()->json(['title' => 'Success', 'message' => 'Successfully Transferred', 'success' => true], 200);
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['title' => 'Failed', 'message' => $e->getMessage(), 'success' => false], 422);
        }
    }


    public function updateAssignBedActiveFreeV2(Request $request)
    {
        $request->validate([
            'ipd_adm_bed_no_pk' => 'required',
            'active_free' => 'required',

        ]);

        try {

            DB::beginTransaction();
            $ipd_admission = DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $request->ipd_adm_bed_no_pk)
                ->select(
                    'admission_no_fk',
                    'ward_no_fk',
                    'bed_no_fk'
                )->first();



            // 1 => Active, 2=> Free
            if ($request->active_free == 1) {


                $data = DB::table('ipd_admission_bed')->where('admission_no_fk', $ipd_admission->admission_no_fk)->where('ipd_adm_bed_no_pk', '!=', $request->ipd_adm_bed_no_pk)->whereNull('end_time')->where('status', 1)->get();

                DB::table('ipd_admission_bed')->where('admission_no_fk', $ipd_admission->admission_no_fk)->where('ipd_adm_bed_no_pk', '!=', $request->ipd_adm_bed_no_pk)->whereNull('end_time')->where('status', 1)->update(['status' => 2]);
                foreach ($data as $item) {
                    DB::table('ipds_bed')
                        ->where('bed_no_pk', $item->ipd_adm_bed_no_pk)
                        ->update([
                            'bed_status' => 2,
                            'au_update_at' => date('Y-m-d'),
                            'au_update_session' => "SESSION",
                            'au_update_hospital_no_fk' => Session::get('user.ses_hospital_no_pk'),
                        ]);
                }


                DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $request->ipd_adm_bed_no_pk)->update(['status' => 1]);
                DB::table('ipds_bed')
                    ->where('bed_no_pk', $ipd_admission->bed_no_fk)
                    ->update([
                        'bed_status' => 2,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                    ]);



            } else if ($request->active_free == 2) {

                DB::table('ipds_bed')
                    ->where('bed_no_pk', $ipd_admission->bed_no_fk)
                    ->update([
                        'bed_status' => 1,
                        'au_update_at' => date('Y-m-d'),
                        'au_update_session' => "SESSION",
                        'au_update_hospital_no_fk' => Session::get('user.ses_hospital_id'),
                    ]);
                DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $request->ipd_adm_bed_no_pk)->update(['end_time' => date('Y-m-d H:i:s')]);
            }

            DB::commit();
            return response()->json(['title' => 'Success', 'message' => 'Successfully Saved', 'success' => true], 200);
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['title' => 'Failed', 'message' => $e->getMessage(), 'success' => false], 422);
        }
    }

    public function getBedByWordWise(Request $request)
    {

        $wrd_no = $request->ward_no_fk;
        $bed_status = $request->bed_status;
        $ipds_beds = DB::table('ipds_bed');
        if (!empty($wrd_no) && $wrd_no != 'NaN') {
            $ipds_beds->where("ward_no_fk", "=", $wrd_no);
        }
        if (!empty($bed_status)) {
            $ipds_beds->where("bed_status", "=", $bed_status);
        }


        $ipds_beds = $ipds_beds->where('status', 1)->whereNotNull('ward_no_fk')->orderBy('bed_no_pk', 'asc')->get();

        $bedStatus['total_beds'] = count($ipds_beds);
        $bedStatus['available'] = collect($ipds_beds)->where('bed_status', 1)->count();
        $bedStatus['occupied'] = collect($ipds_beds)->where('bed_status', 2)->count();
        $bedStatus['not_ready'] = collect($ipds_beds)->where('bed_status', 3)->count();


        return response()->json(['ipds_beds' => $ipds_beds, 'bedStatus' => $bedStatus], 200);
    }




    public function ipdPatientMedicine($patient_id = "", $admission_uid = "", $type = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();
        // dd($patient_info);
        $duration_mu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_name");
        $communicated_by = $this->getLookupListByCode("IPDPSNMEDIA");

        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");
        $dose = $this->getPresLookupListByCode("DOSE", "pres_lookupdata_name");
        $meddurmu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_code");
        $route = $this->getPresLookupListByCode("ROUTE", "pres_lookupdata_name");
        $ipd_followup_type = $this->getLookupListByCode("IPDFOLLOWUPTYPE");
        $ipd_med_priority = $this->getLookupListByCode("IPDMEDPRIORITY");

        $pat_prescription_list = DB::table("psn_t_prescription_vw")
            ->select(
                "prescription_no_pk",
                "au_entry_at",
                "appoint_no_fk",
                "patient_no_fk",
                "dental_ind",
                "eye_ind",
                "patient_code",
                "doctor_name",
                "su_name",
                "prescription_date",
                "doctor_person_no_fk",
                "admission_no_fk",
                "prescription_uid"
            )
            ->where("patient_no_fk", $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderBy("prescription_no_pk", "desc")->get();


            $all = DB::table('psn_t_prescription_med as med')
            ->leftJoin('psn_t_prescription_vw as pres', 'med.prescription_no_fk', '=', 'pres.prescription_no_pk')
            ->leftJoin('psn_t_prescription as p', 'med.prescription_no_fk', '=', 'p.prescription_no_pk')
            ->leftJoin('wsec_user', 'med.discontinue_by', '=', 'wsec_user.user_no_pk')
            ->select([
                'med.prescription_med_no_pk',
                'med.prescription_no_fk',
                'med.prescription_uid',
                'med.item_no_fk',
                'med.generic_name',
                'med.brand_name',
                'med.discontine_ind',
                'med.dosage',
                'med.route',
                'med.item_qty',
                'med.AU_ENTRY_AT',
                'med.discontinue_by',
                'med.DISCONTINUE_TIME',
                'med.discontinue_reason',
                'med.duration',
                'med.instruction_take',
                'med.duration_mu',
                'pres.doctor_name',
                'pres.prescription_date',
                'p.order_med_priority',
                'wsec_user.user_fullname'
            ])
            ->where('med.patient_no_fk', $patient_id)
            ->where('med.admission_pk_no', $admission_uid)
            // ->orderBy('med.prescription_no_fk', 'desc')
            ->orderBy('med.au_entry_at', 'asc')
            ->get();



        $prescription_medicine_list = $all
            ->sortByDesc('prescription_med_no_pk')
            // ->unique('item_no_fk')
            ->values();
        $item_type = DB::table('sysc_itemtype_workflow')->select('workflow_code')->where('service_billing_ind', 1)->where('status', 1)->orderBy('workflow_code', 'asc')->get()->toArray();
        // dd($prescription_medicine_list);
        $item_type_list = [];
        if (!empty($item_type)) {
            foreach ($item_type as $key => $value) {
                $item_type_list[] = $value->workflow_code;
            }
        }
        $item_type_lists = !empty($item_type_list) ? implode(',', $item_type_list) : '';

        // $prescription_medicine_list = DB::table('psn_t_prescription_med')
        //     ->where('patient_no_fk', $patient_id)
        //     ->where('admission_pk_no', $admission_uid)
        //     ->orderBy('prescription_no_fk', 'desc')
        //     ->get()
        //     ->unique('item_no_fk');

        // dd($prescription_medicine_list,$patient_id,$admission_uid);
        return Template::loadview("admin.ipd.nurse_station.v2.patient_medicine", ['pat_prescription_list' => $pat_prescription_list, 'patient_info' => $patient_info, 'duration_mu' => $duration_mu, 'communicated_by' => $communicated_by, 'instructions' => $instructions, 'dose' => $dose, 'meddurmu' => $meddurmu, 'route' => $route, 'ipd_followup_type' => $ipd_followup_type, 'type' => $type, 'prescription_medicine_list' => $prescription_medicine_list,
        'item_type_lists' => $item_type_lists,'ipd_med_priority'=>$ipd_med_priority]);
    }

    //for fresh
    public function ipdPrescriptionFreshOrderV1($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select(
                "a.*",
                "b.admission_no_pk",
                "b.admission_uid",
                "b.admission_date",
                "b.ward_name",
                "b.bed_name",
                "b.bed_uid",
                "b.admitted_department",
                "b.primary_doctor_no_fk",
                "b.primary_doctor_name"
            )
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', 'a.patient_no_pk', '=', 'b.patient_no_fk')
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();

        $latest_per_item = DB::table('psn_t_prescription_med')
            ->select('item_no_fk', DB::raw('MAX(prescription_med_no_pk) as last_med_pk'))
            ->where('patient_no_fk', $patient_id)
            ->where('admission_pk_no', $admission_uid)
            ->groupBy('item_no_fk');

        $prescription_fresh_order = DB::table('psn_t_prescription_med as med')
            ->joinSub($latest_per_item, 'latest', function($join) {
                $join->on('med.item_no_fk', '=', 'latest.item_no_fk')
                    ->on('med.prescription_med_no_pk', '=', 'latest.last_med_pk');
            })
            ->leftJoin('psn_t_prescription_vw as pres', 'med.prescription_no_fk', '=', 'pres.prescription_no_pk')
            ->leftJoin('psn_t_prescription as p', 'med.prescription_no_fk', '=', 'p.prescription_no_pk')
            ->leftJoin('wsec_user', 'med.discontinue_by', '=', 'wsec_user.user_no_pk')
            ->select([
                'med.prescription_med_no_pk',
                'med.prescription_no_fk',
                'med.prescription_uid',
                'med.item_no_fk',
                'med.generic_name',
                'med.brand_name',
                'med.discontine_ind',
                'med.dosage',
                'med.route',
                'med.item_qty',
                'med.AU_ENTRY_AT',
                'med.discontinue_by',
                'med.DISCONTINUE_TIME',
                'med.discontinue_reason',
                'med.duration',
                'med.instruction_take',
                'med.duration_mu',
                'pres.doctor_name',
                'pres.prescription_date',
                'p.order_med_priority',
                'wsec_user.user_fullname'
            ])
            ->orderByDesc('med.AU_ENTRY_AT')
            ->get();

        return response()->json([
            'fresh_order_med' => $prescription_fresh_order,
            'patient' => $patient_info
        ], 200);
    }


