    public function storeNurseStationPatientDetailsV2(Request $request)
    {
        // dd($request->all());

        $request->validate([
            'doctor_id' => 'required'
        ]);

        try {
            DB::beginTransaction();
            $auth_id = Auth::id();
            $user_info = Auth::user();
            $followup_date_char = explode("/", $request->followUpDate);
            $followup_date_day = $followup_date_char[0];
            $followup_date_month = $followup_date_char[1];
            $followup_date_year = $followup_date_char[2];
            $followup_date = $followup_date_day . "/" . $followup_date_month . "/" . $followup_date_year;
            $followup_time_char = explode(":", $request->followUpTime);
            $followup_time_h = $followup_time_char[0];
            $followup_time_m = $followup_time_char[1];
            $followup_time = $followup_time_h . ":" . $followup_time_m;
            $follow_up_type_date_char = explode("/", $request->followUpTypeDate);
            $follow_up_type_date_day = $follow_up_type_date_char[0];
            $follow_up_type_date_month = $follow_up_type_date_char[1];
            $follow_up_type_date_year = $follow_up_type_date_char[2];
            $follow_up_type_date = $follow_up_type_date_day . "/" . $follow_up_type_date_month . "/" . $follow_up_type_date_year;
            $follow_up_type_time_char = explode(":", $request->followUpTypeTime);
            $follow_up_type_time_time_h = $follow_up_type_time_char[0];
            $follow_up_type_time_time_m = $follow_up_type_time_char[1];
            $follow_up_type_time = $follow_up_type_time_time_h . ":" . $follow_up_type_time_time_m;
            $in_doctor_person_no_fk = $request->doctor_id;
            $in_service_unit_no_fk = $request->doctor_id;
            $in_admission_no_fk = $request->hdn_admission_no_pk;
            $in_ipd_ind = 1;
            $in_hospital_code = 'HC';
            $in_ipd_instruct_media_name = $request->instruct_media_name;
            $txt_pulse = $request->txt_pulse;
            $txt_bp_sys = $request->txt_bp_sys;
            $txt_bp_dia = $request->txt_bp_dia;
