            $null = '';

            // OUT PAREMETER INITIALIZE
            $out_prescription_no_pk = $out_prescription_code = $out_error = "";

            $pdo = DB::getPdo();
            $prescription = $pdo->prepare("begin pkg_emr.prescription_ipd(
                                                    :in_doctor_person_no_fk,
                                                    :in_su_no_fk,
                                                    :in_admission_no_fk,
                                                    :in_ipd_ind,
                                                    :in_hospital_uid,
                                                    :in_ipd_instruct_media_name,
                                                    :in_follow_up_date,
                                                    :in_follow_up_time,
                                                    :in_follow_up_note,
                                                    :in_advice,
                                                    :in_assessment,
                                                    :in_treatement_plan,
                                                    :in_pat_complains,
                                                    :in_follow_up_type_date,
                                                    :in_follow_up_type_time,
                                                    :in_follow_up_type,
