                                                    :in_spo2,
                                                    :in_total_intake,
                                                    :in_total_output,
                                                    :in_bed_sore,
                                                    :in_lime_physio,
                                                    :in_chest_physio,
                                                    :in_anemia,
                                                    :in_jaundice,
                                                    :in_a_lookupdata_item_no_fk,
                                                    :in_a_lookup_uid,
                                                    :in_a_lookupdata_uid,
                                                    :in_a_entry_serial_dtl,
                                                    :in_a_prescrition_data,
                                                    :in_a_item_no_fk,
                                                    :in_a_entry_serial,
                                                    :in_a_generic_name,
