            //--------vitals----------------
            $prescription->bindparam(':in_height_val', $height);
            $prescription->bindparam(':in_hight_mu_name', $null);
            $prescription->bindparam(':in_weight_val', $weight);
            $prescription->bindparam(':in_weight_mu_name', $null);
