            $prescription->bindparam(':in_bowel_condition', $in_bowel_condition);
            $prescription->bindparam(':in_bladder_condition', $in_bladder_condition);
            $prescription->bindparam(':in_dehydeation', $in_dehydeation);
            $prescription->bindparam(':in_rr', $in_rr);
