            //------- prescription details----
            $prescription->bindArray(':in_a_lookupdata_item_no_fk', $in_item_lookupdata_no_fk, count($in_item_lookupdata_no_fk), $numelems, SQLT_INT);
            $prescription->bindArray(':in_a_lookup_uid', $in_itemtype_lookup_code, count($in_itemtype_lookup_code), $numelems, SQLT_CHR);
            $prescription->bindArray(':in_a_lookupdata_uid', $in_itemtype_lookupdata_code, count($in_itemtype_lookupdata_code), $numelems, SQLT_CHR);
            $prescription->bindArray(':in_a_entry_serial_dtl', $in_report_serial_dtl, count($in_report_serial_dtl), $numelems, SQLT_INT);
            $prescription->bindArray(':in_a_prescrition_data', $in_presdtl_data, count($in_presdtl_data), $numelems, SQLT_CHR);

            //---- prescription medicine ----
            $prescription->bindArray(':in_a_item_no_fk', $medicine_item_id_arr, (!empty($medicine_item_id_arr) ? count($medicine_item_id_arr) : 1), $numelems, SQLT_INT);
