    public function getMedicineApproval(Request $request)
    {


        if ($request->medicine_approval == 1) {
            //   $con = "(CASE WHEN (
            //         SELECT COUNT(*)
            //         FROM PSN_T_PRESCRIPTION_MED
            //         WHERE PSN_T_PRESCRIPTION_MED.prescription_no_fk = pres_ipd_medicine_vw.prescription_no_pk
            //         AND nvl(approve_ind,0) = 0
            //     ) = 0 THEN 1 ELSE 0 END) AS all_approved";

            $con = "(SELECT COUNT(*)
                    FROM PSN_T_PRESCRIPTION_MED
                    WHERE PSN_T_PRESCRIPTION_MED.prescription_no_fk = pres_ipd_medicine_vw.prescription_no_pk
                    AND NVL(approve_ind, 0) = 1) >= 1";
        } else {
            $con = "
                (SELECT COUNT(*)
                    FROM PSN_T_PRESCRIPTION_MED
                    WHERE PSN_T_PRESCRIPTION_MED.prescription_no_fk = pres_ipd_medicine_vw.prescription_no_pk
                    AND NVL(approve_ind, 0) = 0) >= 1";
        }


        $data = DB::table('pres_ipd_medicine_vw')->select(
            'admission_no_pk',
            'admission_date',
            'bed_name',
            'ward_name',
            'prescription_no_pk',
            'prescription_uid',
            'prescription_date',
            'patient_no_fk',
            'uhid',
            'patient_name',
            'gender_txt',
            'mobile1',
            'doctor_name',
            'su_name'
        )->whereRaw($con)->orderByDesc('prescription_no_pk')->get();




        return response()->json(['data' => $data], 200);
    }

