    public function medicineApproveRequest(Request $request)
    {
        try {
            if (!isset($request->approve_ind)) {
                throw new Exception('please select at least one item!');
            }
            DB::beginTransaction();
            foreach ($request->approve_ind as $key => $value) {
                $data = [
                    'approve_ind' => 1,
                    'approve_date' => new DateTime('now'),
                    'approve_by' => Auth::id(),
                ];
                DB::table('PSN_T_PRESCRIPTION_MED')->where('prescription_med_no_pk', $value)->update($data);
            }
            DB::commit();
            return response()->json(['msg' => 'Successfully Approved', 'title' => 'Success'], 200);
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['msg' => $e->getMessage(), 'title' => 'Failed'], 422);
        }
    }

    public function ipdNursingRequistion($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();

        return Template::loadview("admin.ipd.nurse_station.v2.nursing_requisition", ['patient_info' => $patient_info]);
    }

    public function ipdInvestigationRequistion($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.lock_ind")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();

        return Template::loadview("admin.ipd.nurse_station.v2.investigation_requisition", ['patient_info' => $patient_info]);
    }

    public function getMedicineIndent(Request $request)
    {

        $admission_id = $request->admission_id;
        $patient_id = $request->patient_id;
        $tr_type = 'IR';
        if ($request->medicine_indent == 0) {
            $con = "NVL((SELECT SUM(item_qty)
                    FROM phr_ipdpatmedtran
                    WHERE phr_ipdpatmedtran.tran_type  = '$tr_type' and phr_ipdpatmedtran.RX_NO = psn_t_prescription_med.prescription_med_no_pk and  psn_t_prescription_med.item_no_fk = phr_ipdpatmedtran.item_no_fk),0) <= NVL(PSN_T_PRESCRIPTION_MED.ITEM_QTY,0)";
        } else {
            $tr_type = "RI";
            $con = "
                NVL((SELECT SUM(item_qty)
                    FROM phr_ipdpatmedtran
                    WHERE phr_ipdpatmedtran.tran_type  = '$tr_type' and phr_ipdpatmedtran.RX_NO = psn_t_prescription_med.prescription_med_no_pk and psn_t_prescription_med.item_no_fk = phr_ipdpatmedtran.item_no_fk),0) > 0";
        }


        $data = DB::table('PSN_T_PRESCRIPTION_MED')->select(
            'PSN_T_PRESCRIPTION_MED.PRESCRIPTION_MED_NO_PK',
            'PSN_T_PRESCRIPTION_MED.APPROVE_BY',
            'PSN_T_PRESCRIPTION_MED.DOSAGE',
            'PSN_T_PRESCRIPTION_MED.GENERIC_NAME',
            'PSN_T_PRESCRIPTION_MED.BRAND_NAME',
            'PSN_T_PRESCRIPTION_MED.patient_no_fk',
            'PSN_T_PRESCRIPTION_MED.prescription_no_fk',
            'PSN_T_PRESCRIPTION_MED.DURATION',
            'PSN_T_PRESCRIPTION_MED.ITEM_QTY',
            'PSN_T_PRESCRIPTION_MED.INSTRUCTION_TAKE',
            'PSN_T_PRESCRIPTION_MED.DURATION_MU',
            'PSN_T_PRESCRIPTION_MED.APPROVE_IND',
            'PSN_T_PRESCRIPTION_MED.APPROVE_DATE',
            'wsec_user.user_fullname',
            DB::raw("NVL((SELECT SUM(NVL(item_qty,0))
                                        FROM phr_ipdpatmedtran
                                        WHERE phr_ipdpatmedtran.tran_type  = '$tr_type' and phr_ipdpatmedtran.RX_NO = psn_t_prescription_med.prescription_med_no_pk and psn_t_prescription_med.item_no_fk = phr_ipdpatmedtran.item_no_fk),0) as intended_qty
                                    "),

            DB::raw("(SELECT patmedtran_no_pk
                                    FROM phr_ipdpatmedtran
                                    WHERE
                                       phr_ipdpatmedtran.RX_NO = PSN_T_PRESCRIPTION_MED.prescription_med_no_pk and  psn_t_prescription_med.item_no_fk = phr_ipdpatmedtran.item_no_fk
                                    FETCH FIRST 1 ROWS ONLY) AS patmedtran_no_pk")
        )
            ->join('wsec_user', 'wsec_user.user_no_pk', 'psn_t_prescription_med.approve_by')
            ->whereRaw($con)
            ->where('PSN_T_PRESCRIPTION_MED.discontine_ind', 0)
            ->where('PSN_T_PRESCRIPTION_MED.admission_pk_no', $admission_id)
            ->where('PSN_T_PRESCRIPTION_MED.patient_no_fk', $patient_id)
            ->where('PSN_T_PRESCRIPTION_MED.approve_ind', 1)
            ->orderByDesc('PSN_T_PRESCRIPTION_MED.prescription_no_fk')->get();

        return response()->json(['data' => $data], 200);
    }


