    public function medicineIndentRequest(Request $request)
    {

        try {

            if (!isset($request->pending_indent)) {
                return response()->json(['success' => true, 'message' => 'Please select at least one item!', 'title' => 'Failed'], 422);
            }

            DB::beginTransaction();
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $store_no_fk = DB::table('sysc_serviceunit')->where('ipdphr_ind', 1)->value('serviceunit_no_pk');
            if (empty($store_no_fk)) {
                return response()->json(['success' => true, 'message' => 'Pharmacy not found!'], 422);
            }

            $master_id = $this->getSequence('ipdpatmedtran');
            $nurse_station_fk = '';
            foreach ($request->pending_indent as $key => $value) {

                $seq = $this->getSequence('seq_patmedtran');
                $index = array_search($value, $request->prescription_med_pk);
                $info = DB::table('PSN_T_PRESCRIPTION_MED')->where('PRESCRIPTION_MED_NO_PK', $value)->first();

                if (empty($nurse_station_fk)) {
                    $nurse_station_fk = DB::table('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW')->where('MOVEMENT_NO', 2)->where('admission_no_pk', $info->admission_pk_no)->where('patient_no_fk', $info->patient_no_fk)->value('ns_no_fk');
                }
                if ($request->pending_qty[$index] > 0) {
                    $data = [
                        'TRAN_DATE' => $au_entry_at,
                        'PATMEDTRAN_NO_PK' => $seq,
                        'SL_NO' => $info->entry_serial,
                        'STATUS' => 1,
                        'PATIENT_NO_FK' => $info->patient_no_fk,
                        'PRES_NO_FK' => $info->prescription_no_fk,
                        'ITEM_QTY' => $request->pending_qty[$index],
                        'ITEM_NO_FK' => $info->item_no_fk,
                        'ADMISSION_NO_FK' => $info->admission_pk_no,
                        'AU_ENTRY_BY' => Auth::id(),
                        'AU_ENTRY_AT' => $au_entry_at,
                        'AU_ENTRY_SESSION' => $entry_session,
                        'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_pk_no,
                        'RX_NO' => $info->prescription_med_no_pk,
                        'TRAN_EMP' => null,
                        'STORE_NO_FK' => $store_no_fk,
                        'TRAN_TYPE' => 'IR',
                        'REF_TRAN_ID' => null,
                        'READY_IND' => null,
                        'READY_BY' => null,
                        'READY_AT' => null,
                        'NURSESTATION_NO_FK' => $nurse_station_fk,
                        'MED_REQ_ID' => $master_id,
                        'INVOICE_NO_FK' => null,
                        'GENERIC_NO' => $info->generic_no_fk,
                        'EXP_DATE' => null,
                        'DELIVERY_IND' => null,
                        'DELIVERY_BY' => null,
                        'DELIVERY_AT' => null,
                        'COMMENTS' => null,
                        'BATCH_NO' => null,
                    ];

                    DB::table('PHR_IPDPATMEDTRAN')->insert($data);
                }
            }
            DB::commit();
            return response()->json(['success' => false, 'message' => 'Successfully Indent', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

    // for delete indent
    public function medicineIndentDelete($id)
    {
        try {
            DB::transaction(function() use ($id) {
                $prescription = DB::table('PSN_T_PRESCRIPTION_DTL')
                    ->where('PRESCRIPTION_DTL_NO_PK', $id)
                    ->first();

                if ($prescription) {
                    $prescription_no = $prescription->prescription_no_fk;

                    DB::table('PSN_T_PRESCRIPTION_DTL')
                        ->where('PRESCRIPTION_DTL_NO_PK', $id)
                        ->delete();

                    DB::table('PSN_T_PRESCRIPTION')
                        ->where('PRESCRIPTION_NO_PK', $prescription_no)
                        ->delete();
                }
            });

            return response()->json([
                'success' => true,
                'message' => 'Medicine Indent and Prescription deleted successfully.'
            ], 200);

        } catch (\Throwable $th) {
            return response()->json([
                'success' => false,
                'message' => $th->getMessage()
            ], 500);
        }
    }

    public function getMedicineIndentFromPharmacy(Request $request)
    {
        $data = DB::table('phr_ipdpatmedtran ipd_pat')
            ->leftJoin('ipd_v1_admitted_pat_nsreq_wl_vw', function ($q) {
                $q->on("ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk", "=", "ipd_pat.admission_no_fk");
                $q->on("ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk", "=", "ipd_pat.PATIENT_NO_FK");
            })
            ->select(
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_date',
                'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code as uhid',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.primary_doctor_name as doctor_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.DOC_DEPARTMENT as su_name',
                'ipd_pat.med_req_id',
                DB::raw(
                    "(SELECT SUM(ITEM_QTY)
                                            FROM PHR_IPDPATMEDTRAN
                                            WHERE PHR_IPDPATMEDTRAN.med_req_id = ipd_pat.med_req_id and PHR_IPDPATMEDTRAN.admission_no_fk = ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk  AND PHR_IPDPATMEDTRAN.patient_no_fk = ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk AND NVL(PHR_IPDPATMEDTRAN.DELIVERY_IND,0) = 0 and PHR_IPDPATMEDTRAN.TRAN_TYPE = 'IR') as indent_qty"
                )
            )
            ->where('ipd_pat.tran_type', 'IR')
            ->where('ipd_v1_admitted_pat_nsreq_wl_vw.dis_ind', 0)
            ->groupBy(
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_date',
                'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.primary_doctor_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.DOC_DEPARTMENT',
                'ipd_pat.med_req_id',
            )
            ->orderByDesc('ipd_pat.med_req_id')
            ->get();

        $new_data = [];
        foreach ($data as $key => $value) {
            $bill_qty = DB::select(DB::raw("
                                        SELECT NVL(SUM(ITEM_QTY), 0) AS total_qty
                                        FROM PHR_IPDPATMEDTRAN
                                        WHERE admission_no_fk = :admission_no
                                        AND patient_no_fk = :patient_no
                                        AND TRAN_TYPE = 'RI'
                                        AND med_req_id = :med_req_id
                                    "), [
                'admission_no' => $value->admission_no_pk,
                'patient_no' => $value->patient_no_fk,
                'med_req_id' => $value->med_req_id,
            ]);

            $bill_qty = @$bill_qty[0]->total_qty;
            if ($value->indent_qty != $bill_qty) {
                array_push($new_data, $value);
            }
        }

        return response()->json(['data' => $new_data], 200);
    }


