    public function getMedicineReceiveNS(Request $request)
    {

        $admission_id = $request->admission_id;
        $patient_id = $request->patient_id;


        $data = DB::table('phr_ipdpatmedtran')
            ->leftJoin('ipd_v1_admitted_pat_nsreq_wl_vw', function ($q) {
                $q->on('ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk', '=', 'phr_ipdpatmedtran.admission_no_fk');
                $q->on('ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk', '=', 'phr_ipdpatmedtran.patient_no_fk');
            })
            ->leftJoin('phr_ipdpatmedtran as ipd_ret', function ($q) {
                $q->on('ipd_ret.REF_TRAN_ID', '=', 'phr_ipdpatmedtran.patmedtran_no_pk');
                $q->where('ipd_ret.TRAN_TYPE', '=', 'DR');
            })
            ->select(
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_date',
                'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',

                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code as uhid',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.primary_doctor_name as doctor_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.doc_department as su_name',
                'phr_ipdpatmedtran.med_req_id',
                'phr_ipdpatmedtran.invoice_no_fk',
                'phr_ipdpatmedtran.ledgertrn_no_fk',
                DB::raw('sum(ipd_ret.item_qty) as received_qty')
            );

        $data->whereRaw('NVL(phr_ipdpatmedtran.delivery_ind,0) = 1');
        $data->where('ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk', $admission_id);
        $data->where('ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk', $patient_id);
        $data = $data
            ->where('phr_ipdpatmedtran.tran_type', 'RI')
            ->groupBy(
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_date',
                'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.primary_doctor_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.doc_department',
                'phr_ipdpatmedtran.med_req_id',
                'phr_ipdpatmedtran.invoice_no_fk',
                'phr_ipdpatmedtran.ledgertrn_no_fk',
            )
            ->having(DB::raw('NVL(sum(ipd_ret.item_qty),0)'), '=', 0)
            ->orderByDesc('phr_ipdpatmedtran.med_req_id')
            ->get();

        return response()->json(['data' => $data], 200);
    }

    public function getMedicineReceivedNS(Request $request)
    {
        $admission_id = $request->admission_id;
        $patient_id = $request->patient_id;

        $data = DB::table("phr_ipdpatmedtran")
            ->leftJoin('SYSC_V1_SERVICEITEM_VW', 'SYSC_V1_SERVICEITEM_VW.item_no_pk', 'phr_ipdpatmedtran.item_no_fk')
            ->leftJoin('PSN_T_PRESCRIPTION_MED', function ($q) {
                $q->on("phr_ipdpatmedtran.RX_NO", "=", "psn_t_prescription_med.prescription_med_no_pk");
                $q->on("psn_t_prescription_med.item_no_fk", "=", "phr_ipdpatmedtran.item_no_fk");
                $q->where("approve_ind", 1);
            })

            ->select(
                'PSN_T_PRESCRIPTION_MED.APPROVE_BY',
                'PSN_T_PRESCRIPTION_MED.DOSAGE',
                'PSN_T_PRESCRIPTION_MED.prescription_no_fk',
                'PSN_T_PRESCRIPTION_MED.DURATION',
                'PSN_T_PRESCRIPTION_MED.INSTRUCTION_TAKE',
                'PSN_T_PRESCRIPTION_MED.DURATION_MU',
                'PSN_T_PRESCRIPTION_MED.prescription_med_no_pk',
                'PSN_T_PRESCRIPTION_MED.discontine_ind',
                'SYSC_V1_SERVICEITEM_VW.GENERIC_NAME',
                'SYSC_V1_SERVICEITEM_VW.ITEM_NAME as BRAND_NAME',
                'phr_ipdpatmedtran.patient_no_fk',
                'phr_ipdpatmedtran.admission_no_fk',
                'phr_ipdpatmedtran.item_no_fk',
                'phr_ipdpatmedtran.ITEM_QTY',
                'phr_ipdpatmedtran.invoice_no_fk',
                'phr_ipdpatmedtran.ref_tran_id',
                'phr_ipdpatmedtran.med_req_id',
                'phr_ipdpatmedtran.patmedtran_no_pk',
            )


            ->where('phr_ipdpatmedtran.admission_no_fk', $admission_id)
            ->where('phr_ipdpatmedtran.patient_no_fk', $patient_id)
            ->where('phr_ipdpatmedtran.tran_type', 'DR')
            ->orderByDesc('phr_ipdpatmedtran.patmedtran_no_pk')->get();


        foreach ($data as $key => $value) {
            $value->mr_qty = DB::table("phr_ipdpatmedtran")
                ->where('tran_type', 'MR')
                ->where('med_req_id', $value->med_req_id)
                ->where('invoice_no_fk', $value->invoice_no_fk)
                ->where('item_no_fk', $value->item_no_fk)
                ->where('ref_tran_id', $value->ref_tran_id)
                ->where('patient_no_fk', $value->patient_no_fk)
                ->where('admission_no_fk', $value->admission_no_fk)
                ->whereNull('rtnrcv_ind')
                ->sum('item_qty');

            $value->mc_qty = DB::table("phr_ipdpatmedtran")
                ->where('tran_type', 'MC')
                ->where('med_req_id', $value->med_req_id)
                ->where('item_no_fk', $value->item_no_fk)
                ->where('patient_no_fk', $value->patient_no_fk)
                ->where('invoice_no_fk', $value->invoice_no_fk)
                ->where('ref_tran_id', $value->ref_tran_id)
                ->where('admission_no_fk', $value->admission_no_fk)
                ->sum('item_qty');

            $value->mr_pos_qty = DB::table("FINC_INVOICEDTL")
                ->where('item_no_fk', $value->item_no_fk)
                ->where('invoice_no_fk', $value->invoice_no_fk)
                ->sum('cancel_qty');
        }

        return response()->json(['data' => $data], 200);
    }

