    public function medicinePendingListPharmacy(Request $request)
    {

        $patmedtran_no_pk = $request->id;

        $data = DB::select("select * from (select tmed.pres_no_fk, tmed.au_entry_at, tmed.patmedtran_no_pk,tmed.PATIENT_NO_FK,tmed.ADMISSION_NO_FK,tmed.item_qty indent_qty,
          nvl((select sum(item_qty)
            from phr_ipdpatmedtran imed
            where ref_tran_id=tmed.patmedtran_no_pk ) ,0)issue_qty ,
            tmed.item_qty -nvl((select sum(item_qty)
            from phr_ipdpatmedtran imed where ref_tran_id=tmed.patmedtran_no_pk ) ,0)item_qty ,
            tmed.delivery_ind,prescription_med_no_pk, prescription_no_fk, tmed.item_no_fk, generic_name,brand_name, dosage,instruction_take
            from phr_ipdpatmedtran tmed ,psn_t_prescription_med pmed
            where tmed.med_req_id = $patmedtran_no_pk and nvl(tmed.delivery_ind,0) = 0
            and tmed.pres_no_fk =pmed.prescription_no_fk(+)
                and tmed.TRAN_TYPE = 'IR'
            and tmed.rx_no=pmed.prescription_med_no_pk(+)
                and tmed.TRAN_TYPE = 'IR'
            and tmed.rx_no=pmed.prescription_med_no_pk(+))
            where item_qty > 0");
        // dd($patmedtran_no_pk,$data);
        $patient_info = DB::table('ipd_v1_admitted_pat_nsreq_wl_vw')
            ->select(
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.admission_date',
                'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code as uhid',
                'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.primary_doctor_name as doctor_name',
                'ipd_v1_admitted_pat_nsreq_wl_vw.doc_department as su_name'
            )
            ->where('admission_no_pk', $data[0]->admission_no_fk)
            ->where('patient_no_fk', $data[0]->patient_no_fk)
            ->first();

        return Template::loadview("admin.ipd.nurse_station.v2.modal.medicine_pending_list_pharmacy", compact('patient_info', 'data', 'patmedtran_no_pk'));
    }

