    public function medicineDelivery(Request $request)
    {
        $request->validate([
            'id' => 'required',
            'invoice_no_fk' => 'required',
        ]);

        try {
            $data = [
                'delivery_ind' => 1,
                'delivery_at' => now(),
                'delivery_by' => Auth::id(),
            ];

            DB::table('PHR_IPDPATMEDTRAN')
                ->where('MED_REQ_ID', $request->id)
                ->where('TRAN_TYPE', 'RI')
                ->where('INVOICE_NO_FK', $request->invoice_no_fk)
                ->update($data);

            return response()->json(['message' => 'Successfully Delivered', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['message' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

    public function medicineReceive(Request $request)
    {
        $request->validate([
            'med_req_id' => 'required',
            'invoice_no_fk' => 'required'
        ]);

        try {

            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $store_no_fk = DB::table('sysc_serviceunit')->where('ipdphr_ind', 1)->value('serviceunit_no_pk');

            $master_id = $this->getSequence('ipdpatmedtran');
            $nurse_station_fk = '';


            $item = DB::table('phr_ipdpatmedtran')
                ->where('med_req_id', $request->med_req_id)
                ->where('invoice_no_fk', $request->invoice_no_fk)
                ->where('TRAN_TYPE', 'RI')
                ->get();

            foreach ($item as $key => $value) {

                $info = DB::table('psn_t_prescription_med')->where('prescription_med_no_pk', $value->rx_no)->first();
                if (empty($nurse_station_fk)) {
                    $nurse_station_fk = DB::table('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW')->where('MOVEMENT_NO', 2)->where('admission_no_pk', $value->admission_no_fk)->where('patient_no_fk', $value->patient_no_fk)->value('ns_no_fk');
                }

                $generic_no_fk = DB::table('SYSC_SERVICEITEM')->where('ITEM_NO_PK', $value->item_no_fk)->value('generic_no_fk');
                $seq = $this->getSequence('seq_patmedtran');
                $data = [
                    'tran_date' => $au_entry_at,
                    'patmedtran_no_pk' => $seq,
                    'SL_NO' => $key + 1,
                    'STATUS' => 1,
                    'PATIENT_NO_FK' => $value->patient_no_fk,
                    'PRES_NO_FK' => @$info->prescription_no_fk,
                    'ITEM_QTY' => $value->item_qty,
                    'ITEM_NO_FK' => $value->item_no_fk,
                    'ADMISSION_NO_FK' => $value->admission_no_fk,
                    'AU_ENTRY_BY' => Auth::id(),
                    'AU_ENTRY_AT' => $au_entry_at,
                    'AU_ENTRY_SESSION' => $entry_session,
                    'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_pk_no,
                    'RX_NO' => @$info->prescription_med_no_pk,
                    'TRAN_EMP' => null,
                    'STORE_NO_FK' => $store_no_fk,
                    'TRAN_TYPE' => 'DR',
                    'REF_TRAN_ID' => $value->patmedtran_no_pk,
                    'READY_IND' => null,
                    'READY_BY' => null,
                    'READY_AT' => null,
                    'NURSESTATION_NO_FK' => $nurse_station_fk,
                    'MED_REQ_ID' => $request->med_req_id,
                    'INVOICE_NO_FK' => $value->invoice_no_fk,
                    'LEDGERTRN_NO_FK' => $value->ledgertrn_no_fk,
                    'GENERIC_NO' => $generic_no_fk,
                    'BATCH_NO' => $value->batch_no,
                    'INTERNAL_BATCH_NO' => $value->internal_batch_no,
                    'EXP_DATE' => $value->exp_date !='' ? date('Y-m-d',strtotime($value->exp_date)):'',
                    'DELIVERY_IND' => null,
                    'DELIVERY_BY' => null,
                    'DELIVERY_AT' => null,
                    'COMMENTS' => null,

                ];
                DB::table('phr_ipdpatmedtran')->insert($data);
            }

            return response()->json(['message' => 'Successfully Received', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['message' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }


