    public function getInvestigationItem(Request $request)
    {

        $admission_id = $request->admission_id;
        $patient_id = $request->patient_id;

        $data = DB::table('psn_t_prescription_dtl')
            ->join('wsec_user', 'wsec_user.user_no_pk', 'psn_t_prescription_dtl.au_entry_by')
            ->leftJoin('psn_investigation_indent', function ($join) {
                $join->on('psn_t_prescription_dtl.lookupdata_item_no_fk', '=', 'psn_investigation_indent.lookupdata_item_no_fk');
                $join->on('psn_investigation_indent.prescription_dtl_no_fk', '=', 'PSN_T_PRESCRIPTION_DTL.prescription_dtl_no_pk');
                $join->on('psn_investigation_indent.admission_pk_no', '=', 'PSN_T_PRESCRIPTION_DTL.ADMISSION_PK_NO');
                $join->on('psn_investigation_indent.patient_no_fk', '=', 'PSN_T_PRESCRIPTION_DTL.patient_no_fk');
            })
            ->leftjoin('sysc_serviceitem_vw', 'sysc_serviceitem_vw.item_no_pk', 'psn_t_prescription_dtl.lookupdata_item_no_fk')
            ->select(
                'psn_t_prescription_dtl.prescription_dtl_no_pk',
                'psn_t_prescription_dtl.au_entry_by',
                'psn_t_prescription_dtl.lookup_uid',
                'psn_t_prescription_dtl.lookupdata_uid',
                'psn_t_prescription_dtl.entry_serial',
                'psn_t_prescription_dtl.prescrition_data',
                'psn_t_prescription_dtl.prescription_no_fk',
                'psn_t_prescription_dtl.au_entry_at',
                'wsec_user.user_fullname',
                "psn_investigation_indent.prescription_dtl_no_fk",
                "psn_investigation_indent.inv_indent_no_pk",
                "psn_investigation_indent.indent_ref_no",
                "sysc_serviceitem_vw.serviceunit_name",
                "sysc_serviceitem_vw.container_name",

            );

        if ($request->investigation_indent == 0) {
            $data->whereNull("psn_investigation_indent.prescription_dtl_no_fk");
        } else {
            $data->whereNotNull("psn_investigation_indent.prescription_dtl_no_fk");
        }

        $data = $data->where('PSN_T_PRESCRIPTION_DTL.ADMISSION_PK_NO', $admission_id)
            ->whereIn('PSN_T_PRESCRIPTION_DTL.LOOKUP_UID', ['FINDINGS', 'INVFIND'])
            ->where('PSN_T_PRESCRIPTION_DTL.patient_no_fk', $patient_id)
            ->orderByDesc('PSN_T_PRESCRIPTION_DTL.prescription_no_fk')->get();

        if ($request->investigation_indent == 1) {
            foreach ($data as $key => $value) {
                $item = DB::table('psn_investigation_indent')->where('inv_indent_no_pk', $value->inv_indent_no_pk)->select('invoice_no_fk', 'ledgertrn_no_fk')->first();
                $value->invoice_no_fk = @$item->invoice_no_fk;
                $value->ledgertrn_no_fk = @$item->ledgertrn_no_fk;
            }
        }

        return response()->json(['data' => $data], 200);
    }


    public function InvestigationIndent(Request $request)
    {

        try {

            if (!isset($request->pending_indent)) {
                return response()->json(['success' => true, 'message' => 'Please select at least one item!', 'title' => 'Failed'], 422);
            }

            DB::beginTransaction();
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $master_id = $this->getSequence('indent_ref_no_seq');
            foreach ($request->pending_indent as $key => $value) {

                $seq = $this->getSequence('inv_indent_no_pk_seq');
                $info = DB::table('psn_t_prescription_dtl')->where('prescription_dtl_no_pk', $value)->first();

                $data = [
                    'inv_indent_no_pk' => $seq,
                    'inv_indent_uid' => $seq,
                    'prescription_dtl_no_fk' => $value,
                    'prescription_no_fk' => $info->prescription_no_fk,
                    'prescription_uid' => $info->prescription_uid,

                    'admission_pk_no' => $info->admission_pk_no,
                    'admission_uid' => $info->admission_uid,
                    'patient_no_fk' => $info->patient_no_fk,
                    'appointment_pk_no' => $info->appointment_pk_no,

                    'lookupdata_item_no_fk' => $info->lookupdata_item_no_fk,
                    'lookup_uid' => $info->lookup_uid,
                    'lookupdata_uid' => $info->lookupdata_uid,
                    'status' => 1,
                    'indent_ref_no' => $master_id,
                    'au_entry_by' => Auth::id(),
                    'au_entry_at' => $au_entry_at,
                    'au_entry_session' => $entry_session,
                    'au_entry_hospital_no_fk' => $hospital_pk_no,
                ];

                DB::table('psn_investigation_indent')->insert($data);
            }



            // Bill generate open
            $info = DB::table('psn_t_prescription_dtl')->where('prescription_dtl_no_pk', $request->pending_indent[0])->first();

            // $pat_info = DB::table('patn_registration')->select('patn_registration.*','patient_info_vw.patient_type')->leftJoin('patient_info_vw','patient_info_vw.patient_no_pk','=','patn_registration.patient_no_pk')->where('patn_registration.patient_no_pk', $request->patient_no_pk)->first();
            $pat_info = DB::table('patn_registration')
                ->select('patn_registration.*', 'patient_info_vw.patient_type_code')
                ->leftJoin('patient_info_vw', 'patient_info_vw.patient_no_pk', '=', 'patn_registration.patient_no_pk')
                ->where('patn_registration.patient_no_pk', $request->patient_no_pk)
                ->first();

            $pres_master = DB::table('psn_t_prescription')->where('patient_no_fk', $request->patient_no_pk)->first();
            $nurse_station_pk = DB::table("ipd_admission_details")->where('admission_no_pk', $request->admission_no_pk)->value("ns_receive_by");
            $corporate_id = DB::table('patn_registration')->where('patient_no_pk', $request->patient_no_pk)->value('ccm_client_no_fk') ?? 0;

            $auth_id = Auth::id();
            $time = Carbon::now();
            $cur_date = date('Y-m-d H:i:s', strtotime($time));
            $cur_datetime = date('Y-m-d H:i:s', strtotime($time));
            $module_id = DB::table("sysc_module")->where('module_code', 'IPDI')->value('module_no_pk');
            $patient_type = $pat_info->patient_type;
            $hdn_patient_id = $request->patient_no_pk;
            $hdn_patient_code = $pat_info->patient_code;
            $admission_id = $request->admission_no_pk;

            $service_appointment_id = null;
            $prescription_id = $info->prescription_no_fk;

            $hdn_doctor_id = $pres_master->doctor_person_no_fk;
            $hdn_first_referral_id = null;
            $hdn_second_referral_id = null;
            $hdn_item_id = DB::table("psn_t_prescription_dtl")->whereIn('prescription_dtl_no_pk', $request->pending_indent)->pluck('lookupdata_item_no_fk')->toArray();




            $total_item = count($hdn_item_id);
            $item_vat_prse = $request->vat_pers;
            $provider_no = $request->hdn_provider;
            $hdn_item_rate = $request->hdn_item_rate;
            $hdn_item_qnty = $request->hdn_item_qnty;
            $remarks = "Bill Generated from Investigation Indent";
            $urgent_fee = 0;
            $entry_session = "session";
            $in_counter_su_no_fk = $nurse_station_pk;
            $report_delivery_date = null;
            $invoice_date = null;
            $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
            $hospital_id = $ses_hospital_id;
            $null = '';

            $out_sl_no = '';
            $empty_arr = [];
            $numelems = 200;
            $zero = 0;

            $deli_dt_arr = $hdn_item_name = $hdn_item_rate = $provider_no = $item_vat_prse = $ipd_charge = $hdn_item_urgent_fee_amt = $item_disc_amount = $item_disc_percent = $hdn_item_qnty = $item_level_remarks = $hdn_item_type = $item_delivery_status_arr = $item_mu_arr = $item_disc_percent = $item_disc_amount = $ipd_charge = [];
            $ipd_dis_inapplicable=DB::table('patn_patienttype')->where('patient_type_code',$pat_info->patient_type_code)->value('ipd_discount_inapplicable');
            foreach ($hdn_item_id as $key => $value) {
