    public function medicineReturnConsumption(Request $request)
    {
        try {
            // dd($request->all());
            if (!isset($request->consReturn_qty)) {
                return response()->json(['success' => true, 'message' => 'Please select at least one item!', 'title' => 'Failed'], 422);
            }

            DB::beginTransaction();
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $store_no_fk = DB::table('sysc_serviceunit')->where('ipdphr_ind', 1)->value('serviceunit_no_pk');
            if (empty($store_no_fk)) {
                return response()->json(['success' => true, 'message' => 'Pharmacy not found!'], 422);
            }


            $nurse_station_fk = '';
            $type = 'MC';
            if ($request->consumption_return == 1) {
                $message = 'Successfully Consumption';
            } else {
                $message = 'Successfully Return Request';
                $type = 'MR';
            }

            foreach ($request->consReturn_qty as $key => $value) {

                $seq = $this->getSequence('seq_patmedtran');
                $info = DB::table('phr_ipdpatmedtran')->where('patmedtran_no_pk', $request->patmedtran_no_pk[$key])->first();

                if (empty($nurse_station_fk)) {
                    $nurse_station_fk = DB::table('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW')->where('MOVEMENT_NO', 2)->where('admission_no_pk', $info->admission_no_fk)->where('patient_no_fk', $info->patient_no_fk)->value('ns_no_fk');
                }
                $generic_no_fk = DB::table('SYSC_SERVICEITEM')->where('ITEM_NO_PK', $info->item_no_fk)->value('generic_no_fk');
                if ($value > 0) {
                    $data = [
                        'TRAN_DATE' => $au_entry_at,
                        'PATMEDTRAN_NO_PK' => $seq,
                        'SL_NO' => $key + 1,
                        'STATUS' => 1,
                        'PATIENT_NO_FK' => $info->patient_no_fk,
                        'PRES_NO_FK' => $info->pres_no_fk,
                        'ITEM_QTY' => $value,
                        'ITEM_NO_FK' => $info->item_no_fk,
                        'ADMISSION_NO_FK' => $info->admission_no_fk,
                        'AU_ENTRY_BY' => Auth::id(),
                        'AU_ENTRY_AT' => $au_entry_at,
                        'AU_ENTRY_SESSION' => $entry_session,
                        'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_pk_no,
                        'RX_NO' => $info->rx_no,
                        'TRAN_EMP' => null,
                        'STORE_NO_FK' => $store_no_fk,
                        'TRAN_TYPE' => $type,
                        'REF_TRAN_ID' => $request->ref_tran_id[$key],
                        'READY_IND' => null,
                        'READY_BY' => null,
                        'READY_AT' => null,
                        'NURSESTATION_NO_FK' => $nurse_station_fk,
                        'MED_REQ_ID' => $request->med_req_id[$key],
                        'INVOICE_NO_FK' => $info->invoice_no_fk,
                        'GENERIC_NO' => $generic_no_fk,
                        'BATCH_NO' => $info->batch_no,
                        'INTERNAL_BATCH_NO' => $info->internal_batch_no,
                        'EXP_DATE' => $info->exp_date !='' ? date('Y-m-d',strtotime($info->exp_date)):'',
                        'LEDGERTRN_NO_FK' => $info->ledgertrn_no_fk,
                        'DELIVERY_IND' => null,
                        'DELIVERY_BY' => null,
                        'DELIVERY_AT' => null,
                        'COMMENTS' => null,
                    ];

                    DB::table('PHR_IPDPATMEDTRAN')->insert($data);
                }
            }
            DB::commit();
            return response()->json(['success' => false, 'message' => $message, 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

