    public function medicineReturnReceive(Request $request)
    {
        $request->validate([
            'return_receive' => 'required|array',
            // 'date' => 'required|date'
        ]);

        DB::beginTransaction();

        try {
            // Check for already returned items
            $alreadyReturned = DB::table('PHR_IPDPATMEDTRAN')
                ->whereIn('patmedtran_no_pk', $request->return_receive)
                ->where('TRAN_TYPE', 'MR')
                ->where('rtnrcv_ind', 1)
                ->exists();

            if ($alreadyReturned) {
                return response()->json(['message' => 'Already Returned!', 'title' => 'Failed'], 422);
            }

            // Update the return flag
            DB::table('PHR_IPDPATMEDTRAN')
                ->whereIn('patmedtran_no_pk', $request->return_receive)
                ->where('TRAN_TYPE', 'MR')
                ->update([
                    'rtnrcv_ind' => 1,
                    'rtnrcv_date' => now(),
                    'rtnrcv_by' => Auth::id(),
                ]);

            foreach ($request->return_receive as $value1) {
                $info = DB::table('PHR_IPDPATMEDTRAN')->where('patmedtran_no_pk', $value1)->first();

                if (!$info || empty($info->ref_tran_id) || $info->item_qty <=0) {
                    DB::rollBack();
                    return response()->json(['message' => 'Invalid transaction or missing reference._'.$info->item_no_fk, 'title' => 'Failed'], 422);
                }

                $item_no_arr = [$info->item_no_fk];
                $batch_no_arr = [$info->batch_no];
                $expiry_date_arr = [$info->exp_date ? date('dmY', strtotime($info->exp_date)) : ''];
