                // $billinvoice->bindParam(':out_error', $outError, PDO::PARAM_STR, 500);
                // $billinvoice->execute();
                $billinvoice = $pdo->prepare("begin pkg_billing_v0.prc_phr_sales_cancel_batch_exp(:in_cancel_date,:in_invoice_no_pk,:in_refund_amount,:in_refund_reason,:in_item_no_fk,:in_cancel_qty, :in_item_batch_fk,:in_item_expiry_dt,:in_intern_batch_fk,:in_item_count,:in_module_no_fk,:in_admission_no_fk,:in_counter_su_no_fk,:in_au_entry_by,:in_au_entry_session,:in_au_entry_hospital_pk_no,:in_ledgertrn_no,:out_invoice_no,:out_invoice_id,:out_ledgertrn_no,:out_error); end;");
