                $billinvoice->bindArray(':in_item_batch_fk', $batch_no_arr, $one, 500, SQLT_CHR);
                $billinvoice->bindArray(':in_item_expiry_dt', $expiry_date_arr, $one, 500, SQLT_CHR);
