                $billinvoice->execute();

                if ($outError == 999) {
                    DB::rollBack();
                    return response()->json(['message' => 'Oracle Procedure Error!', 'title' => 'Failed'], 500);
                }
            }

            DB::commit();
            return response()->json(['message' => 'Successfully Returned', 'title' => 'Success'], 200);

        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['message' => $th->getMessage(), 'title' => 'Failed'], 500);
