    public function ipdPatientAssesment($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();
        $relationAll = $this->getLookupListByCodeAll("RELATION");


        $duration_mu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_name");
        $communicated_by = $this->getLookupListByCode("IPDPSNMEDIA");

        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");
        $dose = $this->getPresLookupListByCode("DOSE", "pres_lookupdata_name");
        $meddurmu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_code");
        $route = $this->getPresLookupListByCode("ROUTE", "pres_lookupdata_name");
        $ipd_followup_type = $this->getLookupListByCode("IPDFOLLOWUPTYPE");



        $assessment_info = DB::table('ipd_iniassement')
            ->where('ADMISSION_NO_PK', $patient_info->admission_no_pk)
            ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
            ->first();


        if (!empty($assessment_info)) {
            $assessment_info->doctor_signature_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->doctor_no_fk)->value('FULL_NAME');
            $assessment_info->nurse_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->nurse_no_fk)->value('FULL_NAME');
            $assessment_info->dietician_by_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->dietician_no_fk)->value('FULL_NAME');
            $assessment_info->others_emp_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->others_emp)->value('FULL_NAME');
        }
        $medicine_info = [];
        if (!empty($assessment_info)) {
            $medicine_info = DB::table('IPD_ASSESS_PRESCRIPTION_MED')
                ->where('ADMISSION_NO_FK', $patient_info->admission_no_pk)
                ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
                ->where('INIASSEMENT_NO_FK', $assessment_info->iniassement_no_pk)
                ->get()->toArray();
        }
        // dd($medicine_info);
        return Template::loadview("admin.ipd.nurse_station.v2.assesment", ['assessment_info' => $assessment_info, 'medicine_info' => $medicine_info, 'patient_info' => $patient_info, 'relationAll' => $relationAll, 'duration_mu' => $duration_mu, 'communicated_by' => $communicated_by, 'instructions' => $instructions, 'dose' => $dose, 'meddurmu' => $meddurmu, 'route' => $route, 'ipd_followup_type' => $ipd_followup_type]);
    }


    public function doctorShiftHandoverForm($patient_no_fk, $admission_id)
    {

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

        $doc_handover = null;



        return Template::loadview("admin.ipd.nurse_station.v2.doctor_shift_handover_form", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'doc_handover' => $doc_handover]);

    }


    public function storeDocShiftHandover(Request $request)
    {

        $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

        $out_doc_date = null;

        if ($request->filled('out_doc_date')) {

            $out_doc_date = Carbon::createFromFormat('Y-m-d\TH:i', $request->out_doc_date);
        }

        $in_doc_date = null;

        if ($request->filled('in_doc_date')) {

            $in_doc_date = Carbon::createFromFormat('Y-m-d\TH:i', $request->in_doc_date);
        }

        $data = [

            'ADMISSION_NO_FK' => $request->admission_no_fk ? $request->admission_no_fk : 0,
            'PATIENT_NO_FK' => $request->patient_no_fk ? $request->patient_no_fk : 0,
            'CLINICAL_SUMMARY' => $request->clinical_summary,
            'STABLE' => $request->stable,
            'IMPROVING' => $request->improving,
            'DETERIOR' => $request->deterior,
            'CRITICAL' => $request->critical,
            'VITAL_SIGN' => $request->vital_sign,
            'OXYGEN' => $request->oxygen,
            'CONSCIOUSNESS' => $request->consciousness,
            'MED_THERAP' => json_encode($request->med_therap),
            'DOSE_ROUTE' => json_encode($request->dose_route),
            'FREQUENCY' => json_encode($request->frequency),
            'S_DATE' => json_encode(array_map(function ($date) {
                return $date ? date('Y-m-d', strtotime($date)) : null;
            }, $request->s_date ?? [])),

