     public function consultantChange($patient_no_fk, $admission_id)
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
         $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

         $consultant = DB::table('ipd_consultant_cng as cng')
                        ->select(
                            'cng.*',
                            'usr.USER_FULLNAME'
                        )
                        ->leftJoin('wsec_user as usr', 'usr.USER_NO_PK', '=', 'cng.AU_ENTRY_BY')
                        ->where('cng.patient_no_fk', $patient_no_fk)
                        ->where('cng.admission_no_fk', $admission_id)
                        ->orderByDesc('cng.ipd_consultant_cng_no_pk')
                        ->get();



        //dd($consultant);

        return Template::loadView("admin.ipd.nurse_station.v2.consultant_change", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'consultant' => $consultant]);

    }


 public function saveConsultant(Request $request)
{
                    $auth_id = Auth::id();
                    $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
                    $entry_session = session()->get('user.ses_user_pk_no');

                    try {
                        DB::beginTransaction();

                        $seq = $this->getSequence('ipd_consultant_cng_no_pk_seq');
                        $au_entry_at = now();

                        $data = [
                            'ipd_consultant_cng_no_pk' => $seq,
                            'change_date'               => $au_entry_at,
                            'PRIMARY_DOCTOR_NO_FK'      => $request->h_new_cname,
                            'PRIMARY_DOCTOR_NAME'       => $request->new_cname,
                            'status'                    => 1,
                            'patient_no_fk'             => $request->patient_no_fk,
                            'admission_no_fk'           => $request->admission_no_fk,
                            'au_entry_at'               => $au_entry_at,
                            'au_entry_by'               => $auth_id,
                            'au_entry_session'          => $entry_session,
                            'au_entry_hospital_no_fk'   => $hospital_pk_no,
                        ];

                        DB::table('ipd_consultant_cng')->insert($data);

                        DB::table('IPD_ADMISSION')
                            ->where('admission_uid', $request->admission_no_fk)
                            ->update([
                                'PRIMARY_DOCTOR_NO_FK' => $request->h_new_cname,
                                'AU_UPDATE_BY'         => $auth_id,
                            ]);

                        DB::commit();

                        return response()->json([
                            'msg'   => 'Data saved successfully.',
                            'title' => 'Success',
                        ]);
                    } catch (\Exception $e) {
                        DB::rollBack();
                        return response()->json([
                            'msg'   => 'Error: ' . $e->getMessage(),
                            'title' => 'Failed',
                        ], 500);
                    }
}



