    public function saveCriticalTestResult(Request $request)
    {
        $request->validate([
            'admission_no_fk' => 'required',
            'patient_no_fk' => 'required',

        ]);

        try {
            $seq = $this->getSequence('icu_critical_res_no_pk_seq');
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $data = [
                'icu_critical_res_no_pk' => $seq,
                'critical_date' => $au_entry_at,
                'investigation' => $request->investigation,
                'critical_value' => $request->critical_value,
                'lab_informed' => $request->lab_informed,
                'confirmed_lab' => $request->confirmed_lab,
                'doc_name' => $request->doc_name,
                'action_taken' => $request->action_taken,
                'confirmed_action' => $request->confirmed_action,
                'rn_name' => $request->rn_name,
                'h_rn_name' => $request->h_rn_name,
                'status' => 1,
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,
            ];
            $data['au_entry_at'] = $au_entry_at;
            $data['au_entry_by'] = Auth::id();
            $data['au_entry_session'] = $entry_session;
            $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
            DB::table('icu_critical_res')->insert($data);

            return response()->json(['success' => true, 'msg' => 'Successfully Saved', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

    public function downloadCriticalTestResult($patient_no_pk, $admission_no_pk)
    {
        ini_set('max_execution_time', 0);

        $patient_id = $patient_no_pk;
        $admission_uid = $admission_no_pk;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();



        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();

        $critical_result = DB::table('icu_critical_res')
            ->select('icu_critical_res.*', 'user_fullname' , 'user_code' )
            ->leftJoin('wsec_user usr', 'usr.USER_NO_PK', 'icu_critical_res.au_entry_by')
            ->where('icu_critical_res.patient_no_fk', $patient_no_pk)
            ->where('icu_critical_res.admission_no_fk', $admission_no_pk)
            ->orderByDesc('icu_critical_res.icu_critical_res_no_pk')
            ->get();


        return view("admin.ipd.nurse_station.v2.icu_critical_test_result_pdf", ['userInfo' => $userInfo, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info,'patient_info' => $patient_info,'critical_result' => $critical_result]);
    }

