            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        // Admission info
        $admission_info = DB::table('ipd_admitted_patlist_vw')
            ->where('admission_uid', $admission_id)
            ->first();

        // Latest transfusion monitoring record
        $order_form = DB::table('BLOOD_P_T_M_RECORD')
            ->where('PATIENT_NO_FK', $patient_no_fk)
            ->where('ADMISSION_NO_FK', $admission_id)
            ->orderByDesc('BLOOD_P_T_M_R_NO_PK')
            ->first();

        // If no record exists, create empty stdClass with default properties
        if (!$order_form) {
            $order_form = new \stdClass();
            $order_form->VITAL_SIGNS = null;
            $order_form->blood_group = null;
            $order_form->bags = null;
            $order_form->issue_time = null;
            $order_form->received_by = null;
            $order_form->received_time = null;
            $order_form->components = null;
            $order_form->bag_no = null;
            $order_form->amount = null;
            $order_form->doc = null;
            $order_form->doe = null;
            $order_form->consent = null;
            $order_form->premedication = null;
            $order_form->iv_patient = null;
            $order_form->transfusion_start = null;
            $order_form->transfusion_end = null;
            $order_form->reaction = null;
            $order_form->reaction_symptoms = null;
            $order_form->reaction_symptom_other = null;
            $order_form->reaction_form = null;
            $order_form->reaction_form_text = null;
            $order_form->nurse_signature = null;
            $order_form->nurse_name = null;
            $order_form->nurse_emp_id = null;
            $order_form->nurse_date = null;
            $order_form->nurse_time = null;
            $order_form->supervisor_signature = null;
            $order_form->supervisor_name = null;
            $order_form->supervisor_emp_id = null;
            $order_form->supervisor_date = null;
            $order_form->supervisor_time = null;
            $order_form->blood_p_t_m_r_no_pk = null;
        }

        // Decode vital signs safely
        $vitals = [];
        if (!empty($order_form->vital_signs)) {
            $vitals = json_decode($order_form->vital_signs, true);
        }

        // Pass data to view
        return Template::loadview(
            "admin.ipd.nurse_station.v2.blood_products_transfusion_monitorig_record",
            [
                'patient_info'   => $patient_info,
                'patient_no_fk'  => $patient_no_fk,
                'admission_id'   => $admission_id,
                'admission_info' => $admission_info,
                'order_form'     => $order_form,
                'vitals'         => $vitals,
            ]
        );
    }

