    public function counselingFormCriticalCareSave(Request $request){
        //dd($request->all());

        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

        $date_time = null;

        if ($request->filled('date_time')) {

            $date_time = Carbon::createFromFormat('Y-m-d\TH:i', $request->date_time);
        }

       $data = [
                     'ADMISSION_NO_FK'      => $request->admission_no_fk,
                     'PATIENT_NO_FK'        => $request->patient_no_fk,
                     'DATE_TIME'            => $date_time,
                     'COUNSELING'      => json_encode($request->counseling),
                     'CLINICAL'        => $request->clinical,
                     'CARE'            => $request->care,
                     'MANAGEMENT'      => $request->management,
                     'MEDICATION'      => $request->medication,
                     'INVESTIGATION'   => $request->investigation,
                     'OTHERS'          => $request->others,
                     'RELATIONSHIP'    => $request->relationship,
                     'DOC_NAME'        => $request->doc_name,
                     'H_DOC_NAME'      => $request->h_doc_name,
                     ];



        $sequence = DB::getSequence();
        $counseling_form_no_pk = $sequence->nextValue('counseling_form_no_pk_seq');
        if ($request->counseling_form_no_pk == "") {
            $data['counseling_form_no_pk'] = $counseling_form_no_pk;
            $data['AU_ENTRY_BY'] = $auth_id;
            $data['AU_ENTRY_AT'] = date('Y-m-d');
            $data['AU_ENTRY_SESSION'] = 'sessoin';
            $data['AU_ENTRY_HOSPITAL_NO_FK'] = $hospital_no_pk;
            DB::table('counseling_form')->insert($data);
        } else {
            $data['AU_UPDATE_BY'] = $auth_id;
            DB::table('counseling_form')->where('counseling_form_no_pk', $request->counseling_form_no_pk)->update($data);
        }
        DB::commit();
        $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        return response()->json($this->message);
    }

    //write new code masum
    public function IndoorDialysisOrderSave(Request $request)
    {
        // dd($request->all());
        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

        try {
            $data = [
                'ADMISSION_NO_FK'   => $request->admission_no_fk,
                'PATIENT_NO_FK'     => $request->patient_no_fk,
                'JVC'               => $request->jvc,
                'JCS'        => $request->jcs,
                'H_B_HEP_C'         => $request->h_b_hep_c,
                'NOTE'              => $request->note,
                'RBS'               => $request->rbs,
                'BLOOD_FLOW' => $request->blood_flow,
                'U_F'               => $request->u_f,
                'HEPARIN'    => $request->heparin,
                'DURATION'          => $request->duration,
                'DORCOR_NAME'       => $request->doctor_name,
            ];

            $sequence = DB::getSequence();
            $indoor_dialysis_no_pk = $sequence->nextValue('indoor_dialysis_no_pk_seq');

            if ($request->indoor_dialysis_no_pk == "") {
                // Insert New
                $data['INDOOR_DIALYSIS_NO_PK']   = $indoor_dialysis_no_pk;
                $data['AU_ENTRY_BY']             = $auth_id;
                $data['AU_ENTRY_AT']             = date('Y-m-d H:i:s');
                $data['AU_ENTRY_SESSION']        = 'session';
                $data['AU_ENTRY_HOSPITAL_NO_FK'] = $hospital_no_pk;

                DB::table('INDOOR_DIALYSIS')->insert($data);
            } else {
                // Update Existing
                $data['AU_UPDATE_BY']             = $auth_id;
                $data['AU_UPDATE_AT']             = date('Y-m-d H:i:s');
                $data['AU_UPDATE_SESSION']        = 'session';
                $data['AU_UPDATE_HOSPITAL_NO_FK'] = $hospital_no_pk;

                DB::table('INDOOR_DIALYSIS')
                    ->where('INDOOR_DIALYSIS_NO_PK', $request->indoor_dialysis_no_pk)
                    ->update($data);
            }

            DB::commit();

            $this->message = ['msg' => 'Indoor Dialysis Order saved successfully.', 'title' => 'Success'];
            return response()->json($this->message);

        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['msg' => 'Error: ' . $e->getMessage(), 'title' => 'Error'], 500);
        }
    }

