                // your transfusion form fields
                'BLOOD_GROUP'       => $request->blood_group,
                'PRIMARY_DIAGNOSIS' => $request->primary_diagnosis,
                'INDICATION'        => $request->indication,
                'COMORBIDITIES'     => $request->comorbidities,
