    public function CautiInsertionMaintenanceBundleSave(Request $request)
    {
        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

        try {
            $data = [
                'ADMISSION_NO_FK'       => $request->admission_no_fk,
                'PATIENT_NO_FK'         => $request->patient_no_fk,

                'DIAGNOSIS'             => $request->diagnosis,
                'LOCATION_INSERTED_BY'  => $request->location_inserted_by,
                'FC_INSERTED_ON'        => $request->fc_inserted_on,
                'INDICATION_ON_INSERT'  => $request->indication_on_insert,
                'FC_REMOVED_ON'         => $request->fc_removed_on,
                'INDICATION_ON_REMOVE'  => $request->indication_on_remove,

                'STATUS'                => 1,
            ];

            for ($i = 1; $i <= 12; $i++) {
                if ($i <= 10) {
                    // Dropdowns (Yes/No/N/A)
                    $value = $request->input("row{$i}", []);
                    $data["ROW{$i}_STATUS"] = is_array($value) ? implode(',', $value) : $value;
                } else {
                    // Row11 and Row12 are plain text inputs (NOT arrays anymore)
                    $value = $request->input("row{$i}");
                    $data["ROW{$i}_TEXT"] = $value;
                }
            }



            // Remarks (multiple rows)
            $remarks = $request->input('remarks');
            $data['REMARKS'] = is_array($remarks) ? implode(',', $remarks) : $remarks;

            // use proper sequence
            $sequence = DB::getSequence();
            $cauti_in_m_b_no_pk = $sequence->nextValue('CAUTI_I_MA_B_NO_PK_SEQ');

            if (empty($request->cauti_in_m_b_no_pk)) {
                // Insert new
                $data['CAUTI_I_MA_B_NO_PK']       = $cauti_in_m_b_no_pk;
                $data['AU_ENTRY_BY']            = $auth_id;
                $data['AU_ENTRY_AT']            = date('Y-m-d H:i:s');
                $data['AU_ENTRY_SESSION']       = session()->getId();
                $data['AU_ENTRY_HOSPITAL_NO_FK']= $hospital_no_pk;

                DB::table('CAUTI_INSERT_MAINTENANCES_BUNDLE')->insert($data);
            } else {
                // Update existing
                $data['AU_UPDATE_BY']            = $auth_id;
                $data['AU_UPDATE_AT']            = date('Y-m-d H:i:s');
                $data['AU_UPDATE_SESSION']       = session()->getId();
                $data['AU_UPDATE_HOSPITAL_NO_FK']= $hospital_no_pk;

                DB::table('CAUTI_INSERT_MAINTENANCES_BUNDLE')
                    ->where('CAUTI_I_MA_B_NO_PK', $request->cauti_in_m_b_no_pk)
                    ->update($data);
            }

            DB::commit();

            return response()->json(['msg' => 'Cauti Insertion Maintenance Bundle saved successfully.', 'title' => 'Success']);

        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['msg' => 'Error: ' . $e->getMessage(), 'title' => 'Error'], 500);
        }
    }




