    public function BloodProductsTransfusionMonitoringRecordPDF($patient_no_fk, $admission_id)
    {
        // Patient info with admission
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select(
                "a.*",
                "b.admission_no_pk",
                "b.admission_uid",
                "b.admission_date",
                "b.ward_name",
                "b.bed_name",
                "b.bed_uid",
                "b.admitted_department",
                "b.primary_doctor_name"
            )
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        // Admission info
        $admission_info = DB::table('ipd_admitted_patlist_vw')
            ->where('admission_uid', $admission_id)
            ->first();

        // Latest Blood Products Transfusion & Monitoring Record
        $order_form = DB::table('BLOOD_P_T_M_RECORD')
            ->where('PATIENT_NO_FK', $patient_no_fk)
            ->where('ADMISSION_NO_FK', $admission_id)
            ->orderByDesc('BLOOD_P_T_M_R_NO_PK')
            ->first();

        // Decode components and vitals
        $components = $order_form && $order_form->components ? explode(',', $order_form->components) : [];
        $vitals = $order_form && $order_form->vital_signs ? json_decode($order_form->vital_signs, true) : [];

        // Barcode for Admission UID
        $barcode = new \Picqer\Barcode\BarcodeGeneratorPNG();
        $invoice_barcode = base64_encode($barcode->getBarcode($admission_info->admission_uid, $barcode::TYPE_CODE_128));
        // Barcode for Patient Code
        $pat_barcode = base64_encode($barcode->getBarcode($patient_info->patient_code, $barcode::TYPE_CODE_128));

        $userInfo = Auth::user();

        return view('admin.ipd.nurse_station.v2.blood_products_transfusion_monitorig_record_pdf', [
            'patient_info'   => $patient_info,
            'admission_info' => $admission_info,
            'order_form'     => $order_form,
            'components'     => $components,
            'vitals'         => $vitals,
            'invoice_barcode'=> $invoice_barcode,
            'pat_barcode'    => $pat_barcode,
            'userInfo'       => $userInfo
        ]);
    }

