    public function InitialCardiacAssessment($patient_no_fk, $admission_id)
    {
        // Get patient with admission info
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select(
                "a.*",
                "b.admission_no_pk",
                "b.admission_uid",
                "b.admission_date",
                "b.ward_name",
                "b.bed_name",
                "b.bed_uid",
                "b.admitted_department"
            )
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        // Admission info
        $admission_info = DB::table('ipd_admitted_patlist_vw')
            ->where('admission_uid', $admission_id)
            ->first();

        // Latest
        $order_form = DB::table('INITIAL_CARDIAC_ASSESMENT')
            ->select('INITIAL_CARDIAC_ASSESMENT.*')
            ->where('INITIAL_CARDIAC_ASSESMENT.PATIENT_NO_FK', $patient_no_fk)
            ->where('INITIAL_CARDIAC_ASSESMENT.ADMISSION_NO_FK', $admission_id)
            ->orderByDesc('INITIAL_CARDIAC_ASSESMENT.INITIAL_C_A_NO_PK')
            ->first();

        // Convert comma-separated string into array for checkboxes
        if ($order_form) {
            $multiSelectFields = [
                'risk_factors',
                'pain_condition',
                'pain_elsewhere_select',
                'breathlessness_multiple',
                'heaviness_multiple',
                'chocking_multiple',
                'restlessness_multiple',
                'gidiness_multiple',
                'presyncpe_multiple',
                'sweating_multiple',
                'palpitation_multiple',
                'coughing_multiple',
                'gastric_multiple',
                'smoking_select',
                'alcohol_intake',
                'how_much_ml',
                'physical_exercise',
                'food_habits',
                'yoga_meditation',
                'addictive_drugs',
                'diabetes_mellitus',
                'pain_scale',
                'acuity',
                'character',
                'physical_exam_built',
                'physical_exam_pallor',
                'physical_exam_pedal_oedema',
                'physical_exam_cyanosis',
                'physical_exam_clubbing',
                'physical_exam_adenopthay',
                'd_left_parasternal',
                'c_apex_beat_select',
                'psychiatric_multiple',
                'psychiatric_select',
                'addiction',
                'anasarca_multiple',
                'swelling_multiple',
                'fever_multiple',
                'mi_first_site',
                'mi_second_site',
                'mi_third_site',
                'angina',
                'arrhythmia',
                'paralysis',
                'physical_exam_jvp',
                'f_palpable_select'
            ];

            // Loop through and convert each field to array
            foreach ($multiSelectFields as $field) {
                if (isset($order_form->$field)) {
                    $order_form->$field = !empty($order_form->$field)
                        ? explode(',', $order_form->$field)
                        : [];
                } else {
                    $order_form->$field = [];
                }
            }
        }


        // dd($order_form);

        // Return to view
        return Template::loadview(
            "admin.ipd.nurse_station.v2.initial_cardiac_assessment",
            [
                'patient_info'   => $patient_info,
                'patient_no_fk'  => $patient_no_fk,
                'admission_id'   => $admission_id,
                'admission_info' => $admission_info,
                'order_form' => $order_form,
            ]
        );
    }

