                'GYNAECOLOGICAL_LMP'            => $request->gynaecological_lmp,
                'GYNAECOLOGICAL_DISCHARGE'      => $request->gynaecological_discharge,
                'GYNAECOLOGICAL_CERVICAL'       => $request->gynaecological_cervical,
                'GYNAECOLOGICAL_CONTRACEPJTION' => $request->gynaecological_contracepjtion,
                'GYNAECOLOGICAL_OBESTERIC'      => $request->gynaecological_obesteric,

                'STATUS'                        => 1, // You can set this to a default or request value
            ];

            // Check for an existing record
            if (empty($request->initial_c_a_no_pk)) {
                // Insert a new record
                $data['INITIAL_C_A_NO_PK']          = DB::getSequence()->nextValue('INITIAL_C_A_NO_PK_SEQ'); // Assuming a sequence exists
                $data['AU_ENTRY_BY']                = $auth_id;
                $data['AU_ENTRY_AT']                = now();
                $data['AU_ENTRY_SESSION']           = session()->getId();
                $data['AU_ENTRY_HOSPITAL_NO_FK']    = $hospital_no_pk;

                DB::table('H360_UHL_UAT_V2.INITIAL_CARDIAC_ASSESMENT')->insert($data);
            } else {
                // Update the existing record
                $data['AU_UPDATE_BY']                = $auth_id;
                $data['AU_UPDATE_AT']                = now();
                $data['AU_UPDATE_SESSION']           = session()->getId();
                $data['AU_UPDATE_HOSPITAL_NO_FK']    = $hospital_no_pk;

                DB::table('H360_UHL_UAT_V2.INITIAL_CARDIAC_ASSESMENT')
                    ->where('INITIAL_C_A_NO_PK', $request->initial_c_a_no_pk)
                    ->update($data);
            }

            DB::commit();

            return response()->json(['msg' => 'Initial Cardiac Assessment saved successfully.', 'title' => 'Success']);
        } catch (\Exception $e) {
            DB::rollBack();
            return response()->json(['msg' => 'Error: ' . $e->getMessage(), 'title' => 'Error'], 500);
        }
    }

    public function InitialCardiacAssessmentPDF($patient_no_fk, $admission_id)
    {
        // Get patient info with admission
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select(
                "a.*",
                "b.admission_no_pk",
                "b.admission_uid",
                "b.admission_date",
                "b.ward_name",
                "b.bed_name",
                "b.bed_uid",
                "b.admitted_department"
            )
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        // Admission info
        $admission_info = DB::table('ipd_admitted_patlist_vw')
            ->where('admission_uid', $admission_id)
            ->first();

        // Latest Indoor Dialysis Order
        $cardiac_assessment = DB::table('INITIAL_CARDIAC_ASSESMENT')
            ->where('PATIENT_NO_FK', $patient_no_fk)
            ->where('ADMISSION_NO_FK', $admission_id)
            ->orderByDesc('INITIAL_C_A_NO_PK')
            ->first();

        // Barcode for Admission UID
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();

        // Barcode for Patient Code
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();

        $userInfo = Auth::user();

        // Return Blade view
        return view(
            'admin.ipd.nurse_station.v2.initial_cardiac_assessment_pdf',
            [
                'patient_info'   => $patient_info,
                'admission_info' => $admission_info,
                'cardiac_assessment'=> $cardiac_assessment,
                'invoice_barcode'=> $invoice_barcode,
                'pat_barcode'    => $pat_barcode,
                'userInfo'       => $userInfo
            ]
        );
    }




    public function sicuInvestigationChart($patient_no_fk,$admission_id){

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $sicu_chart=  DB::table('sicu_investigation')
            ->select('sicu_investigation.*')
            ->where('sicu_investigation.patient_no_fk', $patient_no_fk)
            ->where('sicu_investigation.admission_no_fk', $admission_id)
            ->orderByDesc('sicu_investigation.sicu_investigation_no_pk')
            ->first();



        return Template::loadview("admin.ipd.nurse_station.v2.sicu_investigation_chart",['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info,'sicu_chart' =>$sicu_chart]);

     }

