        $sequence = DB::getSequence();
        $sicu_investigation_no_pk = $sequence->nextValue('sicu_investigation_no_pk_seq');
        if ($request->sicu_investigation_no_pk == "") {
            $data['sicu_investigation_no_pk'] = $sicu_investigation_no_pk;
            $data['AU_ENTRY_BY'] = $auth_id;
            $data['AU_ENTRY_AT'] = date('Y-m-d');
            $data['AU_ENTRY_SESSION'] = 'sessoin';
            $data['AU_ENTRY_HOSPITAL_NO_FK'] = $hospital_no_pk;
            DB::table('sicu_investigation')->insert($data);
        } else {
            $data['AU_UPDATE_BY'] = $auth_id;
            DB::table('sicu_investigation')->where('sicu_investigation_no_pk', $request->sicu_investigation_no_pk)->update($data);
        }
        DB::commit();
        $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        return response()->json($this->message);
    }
