        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();




        return view("admin.ipd.nurse_station.v2.nursing_initial_assessment_gynaecology_pdf",['patient_info' => $patient_info, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info,'instructions' => $instructions,'dose' => $dose,'meddurmu' => $meddurmu,'route' => $route,'assessment_info' =>$assessment_info]);

    }


       public function adultEmergencyDeptClinicalBundle($patient_no_fk,$admission_id){

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");
        $dose = $this->getPresLookupListByCode("DOSE", "pres_lookupdata_name");
        $meddurmu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_code");
        $route = $this->getPresLookupListByCode("ROUTE", "pres_lookupdata_name");

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $adult_emergency_dept=  DB::table('adult_emergency_dept')

            ->select('adult_emergency_dept.*')
            ->where('adult_emergency_dept.patient_no_fk', $patient_no_fk)
            ->where('adult_emergency_dept.admission_no_fk', $admission_id)
            ->orderByDesc('adult_emergency_dept.adult_emergency_dept_no_pk')
            ->first();


        $medicine_info = [];
        if (!empty($adult_emergency_dept)) {
            $medicine_info = DB::table('EMERGENCY_CLINICAL_PRESCRIPTION_MED')
                ->where('ADMISSION_NO_FK', $patient_info->admission_no_pk)
                ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
                ->where('INIASSEMENT_NO_FK', $adult_emergency_dept->adult_emergency_dept_no_pk)
                ->get()->toArray();
        }


        return Template::loadview("admin.ipd.nurse_station.v2.adult_emergency_dept_clinical_bundle",['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info,'instructions' => $instructions,'dose' => $dose,'meddurmu' => $meddurmu,'route' => $route,'adult_emergency_dept' =>$adult_emergency_dept,'medicine_info' => $medicine_info]);

     }

