    public function underSedationCathLab($patient_no_fk,$admission_id){

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");
        $dose = $this->getPresLookupListByCode("DOSE", "pres_lookupdata_name");
        $meddurmu = $this->getPresLookupListByCode("DURMU", "pres_lookupdata_code");
        $route = $this->getPresLookupListByCode("ROUTE", "pres_lookupdata_name");

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $cath_lab=  DB::table('psus_cath_lab')
            ->select('psus_cath_lab.*')
            ->where('psus_cath_lab.patient_no_fk', $patient_no_fk)
            ->where('psus_cath_lab.admission_no_fk', $admission_id)
            ->orderByDesc('psus_cath_lab.psus_cath_lab_no_pk')
            ->first();



        return Template::loadview("admin.ipd.nurse_station.v2.pre_sedation_assessment_cath_lab",['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info,'instructions' => $instructions,'dose' => $dose,'meddurmu' => $meddurmu,'route' => $route,'cath_lab' =>$cath_lab]);

     }

