    public function downloadPatientDailyFollowup($patient_no_pk, $admission_no_pk)
    {
        ini_set('max_execution_time', 0);

        $patient_id = $patient_no_pk;
        $admission_uid = $admission_no_pk;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();
        $ipd_symptoms = DB::table('ipd_dailyfollowup_ds_ns_mst')
            ->join('ipd_dailyfollowup_ds_ns_chd', 'ipd_dailyfollowup_ds_ns_chd.dfollowupmst_no_fk', 'ipd_dailyfollowup_ds_ns_mst.dfollowupmst_no_pk')
            ->select('ipd_dailyfollowup_ds_ns_chd.*', 'ipd_dailyfollowup_ds_ns_mst.followup_diagnosis', 'ipd_dailyfollowup_ds_ns_mst.FOLLOWUP_BY_NS_PERSON_NO_FK', 'ipd_dailyfollowup_ds_ns_mst.FOLLOWUP_BY_DOC_PERSON_NO_FK')
            ->where('ipd_dailyfollowup_ds_ns_mst.patient_no_fk', $patient_id)
            ->where('ipd_dailyfollowup_ds_ns_mst.admission_no_fk', $admission_uid)
            ->orderBy('ipd_dailyfollowup_ds_ns_chd.dfollowupchd_no_pk', 'asc')
            ->get();

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();

        foreach ($ipd_symptoms as $key => $item) {
            $item->doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$item->followup_by_doc_person_no_fk)->value('FULL_NAME');
            $item->entry_name = DB::table('WSEC_USER')->where('USER_NO_PK', @$item->followup_by_ns_person_no_fk)->value('USER_FULLNAME');
        }



        return view("admin.ipd.nurse_station.v2.export.daily_followup", ['userInfo' => $userInfo, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info, 'ipd_symptoms' => $ipd_symptoms, 'patient_info' => $patient_info]);
    }



    public function ipdNurseAssesment($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();

        $assessment_info = DB::table('ipd_nursingassessment')
            ->where('ADMISSION_NO_FK', $patient_info->admission_no_pk)
            ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
            ->first();


        if (!empty($assessment_info)) {
            $assessment_info->bystander_signature_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->bystander_signature_id)->value('FULL_NAME');
            $assessment_info->rn_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->complete_by)->value('FULL_NAME');
        }
        return Template::loadview("admin.ipd.nurse_station.v2.nurse_assesment", ['assessment_info' => $assessment_info, 'patient_info' => $patient_info]);
    }

