            ->where('b.admission_uid', $admission_uid)
            ->first();
        $relationAll = $this->getLookupListByCodeAll("RELATION");
        $instructions = $this->getPresLookupListByCode("INSTRUCTION", "pres_lookupdata_name");


        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();


        $assessment_info = DB::table('ipd_nursingassessment')
            ->where('ADMISSION_NO_FK', $patient_info->admission_no_pk)
            ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
            ->first();


        if (!empty($assessment_info)) {
            $assessment_info->bystander_signature_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->bystander_signature_id)->value('FULL_NAME');
            $assessment_info->rn_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->complete_by)->value('FULL_NAME');
        }




        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();
        return view("admin.ipd.nurse_station.v2.export.nurse_assesment_paediatric_pdf", ['userInfo' => $userInfo, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info, 'instructions' => $instructions, 'assessment_info' => $assessment_info, 'patient_info' => $patient_info, 'relationAll' => $relationAll]);
    }

