                'ADMISSION_NO_PK' => $request->admission_no_pk,
                'PRIMARY_DOCTOR_NO_FK' => $request->primary_doctor_id,
                'status' => 1
            ];

            if (!DB::table('ipd_iniassement')->where('ADMISSION_NO_PK', $request->admission_no_pk)->where('PATIENT_NO_FK', $request->patient_id)->exists()) {

                $mast_seq = $this->getSequence('iniassement_no_pk_seq');

                $data['au_entry_at'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['AU_ENTRY_HOSPITAL_NO_FK'] = $hospital_pk_no;

                $data['iniassement_no_pk'] = $mast_seq;
                $data['iniassement_date'] = new DateTime('now');
                DB::table('ipd_iniassement')->insert($data);
                $last_id = DB::table('ipd_iniassement')->orderByDesc('iniassement_no_pk')->value("iniassement_no_pk");
            } else {

                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_no_fk'] = $hospital_pk_no;
                DB::table('ipd_iniassement')->where('ADMISSION_NO_PK', $request->admission_no_pk)->where('PATIENT_NO_FK', $request->patient_id)->update($data);
                DB::table('IPD_ASSESS_PRESCRIPTION_MED')->where('ADMISSION_NO_FK', $request->admission_no_pk)->where('PATIENT_NO_FK', $request->patient_id)->delete();

                $last_id = DB::table('ipd_iniassement')->where('ADMISSION_NO_PK', $request->admission_no_pk)->where('PATIENT_NO_FK', $request->patient_id)->value('iniassement_no_pk');
            }


            // medicine entry
            if (isset($request->hdn_medicine_item_id)) {
                foreach ($request->hdn_medicine_item_id as $key => $value) {

                    $child_seq = $this->getSequence('PRESCRIPTION_MED_NO_PK_seq');
                    $child_data = [
                        'prescription_med_no_pk' => $child_seq,
                        'INIASSEMENT_NO_FK' => $last_id,
                        'ADMISSION_NO_FK' => $request->admission_no_pk,
                        'PATIENT_NO_FK' => $request->patient_id,
                        'ITEM_NO_FK' => $value,
                        'DOSAGE' => $request->medicine_dose[$key],
                        'ITEM_QTY' => $request->medicine_quantity[$key],
                        'INSTRUCTION_TAKE' => $request->instruction[$key],
                        'ROUTE' => $request->medicine_route[$key],
                        'DURATION_MU' => $request->medicine_duration_mu[$key],
                        'BRAND_NAME' => $request->medicine_item[$key],
                        'DURATION' => $request->medicine_duration_type[$key],
                        'STATUS' => 1,
                        'au_entry_at' => $au_entry_at,
                        'au_entry_by' => Auth::id(),
                        'au_entry_session' => $entry_session,
                        'au_entry_hospital_no_fk' => $hospital_pk_no,
                        'ENTRY_SERIAL' => $key + 1,
                    ];


                    DB::table('IPD_ASSESS_PRESCRIPTION_MED')->insert($child_data);
                }
            }

            DB::commit();
            return response()->json(['success' => true, 'message' => 'Successfully Saved'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage()], 422);
        }
    }


    public function referDoctor($patient_no_fk, $admission_id)
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

        $ref_info = DB::table('ipd_consultrecord')
            ->where('PATIENT_NO_FK', $patient_no_fk)
            ->where('ADMISSION_NO_FK', $admission_id)->get();
        foreach ($ref_info as $item) {
            $item->ref_doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->to_doctor_no_fk)->value('FULL_NAME');
            $item->from_doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->from_doctor_no_fk)->value('FULL_NAME');
        }

        return Template::loadView("admin.ipd.nurse_station.v2.refer_doctor", ['ref_info' => $ref_info, 'patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info]);
    }

    public function referDoctorSave(Request $request)
    {
        $request->validate([
            'admission_no_fk' => 'required',
            'ref_type' => 'required',
            'patient_no_fk' => 'required',
            'doctor_id' => 'required',
        ]);
        try {
            $seq = $this->getSequence('consultrecord_no_pk');
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $data = [
                'consultrecord_no_pk' => $seq,
                'from_doctor_no_fk' => $request->doctor_id,
                'to_doctor_no_fk' => $request->ref_doctor_id,
                'REF_TYPE' => $request->ref_type,
                'REF_DATE' => $au_entry_at,
                'REASON' => $request->ref_reason,
                'REPLAY_TO_REFF' => $request->ref_referral,
                'REPLAY_DATE' => !empty($request->ref_referral) ? $au_entry_at : '',
                'status' => 1,
                'PATIENT_NO_FK' => $request->patient_no_fk,
                'ADMISSION_NO_FK' => $request->admission_no_fk,

            ];

            if (isset($request->consultrecord_no_pk) && !empty($request->consultrecord_no_pk)) {
                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_no_fk'] = $hospital_pk_no;

                DB::table('ipd_consultrecord')->where('consultrecord_no_pk', $request->consultrecord_no_pk)->update($data);
            } else {
                $data['au_entry_at'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
                DB::table('ipd_consultrecord')->insert($data);
            }



            return response()->json(['success' => true, 'msg' => 'Successfully Saved', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }
    public function referDoctorSaveReason(Request $request)
    {
        try {
            DB::table('ipd_consultrecord')->where('consultrecord_no_pk', $request->consultrecord_no_pk)->update([
                'REPLAY_TO_REFF' => $request->ref_referral
            ]);

            DB::commit();
            return response()->json(['success' => true, 'msg' => 'Successfully Updated', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

    public function downloadReferralDoctor($consultrecord_no_pk)
    {
        ini_set('max_execution_time', 0);
        $ref_info = DB::table('ipd_consultrecord')
            ->where('consultrecord_no_pk', $consultrecord_no_pk)
            ->first();


        $patient_id = $ref_info->patient_no_fk;
        $admission_uid = $ref_info->admission_no_fk;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();



        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();


        if (isset($ref_info->to_doctor_no_fk)) {
            $ref_info->ref_doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $ref_info->to_doctor_no_fk)->value('FULL_NAME');
            $ref_info->doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $ref_info->from_doctor_no_fk)->value('FULL_NAME');
        }



        return view("admin.ipd.nurse_station.v2.export.refer_doctor_pdf", ['userInfo' => $userInfo, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info, 'ref_info' => $ref_info, 'patient_info' => $patient_info]);
    }

