            ->orderByDesc('ipd_consultrecord_dtl.consultrecord_dtl_no_pk')
            ->get();

        return Template::loadView("admin.ipd.nurse_station.v2.consultation_note", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'follow_notes' => $follow_notes]);
