    public function glucoseChart($patient_no_fk, $admission_id)
    {
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

        $history = DB::table('ipd_diabetic')
            ->where('patient_no_fk', $patient_no_fk)
            ->where('admission_no_fk', $admission_id)
            ->orderBy('time_of_result', 'asc')
            ->get();

        // Attach names
        foreach ($history as $key => $item) {
            $item->doctor_name_0 = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->reported_doctor)->value('full_name');
            $item->rn_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->rn_sign)->value('full_name');
            $item->doctor_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->doc_sign)->value('full_name');
            $item->rn_sign_name_2 = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->rn2_sign)->value('full_name');
            $item->checked_by_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $item->checked_by)->value('full_name');
        }

        // Prepare data for chart
        $volumeArr = [];
        $timeArr = [];

        foreach ($history as $item) {
            $volumeArr[] = $item->volume ?? 0;
            $timeArr[] = date('H:i', strtotime($item->time_of_result));
        }

        $glucoseVolumes = implode(',', $volumeArr);
        $glucoseTimes = json_encode($timeArr);

        return Template::loadView("admin.ipd.nurse_station.v2.glucose_chart", [
            'patient_info' => $patient_info,
            'patient_no_fk' => $patient_no_fk,
            'admission_id' => $admission_id,
            'admission_info' => $admission_info,
            'history' => $history,
            'glucoseVolumes' => $glucoseVolumes,
            'glucoseTimes' => $glucoseTimes,
        ]);
    }

    public function getGlucoseInfo(Request $request)
    {


        $history = DB::table('ipd_diabetic')
            ->where('diabetic_no_pk', $request->diabetic_no_pk)
            ->first();
        if (isset($history->reported_doctor)) {
            $history->doctor_name_0 = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $history->reported_doctor)->value('full_name');
            $history->rn_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $history->rn_sign)->value('full_name');
            $history->doctor_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $history->doc_sign)->value('full_name');
            $history->rn_sign_name_2 = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $history->rn2_sign)->value('full_name');
            $history->checked_by_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $history->checked_by)->value('full_name');
        }

        return response()->json(['data' => $history], 200);
    }

