        $reffered_info = DB::table('anaesthetic_reff_form ref')
            ->leftjoin('hrms_personnel per', 'ref.ref_doctor_no_fk', 'per.person_no_pk')
            ->where(function ($query) use ($patient_id, $ref_no) {
