    public function anaestheTiaReferralStore(Request $request)
    {
        // dd($request->all());
        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();


        try {
            $data = [
                //'admission_no_fk' => $request->admission_id,
                // 'primary_doctor_no_fk' => $request->primary_doctor_no_fk,
                // 'duty_doc_person_no_fk' => $request->duty_doc_person_no_fk,
                'ref_doctor_no_fk' => $request->hdn_doctor_id,
                'patient_no_fk' => $request->pat_id,
                'age' => $request->ptage,
                // 'gender' => $request->gender,
                'gender_txt' => $request->ptsex,
                'weight' => $request->weight,
                'su_no_fk' => $request->su_no_fk,
                'purpose_of_referral' => $request->purpose,
                'history' => $request->history,
                'positive_findings' => $request->positive_findings,
                'diagnosis' => $request->diagnosis,
                'ot_planned' => $request->operationPlanned,
                'ot_planned_date' => date('Y-m-d', strtotime($request->dateOperationPlanned)),
                'doc_reply_text' => $request->doc_reply_text,
                'phy_cond_ind' => $request->phy_cond_ind,
                'status' => $request->status,
                'REFF_ANES_DEPT_NO_fK' => $request->ref_no,
            ];

            $sequence = DB::getSequence();
            $anaesthetic_reff_form_no_pk_seq = $sequence->nextValue('anaesthetic_reff_form_no_pk_seq');
            if ($request->ot_operation_no_pk == "") {
                $data['anaesthetic_reff_form_no_pk'] = $anaesthetic_reff_form_no_pk_seq;
                $data['AU_ENTRY_BY'] = $auth_id;
                $data['AU_ENTRY_AT'] = date('Y-m-d');
                $data['AU_ENTRY_SESSION'] = 'sessoin';
                $data['au_entry_hospital_pk_no'] = $hospital_no_pk;
                DB::table('anaesthetic_reff_form')->insert($data);
            } else {
                $data['AU_UPDATE_BY'] = $auth_id;
                DB::table('anaesthetic_reff_form')->where('anaesthetic_reff_form_no_pk', $request->ot_operation_no_pk)->update($data);
            }
            DB::commit();
            $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        } catch (\Throwable $th) {
            DB::rollback();
            $this->message = ['msg' => 'Failled.', 'title' => 'Error'];
        }
        return response()->json($this->message);
    }


    public function AddMSUITEM($patient_no_pk = "", $admission_no_pk = "")
    {
        $service_point = GrantUserService::where('pharmacy_ind', '1')
            ->select(
                'serviceunit_no_pk',
                'serviceunit_name',
                'serviceunit_code',
                'default_ind',
                'hs_pos_ind'
            )
            ->where('user_no_pk', Auth::id())
            ->where('ipdphr_ind', 1)
            ->where('au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->orderBy('serviceunit_name', 'asc')
            ->distinct()
            ->get();
        return Template::loadView("admin.ipd.nurse_station.v2.modal.add_msu_item", compact('patient_no_pk', 'admission_no_pk', 'service_point'));
    }

    public function saveMSUItem(Request $request)
    {
        $request->validate([
            'patient_no_pk' => 'required',
            'admission_no_pk' => 'required',
        ]);

        try {


            if (!isset($request->item_id)) {
                return response()->json(['success' => true, 'message' => 'Please select at least one item!', 'title' => 'Failed'], 422);
            }


            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $store_no_fk = DB::table('sysc_serviceunit')->where('ipdphr_ind', 1)->value('serviceunit_no_pk');
            if (empty($store_no_fk)) {
                return response()->json(['success' => true, 'message' => 'Pharmacy not found!'], 422);
            }
            DB::beginTransaction();
            $master_id = $this->getSequence('ipdpatmedtran');
            $nurse_station_fk = '';
            $patient_id = $request->patient_no_pk;
            $admission_id = $request->admission_no_pk;
            foreach ($request->item_id as $key => $value) {

                $seq = $this->getSequence('seq_patmedtran');
                $generic_no_fk = DB::table('SYSC_SERVICEITEM')->where('ITEM_NO_PK', $value)->value('generic_no_fk');

                if (empty($nurse_station_fk)) {
                    $nurse_station_fk = DB::table('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW')->where('MOVEMENT_NO', 2)->where('admission_no_pk', $admission_id)->where('patient_no_fk', $patient_id)->value('ns_no_fk');
                }
                if ($request->item_qty[$key] > 0) {
                    $data = [
                        'TRAN_DATE' => $au_entry_at,
                        'PATMEDTRAN_NO_PK' => $seq,
                        'SL_NO' => $key + 1,
                        'STATUS' => 1,
                        'PATIENT_NO_FK' => $patient_id,
                        'PRES_NO_FK' => null,
                        'ITEM_QTY' => $request->item_qty[$key],
                        'ITEM_NO_FK' => $value,
                        'ADMISSION_NO_FK' => $admission_id,
                        'AU_ENTRY_BY' => Auth::id(),
                        'AU_ENTRY_AT' => $au_entry_at,
                        'AU_ENTRY_SESSION' => $entry_session,
                        'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_pk_no,
                        'RX_NO' => null,
                        'TRAN_EMP' => null,
                        'STORE_NO_FK' => $store_no_fk,
                        'TRAN_TYPE' => 'IR',
                        'REF_TRAN_ID' => null,
                        'READY_IND' => null,
                        'READY_BY' => null,
                        'READY_AT' => null,
                        'NURSESTATION_NO_FK' => $nurse_station_fk,
                        'MED_REQ_ID' => $master_id,
                        'INVOICE_NO_FK' => null,
                        'GENERIC_NO' => $generic_no_fk,
                        'EXP_DATE' => null,
                        'DELIVERY_IND' => null,
                        'DELIVERY_BY' => null,
                        'DELIVERY_AT' => null,
                        'COMMENTS' => null,
                        'BATCH_NO' => null,
                    ];

                    DB::table('PHR_IPDPATMEDTRAN')->insert($data);
                }
            }
            DB::commit();
            return response()->json(['msg' => 'Successfully Saved', 'title' => 'Success', 'success' => true], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['msg' => $th->getMessage(), 'title' => 'Failed', 'success' => false], 200);
        }
    }


    public function ipdPatientDischargeCheckList($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();

        $data = DB::table('ipd_dischargelama')->where('admission_no_fk', $admission_uid)->where('patient_no_fk', $patient_id)->first();

        if (isset($data->identified_varified_by)) {
            $data->verified_tl = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', $data->identified_varified_by)->value('FULL_NAME');
