    public function dischargeLAMASave(Request $request)
    {

        $request->validate([
            'patient_no_fk' => 'required|numeric',
            'admission_no_fk' => 'required|numeric',
        ]);
        try {
            DB::beginTransaction();
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $data = [
                'pat_identified_dose' => $request->pat_identified_dose,
                'identified_varified_by' => $request->identified_varified_by,
                'explainedpatient' => $request->explainedpatient,
                'patient_rel' => $request->patient_rel,
                'pfe_care' => $request->pfe_care,
                'pfe_wound' => $request->pfe_wound,
                'hos_uniform' => $request->hos_uniform,
                'removal_id' => $request->removal_id,
                'iv_cannula' => $request->iv_cannula,
                'handed_over' => $request->handed_over,
                'received_slip' => $request->received_slip,
                'assessed_for_transport' => $request->assessed_for_transport,
                'discharge_withmeasures' => $request->discharge_withmeasures,
                'bill_cleared' => $request->bill_cleared,
                'lama_consent' => $request->lama_consent,
                'lama_summary' => $request->lama_summary,
                'death_care_given' => $request->death_care_given,
                'death_certificate_body' => $request->death_certificate_body,
                'relation_patient' => $request->relation_patient,
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,
                'status' => 1
            ];


            if (!DB::table('ipd_dischargelama')->where('admission_no_fk', $request->admission_no_fk)->where('patient_no_fk', $request->patient_no_fk)->exists()) {
                $mast_seq = $this->getSequence('dischargelama_no_pk_seq');
                $data['au_entry_at'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
                $data['dischargelama_no_pk'] = $mast_seq;
                DB::table('ipd_dischargelama')->insert($data);
            } else {
                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_no_fk'] = $hospital_pk_no;
                DB::table('ipd_dischargelama')->where('admission_no_fk', $request->admission_no_fk)->where('patient_no_fk', $request->patient_no_fk)->update($data);
            }


            DB::commit();
            return response()->json(['success' => true, 'message' => 'Successfully Saved'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage()], 422);
        }
    }

    public function downloadDischargeLAMA($patient_no_pk, $admission_no_pk)
