    public function intakeOutputChart($patient_no_fk, $admission_id)
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $uom = DB::table('SYSC_SERVICEITEM_UOM')->where('status', 1)->get();

        $ipd_patoutput = DB::table('ipd_patoutput')
            ->where('patient_no_fk', $patient_no_fk)
            ->where('admission_no_fk', $admission_id)
            ->orderByDesc('patoutput_no_pk')
            ->get();
        $ipd_patintake = DB::table('ipd_patintake')
            ->leftJoin('SYSC_SERVICEITEM_UOM', 'SYSC_SERVICEITEM_UOM.UOM_NO_PK', 'ipd_patintake.UOM_NO_FK')
            ->where('ipd_patintake.patient_no_fk', $patient_no_fk)
            ->where('ipd_patintake.admission_no_fk', $admission_id)
            ->select("ipd_patintake.*", "SYSC_SERVICEITEM_UOM.UOM_CODE")
            ->orderByDesc('ipd_patintake.patintake_no_pk')
            ->get();

        $admission_date = $admission_info->admission_date;
        if (!empty($admission_date)) {
            $admission_date = date('Y-m-d', strtotime($admission_date));
        }
        $discharge_date = $admission_info->discharge_date;
        if (!empty($discharge_date)) {
            $discharge_date = date('Y-m-d', strtotime($discharge_date));
        } else {
            $discharge_date = date('Y-m-d');
        }


        $admission_date = explode('-', $admission_date);
        $discharge_date = explode('-', $discharge_date);
        $startDate = Carbon::create($admission_date[0], $admission_date[1], $admission_date[2]);
        $endDate = Carbon::create($discharge_date[0], $discharge_date[1], $discharge_date[2]);

        // ??????? ?????? ???? ????
        $period = new DatePeriod(
            new DateTime($startDate),
            new DateInterval('P1D'), // ???????? ?? ??? ??? ??? ???
            (new DateTime($endDate))->modify('+1 day') // ??? ????? ??????? ???? ????
        );


        $report_dates = [];
        foreach ($period as $date) {
            $report_dates[] = $date->format('Y-m-d');
        }
        return Template::loadView("admin.ipd.nurse_station.v2.modal.intake_output_chart", ['uom' => $uom, 'report_dates' => $report_dates, 'patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'ipd_patoutput' => $ipd_patoutput, 'ipd_patintake' => $ipd_patintake]);
    }

