            ->first();
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

        $history = DB::table('psn_t_patvitals')
            ->where('patient_no_fk', $patient_no_fk)
            ->where('admission_no_fk', $admission_id)
            ->whereNotNull('pulse_val')
            ->orderByDesc('vital_no_pk')
            ->get();

        $height = DB::table('psn_t_patvitals')
            ->where('patient_no_fk', $patient_no_fk)
            ->where('admission_no_fk', $admission_id)
            ->whereNotNull('height_val')
            ->orderByDesc('vital_no_pk')
            ->value('height_val');
        $weight = DB::table('psn_t_patvitals')
