        return Template::loadView("admin.ipd.nurse_station.v2.modal.vital_entry", ['height' => $height, 'weight' => $weight, 'patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'history' => $history]);
