    public function saveVitalEntry(Request $request)
    {

        $request->validate([
            'admission_no_fk' => 'required',
            'patient_no_fk' => 'required',
            'temperature' => 'required',
            'bp_first' => 'required',
            'bp_second' => 'required',
            'pulse' => 'required',
            // 'height' => 'required',
            // 'weight' => 'required',
            // 'bmi' => 'required',
        ]);
        try {
            $seq = $this->getSequence('psn_t_patvitals_seq');
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $data = [
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,

                'pulse_val' => $request->pulse,
                'BP_VAL' => $request->bp_first . '/' . $request->bp_second,
                'bp_val_dia' => $request->bp_second,
                'bp_val_sys' => $request->bp_first,
                'TEMP_VAL' => $request->temperature,
                'respiration' => $request->respiration,
                'SPO2' => $request->spo2,
                // 'HEIGHT_VAL' => $request->height,
                // 'WEIGHT_VAL' => $request->weight,
                // 'BMI' => $request->bmi,
                'status' => 1,
            ];


            if (!empty($request->vital_no_pk)) {
                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_no_fk'] = $hospital_pk_no;
                DB::table('psn_t_patvitals')->where('vital_no_pk', $request->vital_no_pk)->update($data);
            } else {
                $data['vital_no_pk'] = $seq;
                $data['au_entry_at'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
                DB::table('psn_t_patvitals')->insert($data);
            }

            return response()->json(['success' => true, 'msg' => 'Successfully Saved', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

