    public function vitalGenerateReport($patient_no_fk, $admission_id)
    {
        ini_set('max_execution_time', 0);

        $patient_id = $patient_no_fk;
        $admission_uid = $admission_id;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();



        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();


        $history = DB::table('psn_t_patvitals')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->whereNotNull('pulse_val')
            ->whereNotNull('pulse_val')
            ->orderByDesc('vital_no_pk')
            ->select("respiration", 'pulse_val', 'spo2', 'temp_val', 'bp_val_sys', 'bp_val_dia', 'au_entry_at')
            ->selectRaw("TO_CHAR(TRUNC(AU_ENTRY_AT), 'YYYY-MM-DD') as vital_date")
            ->get();

        // Vital Sign Calculation

        foreach ($history as $item) {

            // RR
            $item->rr_calculate = !is_null($item->respiration) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'RR')
                ->where('START_VALUE', '<=', $item->respiration)
                ->where('END_VALUE', '>=', $item->respiration)
                ->value('mews_rate') : 0;

            // PLUSE
            $item->pulse_calculate = !is_null($item->pulse_val) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'PLUSE')
                ->where('START_VALUE', '<=', $item->pulse_val)
                ->where('END_VALUE', '>=', $item->pulse_val)
                ->value('mews_rate') : 0;

            // OX2
            $item->ox2_calculate = !is_null($item->spo2) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'OX2')
                ->where('START_VALUE', '<=', $item->spo2)
                ->where('END_VALUE', '>=', $item->spo2)
                ->value('mews_rate') : 0;

            // TEMP
            $item->temp_calculate = !is_null($item->temp_val) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'TEMP')
                ->where('START_VALUE', '<=', $item->temp_val)
                ->where('END_VALUE', '>=', $item->temp_val)
                ->value('mews_rate') : 0;

            // BP SYS
            $item->bp_calculate_high = !is_null($item->bp_val_sys) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'BP')
                ->where('START_VALUE', '<=', $item->bp_val_sys)
                ->where('END_VALUE', '>=', $item->bp_val_sys)
                ->value('mews_rate') : 0;

            // BP DIA
            $item->bp_calculate_low = !is_null($item->bp_val_dia) ? DB::table("ipds_mewsdtl")
                ->join('ipds_mewsmst', 'ipds_mewsmst.mewsmst_no_pk', '=', 'ipds_mewsdtl.mewsmst_no_fk')
                ->where('ipds_mewsmst.mews_type', 'BP')
                ->where('START_VALUE', '<=', $item->bp_val_dia)
                ->where('END_VALUE', '>=', $item->bp_val_dia)
                ->value('mews_rate') : 0;

            // Final Score Calculation
            $result = $item->rr_calculate + $item->pulse_calculate + $item->ox2_calculate + $item->temp_calculate + $item->bp_calculate_high + $item->bp_calculate_low;

            $result_value = DB::table("ipds_mewsresult")
                ->where('START_VALUE', '<=', $result)
                ->where('END_VALUE', '>=', $result)
                ->first();

            $item->mews_score = $result;
            $item->pat_risk = @$result_value->patient_risk;
            $item->f_ob = @$result_value->freq_obs;
            $item->action = @$result_value->action;
        }





        $data = DB::table('psn_t_patvitals')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderByDesc('vital_date') // Ordering by the formatted vital_date
            ->selectRaw("TO_CHAR(TRUNC(AU_ENTRY_AT), 'YYYY-MM-DD') as vital_date")
            ->groupByRaw("TO_CHAR(TRUNC(AU_ENTRY_AT), 'YYYY-MM-DD')") // Grouping by the formatted date
            ->get();

        foreach ($data as $item) {
            $item->vitals = collect($history)->where('vital_date', $item->vital_date)->values();
        }





        return view("admin.ipd.nurse_station.v2.export.generate_vital_report_pdf", ['userInfo' => $userInfo, 'pat_barcode' => $pat_barcode, 'invoice_barcode' => $invoice_barcode, 'admission_info' => $admission_info, 'history' => $data, 'patient_info' => $patient_info]);
    }



