            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $data['discontine_ind'] = DB::table('psn_t_prescription_med')->where('prescription_med_no_pk', $request->prescription_med_no_pk)->value('discontine_ind') == 1 ? 0 : 1;
            $data['au_update_at'] = $au_entry_at;
            $data['discontinue_time'] = $au_entry_at;
            $data['au_update_by'] = auth::id();
            $data['discontinue_by'] = auth::id();
            $data['au_update_session'] = $entry_session;
            $data['discontinue_reason'] = $request->ref_referral;
