    public function getPendingReferalPatient(Request $request)
    {

        $nurse_station = $request->nurse_station;



        $data = DB::table('ipd_consultrecord')
            ->Join('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW', function ($q) {
                $q->on("ipd_v1_admitted_pat_nsreq_wl_vw.patient_no_fk", "=", "ipd_consultrecord.patient_no_fk");
                $q->on("ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk", "=", "ipd_consultrecord.admission_no_fk");
            })
            ->Join('HRMS_PERSONNEL', function ($q) {
                $q->on("HRMS_PERSONNEL.PERSON_NO_PK", "=", "ipd_consultrecord.to_doctor_no_fk");
            })
            ->Join('HRMS_PERSONNEL fdoctor', function ($q) {
                $q->on("fdoctor.PERSON_NO_PK", "=", "ipd_consultrecord.from_doctor_no_fk");
            })
            ->select(
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.admission_date",
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.bed_name",
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.patient_name",
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.admission_uid",
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.doc_department",
                "IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.ward_name",


                "ipd_consultrecord.patient_no_fk",
                "ipd_consultrecord.admission_no_fk",
                "ipd_consultrecord.to_doctor_no_fk",
                "ipd_consultrecord.from_doctor_no_fk",
                "HRMS_PERSONNEL.full_name as to_doctor_name",
                "fdoctor.full_name as from_doctor_name"
            )
            ->where('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.ns_no_fk', $nurse_station)
            ->where('IPD_V1_ADMITTED_PAT_NSREQ_WL_VW.dis_ind', 0)
            ->whereNull('ipd_consultrecord.replay_to_reff')
            ->get();

        return response()->json(['message' => 'success', 'data' => $data], 200);
    }

