    public function datewiseIntakeOutput($patient_no_pk, $admission_no_pk, $date)
    {
        ini_set('max_execution_time', 0);

        $patient_id = $patient_no_pk;
        $admission_uid = $admission_no_pk;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();



        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();



        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(7)->setTimezone('Asia/Dhaka');
        $endDate = $startDate->copy()->addDay()->subSecond()->setTimezone('Asia/Dhaka');


        $ipd_patoutput = DB::table('ipd_patoutput')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->whereBetween('PATOUTPUT_DATE', [$startDate, $endDate])
            ->orderByDesc('patoutput_no_pk')
            ->get();




        $ipd_patintake = DB::table('ipd_patintake')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderByDesc('patintake_no_pk')
            ->whereBetween('PATINTAKE_DATE', [$startDate, $endDate])
            ->get();


        // intake calculate
        // morning
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(7)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addHours(13)->subSecond()->setTimezone('Asia/Dhaka');
        $moring_intake = DB::table('ipd_patintake')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderByDesc('patintake_no_pk')
            ->whereBetween('PATINTAKE_DATE', [$startDate, $endDate])
            ->sum('intake_value');

        // evening
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(13)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addHours(19)->subSecond()->setTimezone('Asia/Dhaka');
        $evening_intake = DB::table('ipd_patintake')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderByDesc('patintake_no_pk')
            ->whereBetween('PATINTAKE_DATE', [$startDate, $endDate])
            ->sum('intake_value');
        // night
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(19)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addDay()->addHours(7)->subSecond()->setTimezone('Asia/Dhaka');
        $night_intake = DB::table('ipd_patintake')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->orderByDesc('patintake_no_pk')
            ->whereBetween('PATINTAKE_DATE', [$startDate, $endDate])
            ->sum('intake_value');




        // outtake calculate
        // morning
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(7)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addHours(13)->subSecond()->setTimezone('Asia/Dhaka');
        $moring_output = DB::table('ipd_patoutput')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->whereBetween('PATOUTPUT_DATE', [$startDate, $endDate])
            ->get();
        $moring_output = collect($moring_output)->sum('urin_val') + collect($moring_output)->sum('emosis_val') + collect($moring_output)->sum('rt_val') + collect($moring_output)->sum('drain_val');

        // evening
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(13)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addHours(19)->subSecond()->setTimezone('Asia/Dhaka');
        $evening_output = DB::table('ipd_patoutput')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->whereBetween('PATOUTPUT_DATE', [$startDate, $endDate])
            ->get();
        $evening_output = collect($evening_output)->sum('urin_val') + collect($evening_output)->sum('emosis_val') + collect($evening_output)->sum('rt_val') + collect($evening_output)->sum('drain_val');
        // night
        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(19)->setTimezone('Asia/Dhaka');
        $endDate = $today->copy()->addDay()->addHours(7)->subSecond()->setTimezone('Asia/Dhaka');
        $night_output = DB::table('ipd_patoutput')
            ->where('patient_no_fk', $patient_id)
            ->where('admission_no_fk', $admission_uid)
            ->whereBetween('PATOUTPUT_DATE', [$startDate, $endDate])
            ->get();
        $night_output = collect($night_output)->sum('urin_val') + collect($night_output)->sum('emosis_val') + collect($night_output)->sum('rt_val') + collect($night_output)->sum('drain_val');


        $endDate = $startDate->copy()->addDay()->subSecond()->setTimezone('Asia/Dhaka');



        return view("admin.ipd.nurse_station.v2.export.datewise_intake_output_pdf", [
            'userInfo' => $userInfo,
            'pat_barcode' => $pat_barcode,
            'invoice_barcode' => $invoice_barcode,
            'admission_info' => $admission_info,
            'ipd_patoutput' => $ipd_patoutput,
            'ipd_patintake' => $ipd_patintake,
            'patient_info' => $patient_info,

            'moring_intake' => $moring_intake,
            'evening_intake' => $evening_intake,
            'night_intake' => $night_intake,
            'moring_output' => $moring_output,
            'evening_output' => $evening_output,
            'night_output' => $night_output,
            'date' => $date
        ]);
    }


