    public function saveFallRisk(Request $request)
    {

        $request->validate([
            'patient_no_fk' => 'required|numeric',
            'admission_no_fk' => 'required|numeric',
        ]);
        try {
            DB::beginTransaction();
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $ipd_fall_preven_measures_val = implode(',', $request->fall_prevention);
            $data = [
                'asmnt_rn_no' => $request->asmnt_rn_no,
                'his_fall' => $request->his_fall,
                'age' => $request->age,
                'sec_diagnosis' => $request->sec_diagnosis,
                'invasive_lines' => $request->invasive_lines,
                'ambulatory_aids' => $request->ambulatory_aids,
                'gaint' => $request->gaint,
                'memtal' => $request->memtal,
                'medication_use' => $request->medication_use,
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,
                'ipd_fall_preven_measures' => $ipd_fall_preven_measures_val,
                'status' => 1
            ];


            if (!DB::table('ipd_fallriskasmnt')->where('admission_no_fk', $request->admission_no_fk)->where('patient_no_fk', $request->patient_no_fk)->exists()) {
                $mast_seq = $this->getSequence('fallriskasmnt_no_pk_seq');
                $data['au_entry_at'] = $au_entry_at;
                $data['asmnt_date'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_pk_no'] = $hospital_pk_no;
                $data['fallriskasmnt_no_pk'] = $mast_seq;
                DB::table('ipd_fallriskasmnt')->insert($data);
            } else {
                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_pk_no'] = $hospital_pk_no;
                DB::table('ipd_fallriskasmnt')->where('admission_no_fk', $request->admission_no_fk)->where('patient_no_fk', $request->patient_no_fk)->update($data);
            }


            DB::commit();
            return response()->json(['success' => true, 'message' => 'Successfully Saved'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage()], 422);
        }
    }

