    public function billGenerate(Request $request)
    {


        try {
            DB::beginTransaction();
            $ipd_adm_bed_no_pk = $request->ipd_adm_bed_no_pk;


            $days = $request->days;
            // $bed_no_fk = DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk',$ipd_adm_bed_no_pk)->value('bed_no_fk');
            $admission_no_fk = DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $ipd_adm_bed_no_pk)->value('admission_no_fk');
            $patient_no_fk = DB::table('ipd_admission')->where('admission_no_pk', $admission_no_fk)->value('patient_no_fk');
            $corporate_info = DB::table('pat_registration_wl_vw')->where('patient_no_pk', $patient_no_fk)->first(['ccm_client_no_fk', 'patient_type_code']);

            if (DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $ipd_adm_bed_no_pk)->value('status') == 1 && DB::table("ipd_admitted_patlist_vw")->where('patient_no_fk', $patient_no_fk)->where('admission_no_pk', $admission_no_fk)->value('dis_req_ind') != 1) {
                throw new Error('Please at First Discharge Request');
            }


            $pat_info = DB::table('patn_registration')->where('patient_no_pk', $patient_no_fk)->first();
            $pres_master = DB::table('psn_t_prescription')->where('patient_no_fk', $patient_no_fk)->first();
            $nurse_station_pk = DB::table("ipd_admission_details")->where('admission_no_pk', $admission_no_fk)->value("ns_receive_by");
            $corporate_id = $corporate_info->ccm_client_no_fk ?? 0;
            $pt_type_code = $corporate_info->patient_type_code;
            // dd( $corporate_id, $pt_type_code);
            // $corporate_id = DB::table('patn_registration')->where('patient_no_pk', $patient_no_fk)->value('ccm_client_no_fk');

            $auth_id = Auth::id();
            $time = Carbon::now();
            $cur_date = date('Y-m-d H:i:s', strtotime($time));
            $cur_datetime = date('Y-m-d H:i:s', strtotime($time));
            $module_id = DB::table("sysc_module")->where('module_code', 'IPDI')->value('module_no_pk');
            $patient_type = $pat_info->patient_type;
            $hdn_patient_id = $patient_no_fk;
            $hdn_patient_code = $pat_info->patient_code;
            $admission_id = $admission_no_fk;

            $service_appointment_id = null;
            $prescription_id = null;

            $hdn_doctor_id = @$pres_master->doctor_person_no_fk;
            $hdn_first_referral_id = null;
            $hdn_second_referral_id = null;

            $bed_no_fk = DB::table('ipd_admission_bed')->where('ipd_adm_bed_no_pk', $ipd_adm_bed_no_pk)->value('bed_no_fk');
            $hdn_item_id = DB::table('ipds_bed')->where('bed_no_pk', $bed_no_fk)->pluck('bed_charge_item_no_fk')->toArray();



            $total_item = count($hdn_item_id);
            $item_vat_prse = $request->vat_pers;
            $provider_no = $request->hdn_provider;
            $hdn_item_rate = $request->hdn_item_rate;
            $hdn_item_qnty = $request->hdn_item_qnty;
            $remarks = "Bill Generated from Bed Charge";
            $urgent_fee = 0;
            $entry_session = "session";
            $in_counter_su_no_fk = $nurse_station_pk;
            $report_delivery_date = null;
            $invoice_date = null;
            $ses_hospital_id = Session::get('user.ses_hospital_no_pk');
            $hospital_id = $ses_hospital_id;
            $null = '';

            $out_sl_no = '';
            $empty_arr = [];
            $numelems = 200;
            $zero = 0;

            $deli_dt_arr = $hdn_item_name = $hdn_item_rate = $provider_no = $item_vat_prse = $ipd_charge = $hdn_item_urgent_fee_amt = $item_disc_amount = $item_disc_percent = $hdn_item_qnty = $item_level_remarks = $hdn_item_type = $item_delivery_status_arr = $item_mu_arr = $item_disc_percent = $item_disc_amount = $ipd_charge = $def_dis = [];
            // dd($hdn_item_id);
            $null = null;
            $numelems = 200;
            $ipd_dis_inapplicable=DB::table('patn_patienttype')->where('patient_type_code',$pt_type_code)->value('ipd_discount_inapplicable');
            foreach ($hdn_item_id as $key => $value) {
                $deli_dt_arr[$key] = null;
                $item_delivery_status_arr[$key] = null;
                $package_ind_arr[$key] = 0;
                $item_mu_arr[$key] = 0;
                $batch_no_arr[$key] = null;
                $expire_dt_arr[$key] = null;
                $item_info = DB::table("sysc_serviceitem")->where('item_no_pk', $value)->select("item_name", "item_type", "itemtype_no_fk", "sales_price", "default_discount_pct", "note_text")->first();

                $hdn_item_name[$key] = isset($item_info->item_name) ? $item_info->item_name : null;
                $hdn_item_type[$key] = isset($item_info->itemtype_no_fk) ? $item_info->itemtype_no_fk : null;
                $item_level_remarks[$key] = isset($item_info->note_text) ? $item_info->note_text : null;
                ;
                $hdn_item_qnty[$key] = $days;
                $hdn_item_rate[$key] = isset($item_info->sales_price) ? $item_info->sales_price : 0;
                $item_disc_percent[$key] = isset($item_info->default_discount_pct) ? $item_info->default_discount_pct : 0;
                // $item_disc_amount[$key] =  (floatVal($item_info->sales_price) * floatVal($item_info->default_discount_pct)) / 100;
                $def_dis_perc = $item_info->default_discount_pct != '' ? $item_info->default_discount_pct : 0;
                $sales_amt = $item_info->sales_price != '' ? $item_info->sales_price : 0;
                $hdn_item_urgent_fee_amt[$key] = 0;
                $ipd_charge[$key] = 0;
                $item_vat_prse[$key] = 0;
                $provider_no[$key] = 0;
                if ($admission_id !="" && $ipd_dis_inapplicable==1) {
                    $item_disc_amount[$key] =0;
                }else{
                    $def_dis[$key] = DB::select(DB::raw("select pkg_corporate.fnc_get_item_discount( $value,'$pt_type_code',$corporate_id, $sales_amt,0,$def_dis_perc,'AMT') as def_discount from dual"));
                    $item_disc_amount[$key] = $def_dis[0][0]->def_discount = !'' && $days > 0 ? ($def_dis[0][0]->def_discount * $days) : 0;
                }
                // AMTPCT
                // dd( $value,$pt_type_code,$corporate_id, $sales_amt,0,$def_dis_perc,$def_dis,$item_disc_amount );

            }

            $item_total = array_sum($hdn_item_rate);
            $total_payment = 0;
            $total_discount_amount = array_sum($item_disc_amount);
            // dd( $hdn_item_rate, $item_total,$item_disc_amount, $total_discount_amount, $days);
            // dd($item_disc_amount,$hdn_item_rate);
            // OUT PAREMETER INITIALIZE
            $out_ledgertrn_no = 0;
            $in_ledgertrn_no = $out_invoice_no = $out_invoice_id = $out_error = 0;
            $item_level_disc_ind = 1;
            $emergency_ind = null;
            $daycare_ind = null;

            $pdo = DB::getPdo();
            $billinvoice = $pdo->prepare("begin pkg_billing_v0.prc_billinvoice_wp(
                                            :in_invoice_date,
                                            :in_invoice_datetime,
                                            :in_module_no_fk,
                                            :in_patient_no_fk,
                                            :in_patient_code,
                                            :in_admission_no_pk,
                                            :in_admission_code,
                                            :in_appointment_no_fk,
                                            :in_prescription_no_fk,
                                            :in_doc_person_no_fk,
                                            :in_first_ref_doc,
                                            :in_second_ref_doc,
                                            :in_report_delivary_date,
                                            :in_report_deli_datetime,
                                            :in_counter_su_no_fk,
                                            :in_cor_client_no_fk,
                                            :in_cor_client_card_no_fk,
                                            :in_relation_lookup_no_fk,
                                            :in_ref_invoice_no_fk,
                                            :in_pat_type_lookup_no_fk,
                                            :in_dob,
                                            :in_age,
                                            :in_age_dd,
                                            :in_age_mm,
                                            :in_age_yy,
                                            :in_customer_addr,
                                            :in_customer_name,
                                            :in_gender_txt,
                                            :in_marital_status_txt,
                                            :in_blood_group,
                                            :in_phone_mobile,
                                            :in_invoice_remarks,
                                            :in_urgent_fee_total,
                                            :in_invoice_type,
                                            :in_emergency_ind,
                                            :in_daycare_ind,
                                            :in_ot_ind,
                                            :in_au_entry_by,
                                            :in_au_entry_session,
                                            :in_au_entry_hospital_pk_no,
                                            :in_item_level_disc_ind,
                                            :in_item_count,
                                            :in_item_no_fk,
                                            :in_item_batch_fk,
                                            :in_item_expiry_dt,
                                            :in_item_name,
                                            :in_itemtype_no_fk,
                                            :in_item_qty,
                                            :in_item_mu,
                                            :in_item_rate,
                                            :in_item_disc_percent,
                                            :in_item_disc_amount,
                                            :in_item_vat,
                                            :in_urgent_fee,
                                            :in_service_charge,
                                            :in_report_deli_date,
                                            :in_report_deli_time,
                                            :in_deli_status_lookup,
                                            :in_package_item_ind,
                                            :in_item_level_remarks,
                                            :in_provider_no_fk,
                                            :in_ledgertrn_no,
                                            :out_invoice_no,
                                            :out_invoice_id,
                                            :out_ledgertrn_no,
