    public function otRequsition($patient_no_fk, $admission_id)
    {


        $ot_item = DB::table("sysc_room")->select("room_no_pk", "room_code", "room_name")
            ->where('status', 1)
            ->where('ot_ind', 1)
            ->orderby('room_code', 'asc')
            ->get();

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $history = DB::table('opt_prescribed_ot')
    ->select(
        'opt_prescribed_ot.ot_req_date',
        'opt_prescribed_ot.item_no_fk',
        'opt_prescribed_ot.item_name',
        'opt_prescribed_ot.ot_date',
        'opt_prescribed_ot.ot_in_ind',
        'opt_prescribed_ot.reff_anes_dept_no_fk',
        'opt_prescribed_ot.ot_req_no_pk',
        'opt_prescribed_ot.BILL_CLEARENCE_IND',
        'opt_prescribed_ot.ANEST_CLEARANCE_IND',
        'ot_complete_status.OT_COMPLETE_IND'
    )
    ->leftJoin('ot_complete_status', 'ot_complete_status.admission_no_fk', '=', 'opt_prescribed_ot.admission_no_fk')
    ->where('opt_prescribed_ot.patient_no_fk', $patient_no_fk)
    ->where('opt_prescribed_ot.admission_no_fk', $admission_id)
    ->get();



        return Template::loadView("admin.ipd.nurse_station.v2.ot_requsition", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info, 'history' => $history, 'ot_item' => $ot_item]);
    }
    public function ipdConsultantBill($patient_no_fk, $admission_id,$type="")
    {

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();
        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();
        $ipdConsultantFee=DB::table('ipd_surgeon_visit_fee')->select('ipd_surgeon_visit_fee.*','hrms_personnel.full_name','wsec_user.user_fullname','sysc_lookupdata.lookupdata_name')->leftJoin('hrms_personnel','hrms_personnel.person_no_pk','=','ipd_surgeon_visit_fee.doctor_no_fk')->leftJoin('wsec_user','wsec_user.user_no_pk','=','ipd_surgeon_visit_fee.au_entry_by')->leftJoin('sysc_lookupdata','sysc_lookupdata.lookupdata_no_pk','=','ipd_surgeon_visit_fee.visit_type_no')->where('admission_no_fk', $admission_id)->orderByDesc('ipd_surgeon_visit_fee.au_entry_at')->get();
        // dd($ipdConsultantFee);
        $lookupdata = DB::table('sysc_lookup')
            ->join('sysc_lookupdata', 'sysc_lookup.lookup_no_pk', '=', 'sysc_lookupdata.lookup_no_fk')
            ->select('sysc_lookupdata.lookupdata_no_pk', 'sysc_lookupdata.lookupdata_name', 'sysc_lookupdata.lookupdata_desc')
            ->where('sysc_lookup.lookup_code', '=', 'VISITTYPE')
            ->where('sysc_lookupdata.status', 1)
            ->where('sysc_lookupdata.status', 1)
            ->where('sysc_lookup.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->where('sysc_lookupdata.au_entry_hospital_pk_no', Session::get('user.ses_hospital_no_pk'))
            ->where('ipd_consultant_ind',1)
            //->orderBy('sysc_lookupdata.serial_no', 'asc')
            ->orderBy('sysc_lookupdata.lookupdata_name', 'asc')
            ->get();

        // Base query for referred patients
        $user_no_pk = Session::get('user.ses_person_no_fk');
        $referredPatientsOnly = DB::table('ipd_consultrecord as cons')
            ->join('ipd_v1_admitted_pat_nsreq_wl_vw as pat', 'cons.admission_no_fk', '=', 'pat.admission_no_pk')
            ->where('cons.to_doctor_no_fk', $user_no_pk)
            ->where('cons.admission_no_fk', $admission_id)
            ->select(
                'pat.*',
                DB::raw("fnc_ipdvulnerability(pat.admission_no_pk) as vulnerability_alert"),
                DB::raw("fnc_ipdClinicalalert(pat.admission_no_pk) as clinial_alert"),
                DB::raw("fnc_ipdAllergiesalert(pat.admission_no_pk) as allergy_alert"),
                DB::raw("'referred' as source")
            )->get();
        // dd($referredPatientsOnly);
        $lookup_arr = [];
        if (!empty($lookupdata)) {
            foreach ($lookupdata as $row) {
                $lookup_arr[$row->lookupdata_no_pk] = $row->lookupdata_name;
            }
        }

        return Template::loadView("admin.ipd.nurse_station.v2.ipd_consultant_bill", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info,'lookup_arr'=>$lookup_arr,'ipdConsultantFee'=>$ipdConsultantFee,'type'=>$type,'referredPatientsOnly'=>$referredPatientsOnly]);
    }

    public function ipdConsultantBillGenerate(Request $request){


        try {

            // dd($request->all());
            $auth_id = Auth::id();
            DB::beginTransaction();

            $page_type = !empty($request->page_type) ? $request->page_type : "";
            date_default_timezone_set('Asia/Dhaka');
            $time = Carbon::now();
            $cur_date = date('Y-m-d H:i:s', strtotime($time)); //date("Y-M-d h:i:s");
            $cur_datetime = date('Y-m-d H:i:s', strtotime($time)); //date("Y-M-d h:i:s");
            $module_id = 0;
            $patient_type = !empty($request->patient_type) ? $request->patient_type : '';
            $patient_type_code = !empty($request->patient_type_code) ? $request->patient_type_code : '';
            $hdn_patient_id = !empty($request->patient_no_fk) ? $request->patient_no_fk : '';
            $hdn_patient_code = !empty($request->patient_id) ? $request->patient_id : '';
            $admission_id = !empty($request->admission_no_fk) ? $request->admission_no_fk : ''; //appointment_id
            $service_appointment_id = !empty($request->service_appointment_id) ? $request->service_appointment_id : '';
            $prescription_id = !empty($request->hdn_prescription_id) ? $request->hdn_prescription_id : '';

            $hdn_doctor_id = !empty($request->doctor_id) ? $request->doctor_id : '';
            $dis_requ_by = !empty($request->dis_requ_by) ? ucwords($request->dis_requ_by) : '';

            $hdn_dis_doctor_id = !empty($request->hdn_dis_doctor_id) ? $request->hdn_dis_doctor_id : '';
            $hdn_first_referral_id = !empty($request->hdn_first_refer) ? $request->hdn_first_refer : '';
            $hdn_second_referral_id = !empty($request->hdn_second_refer) ? $request->hdn_second_refer : '';
            $item_info=$request->visitType !="" ? DB::table('hrms_doctorfee')->select('sysc_serviceitem.*')->leftJoin('sysc_serviceitem','sysc_serviceitem.item_no_pk','=','hrms_doctorfee.item_no_fk')->where('visit_type_lookup_no_fk',$request->visitType )->where('person_no_fk',$request->doctor_id)->first():'';

            if ($item_info) {
                 $hdn_item_id[] = $item_info->item_no_pk;
            }else{
                return response()->json(['msg' => 'Consultation fee is not set for the selected visit type of this doctor.', 'title' => 'Error'],500);
            }
