                $billpayment->bindParam(':out_error', $out_error, PDO::PARAM_STR, 500);
                // dd( $billpayment);
                $billpayment->execute();


            }
            $sequence = DB::getSequence();
            $surgeon_visit_fee = $sequence->nextValue('surgeon_visit_fee_no_pk_seq');

            $data=[

                'surgeon_visit_fee_no_pk' =>$surgeon_visit_fee,
                'admission_no_fk' => $request->admission_no_fk,
                'patient_no_fk' =>  $request->patient_no_fk,
                'doctor_no_fk' => $request->doctor_id,
                'visit_type_no' =>$request->visitType,
                'invoice_no_fk' =>$out_invoice_no,
                'ledgertrn_no' =>$out_ledgertrn_no,
                'visit_fee' =>$hdn_item_rate[0] ,
                'qty' =>$hdn_item_qnty[0],
                'discount' => $item_disc_amount[0],
                'status' => 1,
                'au_entry_by' =>$auth_id,
                'au_entry_at' =>date('Y-m-d H:i'),
                'au_entry_session' =>'ipd consultant',
                'au_entry_hospital_pk_no' => $hospital_id,
            ];
            // dd( $data);
            DB::table('ipd_surgeon_visit_fee')->insert( $data);
            DB::commit();
            return response()->json(['msg' => 'Bill created successfully.Invoice ID = ' . $out_invoice_no, 'title' => 'Success'],200);
        } catch (\Throwable $th) {
                DB::rollback();
             return response()->json(['msg' => 'save Failled.', 'title' => 'Error'],500);
        }
    }

