    public function searchOTRequisition(Request $request)
    {

        $from_date = null;
        if (!empty($request->ot_req_date_from)) {
            $dateTime = DateTime::createFromFormat('d/m/Y', $request->ot_req_date_from);
            $from_date = $dateTime->format('m/d/Y');
        }

        $to_date = null;
        if (!empty($request->ot_req_date_to)) {
            $dateTime = DateTime::createFromFormat('d/m/Y', $request->ot_req_date_to);
            $to_date = $dateTime->format('m/d/Y');
        }


        $query = DB::table('opt_ot_reqlist_wl_vw')->where('ot_comfirmation_ind', 0)->whereNull('reject_ind')
            ->leftJoin('ipd_admitted_patlist_vw', 'ipd_admitted_patlist_vw.admission_no_pk', '=', 'opt_ot_reqlist_wl_vw.admission_no_fk')
            ->select('opt_ot_reqlist_wl_vw.*', 'ipd_admitted_patlist_vw.new_serivce_unit_name', 'ipd_admitted_patlist_vw.gender_txt');

        if (!empty($request->ip_no)) {
            $query = $query->where('opt_ot_reqlist_wl_vw.admission_no_fk', $request->ip_no);
        }

        if (!empty($request->hdn_patient_id)) {
            $query = $query->where('opt_ot_reqlist_wl_vw.patient_no_fk', $request->hdn_patient_id);
        }
        if (!empty($request->ot_id)) {
            $query = $query->where('opt_ot_reqlist_wl_vw.item_no_fk', $request->ot_id);
        }
        if (!empty($request->doctor_id)) {
            $query = $query->where('opt_ot_reqlist_wl_vw.surg_doc_person_no_fk', $request->doctor_id);
        }

        if (!empty($from_date) && !empty($to_date)) {
            $query->whereRaw("TRUNC(opt_ot_reqlist_wl_vw.ot_req_date) >= TO_DATE(?, 'MM/DD/YYYY')", [$from_date]);
            $query->whereRaw("TRUNC(opt_ot_reqlist_wl_vw.ot_req_date) <= TO_DATE(?, 'MM/DD/YYYY')", [$to_date]);
        } elseif (!empty($from_date)) {
            $query->whereRaw("TRUNC(opt_ot_reqlist_wl_vw.ot_req_date) = TO_DATE(?, 'MM/DD/YYYY')", [$from_date]);
        } elseif (!empty($to_date)) {
            $query->whereRaw("TRUNC(opt_ot_reqlist_wl_vw.ot_req_date) = TO_DATE(?, 'MM/DD/YYYY')", [$to_date]);
        }

        $data = $query->orderBy('opt_ot_reqlist_wl_vw.ot_req_date', 'desc')
            ->orderBy('opt_ot_reqlist_wl_vw.admission_no_fk', 'desc')
            ->get();


        return response()->json(['data' => $data, 'title' => 'Success'], 200);
    }


    public function searchOTStatus(Request $request)
    {

        $from_date = null;
        if (!empty($request->ot_req_date_from)) {
            $dateTime = DateTime::createFromFormat('d/m/Y', $request->ot_req_date_from);
            $from_date = $dateTime->format('m/d/Y');
        }

