                "ot_complete_status.op_note",
                "ot_complete_status.pre_anes_chkup_frm",
                "ot_complete_status.pre_oper_chklist",
                "ot_complete_status.high_risk_consent",
                "ot_complete_status.ot_complete_ind",
                "ipd_admitted_patlist_vw.new_serivce_unit_name"
            );

        if (!empty($request->ip_no)) {
            $query = $query->where('a.admission_no_fk', $request->ip_no);
