        if (!empty($request->ot_id)) {
            $query = $query->where('a.item_no_fk', $request->ot_id);
        }
        if (!empty($request->doctor_id)) {
            $query = $query->where('a.surg_doc_person_no_fk', $request->doctor_id);
        }

        if (!empty($from_date) && !empty($to_date)) {
            $query->whereRaw("TRUNC(a.ot_req_date) >= TO_DATE(?, 'MM/DD/YYYY')", [$from_date]);
            $query->whereRaw("TRUNC(a.ot_req_date) <= TO_DATE(?, 'MM/DD/YYYY')", [$to_date]);
        } elseif (!empty($from_date)) {
            $query->whereRaw("TRUNC(a.ot_req_date) = TO_DATE(?, 'MM/DD/YYYY')", [$from_date]);
        } elseif (!empty($to_date)) {
            $query->whereRaw("TRUNC(a.ot_req_date) = TO_DATE(?, 'MM/DD/YYYY')", [$to_date]);
        }

        $data = $query->orderBy('a.ot_req_date', 'desc')
            ->orderBy('a.admission_no_fk', 'desc')
            ->get();


        return response()->json(['data' => $data, 'title' => 'Success'], 200);
    }



