    public function getOTList(Request $request)
    {

        $ot_date = $request->ot_date;
        if (!empty($ot_date)) {
            $dateTime = DateTime::createFromFormat('d/m/Y', $ot_date);
            $ot_date = $dateTime->format('Y-m-d');
        }


        $ot_room_pk = $request->ot_room_pk;
        $data = DB::table('OT_SCHEDULE')
            ->leftJoin('SYSC_ROOM', 'SYSC_ROOM.ROOM_NO_PK', 'OT_SCHEDULE.OT_ROOM_NO_FK')
            ->whereDate('OT_SCHEDULE.SCHEDULE_DT', $ot_date)
            ->when(!empty($ot_room_pk), function ($q) use ($ot_room_pk) {
                $q->where('OT_SCHEDULE.OT_ROOM_NO_FK', $ot_room_pk);
            })
            ->where('sysc_room.ot_ind', 1)
            ->select('OT_SCHEDULE.OT_ROOM_NO_FK', 'OT_SCHEDULE.OT_SCHEDULE_NO_PK', "sysc_room.room_name", 'sysc_room.room_code')
            ->get();


        foreach ($data as $item) {
            $item->time = DB::table('OT_SCHEDULE_SLOT')

                ->leftJoin('ipd_v1_admitted_pat_nsreq_wl_vw', 'ipd_v1_admitted_pat_nsreq_wl_vw.admission_no_pk', 'ot_schedule_slot.admission_no_fk')
                ->leftJoin('opt_prescribed_ot', 'opt_prescribed_ot.ot_req_no_pk', 'ot_schedule_slot.OT_REQ_NO_FK')
                ->leftJoin('HRMS_PERSONNEL', 'HRMS_PERSONNEL.PERSON_NO_PK', 'opt_prescribed_ot.doc_person_no_fk')


                ->whereDate('OT_SCHEDULE_SLOT.SCHEDULE_DT', $ot_date)
                ->where('OT_SCHEDULE_SLOT.OT_ROOM_NO_FK', $item->ot_room_no_fk)
                ->where('OT_SCHEDULE_SLOT.ot_schedule_no_fk', $item->ot_schedule_no_pk)
                ->where('OT_SCHEDULE_SLOT.ACTIVE_STATUS', 1)
                ->select(
                    'OT_SCHEDULE_SLOT.OT_SLOT_NO_PK',
                    'OT_SCHEDULE_SLOT.OT_ROOM_NO_FK',
                    'OT_SCHEDULE_SLOT.AVAILABLE_IND',
                    'OT_SCHEDULE_SLOT.patient_no_fk',
                    'OT_SCHEDULE_SLOT.BLOCK_IND',
                    'OT_SCHEDULE_SLOT.admission_no_fk',
                    'ipd_v1_admitted_pat_nsreq_wl_vw.patient_name',
                    'ipd_v1_admitted_pat_nsreq_wl_vw.bed_name',
                    'ipd_v1_admitted_pat_nsreq_wl_vw.ward_name',
                    'ipd_v1_admitted_pat_nsreq_wl_vw.patient_code',
                    'hrms_personnel.full_name',
                    'hrms_personnel.person_no_pk',
                    DB::raw("TO_CHAR(OT_SCHEDULE_SLOT.END_TIME, 'HH:MI AM') as END_TIME"), // Removes seconds
                    DB::raw("TO_CHAR(OT_SCHEDULE_SLOT.START_TIME, 'HH:MI AM') as START_TIME")
                )
                ->get();
        }

        $ot = DB::table('opt_prescribed_ot')
            ->leftJoin('SYSC_SERVICEITEM', 'SYSC_SERVICEITEM.ITEM_NO_PK', 'opt_prescribed_ot.ITEM_NO_FK')
            ->where('opt_prescribed_ot.patient_no_fk', $request->patient_no_fk)
            ->where('opt_prescribed_ot.admission_no_fk', $request->admission_no_fk)
            ->whereDate('opt_prescribed_ot.OT_DATE', $ot_date)
            ->select('opt_prescribed_ot.ITEM_NO_FK', 'SYSC_SERVICEITEM.ITEM_NAME', 'opt_prescribed_ot.doc_person_no_fk', 'opt_prescribed_ot.ot_req_no_pk')
            ->first();


        if(!empty($ot)){
            $doctor_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$ot->doc_person_no_fk)->value('FULL_NAME');
        }

        if (empty($ot)) {
            $doctor_name = '';
        }
        $primary_doctor_no_fk = $doc_info->primary_doctor_no_fk ?? null;
        $primary_doctor_name  = $doc_info->primary_doctor_name ?? '';

        $doc_info = DB::table('ipd_admitted_patlist_vw')->select('primary_doctor_no_fk', 'primary_doctor_name')->where('patient_no_fk', $request->patient_no_fk)->where('admission_no_pk', $request->admission_no_fk)->first();

        return response()->json(['data' => $data, 'success' => true, 'procedure_name' => @$ot->item_name, 'ot_id' => @$ot->item_no_fk, 'doctor_id' => @$ot->doc_person_no_fk, 'doctor_name' => @$doctor_name, 'ot_req_no_fk' => @$ot->ot_req_no_pk, 'primary_doctor_no_fk' => $primary_doctor_no_fk, 'primary_doctor_name' => $primary_doctor_name], 200);
    }


    public function saveOT(Request $request)
    {
        $request->validate([
            'admission_no_fk' => 'required',
            'patient_no_fk' => 'required',
            'ot_id' => 'required',
            'doctor_id' => 'required',
        ]);

        try {

            DB::beginTransaction();
            $seq = $this->getSequence('OT_REQ_NO_PK_SEQ');
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');

            $ot_date = $request->ot_date;
            if (!empty($ot_date)) {
                $dateTime = DateTime::createFromFormat('d/m/Y', $ot_date);
                $ot_date = $dateTime->format('Y-m-d');
            }


            $item_info = DB::table('sysc_serviceitem')
                ->where('item_no_pk', $request->ot_id)
                ->select('item_no_pk', 'item_code', 'item_name')
                ->first();


            if (!isset($item_info->item_name)) {
                throw new Error("Item Info not found");

            }

            if (!isset($request->ot_time) || empty($request->ot_time)) {
                throw new Error("Please Select at least one item");

            }

            $data = [
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,
                'item_no_fk' => $request->ot_id,
                'ot_req_date' => $au_entry_at,
                'OT_DATE' => $ot_date,
                'item_name' => $item_info->item_name,
                'doc_person_no_fk' => $request->doctor_id,
                'status' => 1,
            ];

            $last_id = $request->ot_req_no_fk;

            if (!empty($last_id)) {
                $data['au_update_at'] = $au_entry_at;
                $data['au_update_by'] = Auth::id();
                $data['au_update_session'] = $entry_session;
                $data['au_update_hospital_no_fk'] = $hospital_pk_no;

                DB::table('opt_prescribed_ot')
                    ->where('ot_req_no_pk', $last_id)
                    ->update($data);

            } else {
                $data['ot_req_no_pk'] = $seq;
                $data['au_entry_at'] = $au_entry_at;
                $data['anest_clearance_ind'] = 1;
                $data['ot_comfirmation_ind'] = 1;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
                DB::table('opt_prescribed_ot')->insert($data);
                $last_id = DB::table('opt_prescribed_ot')->orderByDesc('ot_req_no_pk')->value('ot_req_no_pk');
            }



            if (DB::table('OT_SCHEDULE_SLOT')->whereIn('OT_SLOT_NO_PK', $request->ot_time)->whereDate('SCHEDULE_DT', $ot_date)->where('PATIENT_NO_FK', '!=', $request->patient_no_fk, )->where('AVAILABLE_IND', 0)->count() > 0) {
                return response()->json(['success' => false, 'message' => 'Already Booked For Another Patient. Refresh and Try again', 'title' => 'Failed'], 422);
            }

            DB::table('OT_SCHEDULE_SLOT')->whereIn('OT_SLOT_NO_PK', $request->ot_time)->whereDate('SCHEDULE_DT', $ot_date)->where('AVAILABLE_IND', 1)
                ->update([
                    'AVAILABLE_IND' => 0,
                    'OT_REQ_NO_FK' => $last_id,
                    'PATIENT_NO_FK' => $request->patient_no_fk,
                    'admission_no_fk' => $request->admission_no_fk,
                ]);

            $sequenceanesRef = DB::getSequence();
            $seqRef = $sequenceanesRef->nextValue('REFF_ANES_DEPT_NO_PK_SEQ');
            DB::table('OPD_REFF_ANESTHESIA_DEPT')->insert([
                'REFF_ANES_DEPT_NO_PK' => $seqRef,
                'PATIENT_NO_FK' => $request->patient_no_fk,
                'REFF_DOC_NO_FK' => $request->doctor_id,
                'PATIENT_TYPE' => 'IPD',
                'OT_REQ_NO_FK' => $seq,
                'REFF_DATE' => $ot_date,
                'STATUS' => 1, //refered
                'AU_ENTRY_BY' => Auth::id(),
                'AU_ENTRY_AT' => date('Y-m-d'),
                'AU_ENTRY_SESSION' => $entry_session,
                'AU_ENTRY_HOSPITAL_PK_NO' => $hospital_pk_no,
            ]);

            DB::commit();
            return response()->json(['success' => true, 'message' => 'Successfully Saved', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }
    //pre ot form
    public function intraOperativeNursingRecord($patient_id = "", $admission_uid = "")
    {
        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();
        $assessment_info = DB::table('ipd_nursingassessment')
            ->where('ADMISSION_NO_FK', $patient_info->admission_no_pk)
            ->where('PATIENT_NO_FK', $patient_info->patient_no_pk)
            ->first();


        if (!empty($assessment_info)) {
            $assessment_info->bystander_signature_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->bystander_signature_id)->value('FULL_NAME');
            $assessment_info->rn_sign_name = DB::table('HRMS_PERSONNEL')->where('PERSON_NO_PK', @$assessment_info->complete_by)->value('FULL_NAME');
        }
        return Template::loadview("admin.ipd.nurse_station.v2.pre_ot.intra_operative_nursing_record", ['assessment_info' => $assessment_info, 'patient_info' => $patient_info]);
    }


    public function intraOperativeNursingForm($patient_id = "",$ref_no = "")
    {

        $pat_info = DB::table('patient_info_vw')->where('patient_no_pk', $patient_id)->first();


        $intraOperativeNursingData = DB::table('ipd_intraoperative')
                                    ->where(function ($query) use ($patient_id, $ref_no) {
                                    $query->where('patient_no_fk', $patient_id)
                                        ->orWhere('REFF_ANES_DEPT_NO_fK', $ref_no);
                                })
                                ->first();

        return Template::loadView("admin.ipd.reports.intra_operative_nursing_form", [ 'pat_info' => $pat_info, 'intraOperativeNursingData' => $intraOperativeNursingData, 'ref_no' => $ref_no]);
    }

