            db::table('ipd_intraoperative')->insert($data);
        } else {
            $data['au_update_by'] = $auth_id;
            $data['au_update_at'] = date('y-m-d');
            $data['au_update_hospital_no_fk'] = $hospital_no_pk;
            $data['au_update_session'] = 'sessoin';
            db::table('ipd_intraoperative')->where('intraoperative_no_pk', $request->intraoperative_no_pk)->update($data);
        }
        DB::commit();
