    public function intraOperativeNursingPdf($patient_id = "",$ref_no = "")
    {
        $pat_info = DB::table('patient_info_vw')->where('patient_no_pk', $patient_id)->first();
        $intraOperativeNursingData = DB::table('ipd_intraoperative')
                                    ->where(function ($query) use ($patient_id, $ref_no) {
                                    $query->where('patient_no_fk', $patient_id)
                                        ->orWhere('REFF_ANES_DEPT_NO_fK', $ref_no);
                                })
                                ->first();

        $po_hospital_details = DB::table("WSEC_HOSPITAL")->first();

        $barcode = new BarcodeGenerator();
        $barcode->setText($pat_info->patient_no_pk);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
