    public function dailyMedicineInvestigation($patient_no_fk, $admission_id)
    {
        $patient_info = DB::table('pat_registration_wl_vw as a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw as b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_no_fk)
            ->where('b.admission_uid', $admission_id)
            ->first();

        $admission_info = DB::table('ipd_admitted_patlist_vw')
            ->where('admission_uid', $admission_id)
            ->first();

        // Use Carbon to parse dates safely
        $startDate = $admission_info && !empty($admission_info->admission_date)
            ? Carbon::parse($admission_info->admission_date)
            : Carbon::today();

        $endDate = $admission_info && !empty($admission_info->discharge_date)
            ? Carbon::parse($admission_info->discharge_date)
            : Carbon::today();

        // Create date range including end date
        $period = new DatePeriod(
            $startDate,
            new DateInterval('P1D'),
            $endDate->copy()->addDay()
        );

        $report_dates = [];
        foreach ($period as $date) {
            $report_dates[] = $date->format('Y-m-d');
        }

        return Template::loadView("admin.ipd.nurse_station.v2.modal.medicine_investigation_popup", [
            'report_dates' => $report_dates,
            'patient_info' => $patient_info,
            'patient_no_fk' => $patient_no_fk,
            'admission_id' => $admission_id,
            'admission_info' => $admission_info,
        ]);
    }

    public function medicineInvestigationChart($patient_no_pk, $admission_no_pk, $date)
    {
        ini_set('max_execution_time', 0);

        $patient_id = $patient_no_pk;
        $admission_uid = $admission_no_pk;

        $patient_info = DB::table('pat_registration_wl_vw a')
            ->select("a.*", "b.admission_no_pk", "b.admission_uid", "b.admission_date", "b.ward_name", "b.bed_name", "b.bed_uid", "b.admitted_department", "b.primary_doctor_no_fk", "b.primary_doctor_name")
            ->leftJoin('ipd_admitted_pat_nsrcv_wl_vw b', "a.patient_no_pk", "=", "b.patient_no_fk")
            ->where('a.patient_no_pk', $patient_id)
            ->where('b.admission_uid', $admission_uid)
            ->first();



        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_no_pk', $admission_uid)->first();
        $barcode = new BarcodeGenerator();
        $barcode->setText($admission_info->admission_uid);
        $barcode->setType(BarcodeGenerator::Code128);
        $barcode->setLabel('');
        $barcode->setScale(1);
        $barcode->setThickness(25);
        $barcode->setFontSize(10);
        $invoice_barcode = $barcode->generate();
        $pat_code = new BarcodeGenerator();
        $pat_code->setText($patient_info->patient_code);
        $pat_code->setType(BarcodeGenerator::Code128);
        $pat_code->setLabel('');
        $pat_code->setScale(1);
        $pat_code->setThickness(25);
        $pat_code->setFontSize(10);
        $pat_barcode = $pat_code->generate();
        $userInfo = Auth::user();




        $today = Carbon::parse($date);
        $startDate = $today->copy()->addHours(7)->setTimezone('Asia/Dhaka');
        $endDate = $startDate->copy()->addDay()->subSecond()->setTimezone('Asia/Dhaka');
        $investigation = DB::table('psn_t_prescription_dtl_vw')
            ->where('patient_no_fk', '=', $patient_id)
            ->where('admission_pk_no', '=', $admission_uid)
            ->whereBetween('prescription_date', [$startDate, $endDate])
            ->get();

        $prescription_med = DB::table('psn_t_prescription_med_vw')
            ->where('patient_no_fk', '=', $patient_id)
            ->where('admission_pk_no', '=', $admission_uid)
            ->whereBetween('AU_ENTRY_AT', [$startDate, $endDate])
            ->orderBy('entry_serial', 'ASC')
            ->get();



        return view("admin.ipd.nurse_station.v2.export.medicine_investigation_chart", [
            'userInfo' => $userInfo,
            'pat_barcode' => $pat_barcode,
            'invoice_barcode' => $invoice_barcode,
            'admission_info' => $admission_info,
            'investigation' => $investigation,
            'prescription_med' => $prescription_med,
            'patient_info' => $patient_info,
            'date' => $date
        ]);
    }


