                ->where('admission_no_fk', $request->admission_no_fk)
                ->where('patient_no_fk', $request->patient_no_fk)
                ->update($data);
        }

        DB::commit();
            return response()->json(['success' => true, 'message' => 'Successfully Saved'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'message' => $th->getMessage()], 422);
        }
    }


