      public function storeSurgicalPreventionBundle(Request $request){
        //dd($request->all());

        $hospital_no_pk = Session::get('user.ses_hospital_no_pk');
        $auth_id = Auth::id();
        DB::beginTransaction();

         $proc_start = null;
        $timeInput = $request->input('proc_start'); // Format: HH:mm
        if (!empty($timeInput)) {
            $proc_start = Carbon::now(); // or new DateTime('now');
            $timeInput = explode(":", $timeInput);
            $timeInput = $timeInput[0] . ':' . $timeInput[1];
            $proc_start = Carbon::createFromFormat('Y-m-d H:i', $proc_start->format('Y-m-d') . ' ' . $timeInput);
        }

         $proc_end = null;
        $timeInput = $request->input('proc_end'); // Format: HH:mm
        if (!empty($timeInput)) {
            $proc_end = Carbon::now(); // or new DateTime('now');
            $timeInput = explode(":", $timeInput);
            $timeInput = $timeInput[0] . ':' . $timeInput[1];
            $proc_end = Carbon::createFromFormat('Y-m-d H:i', $proc_end->format('Y-m-d') . ' ' . $timeInput);
        }



       $data = [
                        'ADMISSION_NO_FK'      => $request->admission_no_fk,
                        'PATIENT_NO_FK'        => $request->patient_no_fk,
                        'DIAGNOSIS'            => $request->diagnosis,
                        'OBSERVER_NAME'        => $request->observer_name,
                        'DOC_NAME'             => $request->doc_name,
                        'SCRUB_NURSE'          => $request->scrub_nurse,
                        'SURGERY_NAME'         => $request->surgery_name,
                        'PROC_START'           => $proc_start,
                        'PROC_END'             => $proc_end,
                        'VERIFY_PATIENT'       => $request->verify_patient,
                        'REMARKS1'             => $request->remarks1,
                        'VERIFY_INVEST'        => $request->verify_invest,
                        'REMARKS2'             => $request->remarks2,
                        'VERIFY_CLEAN'         => $request->verify_clean,
                        'REMARKS3'             => $request->remarks3,
                        'VERIFY_SCREENING'     => $request->verify_screening,
                        'REMARKS4'             => $request->remarks4,
                        'SIGN_STAFF'           => $request->sign_staff,
                        'VERIFY_PROCEDURE'     => $request->verify_procedure,
                        'REMARKS5'             => $request->remarks5,
                        'VERIFY_SIGN'          => $request->verify_sign,
                        'REMARKS6'             => $request->remarks6,
                        'VERIFY_SITE'          => $request->verify_site,
                        'REMARKS7'             => $request->remarks7,
                        'VERIFY_BLOOD'         => $request->verify_blood,
                        'REMARKS8'             => $request->remarks8,
                        'OT_STAFF'             => $request->ot_staff,
                        'VERIFY_ALLERGY'       => $request->verify_allergy,
                        'REMARKS9'             => $request->remarks9,
                        'VERIFY_ANTICOAG'      => $request->verify_anticoag,
                        'REMARKS10'            => $request->remarks10,
                        'VERIFY_CART'          => $request->verify_cart,
                        'REMARKS11'            => $request->remarks11,
                        'VERIFY_SITE_ASSESS'   => $request->verify_site_assess,
                        'REMARKS12'            => $request->remarks12,
                        'ASSIGNED_STAFF'       => $request->assigned_staff,
                                        ];



        $sequence = DB::getSequence();
        $surgical_infection_no_pk = $sequence->nextValue('surgical_infection_no_pk_seq');
        if ($request->surgical_infection_no_pk == "") {
            $data['surgical_infection_no_pk'] = $surgical_infection_no_pk;
            $data['AU_ENTRY_BY'] = $auth_id;
            $data['AU_ENTRY_AT'] = date('Y-m-d');
            $data['AU_ENTRY_SESSION'] = 'sessoin';
            $data['AU_ENTRY_HOSPITAL_NO_FK'] = $hospital_no_pk;
            DB::table('surgical_infection')->insert($data);
        } else {
            $data['AU_UPDATE_BY'] = $auth_id;
            DB::table('surgical_infection')->where('surgical_infection_no_pk', $request->surgical_infection_no_pk)->update($data);
        }
        DB::commit();
        $this->message = ['msg' => 'Data saved successfully.', 'title' => 'Success'];
        return response()->json($this->message);
    }

