                    'mouthcare_7am' => $request->mouthcare_7am,
        ]);


        $saveOrUpdate = function ($table, $data) use ($auth_id) {
            $exists = DB::table($table)
                ->where('ADMISSION_NO_FK', $data['ADMISSION_NO_FK'])
                ->where('PATIENT_NO_FK', $data['PATIENT_NO_FK'])
                ->first();

            if ($exists) {
                // update
                $data['AU_UPDATE_BY'] = $auth_id;
                $data['AU_UPDATE_AT'] = date('Y-m-d H:i:s');
                DB::table($table)
                    ->where('ADMISSION_NO_FK', $data['ADMISSION_NO_FK'])
                    ->where('PATIENT_NO_FK', $data['PATIENT_NO_FK'])
                    ->update($data);
            } else {
                // insert new
                $pkField = $table . '_NO_PK'; // e.g. NICU_FLOW1_NO_PK
                $data[$pkField] = DB::getSequence()->nextValue($pkField . '_SEQ');
                $data['AU_ENTRY_BY'] = $auth_id;
                $data['AU_ENTRY_AT'] = date('Y-m-d H:i:s');
                $data['AU_ENTRY_SESSION'] = 'session';
                DB::table($table)->insert($data);
            }
        };


        $saveOrUpdate('NICU_FLOW_SHEET1', $data1);
        $saveOrUpdate('NICU_FLOW_SHEET2', $data2);
        $saveOrUpdate('NICU_FLOW_SHEET3', $data3);

        DB::commit();

        return response()->json([
            'msg' => 'Data Saved Successfully',
            'title' => 'Success'
        ]);
    } catch (\Exception $e) {
        DB::rollBack();
        return response()->json([
            'msg' => 'Error: ' . $e->getMessage(),
            'title' => 'Failed'
        ], 500);
    }
}



