        $admission_info = DB::table('ipd_admitted_patlist_vw')->where('admission_uid', $admission_id)->first();

        $oxyzen = DB::table('b_type_oxygen')
            ->select('b_type_oxygen.*', 'user_fullname' , 'user_code')
            ->leftJoin('wsec_user usr', 'usr.user_no_pk', 'b_type_oxygen.au_entry_by')
            ->where('b_type_oxygen.patient_no_fk', $patient_no_fk)
            ->where('b_type_oxygen.admission_no_fk', $admission_id)
            ->orderByDesc('b_type_oxygen.b_type_oxygen_no_pk')
            ->get();
        $unit_month = DB::table('b_type_oxygen')
            ->select('b_type_oxygen.*', 'user_fullname' , 'user_code')
            ->leftJoin('wsec_user usr', 'usr.user_no_pk', 'b_type_oxygen.au_entry_by')
            ->where('b_type_oxygen.patient_no_fk', $patient_no_fk)
            ->where('b_type_oxygen.admission_no_fk', $admission_id)
            ->orderByDesc('b_type_oxygen.b_type_oxygen_no_pk')
            ->first();

        return Template::loadView("admin.ipd.nurse_station.v2.daily_checklist_btype_oxyzen_cylinder", ['patient_info' => $patient_info, 'patient_no_fk' => $patient_no_fk, 'admission_id' => $admission_id, 'admission_info' => $admission_info,'oxyzen' => $oxyzen,'unit_month' => $unit_month]);

    }



  public function storebTypeOxyzenCylinder(Request $request)
    {
        $request->validate([
            'admission_no_fk' => 'required',
            'patient_no_fk' => 'required',

        ]);

        try {
            $seq = $this->getSequence('b_type_oxygen_no_pk_seq');
            $au_entry_at = new DateTime('now');
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = Session()->get('user.ses_user_pk_no');
            $data = [
                'b_type_oxygen_no_pk' => $seq,
                'laryngoscope_date' => $au_entry_at,
                'UNIT'              => $request->unit,
                'MONTH'             => $request->month,
                'M_READING'         => $request->m_reading,
                'M_SIGN'            => $request->m_sign,
                'E_READING'         => $request->e_reading,
                'E_SIGN'            => $request->e_sign,
                'N_READING'         => $request->n_reading,
                'N_SIGN'            => $request->n_sign,
                'status' => 1,
                'patient_no_fk' => $request->patient_no_fk,
                'admission_no_fk' => $request->admission_no_fk,
            ];
            $data['au_entry_at'] = $au_entry_at;
            $data['au_entry_by'] = Auth::id();
            $data['au_entry_session'] = $entry_session;
            $data['au_entry_hospital_no_fk'] = $hospital_pk_no;
            DB::table('b_type_oxygen')->insert($data);

            return response()->json(['success' => true, 'msg' => 'Successfully Saved', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }


