    public function getIpdPackageSetupV1($pkg_no_pk = '')
    {
        $bedcategory = $this->getLookupListByCode("CATEGORYTYPE");
        // echo "test";
        // dd($bedcategory);
        $service_item = DB::table('sysc_serviceitem')
            ->where('IPD_PKG_IND', 1)
            ->get();

        $package = null;
        $packageItems = [];

        if ($pkg_no_pk) {
            $package = DB::table('sysc_pkgmst')->where('pkg_no_pk', $pkg_no_pk)->first();
            $packageItems = DB::table('sysc_pkgdtl')->where('pkg_no_fk', $pkg_no_pk)->get();
