            'package' => $package,
            'packageItems' => $packageItems
        ]);
    }
    public function v1IpdPackageStore(Request $request)
    {
        DB::beginTransaction();
        try {
            $hospital_pk_no = session()->get('user.ses_hospital_no_pk');
            $entry_session = session()->get('user.ses_user_pk_no');
            $au_entry_at = now();

            $packageFor = (int) $request->input('package_for');
            $pkgNo = $request->input('pkg_no_pk');
            //insert or update package details rr
            $data = [
                'PKG_NAME' => $request->package_name,
                'PKG_DETAILS' => $request->package_details,
                'PKG_FOR_IPD' => $packageFor == 1 ? $packageFor : '',
                'PKG_FOR_OPD' => $packageFor == 2 ? $packageFor : '',
                'PKG_FOR_DAYCARE' => $packageFor == 3 ? $packageFor : '',
                'PATHOLOGY_AMOUNT' => $request->package_pathology ?? '',
                'RADIOLOGY_AMOUNT' => $request->package_radiology ?? '',
                'MEDICONE_AMOUNT' => $request->package_medicine ?? '',
                'CONSULTATION_AMOUNT' => $request->package_consultation ?? '',
                'OT_SUR_ANA_AMOUNT' => $request->package_ot ?? '',
                'PROCEDURE_AMOUNT' => $request->package_procedure ?? '',
                'FOOD_AMOUNT' => $request->package_food ?? '',
                'SERVICE_AMOUNT' => $request->package_services ?? '',
                'CONSUMABLE_AMOUNT' => $request->package_consumable ?? '',
            ];

            if ($pkgNo) {
                DB::table('sysc_pkgmst')->where('pkg_no_pk', $pkgNo)->update($data);
                DB::table('sysc_pkgdtl')->where('pkg_no_fk', $pkgNo)->delete();
            } else {
                $pkgSeq = $this->getSequence('pkg_no_pk_seq');
                $data['pkg_no_pk'] = $pkgSeq;
                $data['au_entry_at'] = $au_entry_at;
                $data['au_entry_by'] = Auth::id();
                $data['au_entry_session'] = $entry_session;
                $data['au_entry_hospital_pk_no'] = $hospital_pk_no;

                DB::table('sysc_pkgmst')->insert($data);
                $pkgNo = $pkgSeq;
            }

            // Insert package items
            if ($request->has('items')) {
                foreach ($request->items['item_name'] as $key => $value) {
                    $pkgDtlSeq = $this->getSequence('pkgdtl_no_pk_seq');
                    DB::table('sysc_pkgdtl')->insert([
                        'pkgdtl_no_pk' => $pkgDtlSeq,
                        'PKG_NO_FK' => $pkgNo,
                        'ITEM_NO_FK' => $request->items['item_no_pk'][$key] ?? null,
                        'ITEM_NAME' => $request->items['item_name'][$key],
                        'ITEM_TYPE' => $request->items['item_type'][$key] ?? '',
                        'ITEM_QTY' => $request->items['item_qty'][$key] ?? 0,
                        'ITEM_RATE' => $request->items['item_rate'][$key] ?? 0,
                        'ITEM_PKG_RATE' => $request->items['item_package_rate'][$key] ?? 0,
                        'ITEM_PKG_DISCOUNT_PCT' => $request->items['package_discount_percent'][$key] ?? 0,
                        'ITEM_PKG_DISCOUNT_AMT' => $request->items['package_discount_amount'][$key] ?? 0,
                    ]);
                }
            }

            DB::commit();
            return response()->json(['success' => true, 'msg' => 'Package saved successfully', 'title' => 'Success'], 200);
        } catch (\Throwable $th) {
            DB::rollBack();
            return response()->json(['success' => false, 'msg' => $th->getMessage(), 'title' => 'Failed'], 422);
        }
    }

