    public function v1IpdPackageDelete($pkg_no_pk)
    {
        DB::beginTransaction();
        try {
            DB::table('sysc_pkgdtl')->where('pkg_no_fk', $pkg_no_pk)->delete();

            DB::table('sysc_pkgmst')->where('pkg_no_pk', $pkg_no_pk)->delete();

            DB::commit();
            return redirect()->route('v1.ipd-package-list')
                ->with('success', 'Package deleted successfully');
        } catch (\Throwable $th) {
            DB::rollBack();
            return redirect()->route('v1.ipd-package-list')
                ->with('error', 'Failed to delete package: '.$th->getMessage());
        }
    }
