    public function v1IpdPackagePatientStore(Request $request)
    {
        // try {
           $admissionNo = trim($request->input('hdn_admission_id'));

            $bedInfo = DB::table('IPD_ADMITTED_PATLIST_VW')
                ->select('new_bed_no_fk', 'new_bed_name')
                ->where('ADMISSION_NO_PK', $admissionNo)
                ->first();


            // dd($bedInfo);
            $pkgNo = $request->input('package_ipd_r');
            
            $applyDate = $request->input('package_start_date') 
                ? date('Y-m-d', strtotime($request->input('package_start_date')))
                : date('Y-m-d');

            $in_admission_no_pk = (int)$admissionNo;
            $in_bed_no_pk = $bedInfo->new_bed_no_fk ? (int)$bedInfo->new_bed_no_fk : null;
            $in_voucher_no_pk = $request->input('voucher_no_pk');
            $in_voucher_no_pk = ($in_voucher_no_pk === '' || $in_voucher_no_pk === null) ? null : (int)$in_voucher_no_pk;
            $in_pkg_no_pk = $pkgNo ? (int)$pkgNo : null;
            $in_apply_date = $applyDate;

            $au_entry_by = auth()->user()->user_no_pk ?? 1;
            $entry_session = 'package assign';
            $hospital_pk_no = Session::get('user.ses_hospital_no_pk');

            $out_pkgpat_no_pk = 0;
            $out_pkgpat_uid = '';
            $out_error = '';

            $pdo = DB::getPdo();
            $stmt = $pdo->prepare("
                BEGIN
                    pkg_corporate.prc_patient_pkg_assign(
                        :in_admission_no_pk,
                        :in_bed_no_pk,
                        :in_voucher_no_pk,
                        :in_pkg_no_pk,
                        :in_apply_date,
                        :in_au_entry_by,
                        :in_au_entry_session,
                        :in_au_entry_hospital_pk_no,
                        :out_pkgpat_no_pk,
                        :out_pkgpat_uid,
                        :out_error
                    );
                END;
            ");

            $stmt->bindParam(':in_admission_no_pk', $in_admission_no_pk, PDO::PARAM_INT);
            $stmt->bindParam(':in_bed_no_pk', $in_bed_no_pk, PDO::PARAM_INT);
            $stmt->bindParam(':in_voucher_no_pk', $in_voucher_no_pk, PDO::PARAM_INT);
            $stmt->bindParam(':in_pkg_no_pk', $in_pkg_no_pk, PDO::PARAM_INT);
            $stmt->bindParam(':in_apply_date', $in_apply_date);
            $stmt->bindParam(':in_au_entry_by', $au_entry_by, PDO::PARAM_INT);
            $stmt->bindParam(':in_au_entry_session', $entry_session);
            $stmt->bindParam(':in_au_entry_hospital_pk_no', $hospital_pk_no, PDO::PARAM_INT);

            $stmt->bindParam(':out_pkgpat_no_pk', $out_pkgpat_no_pk, PDO::PARAM_INT | PDO::PARAM_INPUT_OUTPUT, 32);
            $stmt->bindParam(':out_pkgpat_uid', $out_pkgpat_uid, PDO::PARAM_STR | PDO::PARAM_INPUT_OUTPUT, 4000);
            $stmt->bindParam(':out_error', $out_error, PDO::PARAM_STR | PDO::PARAM_INPUT_OUTPUT, 4000);

            // dd($stmt);
            $stmt->execute();

            if ($out_error == '000') {
                DB::commit();
                $message = ['msg' => 'Package assigned successfully.', 'title' => 'Success', 'pkgpat_no_pk' => $out_pkgpat_no_pk];
            } else {
                DB::rollback();
                $message = ['msg' => 'Process Failed' . $out_error, 'title' => 'Error'];
            }

           return response()->json($message);
        // } catch (\Exception $e) {
        //     return response()->json([
        //         'title' => 'Exception',
        //         'msg' => $e->getMessage(),
        //     ], 500);
        // }
    }


    



